#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 configuration values
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000  // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // PGA = ±4.096V
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000 // Disable comparator

// MLX91219 sensitivity (mV/A)
#define MLX91219_SENSITIVITY 40.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the ADS1115
int ads1115_init() {
    // Configure the ADS1115 for single-shot mode
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_OS_SINGLE) < 0) {
        fprintf(stderr, "Error writing to ADS1115_REG_CONFIG\n");
        return -1;
    }

    // Configure the ADS1115 for AIN0 single-ended
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG + 1, ADS1115_CONFIG_MUX_AIN0) < 0) {
        fprintf(stderr, "Error writing to ADS1115_REG_CONFIG + 1\n");
        return -1;
    }

    // Configure the ADS1115 for PGA = ±4.096V
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG + 2, ADS1115_CONFIG_PGA_4_096V) < 0) {
        fprintf(stderr, "Error writing to ADS1115_REG_CONFIG + 2\n");
        return -1;
    }

    // Configure the ADS1115 for single-shot mode
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG + 3, ADS1115_CONFIG_MODE_SINGLE) < 0) {
        fprintf(stderr, "Error writing to ADS1115_REG_CONFIG + 3\n");
        return -1;
    }

    // Configure the ADS1115 for 128 SPS
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG + 4, ADS1115_CONFIG_DR_128SPS) < 0) {
        fprintf(stderr, "Error writing to ADS1115_REG_CONFIG + 4\n");
        return -1;
    }

    // Disable comparator
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG + 5, ADS1115_CONFIG_COMP_QUE_DISABLE) < 0) {
        fprintf(stderr, "Error writing to ADS1115_REG_CONFIG + 5\n");
        return -1;
    }

    return 0;
}

// Function to read the ADS1115 data
int ads1115_read_data(int16_t *data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115_REG_CONVERT\n");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert the raw ADC value to current in amperes
float convert_to_current(int16_t raw_value) {
    float voltage = (float)raw_value * 4.096 / 32768.0; // Assuming PGA = 4.096V
    float current = voltage / MLX91219_SENSITIVITY; // Convert to amperes
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init() < 0) {
        fprintf(stderr, "ADS1115 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (ads1115_read_data(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current data\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

