#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define HEAT_SENSOR_I2C_ADDR 0x48
#define HEAT_SENSOR_CHANNEL 0 // AIN0
#define BUZZER_GPIO 27
#define DEBOUNCE_TIME_MS 50
#define BUZZER_DURATION_S 2
#define LOG_FILE "fire_log.txt"

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;
static int last_flame_event_time = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int configure_adc();
int read_adc(int handle, int channel);
float convert_adc_to_temperature(int adc_value);
int detect_flame();
int check_temperature(float temperature);
void log_event(const char *message);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
void flame_callback(int gpio, int level, uint32_t tick);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer();

    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, HEAT_SENSOR_I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Function to configure the ADS1115 ADC
int configure_adc() {
    // Configuration register value for single-shot mode, ±4.096V, 128 SPS
    unsigned short config = 0x4003; // Single-shot, AIN0, +/-4.096V, 128 SPS
    char buf[3];
    buf[0] = 0x01; // Configuration register address
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF; // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "ADC configuration failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to read the ADC value
int read_adc(int handle, int channel) {
    // Write the configuration register again to start a conversion
    unsigned short config = 0x4003; // Single-shot, AIN0, +/-4.096V, 128 SPS
    char buf[3];
    buf[0] = 0x01; // Configuration register address
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF; // LSB

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "ADC configuration failed: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8.5ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register (0x00-0x07)
    char reg = 0x00; // Conversion register address
    char read_buf[2];
    int result2 = i2cWriteDevice(handle, &reg, 1);
    if (result2 != 0) {
        fprintf(stderr, "ADC read failed: %d\n", result2);
        return -1;
    }

    result2 = i2cReadDevice(handle, read_buf, 2);
    if (result2 != 2) {
        fprintf(stderr, "ADC read failed: %d\n", result2);
        return -1;
    }

    // Combine the two bytes to get the 16-bit ADC value
    int adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * 4.096 / 32768.0; // Assuming 4.096V range
    float temperature = (voltage - 0.5) * 20.0; // Linear conversion to 20-80C
    return temperature;
}

// Function to detect flame
int detect_flame() {
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level == 0) { // Flame detected (LOW signal)
        return 1;
    } else {
        return 0;
    }
}

// Function to check temperature
int check_temperature(float temperature) {
    return (temperature > 60.0) ? 1 : 0;
}

// Function to log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write to file
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO HIGH
    gpioDelay(BUZZER_DURATION_S * 1000000); // Delay for 2 seconds
    deactivate_buzzer();
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO LOW
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    deactivate_buzzer();
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

// Flame sensor callback function
void flame_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected
        int current_time = gpioTick();
        if (current_time - last_flame_event_time > DEBOUNCE_TIME_MS * 1000) { // Debounce
            last_flame_event_time = current_time;
            int flame_detected = detect_flame();
            float temperature = read_adc(i2c_handle, HEAT_SENSOR_CHANNEL);
            if (temperature != -1) {
                int temperature_above_60 = check_temperature(temperature);
                if (flame_detected && temperature_above_60) {
                    log_event("Fire detected!");
                    activate_buzzer();
                } else if (flame_detected) {
                    log_event("Flame detected!");
                } else if (temperature_above_60) {
                    log_event("Temperature above 60C!");
                }
            } else {
                log_event("Error reading temperature!");
            }
        }
    }
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADC
    if (configure_adc() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up ISR for flame sensor
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_callback, NULL);

    // Main loop
    while (running) {
        gpioDelay(100000); // 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_buzzer();
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

