#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip4" // Or "gpiochip0" if not using gpiochip4
#define GPIO_PIN 18
#define DEFAULT_SENSITIVITY 0.1 // 100 mV/A
#define DEFAULT_THRESHOLD 5.0 // 5.0 A
#define LOG_FILE "current_log.txt"

// Global variables
static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static double sensitivity = DEFAULT_SENSITIVITY;
static double threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_adc(int fd, int channel);
double adc_to_current(int adc_value, double sensitivity);
bool check_threshold(double current, double threshold);
int gpio_init(const char *chip, int pin);
int gpio_set_value(int chip, int pin, int value);
int gpio_release(struct gpiod_chip *chip, struct gpiod_line *line);
void log_data(double current, int adc_value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = (mode & 0x07) << 4;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_val = (bits & 0x07) << 2;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC reading function
int read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI command (MCP3008 single-ended read)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading ADC channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Current conversion function
double adc_to_current(int adc_value, double sensitivity) {
    return (adc_value * sensitivity) / 1000.0; // Convert to Amperes
}

// Threshold check function
bool check_threshold(double current, double threshold) {
    return current > threshold;
}

// GPIO initialization function
int gpio_init(const char *chip, int pin) {
    struct gpiod_chip *chip_ptr = gpiod_chip_open_by_name(chip);
    if (!chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ptr = gpiod_chip_get_line(chip_ptr, pin);
    if (!line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    if (gpiod_line_request_output(line_ptr, "current_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_ptr);
        gpiod_line_release(line_ptr);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(int chip, int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// GPIO release function
int gpio_release(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Data logging function
void log_data(double current, int adc_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, ADC: %d, Current: %.2f A\n", timestamp, adc_value, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_chip != NULL) {
        gpio_release(gpio_chip, gpio_line);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Current sensor monitoring started. Sensitivity: %.2f V/A, Threshold: %.2f A\n", sensitivity, threshold);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, 0);
