#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define CO_REG 0x01
#define NO2_REG 0x02
#define ALERT_THRESHOLD 25.0
#define LOG_FILE_CO "co_log.txt"
#define LOG_FILE_ALERT "alert_log.txt"

// Global variables
int i2c_handle;
FILE *co_log_file = NULL;
FILE *alert_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *co_value, int *no2_value);
float calculate_co_ppm(int co_value);
void log_co_ppm(float co_ppm);
void log_alert(float co_ppm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int *co_value, int *no2_value) {
    char buffer[4];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, CO_REG, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    *co_value = (buffer[0] << 8) | buffer[1];
    *no2_value = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Function to calculate CO level in PPM
float calculate_co_ppm(int co_value) {
    // Simple linear conversion (replace with actual calibration curve if needed)
    return (float)co_value * 0.1; // Example: 0.1 PPM per unit
}

// Function to log CO level to file
void log_co_ppm(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (co_log_file != NULL) {
        fprintf(co_log_file, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
        fflush(co_log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: CO log file is not open.\n");
    }
}

// Function to log alert to file
void log_alert(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (alert_log_file != NULL) {
        fprintf(alert_log_file, "%s, ALERT: CO level exceeds threshold (%.2f PPM > %.2f PPM)\n", timestamp, co_ppm, ALERT_THRESHOLD);
        fflush(alert_log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Alert log file is not open.\n");
    }
}

int main() {
    int co_value, no2_value;
    float co_ppm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log files
    co_log_file = fopen(LOG_FILE_CO, "a");
    if (co_log_file == NULL) {
        fprintf(stderr, "Error opening CO log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    alert_log_file = fopen(LOG_FILE_ALERT, "a");
    if (alert_log_file == NULL) {
        fprintf(stderr, "Error opening alert log file!\n");
        fclose(co_log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO/NO2 Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&co_value, &no2_value) == 0) {
            // Calculate CO level in PPM
            co_ppm = calculate_co_ppm(co_value);

            // Log CO level
            log_co_ppm(co_ppm);

            // Check for alert condition
            if (co_ppm > ALERT_THRESHOLD) {
                log_alert(co_ppm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(co_log_file);
    fclose(alert_log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

