#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define I2C addresses for the microphones
#define MICROPHONE1_ADDR 0x48
#define MICROPHONE2_ADDR 0x49

// Define the number of samples to read from each microphone
#define NUM_SAMPLES 16

// Define the sampling rate (Hz)
#define SAMPLING_RATE 100

// Define the reference pressure (Pa)
#define REFERENCE_PRESSURE 20e-6

// Define the microphone sensitivity (dBV/Pa)
#define MICROPHONE_SENSITIVITY -38.0

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold microphone data
typedef struct {
    int handle;
    int address;
} Microphone;

// Function prototypes
int initialize_i2c(Microphone *mic1, Microphone *mic2);
int read_microphone_data(int handle, int *data);
float convert_to_db(int raw_data);
float calculate_average_db(float db1, float db2);
void log_data(float average_db);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize I2C
int initialize_i2c(Microphone *mic1, Microphone *mic2) {
    mic1->handle = i2cOpen(1, mic1->address, 0); // Open I2C bus 1
    if (mic1->handle < 0) {
        fprintf(stderr, "Error opening I2C device for microphone 1 at address 0x%02x: %d\n", mic1->address, mic1->handle);
        return -1;
    }

    mic2->handle = i2cOpen(1, mic2->address, 0); // Open I2C bus 1
    if (mic2->handle < 0) {
        fprintf(stderr, "Error opening I2C device for microphone 2 at address 0x%02x: %d\n", mic2->address, mic2->handle);
        i2cClose(mic1->handle);
        return -1;
    }

    return 0;
}

// Function to read data from a microphone
int read_microphone_data(int handle, int *data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (buffer[0] << 8) | buffer[1];
    if (*data > 32767) *data -= 65536; // Handle two's complement

    return 0;
}

// Function to convert raw data to dB
float convert_to_db(int raw_data) {
    // Calculate the voltage from the raw data (assuming 16-bit signed integer)
    float voltage = (float)raw_data / 32767.0 * 3.3; // Assuming 3.3V reference

    // Calculate the sound pressure level in dB
    float sound_pressure_level = MICROPHONE_SENSITIVITY + 20 * log10(voltage / REFERENCE_PRESSURE);

    return sound_pressure_level;
}

// Function to calculate the average sound pressure level
float calculate_average_db(float db1, float db2) {
    return (db1 + db2) / 2.0;
}

// Function to log the data to a file
void log_data(float average_db) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f dB\n", timestamp, average_db);
    fclose(fp);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize microphones
    Microphone mic1 = {0, MICROPHONE1_ADDR};
    Microphone mic2 = {0, MICROPHONE2_ADDR};

    if (initialize_i2c(&mic1, &mic2) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int raw_data1, raw_data2;
        float db1, db2, average_db;

        // Read data from microphone 1
        if (read_microphone_data(mic1.handle, &raw_data1) == 0) {
            db1 = convert_to_db(raw_data1);
        } else {
            db1 = -999.0;
        }

        // Read data from microphone 2
        if (read_microphone_data(mic2.handle, &raw_data2) == 0) {
            db2 = convert_to_db(raw_data2);
        } else {
            db2 = -999.0;
        }

        // Calculate the average sound pressure level
        average_db = calculate_average_db(db1, db2);

        // Log the data
        log_data(average_db);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

