#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define THRESHOLD 0.7
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_RATE_MS 1
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_RATE_MS)
#define MCP3008_CHANNEL_1 0
#define MCP3008_CHANNEL_2 1

// Global variables
int spi_handle_0 = -1;
int spi_handle_1 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t samples[NUM_SAMPLES];
    double rms;
} MicrophoneData;

// Function prototypes
int initialize_spi(int channel);
int read_mcp3008(int channel);
double calculate_rms(const int16_t *samples, int num_samples);
void control_led(int on);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi(int channel) {
    int handle = spiOpen(channel, SPI_SPEED, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle_, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error for channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(const int16_t *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Function to log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle_0 >= 0) {
        spiClose(spi_handle_0);
    }
    if (spi_handle_1 >= 0) {
        spiClose(spi_handle_1);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI channels
    spi_handle_0 = initialize_spi(SPI_CHANNEL_0);
    if (spi_handle_0 < 0) {
        cleanup();
        return 1;
    }

    spi_handle_1 = initialize_spi(SPI_CHANNEL_1);
    if (spi_handle_1 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read microphone data
        int16_t mic1_samples[NUM_SAMPLES];
        int16_t mic2_samples[NUM_SAMPLES];
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = (int16_t)read_mcp3008(MCP3008_CHANNEL_1);
            mic2_samples[i] = (int16_t)read_mcp3008(MCP3008_CHANNEL_2);
        }

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Check threshold and control LED
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(500);  // Wait 500 ms
            control_led(0); // Turn off LED
        }

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Delay for sampling window
        gpioDelay(SAMPLE_WINDOW_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

