// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define OVERCURRENT_THRESHOLD 50.0f
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_adc(int16_t *adc_value);
float convert_adc_to_current(int16_t adc_value);
void add_to_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    float overcurrent_threshold;
    int led_gpio;
    int sample_rate;
    int buffer_size;
} config_t;

config_t config = {
    I2C_BUS,
    ADS1115_ADDR,
    OVERCURRENT_THRESHOLD,
    LED_GPIO,
    SAMPLE_RATE,
    BUFFER_SIZE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t adc_value;
    float current;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_adc(&adc_value) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to current
        current = convert_adc_to_current(adc_value);

        // Add current to circular buffer
        add_to_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Control LED
        control_led(average_current);

        // Delay for sample rate
        gpioDelay(1000000 / config.sample_rate); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(config.led_gpio, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V range, 128 SPS, disable comparator
    char config_data[3];
    config_data[0] = ADS1115_REG_CONFIG;
    config_data[1] = 0xC2; // Single-ended A0, 4.096V, 128 SPS
    config_data[2] = 0x83; // Disable comparator, start single conversion

    if (i2cWriteDevice(i2c_handle, config_data, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc(int16_t *adc_value) {
    char convert_data[1];
    char read_data[2];

    convert_data[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, convert_data, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return 1;
    }

    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return 1;
    }

    *adc_value = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Convert ADC value to current
float convert_adc_to_current(int16_t adc_value) {
    // Assuming 5V supply and 0.5V to 4.5V output
    float voltage = (float)adc_value * (4.096 / 32768.0); // 4.096V range
    float current = voltage / 0.5; // 0.5V to 100A
    return current;
}

// Add current to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > config.overcurrent_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn on LED
    } else {
        gpioWrite(config.led_gpio, 0); // Turn off LED
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Terminating...\n");
    terminate = 1;
}

