#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *color_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable power and ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x01 | 0x02) < 0) {
        fprintf(stderr, "Error: Failed to enable sensor (ENABLE register): %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error: Failed to set integration time (ATIME register): %s\n", strerror(errno));
        return -1;
    }

    // Set gain (CONTROL)
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set gain (CONTROL register): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buffer, 8) != 8) {
        fprintf(stderr, "Error: Failed to read color data: %s\n", strerror(errno));
        return -1;
    }

    *clear = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];
    *red = (uint16_t)buffer[3] << 8 | (uint16_t)buffer[2];
    *green = (uint16_t)buffer[5] << 8 | (uint16_t)buffer[4];
    *blue = (uint16_t)buffer[7] << 8 | (uint16_t)buffer[6];

    return 0;
}

// Function to log color data to a CSV file
int log_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (color_log_file == NULL) {
        fprintf(stderr, "Error: Color log file is not open.\n");
        return -1;
    }

    fprintf(color_log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(color_log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open color log file
    color_log_file = fopen("color_log.csv", "a");
    if (color_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open color_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(color_log_file, 0, SEEK_END);
    long file_size = ftell(color_log_file);
    if (file_size == 0) {
        fprintf(color_log_file, "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n");
        fflush(color_log_file);
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;
    int read_attempts = 0;
    int consecutive_failures = 0;

    // Main loop
    while (!terminate) {
        // Read color data
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            // Log color data
            if (log_color_data(clear, red, green, blue) != 0) {
                fprintf(stderr, "Error: Failed to log color data.\n");
            }

            // Reset read attempts and consecutive failures
            read_attempts = 0;
            consecutive_failures = 0;
        } else {
            // Handle I2C read failure
            fprintf(stderr, "Warning: I2C read failed. Attempt %d\n", read_attempts + 1);
            if (errno == EIO) {
                read_attempts++;
                consecutive_failures++;
                if (consecutive_failures >= 3) {
                    fprintf(stderr, "Error: Too many consecutive I2C read failures. Exiting.\n");
                    break;
                }
            } else {
                read_attempts = 0; // Reset attempts if not EIO
                consecutive_failures = 0;
            }
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(color_log_file);
    gpioTerminate();

    return 0;
}

