#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define SENSITIVITY 0.1 // V/A
#define OFFSET 0.05    // V
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define MOTOR_PIN 17
#define LOG_FILE "current_log.csv"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
int log_current(float current);
int overcurrent_check(float current);
int shutdown_motor(int state);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd;
    unsigned int mode = SPI_MODE_0;
    unsigned int bits = 8;
    unsigned int speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// MCP3008 reading function
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to voltage conversion function
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 3.3;
}

// Voltage to current conversion function
float voltage_to_current(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Logging function
int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,current_in_Amperes\n");
    }

    fprintf(log_file, "%s,%.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Overcurrent check function
int overcurrent_check(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        return 1; // Overcurrent detected
    }
    return 0; // No overcurrent
}

// Motor shutdown function
int shutdown_motor(int state) {
    if (gpiod_line_set_value(motor_line, state) < 0) {
        perror("Error setting motor pin state");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (motor_line != NULL) {
        gpiod_line_release(motor_line);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    // Ensure motor is off on exit
    shutdown_motor(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        return 1;
    }

    motor_line = gpiod_chip_get_line(chip, MOTOR_PIN);
    if (motor_line == NULL) {
        perror("Error getting motor pin line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(motor_line, "motor_control", 0) < 0) {
        perror("Error requesting motor pin as output");
        gpiod_chip_close(chip);
        gpiod_line_release(motor_line);
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        gpiod_chip_close(chip);
        gpiod_line_release(motor_line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current
        if (log_current(current) < 0) {
            fprintf(stderr, "Error logging current\n");
        }

        // Check for overcurrent
        if (overcurrent_check(current)) {
            printf("Overcurrent detected! Shutting down motor.\n");
            if (shutdown_motor(0) < 0) {
                fprintf(stderr, "Error shutting down motor\n");
            }
            sleep(1); // Wait before attempting to re-enable
            if (shutdown_motor(1) < 0) {
                fprintf(stderr, "Error re-enabling motor\n");
            }
        }

        printf("Current: %.3f A\n", current);

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

