#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define LOG_FILE "pressure_log.csv"

int i2c_handle;
FILE *log_file;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read pressure from the MLX90817 sensor
float read_pressure() {
    int raw_pressure;
    int retries = 3; // Number of retries

    while (retries > 0) {
        raw_pressure = i2cReadWordData(i2c_handle, PRESSURE_REG);
        if (raw_pressure >= 0) {
            // Success, return the pressure value
            return (float)raw_pressure / 65535.0 * 500.0;
        } else {
            // Failure, print error message and retry
            fprintf(stderr, "Error reading pressure register: %d\n", raw_pressure);
            retries--;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }

    // If all retries failed, return a default value or handle the error appropriately
    fprintf(stderr, "Failed to read pressure after multiple retries.\n");
    return -1.0; // Indicate an error
}

// Function to log the pressure data to a file
void log_pressure(float pressure_kPa) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
        fflush(log_file); // Flush the buffer to ensure data is written to the file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

