#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0
#define SLEEP_DURATION 1 // seconds

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_ads1115();
int read_ads1115(int16_t *pressure, int16_t *temperature);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void control_led(float pressure);
void display_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure ADS1115
int configure_ads1115() {
    // Configuration register: Single-shot mode, AIN0/AIN1, +/-6.144V, 128 SPS, Continuous conversion disabled
    uint16_t config_value = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;       // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *pressure, int16_t *temperature) {
    char buf[1];
    char read_buf[2];
    int result;

    // Start conversion
    buf[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to start conversion: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read pressure data
    buf[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 convert register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }

    *pressure = (read_buf[0] << 8) | read_buf[1];

    // Read temperature data
    buf[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 convert register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    *temperature = (read_buf[0] << 8) | read_buf[1];

    return 0;
}

// Convert raw pressure data to kPa
float convert_pressure(int16_t raw_pressure) {
    // Assuming a linear transfer function: 0V = 0 kPa, 5V = 400 kPa
    // and the ADC range is 0-5V (FSR = 6.144V)
    float pressure = (float)raw_pressure * 6.144 / 32767.0 * 400.0; // Scale factor for 16-bit ADC
    return pressure;
}

// Convert raw temperature data to Celsius
float convert_temperature(int16_t raw_temperature) {
    // Simplified linear NTC approximation: 1V = 0°C, 2V = 100°C
    float temperature = (float)raw_temperature * 100.0 / 32767.0; // Scale factor for 16-bit ADC
    return temperature;
}

// Control the warning LED
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // HIGH
    } else {
        gpioWrite(LED_GPIO, 0); // LOW
    }
}

// Display sensor data
void display_data(sensor_data_t data) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", data.pressure, data.temperature);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    int16_t raw_pressure, raw_temperature;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_ads1115(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            sensor_data.pressure = convert_pressure(raw_pressure);
            sensor_data.temperature = convert_temperature(raw_temperature);

            // Display data
            display_data(sensor_data);

            // Control LED
            control_led(sensor_data.pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_DURATION * 1000000); // Convert seconds to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

