#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MOTOR_PIN 27
#define SPI_CE0 8
#define SPI_CE1 11
#define SPI_MOSI 10
#define SPI_MISO 9

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define ADC channel
#define ADC_CHANNEL 0

// Define current limits
#define OVERCURRENT_THRESHOLD 10.0

// Define zero current voltage
#define ZERO_CURRENT_VOLTAGE 1.65

// Define sensitivity (mV/A)
#define SENSITIVITY 66.0

// Define full-scale voltage
#define FULL_SCALE_VOLTAGE 3.3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_data(float current);
void safety_monitor(float current);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int motor_pin;
    int spi_ce0_pin;
    int spi_ce1_pin;
    int spi_mosi_pin;
    int spi_miso_pin;
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float zero_current_voltage;
    float sensitivity;
    float full_scale_voltage;
    float overcurrent_threshold;
} Config;

Config config = {
    MOTOR_PIN, SPI_CE0, SPI_CE1, SPI_MOSI, SPI_MISO, SPI_CHANNEL, SPI_SPEED, ADC_CHANNEL, ZERO_CURRENT_VOLTAGE, SENSITIVITY, FULL_SCALE_VOLTAGE, OVERCURRENT_THRESHOLD
};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log data
        log_data(current);

        // Safety monitor
        safety_monitor(current);

        // Delay
        gpioDelay(100); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.full_scale_voltage;
}

// Convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - config.zero_current_voltage) / (config.sensitivity / 1000.0);
}

// Log data to file
void log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

