#define SPI_MOSI 10

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define sensor parameters
#define VREF 3.3 // Reference voltage
#define ADC_RESOLUTION 1024 // 10-bit ADC

// Define alarm threshold
#define ALARM_THRESHOLD 1000.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_ppm(int adc_value);
void log_data(float ppm);
void handle_alarm(float ppm);
void signal_handler(int signal);

