        // Handle alarm
        handle_alarm(ppm);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

