    // 0x01: Configuration register address
    // 0x4003: Single-ended AIN0, +/-4.096V, Continuous conversion
    uint16_t config = 0x4003; //0x4003; // Single-ended AIN0, +/-4.096V, Continuous conversion

    // Write the configuration to the ADS1115
    int result = i2cWriteWordData(handle, 0x01, config);
    if (result < 0) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }

    return 0;
}

