#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel for humidity
#define MCP3008_CHANNEL_2 1 // ADC channel for thermistor
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define EMAIL_SUBJECT "Humidity Alert"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate relative humidity
float calculate_humidity(int adc_value) {
    // Convert ADC value to voltage (assuming 5V reference)
    float voltage = (float)adc_value / 1023.0 * 5.0;

    // Use the HIH-4602-A transfer function
    float humidity = (voltage - 0.824) / 0.0315;

    // Clamp humidity to 0-100%
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;

    return humidity;
}

// Function to calculate temperature
float calculate_temperature(int adc_value) {
    // Convert ADC value to voltage (assuming 5V reference)
    float voltage = (float)adc_value / 1023.0 * 5.0;

    // Use the Beta parameter equation for thermistor
    // This is a simplified equation.  A more accurate equation would require
    // the Beta value and the thermistor's resistance at a known temperature.
    // This example assumes a linear relationship for demonstration purposes.
    float temperature = (voltage - 0.5) / 0.002; // Example equation

    // Clamp temperature to -40 to 125 degrees Celsius
    if (temperature < -40.0) temperature = -40.0;
    if (temperature > 125.0) temperature = 125.0;

    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char email_body[256];
    snprintf(email_body, sizeof(email_body), "Humidity alert: Humidity is %.2f%% at %s", humidity, timestamp);

    char command[512];
    snprintf(command, sizeof(command), "ssmtp %s <<< '%s'", EMAIL_RECIPIENT, email_body);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Failed to execute ssmtp command\n");
    } else {
        printf("Email alert sent: %s\n", email_body);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_humidity = read_mcp3008(MCP3008_CHANNEL);
        int adc_thermistor = read_mcp3008(MCP3008_CHANNEL_2);

        if (adc_humidity == -1 || adc_thermistor == -1) {
            fprintf(stderr, "Failed to read ADC values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        float humidity = calculate_humidity(adc_humidity);
        float temperature = calculate_temperature(adc_thermistor);

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);
        sleep(5);
    }

    cleanup();
    return 0;
}

