#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for SPI communication
#define SPI_CE0 8
#define SPI_MOSI 10
#define SPI_SCLK 11
#define SPI_MISO 9

// Define SPI parameters
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz

// Define VREF
#define VREF 3.3

// Define TMP36 temperature range
#define MIN_TEMP -40.0
#define MAX_TEMP 125.0

// Define log file name
#define LOG_FILE "temperature_log.csv"

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3208(int channel);
float convert_to_voltage(int adc_value);
float convert_to_celsius(float voltage);
int log_temperature(float temperature_celsius);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize SPI
int initialize_spi() {
    // Open SPI device
    spi_fd = spiOpen(0, SPI_MODE, SPI_BITS_PER_WORD);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_fd);
        return -1;
    }

    // Configure CS pin as output
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioWrite(SPI_CE0, 1); // Initially high (inactive)

    return 0;
}

// Function to read from MCP3208
int read_mcp3208(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Activate CS
    gpioWrite(SPI_CE0, 0);

    // Transfer data
    if (spiXfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        gpioWrite(SPI_CE0, 1); // Deactivate CS on error
        return -1;
    }

    // Deactivate CS
    gpioWrite(SPI_CE0, 1);

    // Extract ADC value
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 4095.0) * VREF;
}

// Function to convert voltage to Celsius
float convert_to_celsius(float voltage) {
    return (voltage - 0.5) / 0.01;
}

// Function to log temperature to file
int log_temperature(float temperature_celsius) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature_celsius);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

