    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3208(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = convert_to_voltage(adc_value);

        // Convert voltage to Celsius
        float temperature_celsius = convert_to_celsius(voltage);

        // Validate temperature
        if (temperature_celsius < MIN_TEMP || temperature_celsius > MAX_TEMP) {
            fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature_celsius);
            continue; // Skip to the next iteration
        }

        // Log temperature
        if (log_temperature(temperature_celsius) != 0) {
            fprintf(stderr, "Error logging temperature\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // Close SPI device
    spiClose(spi_fd);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

