#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_GPIO 8
#define NUM_CHANNELS 3
#define SAMPLE_RATE 100 // Hz
#define IMPACT_THRESHOLD 2.0 // g
#define V_SUPPLY 3.3 // Volts
#define V_ZERO 1.65 // Volts
#define SENSITIVITY 0.3 // mV/g
#define ADC_RESOLUTION 1024.0 // 10-bit ADC

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
accelerometer_data_t read_accelerometer_data();
float calculate_acceleration_magnitude(int x, int y, int z);
void log_data(accelerometer_data_t data, float magnitude);
void impact_detected(float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_GPIO, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_GPIO, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Read accelerometer data from all channels
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    data.x = read_mcp3008(0);
    data.y = read_mcp3008(1);
    data.z = read_mcp3008(2);
    return data;
}

// Calculate acceleration magnitude in g
float calculate_acceleration_magnitude(int x, int y, int z) {
    float x_voltage = (x / ADC_RESOLUTION) * V_SUPPLY;
    float y_voltage = (y / ADC_RESOLUTION) * V_SUPPLY;
    float z_voltage = (z / ADC_RESOLUTION) * V_SUPPLY;

    float x_g = (x_voltage - V_ZERO) / SENSITIVITY;
    float y_g = (y_voltage - V_ZERO) / SENSITIVITY;
    float z_g = (z_voltage - V_ZERO) / SENSITIVITY;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log data to file
void log_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Impact detection
void impact_detected(float magnitude) {
    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "IMPACT DETECTED: %.3f g\n", magnitude);
        fflush(log_file);
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure CS GPIO as output
    gpioSetMode(CS_GPIO, PI_OUTPUT);
    gpioWrite(CS_GPIO, 1); // Deselect MCP3008 initially

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_acceleration_magnitude(data.x, data.y, data.z);
        log_data(data, magnitude);
        impact_detected(magnitude);
        gpioDelay(1000000 / SAMPLE_RATE); // Delay for 10ms (100Hz)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

