int read_si1172_data(int *ir, int *red);
float convert_to_bpm(int ir);
float convert_to_spo2(int red);
int log_data(float bpm, float spo2, int error_flag);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize Si1172 sensor
int init_si1172() {
    // Configure Si1172 for continuous mode, 100ms measurement rate
    if (i2cWriteByteData(i2c_handle, SI1172_REG_MEAS_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error writing to SI1172_REG_MEAS_RATE: %s\n", strerror(errno));
        return -1;
    }

    // Configure IR ADC gain
    if (i2cWriteByteData(i2c_handle, SI1172_REG_ALS_IR_ADC_GAIN, 0x7B) < 0) {
        fprintf(stderr, "Error writing to SI1172_REG_ALS_IR_ADC_GAIN: %s\n", strerror(errno));
        return -1;
    }

    // Configure RED ADC gain
    if (i2cWriteByteData(i2c_handle, SI1172_REG_ALS_RED_ADC_GAIN, 0x7B) < 0) {
        fprintf(stderr, "Error writing to SI1172_REG_ALS_RED_ADC_GAIN: %s\n", strerror(errno));
        return -1;
    }

    // Configure FIFO
    if (i2cWriteByteData(i2c_handle, SI1172_REG_FIFO_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Error writing to SI1172_REG_FIFO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read data from Si1172 sensor
int read_si1172_data(int *ir, int *red) {
    int result;

    result = i2cReadWordData(i2c_handle, SI1172_REG_FIFO_DATA);
    if (result < 0) {
        fprintf(stderr, "Error reading from SI1172_REG_FIFO_DATA: %s\n", strerror(errno));
        return -1;
    }

    *ir = result;

    result = i2cReadWordData(i2c_handle, SI1172_REG_FIFO_DATA + 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from SI1172_REG_FIFO_DATA + 2: %s\n", strerror(errno));
        return -1;
    }

    *red = result;

    return 0;
}

// Convert raw IR data to BPM (placeholder)
float convert_to_bpm(int ir) {
    // Replace with actual conversion formula from Si1172 datasheet
    return (float)ir * 0.5; // Example: linear conversion
}

// Convert raw RED data to SpO2 (%) (placeholder)
float convert_to_spo2(int red) {
    // Replace with actual conversion formula from Si1172 datasheet
    return (float)red * 0.8; // Example: linear conversion
}

// Log data to CSV file
int log_data(float bpm, float spo2, int error_flag) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, bpm, spo2, error_flag);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int ir, red;
    float bpm, spo2;
    int error_flag = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize Si1172 sensor
    if (init_si1172() < 0) {
        fprintf(stderr, "Si1172 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error Flag\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from Si1172
        if (read_si1172_data(&ir, &red) == 0) {
            // Convert data to BPM and SpO2
            bpm = convert_to_bpm(ir);
            spo2 = convert_to_spo2(red);

            // Log data
            log_data(bpm, spo2, error_flag);
        } else {
            error_flag = 1;
            log_data(0.0, 0.0, error_flag);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

