#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SAMPLE_RATE 16000
#define NUM_CHANNELS 2
#define NUM_SAMPLES 1024
#define GAIN 100 // Command-line argument for gain

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    int sample_rate;
    int num_channels;
    int num_samples;
    int gain;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int baud);
int read_mcp3008(int channel);
void signal_handler(int signal);
void cleanup();
void print_usage(const char *program_name);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // SPI_MODE_0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

// Print usage instructions
void print_usage(const char *program_name) {
    fprintf(stderr, "Usage: %s [optional_gain]\n", program_name);
    fprintf(stderr, "  -g <gain>  : Set the gain (default: 100)\n");
    fprintf(stderr, "  -h          : Show this help message\n");
}

int main(int argc, char *argv[]) {
    Config config;

    // Set default values
    config.spi_channel = SPI_CHANNEL;
    config.spi_baud = SPI_BAUD;
    config.sample_rate = SAMPLE_RATE;
    config.num_channels = NUM_CHANNELS;
    config.num_samples = NUM_SAMPLES;
    config.gain = GAIN;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "g:h")) != -1) {
        switch (opt) {
            case 'g':
                config.gain = atoi(optarg);
                break;
            case 'h':
                print_usage(argv[0]);
                return 0;
            default:
                print_usage(argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(config.spi_channel, config.spi_baud);
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio sampling started. Gain: %d\n", config.gain);

    // Main loop
    while (!terminate) {
        // Read audio data from both microphones
        int mic1_value = read_mcp3008(0);
        int mic2_value = read_mcp3008(1);

        if (mic1_value < 0 || mic2_value < 0) {
            fprintf(stderr, "Error reading from MCP3008\n");
            break;
        }

        // Apply gain (simple multiplication)
        int mic1_gain = mic1_value * config.gain;
        int mic2_gain = mic2_value * config.gain;

        // Subtract the two audio streams
        int noise_canceled_value = mic1_gain - mic2_gain;

        // Output the result to the terminal in CSV format
        printf("%d,%d\n", noise_canceled_value, noise_canceled_value);

        // Delay to control sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

