#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define TEMP_FILE "ambient_temp.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
static int spi_handle = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int spi_handle, unsigned char *tx_buf, unsigned char *rx_buf, int len);
float read_temperature(const char *filename);
float compensate_voltage(float voltage, float temperature);
int read_flame_sensor(int spi_handle);
int log_data(FILE *log_file, float raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int gpio_pin, int state);
void signal_handler(int signal);
int initialize_gpio(void);
int initialize_spi(void);
int initialize_logging(void);
void cleanup(void);

// SPI transfer function
int spi_transfer(int spi_handle, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int status = spiXfer(spi_handle, tx_buf, rx_buf, len);
    if (status != len) {
        fprintf(stderr, "SPI transfer failed: %d\n", status);
        return -1;
    }
    return 0;
}

// Read temperature from file
float read_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", filename);
        return 25.0; // Default temperature
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return 25.0; // Default temperature
    }

    fclose(fp);
    return temperature;
}

// Compensate voltage
float compensate_voltage(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

// Read flame sensor
int read_flame_sensor(int spi_handle) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;
    int retries = 0;

    // MCP3008 configuration: start bit, single-ended mode, channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Dummy byte

    while (retries < MAX_RETRIES) {
        if (spi_transfer(spi_handle, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Log data to file
int log_data(FILE *log_file, float raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.0f,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control buzzer
void control_buzzer(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially
    return 0;
}

// Initialize SPI
int initialize_spi(void) {
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize logging
int initialize_logging(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_chip != NULL) {
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(gpio_chip);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Open GPIO chip and get buzzer line
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        cleanup();
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(buzzer_line, &config, 0) != 0) {
        fprintf(stderr, "Error requesting GPIO line\n");
        cleanup();
        return 1;
    }

    float temperature = read_temperature(TEMP_FILE);
    float voltage, compensated_voltage;
    int flame_detected;

    while (!terminate) {
        int raw_adc = read_flame_sensor(spi_handle);
        if (raw_adc < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping iteration\n");
            control_buzzer(BUZZER_GPIO, 0); // Turn off buzzer
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500ms
            continue;
        }

        voltage = (float)raw_adc / 1023.0 * 3.3; // Assuming 3.3V reference
        compensated_voltage = compensate_voltage(voltage, temperature);
        flame_detected = (compensated_voltage > 1.0) ? 1 : 0;

        log_data(log_file, (float)raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        control_buzzer(BUZZER_GPIO, flame_detected);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

