#include <pigpio.h>

// Define GPIO pins
#define SPI_CE0 8
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define water level thresholds
#define WATER_LEVEL_HIGH_THRESHOLD 75.0
#define WATER_LEVEL_LOW_THRESHOLD 70.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_data(float percentage);
void control_led(float percentage);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x80 | (channel << 4)) & 0xFF; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to JSON file
void log_data(float percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

