#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define VREF 3.3         // Reference voltage
#define AWM7300V_MAX 25.0 // Maximum output voltage (AWM7300V)
#define AWM7300V_MIN 0.0  // Minimum output voltage (AWM7300V)
#define AWM7300V_MAX_LPM 100.0 // Maximum flow rate (LPM)
#define AWM7300V_MIN_LPM 0.0  // Minimum flow rate (LPM)
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_baud;
    float vref;
    float awm7300v_max;
    float awm7300v_min;
    float awm7300v_max_lpm;
    float awm7300v_min_lpm;
    int sample_interval_ms;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int baud);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_flow_rate(float voltage, float awm7300v_max, float awm7300v_min, float awm7300v_max_lpm, float awm7300v_min_lpm);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // SPI_MODE_0
    if (handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Convert voltage to flow rate (LPM)
float voltage_to_flow_rate(float voltage, float awm7300v_max, float awm7300v_min, float awm7300v_max_lpm, float awm7300v_min_lpm) {
    float flow_rate = (voltage - awm7300v_min) / (awm7300v_max - awm7300v_min) * (awm7300v_max_lpm - awm7300v_min_lpm) + awm7300v_min;
    return flow_rate;
}

// Log data to file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_baud = SPI_BAUD,
        .vref = VREF,
        .awm7300v_max = AWM7300V_MAX,
        .awm7300v_min = AWM7300V_MIN,
        .awm7300v_max_lpm = AWM7300V_MAX_LPM,
        .awm7300v_min_lpm = AWM7300V_MIN_LPM,
        .sample_interval_ms = SAMPLE_INTERVAL_MS
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(config.spi_channel, config.spi_baud);
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlowRate (LPM)\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, config.vref);

        // Convert voltage to flow rate
        float flow_rate = voltage_to_flow_rate(voltage, config.awm7300v_max, config.awm7300v_min, config.awm7300v_max_lpm, config.awm7300v_min_lpm);

        // Log data
        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

