#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    float moisture_threshold;
    int logging_frequency;
    char email_recipient[256];
    char msmtp_config[256];
} Config;

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
int initialize_spi(int channel);
int read_adc(int channel);
float calculate_moisture(int raw_value, int min_raw, int max_raw);
void log_data(float moisture_percent);
void send_email_alert(float moisture_percent);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *name = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (name == NULL || value == NULL) continue;

        if (strcmp(name, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(name, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(name, "min_raw") == 0) {
            config->min_raw = atoi(value);
        } else if (strcmp(name, "max_raw") == 0) {
            config->max_raw = atoi(value);
        } else if (strcmp(name, "moisture_threshold") == 0) {
            config->moisture_threshold = atof(value);
        } else if (strcmp(name, "logging_frequency") == 0) {
            config->logging_frequency = atoi(value);
        } else if (strcmp(name, "email_recipient") == 0) {
            strncpy(config->email_recipient, value, sizeof(config->email_recipient) - 1);
            config->email_recipient[sizeof(config->email_recipient) - 1] = '\0';
        } else if (strcmp(name, "msmtprc") == 0) {
            strncpy(config->msmtprc, value, sizeof(config->msmtprc) - 1);
            config->msmtprc[sizeof(config->msmtprc) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize SPI
int initialize_spi(int channel) {
    int handle = spiOpen(channel, 500000, 0); // CE0, 500kHz, mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (min_raw == max_raw) {
        return 0.0; // Avoid division by zero
    }
    return 100.0 * (raw_value - min_raw) / (max_raw - min_raw);
}

// Function to log data to file
void log_data(float moisture_percent) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percent);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float moisture_percent) {
    char command[512];
    snprintf(command, sizeof(command), "echo \"Moisture level is below threshold: %.2f%%\" | msmtp -t %s", moisture_percent, config.msmtp_config);

    FILE *pipe = popen(command, "r");
    if (pipe == NULL) {
        perror("Error sending email");
        return;
    }

    int status = pclose(pipe);
    if (status != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", status);
