#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <pthread.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_SENSORS 4
#define CSV_FILE "environmental_data.csv"

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *csv_file = NULL;
static pthread_mutex_t csv_mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure to hold sensor data
typedef struct {
    int channel;
    float voltage;
} sensor_data_t;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
float adc_to_voltage(int adc_value, float vref);
void log_data(FILE *fp, time_t timestamp, sensor_data_t data[NUM_SENSORS]);
void signal_handler(int sig);
void cleanup();
void *sensor_thread(void *arg);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC to voltage conversion function
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Data logging function
void log_data(FILE *fp, time_t timestamp, sensor_data_t data[NUM_SENSORS]) {
    pthread_mutex_lock(&csv_mutex);
    fprintf(fp, "%ld", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(fp, ",%.3f", data[i].voltage);
    }
    fprintf(fp, "\n");
    fflush(fp);
    pthread_mutex_unlock(&csv_mutex);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, exiting...\n");
    keep_running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (chip != NULL) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
    }

    pthread_mutex_destroy(&csv_mutex);
}

// Sensor thread function
void *sensor_thread(void *arg) {
    int channels[NUM_SENSORS] = {0, 1, 2, 3};
    int i;
    time_t timestamp;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1; // 1 second
    sleep_time.tv_nsec = 0;

    while (keep_running) {
        for (i = 0; i < NUM_SENSORS; i++) {
            int adc_value = 0;
            uint8_t tx_buf[3] = {0x01, (0x80 | channels[i]), 0x00};
            uint8_t rx_buf[3] = {0};

            if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == 0) {
                adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
                timestamp = time(NULL);
                float voltage = adc_to_voltage(adc_value, VREF);
                sensor_data_t data;
                data.channel = channels[i];
                data.voltage = voltage;
                log_data(csv_file, timestamp, data);
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }
        nanosleep(&sleep_time, NULL);
    }

    pthread_exit(NULL);
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO for chip select
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    gpiod_line_request_output(cs_line, "sensor_data", 0);

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp");
        for (int i = 0; i < NUM_SENSORS; i++) {
            fprintf(csv_file, ",Sensor%d", i);
        }
        fprintf(csv_file, "\n");
    }

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        perror("Error creating sensor thread");
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        sleep(1);
    }

    // Wait for sensor thread to finish
    pthread_join(sensor_thread_id, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

