#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PUMP_GPIO 17
#define SPI_CE0 8 // Chip Enable 0 (GPIO8)

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define moisture thresholds
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600

// Define circular buffer size
#define BUFFER_SIZE 20

// Define timer interval (seconds)
#define TIMER_INTERVAL 5

// Structure to hold log data
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int read_moisture_level();
void control_pump(int moisture_level);
void log_data(int moisture_level, int pump_state);
void signal_handler(int signal);

// Function to read moisture level from MCP3008
int read_moisture_level() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // MCP3008 command to read channel 0 (single-ended)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        log_data(moisture_level, 1); // Log pump ON
    } else if (moisture_level > HIGH_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        log_data(moisture_level, 0); // Log pump OFF
