#include <string.h>
#include <unistd.h>

// MAX30102 I2C address
#define MAX30102_I2C_ADDR 0x57

// MAX30102 register addresses
#define MAX30102_PART_ID_ADDR 0xFF
#define MAX30102_MODE_CONFIG_ADDR 0x06
#define MAX30102_SPO2_CONFIG_ADDR 0x08
#define MAX30102_LED1_PA_ADDR 0x09
#define MAX30102_LED2_PA_ADDR 0x0A
#define MAX30102_FIFO_DATA_ADDR 0x07

// FIFO data size
#define FIFO_DATA_SIZE 6

// SpO2 and Heart Rate thresholds
#define SPO2_THRESHOLD 95.0
#define HR_THRESHOLD 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold SpO2 and Heart Rate data
typedef struct {
    float spo2;
    int heart_rate;
} HealthData;

// Function prototypes
int init_max30102();
int read_max30102_data(int *red, int *ir);
float calculate_spo2(int red, int ir);
int detect_heart_rate(int *ir_data, int data_size);
void log_health_data(float spo2, int heart_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the MAX30102 sensor
int init_max30102() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, MAX30102_MODE_CONFIG_ADDR, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Clear interrupts
    if (i2cWriteByteData(i2c_handle, 0x04, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupts\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, MAX30102_MODE_CONFIG_ADDR, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure SpO2 mode\n");
        return -1;
    }

    // Configure SPO2_CONFIG
    if (i2cWriteByteData(i2c_handle, MAX30102_SPO2_CONFIG_ADDR, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to configure SPO2_CONFIG\n");
        return -1;
    }

    // Configure LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, MAX30102_LED1_PA_ADDR, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to configure LED1_PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MAX30102_LED2_PA_ADDR, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to configure LED2_PA\n");
        return -1;
    }

    return 0;
}

// Read data from the MAX30102 FIFO
int read_max30102_data(int *red, int *ir) {
    char data[FIFO_DATA_SIZE];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, MAX30102_FIFO_DATA_ADDR, data, FIFO_DATA_SIZE);

    if (bytes_read != FIFO_DATA_SIZE) {
        fprintf(stderr, "Error: Failed to read FIFO data (%d bytes read, expected %d)\n", bytes_read, FIFO_DATA_SIZE);
        return -1;
    }

    // Extract red and IR data from the buffer
    *red = (data[0] << 16) | (data[1] << 8) | data[2];
    *ir = (data[3] << 16) | (data[4] << 8) | data[5];

    return 0;
}

// Calculate SpO2 using the ratio-of-ratios method
float calculate_spo2(int red, int ir) {
    // Simplified SpO2 calculation (replace with actual MAX30102 formula)
    float ratio = (float)red / (float)ir;
    float spo2 = 100.0 - (ratio - 1.0) * 100.0; // Example calculation
    if (spo2 < 0.0) spo2 = 0.0;
    if (spo2 > 100.0) spo2 = 100.0;
    return spo2;
}

// Detect heart rate from the IR signal
int detect_heart_rate(int *ir_data, int data_size) {
    // Simple peak detection algorithm
    int peaks = 0;
    int peak_index = 0;
    int current_index = 0;
    int rising = 0;
    int falling = 0;
    int last_ir = ir_data[0];

    for (int i = 1; i < data_size - 1; i++) {
        int diff = ir_data[i] - ir_data[i - 1];

        if (diff > 0 && rising == 0) {
            rising = 1;
            peak_index = i;
        }

        if (diff < 0 && falling == 0) {
            falling = 1;
            if (rising && falling) {
                peaks++;
                current_index = i;
            }
        }

        if (rising && falling) {
            if (ir_data[i] > last_ir) {
                rising = 1;
                falling = 0;
            } else {
                falling = 1;
                rising = 0;
            }
            last_ir = ir_data[i];
        }
    }

    // Calculate heart rate (adjust based on peak detection)
    if (peaks > 0) {
        return peaks * 60; // Beats per minute
    } else {
        return 0; // No peaks detected
    }
}

// Log health data to file
void log_health_data(float spo2, int heart_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, spo2, heart_rate);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MAX30102_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int part_id = i2cReadByteData(i2c_handle, MAX30102_PART_ID_ADDR);
    if (part_id != 0x15) {
        fprintf(stderr, "Error: MAX30102 not found (Part ID: 0x%02X)\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_max30102() < 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, ir;
    float spo2;
    int heart_rate;

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_max30102_data(&red, &ir) == 0) {
            // Calculate SpO2
            spo2 = calculate_spo2(red, ir);

            // Detect heart rate
            heart_rate = detect_heart_rate((int *)ir, FIFO_DATA_SIZE);

            // Log health data
            log_health_data(spo2, heart_rate);

            // Print SpO2 and Heart Rate to console
            printf("SpO2: %.2f%%, Heart Rate: %d BPM\n", spo2, heart_rate);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

