#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define CSV_FILE "analog_log.csv"

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value, float vref);
void log_data(int channel, float voltage);
void signal_handler(int signal);
int spi_transfer(spi_config_t config);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid channel number: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    int result = spi_transfer({SPI_CHANNEL, SPI_SPEED});
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0) * vref;
}

// Function to log data to CSV file
void log_data(int channel, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(csv_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(csv_file); // Ensure data is written to file immediately
}

// Function to perform SPI transfer
int spi_transfer(spi_config_t config) {
