        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// ADS1115 initialization function
int ads1115_init(int fd) {
    // Configure ADS1115 for single-ended A0 input, 4.096V range, 128 SPS, single-shot mode
    unsigned char config[3];
    config[0] = ADS1115_REG_CONFIG_BASE; // Configuration register address
    config[1] = 0xC2; // Single-shot mode, A0 single-ended, 4.096V, 128 SPS
    config[2] = 0x83; // Start single conversion

    if (i2c_write_reg(fd, config[1], config[2]) != 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }
    return 0;
}

// Read distance from ADS1115 function
int read_distance(int fd) {
    unsigned char data[2];
    unsigned char config[3];

    // Start a single conversion
    config[0] = ADS1115_REG_CONFIG_BASE; // Configuration register address
    config[1] = 0x40; // Configuration register
    config[2] = 0x83; // Start single conversion

    if (i2c_write_reg(fd, config[1], config[2]) != 0) {
        fprintf(stderr, "Failed to start conversion\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    config[0] = ADS1115_REG_CONVERT_BASE; // Conversion register address
    config[1] = 0x00; // Conversion register

    if (i2c_write_reg(fd, config[1], config[1]) != 0) {
        fprintf(stderr, "Failed to select conversion register\n");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data\n");
        return -1;
    }

    // Combine the two bytes to get the 16-bit distance value
    int distance = (data[0] << 8) | data[1];
    return distance;
}

// Calculate average distance
float calculate_average_distance(int *samples, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    return sum / num_samples;
}

// Calculate threshold
float calculate_threshold(float average_distance) {
    return average_distance * THRESHOLD_PERCENTAGE / 100.0;
}

// Control relay function
void control_relay(int gpio, int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        fprintf(stderr, "Failed to set relay state\n");
    }
}

// Read reed sensor function
int read_reed_sensor(int gpio) {
    return gpiod_line_get_value(reed_sensor_line);
}

// Log event function
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// gpiod_line_request_output function
int gpiod_line_request_output(int chip, int line, const char *consumer, int flags) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = consumer;
    config.flags = flags;

    struct gpiod_line *line = gpiod_chip_get_line(chip, line);
    if (!line) {
        fprintf(stderr, "Failed to get line %d from chip %d\n", line, chip);
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request line %d\n", line);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize libgpiod
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO lines
    if (gpiod_line_request_output(gpio_chip, RELAY_GPIO, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay GPIO\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(gpio_chip, REED_SENSOR_GPIO, "reed_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request reed sensor GPIO\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Baseline sampling
    int baseline_samples[NUM_SAMPLES];
    for (int i = 0; i < NUM_SAMPLES; i++) {
        baseline_samples[i] = read_distance(i2c_fd);
        if (baseline_samples[i] < 0) {
            fprintf(stderr, "Failed to read baseline sample %d\n", i);
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // 50ms
    }

    float average_baseline_distance = calculate_average_distance(baseline_samples, NUM_SAMPLES);
    float threshold_distance = calculate_threshold(average_baseline_distance);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        float current_average_distance = calculate_average_distance(baseline_samples, NUM_SAMPLES);
        float current_threshold_distance = calculate_threshold(current_average_distance);

        if (distance < current_threshold_distance) {
            fprintf(stderr, "Distance below threshold, activating relay\n");
            control_relay(RELAY_GPIO, 1); // Activate relay
            usleep(RELAY_ENERGY_TIME_S * 1000000); // 3 seconds
            control_relay(RELAY_GPIO, 0); // Deactivate relay
            int reed_state = read_reed_sensor(REED_SENSOR_GPIO);
            log_event(reed_state ? "door opened" : "door not opened");
        }

        usleep(POLL_INTERVAL_MS * 1000); // 200ms
    }

    // Cleanup
    control_relay(RELAY_GPIO, 0); // Deactivate relay
    gpiod_line_release(reed_sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

