#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for chip select lines
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define chip select chip numbers
#define CHIP0 0
#define CHIP1 1
#define CHIP2 2

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Global variables for chip select lines
struct gpiod_line *cs0_line = NULL;
struct gpiod_line *cs1_line = NULL;
struct gpiod_line *cs2_line = NULL;

// Global variable for SPI file descriptor
int spi_fd = -1;

// Function prototypes
int spi_init(const char *device, uint8_t mode);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int chip, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void cleanup();
void signal_handler(int sig);

// Function to initialize SPI
int spi_init(const char *device, uint8_t mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_val = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to transfer data over SPI
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int chip, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int adc_value;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Select the chip
    if (chip == CHIP0) {
        if (gpiod_line_request_output(cs0_line, "soil_sensor", 0) < 0) {
            fprintf(stderr, "Error requesting CS0 line: %s\n", strerror(errno));
            return -1;
        }
        if (gpiod_line_set_value(cs0_line, 0) < 0) {
            fprintf(stderr, "Error setting CS0 line: %s\n", strerror(errno));
            return -1;
        }
    } else if (chip == CHIP1) {
        if (gpiod_line_request_output(cs1_line, "soil_sensor", 0) < 0) {
            fprintf(stderr, "Error requesting CS1 line: %s\n", strerror(errno));
            return -1;
        }
        if (gpiod_line_set_value(cs1_line, 0) < 0) {
            fprintf(stderr, "Error setting CS1 line: %s\n", strerror(errno));
            return -1;
        }
    } else if (chip == CHIP2) {
        if (gpiod_line_request_output(cs2_line, "soil_sensor", 0) < 0) {
            fprintf(stderr, "Error requesting CS2 line: %s\n", strerror(errno));
            return -1;
        }
        if (gpiod_line_set_value(cs2_line, 0) < 0) {
            fprintf(stderr, "Error setting CS2 line: %s\n", strerror(errno));
            return -1;
        }
    }

    // Perform SPI transfer
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during SPI transfer for chip %d\n", chip);
        return -1;
    }

    // Deselect the chip
    if (chip == CHIP0) {
        if (gpiod_line_release(cs0_line) < 0) {
            fprintf(stderr, "Error releasing CS0 line: %s\n", strerror(errno));
            return -1;
        }
    } else if (chip == CHIP1) {
        if (gpiod_line_release(cs1_line) < 0) {
            fprintf(stderr, "Error releasing CS1 line: %s\n", strerror(errno));
            return -1;
        }
    } else if (chip == CHIP2) {
        if (gpiod_line_release(cs2_line) < 0) {
            fprintf(stderr, "Error releasing CS2 line: %s\n", strerror(errno));
            return -1;
        }
    }

    // Extract ADC value
    adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }

    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release chip select lines
    if (cs0_line) {
        gpiod_line_release(cs0_line);
    }
    if (cs1_line) {
        gpiod_line_release(cs1_line);
    }
    if (cs2_line) {
        gpiod_line_release(cs2_line);
    }

    printf("Cleanup complete.\n");
}

int main() {
    FILE *fp;
    int sensor1, sensor2, sensor3;
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;  // 5 seconds
    sleep_time.tv_nsec = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get chip lines
    cs0_line = gpiod_chip_get_line(chip, CS0_PIN);
    cs1_line = gpiod_chip_get_line(chip, CS1_PIN);
    cs2_line = gpiod_chip_get_line(chip, CS2_PIN);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request chip select lines as output
    if (gpiod_line_request_output(cs0_line, "soil_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting CS0 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }
    if (gpiod_line_request_output(cs1_line, "soil_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting CS1 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }
    if (gpiod_line_request_output(cs2_line, "soil_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting CS2 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }

    // Open CSV file for appending
    fp = fopen("soil_moisture_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(fp);

    // Main loop
    while (1) {
        // Read sensor values
        sensor1 = read_mcp3008(CHIP0, 0);
        sensor2 = read_mcp3008(CHIP1, 0);
        sensor3 = read_mcp3008(CHIP2, 0);

        // Log data
        if (log_data(fp, sensor1, sensor2, sensor3) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

