    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get chip lines
    cs0_line = gpiod_chip_get_line(chip, CS0_PIN);
    cs1_line = gpiod_chip_get_line(chip, CS1_PIN);
    cs2_line = gpiod_chip_get_line(chip, CS2_PIN);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request chip select lines as output
    if (gpiod_line_request_output(cs0_line, "soil_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting CS0 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }
    if (gpiod_line_request_output(cs1_line, "soil_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting CS1 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }
    if (gpiod_line_request_output(cs2_line, "soil_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting CS2 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpiod_chip_close(chip);
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        return 1;
    }

    // Open CSV file for appending
    fp = fopen("soil_moisture_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(fp);

    // Main loop
    while (1) {
        // Read sensor values
        sensor1 = read_mcp3008(CHIP0, 0);
        sensor2 = read_mcp3008(CHIP1, 0);
        sensor3 = read_mcp3008(CHIP2, 0);

        // Log data
        if (log_data(fp, sensor1, sensor2, sensor3) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

