#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define NUM_SENSORS 3
#define NUM_SENSORS_CHANNELS 3
#define MAX_RETRIES 3
#define MAX_RETRIES_DELAY 10 // seconds

// Moisture thresholds and durations
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10.0
#define DEFAULT_SLEEP_INTERVAL 60.0

// Moisture bounds
#define DRY 200
#define WET 800

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void log_data(int sensor_id, int adc_value, float moisture_percentage, int pump_state);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], float *threshold, float *duration, float *sleep_interval);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            // Extract ADC value
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(log_file, "%s SPI read failed (channel %d, retry %d)\n", __TIME__, channel, retries + 1);
            fflush(log_file);
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(MAX_RETRIES_DELAY * 1000); // Delay before retrying
            }
        }
    }

    fprintf(log_file, "%s SPI read failed (channel %d, max retries)\n", __TIME__, channel);
    fflush(log_file);
    return -1; // Indicate error
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = ((float)(adc_value - DRY) / (WET - DRY)) * 100.0;
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }
    return percentage;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Function to log data to file
void log_data(int sensor_id, int adc_value, float moisture_percentage, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s Sensor %d: ADC Value = %d, Moisture = %.2f%%, Pump = %s\n",
            timestamp, sensor_id, adc_value, moisture_percentage, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
    control_pump(0); // Turn off pump
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], float *threshold, float *duration, float *sleep_interval) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                *threshold = atof(optarg);
                break;
            case 'd':
                *duration = atof(optarg);
                break;
            case 's':
                *sleep_interval = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    float duration = DEFAULT_DURATION;
    float sleep_interval = DEFAULT_SLEEP_INTERVAL;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &threshold, &duration, &sleep_interval) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Threshold: %.2f%%, Duration: %.2f s, Sleep Interval: %.2f s\n", threshold, duration, sleep_interval);

    // Main loop
    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(NUM_SENSORS_CHANNELS[i]);
            if (adc_value != -1) {
                float moisture_percentage = calculate_moisture_percentage(adc_value);
                int pump_state = 0; // Initially off

                if (moisture_percentage < threshold) {
                    printf("Moisture below threshold on sensor %d, ADC value: %d, Moisture: %.2f%%\n", i + 1, adc_value, moisture_percentage);
                    pump_state = 1; // Turn on pump
                    gpioDelay(duration * 1000); // Activate pump for duration
                    control_pump(0); // Turn off pump after duration
                    pump_state = 0; // Ensure pump is off after activation
                }

                log_data(i + 1, adc_value, moisture_percentage, pump_state);
            } else {
                fprintf(log_file, "%s Error reading sensor %d\n", __TIME__, i + 1);
                fflush(log_file);
            }
        }

        gpioDelay(sleep_interval * 1000); // Sleep for sleep_interval seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

