#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define EMA_ALPHA 0.1
#define THRESHOLD_MARGIN 0.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
double ema = 0.0;
int running = 1;

// Function prototypes
int read_adc(int channel);
double calculate_ema(double new_value, double alpha);
int detect_peak(double raw_value, double ema, double threshold_margin);
int log_event(int adc_value);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate Exponential Moving Average (EMA)
double calculate_ema(double new_value, double alpha) {
    ema = alpha * new_value + (1 - alpha) * ema;
    return ema;
}

// Function to detect peak
int detect_peak(double raw_value, double ema, double threshold_margin) {
    double threshold = ema * (1 + threshold_margin);
    if (raw_value > threshold) {
        return 1; // Peak detected
    } else {
        return 0; // No peak detected
    }
}

// Function to log event to file
int log_event(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, %d\n", timestamp, adc_value);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate EMA
        ema = calculate_ema((double)adc_value, EMA_ALPHA);

        // Detect peak
        int peak_detected = detect_peak((double)adc_value, ema, THRESHOLD_MARGIN);

        // Log event
        if (log_event(adc_value) != 0) {
            fprintf(stderr, "Error: Failed to log event\n");
        }

        // Print peak detection status
        if (peak_detected) {
            printf("Peak detected! Raw value: %d, EMA: %.2f\n", adc_value, ema);
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Sound level monitoring stopped.\n");
    return 0;
}

