#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define CONTROL_BYTE 0x40 // Single-ended mode, AIN0

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to the PCF8591
int write_pcf8591(int fd, uint8_t byte) {
    uint8_t control_byte = CONTROL_BYTE | (byte & 0xF0) | 0x80; // Set read bit
    if (write(fd, &control_byte, 1) != 1) {
        perror("Failed to write control byte");
        return -1;
    }
    return 0;
}

// Function to read a byte from the PCF8591
int read_pcf8591(int fd, uint8_t *byte) {
    if (write(fd, &CONTROL_BYTE, 1) != 1) {
        perror("Failed to write control byte for read");
        return -1;
    }
    if (read(fd, byte, 1) != 1) {
        perror("Failed to read byte");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t current_byte, new_byte;
    int16_t sample;

    while (1) {
        // Dummy read to clear the read bit
        if (read_pcf8591(i2c_fd, &current_byte) != 0) {
            fprintf(stderr, "Error reading dummy byte, exiting.\n");
            break;
        }

        // Read the analog value from AIN0
        if (read_pcf8591(i2c_fd, &new_byte) != 0) {
            fprintf(stderr, "Error reading analog value, exiting.\n");
            break;
        }

        // Combine the two bytes to get the 10-bit sample
        sample = (int16_t)((new_byte << 8) | current_byte) >> 8; // Shift right by 8 bits

        // Print the sample value
        printf("Sample: %d\n", sample);

        // Wait for 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

