#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_PIN 27
#define SAMPLE_RATE 1 // Hz
#define BUFFER_SIZE 10
#define THRESHOLD 500.0 // Gauss
#define ZERO_FIELD_VOLTAGE 2.5
#define SENSITIVITY 1.4
#define VCC 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float voltage_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float voltage_to_gauss(int16_t raw_voltage);
void update_circular_buffer(float voltage);
float calculate_rolling_average();
void shutdown_motor();
void log_data(float voltage, float gauss, int rolling_average);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
    uint8_t config[3];
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // Single-ended, AIN0, 4.096V, Continuous conversion
    config[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write to ADS1115 configuration register");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read ADC value from ADS1115
int16_t read_adc() {
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from ADS1115");
        return 0; // Return 0 on error
    }

    int16_t raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Function to convert raw ADC value to Gauss
float voltage_to_gauss(int16_t raw_voltage) {
    float voltage = (float)raw_voltage / 32768.0 * VCC; // Assuming 16-bit ADC
    float gauss = (voltage - ZERO_FIELD_VOLTAGE) / (SENSITIVITY / 1000.0); // Convert to Gauss
    return gauss;
}

// Function to update the circular buffer
void update_circular_buffer(float voltage) {
    voltage_buffer[buffer_index] = voltage;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to calculate the rolling average of the buffer
float calculate_rolling_average() {
    if (buffer_count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += voltage_buffer[i];
    }
    return sum / buffer_count;
}

// Function to shutdown the motor
void shutdown_motor() {
    gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
    syslog(LOG_INFO, "Motor shutdown triggered!");
}

// Function to log data to syslog
void log_data(float voltage, float gauss, int rolling_average) {
    syslog(LOG_INFO, "Voltage: %.2f V, Gauss: %.2f, Rolling Average: %.2f", voltage, gauss, rolling_average);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("motor_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize to LOW

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Motor control system started");

    // Main loop
    while (!terminate) {
        int16_t raw_voltage = read_adc();
        if (raw_voltage < 0) {
            syslog(LOG_ERR, "Failed to read ADC value, skipping sample");
            gpioDelay(1000000 / SAMPLE_RATE); // Delay for 1 second
            continue;
        }

        float voltage = voltage_to_gauss(raw_voltage);
        update_circular_buffer(voltage);
        float rolling_average = calculate_rolling_average();

        log_data(voltage, rolling_average, rolling_average);

        if (rolling_average > THRESHOLD) {
            shutdown_motor();
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW before exiting
    gpioTerminate();
    closelog();

    return 0;
}

