    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0 CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stdout, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            continue; // Skip to the next iteration
        }

        // Validate ADC reading
        if (validate_adc_reading(moisture_level) < 0) {
            fprintf(stderr, "Error: Invalid ADC reading, skipping watering cycle\n");
            continue;
        }

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            fprintf(stdout, "Moisture level low (%d), activating pump\n", moisture_level);
            control_pump(1); // Activate pump
            gpioDelay(WATERING_DURATION * 1000); // Wait for watering duration
            control_pump(0); // Deactivate pump
            log_event(moisture_level);
        }

        // Wait for the next reading
        gpioDelay(READ_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    fprintf(stdout, "Cleaning up and exiting...\n");
    control_pump(0); // Ensure pump is off
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

