// Define GPIO pins
#define SPI_CE0 8   // SPI Chip Enable 0 (CE0)
#define SPI_MOSI 10 // SPI Master Out Slave In (MOSI)
#define SPI_MISO 9  // SPI Master In Slave Out (MISO)
#define SPI_SCLK 11 // SPI Serial Clock (SCLK)

#define MOTOR_PWM 18 // GPIO pin for motor PWM

// SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_pwm(int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_motor_pwm(0); // Stop the motor
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to set motor PWM duty cycle
void set_motor_pwm(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 1023) {
        fprintf(stderr, "Error: Invalid duty cycle value: %d\n", duty_cycle);
        return;
    }

    // Set PWM duty cycle (0-1023 maps directly to duty cycle)
    gpioPWM(MOTOR_PWM, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_handle = spiOpen(0, 1000000, 0); // SPI0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure motor PWM
    gpioSetMode(MOTOR_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR_PWM, 1000); // 1 kHz
    gpioSetPWMrange(MOTOR_PWM, 1024);    // Set PWM range to 0-1023

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Set motor PWM duty cycle
        set_motor_pwm(adc_value);

        // Print ADC value and PWM duty cycle
        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, gpioGetPWMdutycycle(MOTOR_PWM));

        // Delay for 100 ms
        gpioDelay(100);
    }

    return 0;
}

