#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define THRESHOLD 100.0 // Default threshold in Gauss
#define BLINK_DURATION 1 // Second
#define SAMPLE_RATE_MS 100

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Global variables
int i2c_handle;
double threshold = THRESHOLD; // Default threshold

// Function prototypes
int init_pigpio();
int init_i2c();
int16_t read_adc();
double convert_to_gauss(int16_t adc_value);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    double threshold;
    int blink_duration;
    int sample_rate_ms;
} Config;

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc() {
    char config[3];
    char convert[3];

    // Configure for single-ended AIN0, +/-4.096V, continuous conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0x83; // Single-ended, AIN0, +/-4.096V, Continuous conversion
    config[2] = 0x83; // Default configuration

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 16-bit resolution)
    gpioDelay(10); // Wait 10ms

    // Read conversion register
    if (i2cWriteDevice(i2c_handle, &config[0], 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register address\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, convert, 3) != 3) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    int16_t adc_value = (convert[0] << 8) | convert[1];
    return adc_value;
}

// Convert ADC value to Gauss
double convert_to_gauss(int16_t adc_value) {
    // Assuming 1.65V is 0 Gauss and 3.3V is 1000 Gauss
    double zero_gauss_voltage = 1.65; // V
    double max_gauss_voltage = 1000.0; // Gauss
    double max_adc_value = 32767.0; // 2^15 - 1

    // Scale the ADC value to the range 0-1000 Gauss
    double gauss_value = (adc_value / max_adc_value) * max_gauss_voltage;
    return gauss_value;
}

// Control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Using threshold: %.2f Gauss\n", threshold);
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring magnetic field strength... Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        double gauss_value = convert_to_gauss(adc_value);

        printf("Magnetic field strength: %.2f Gauss\n", gauss_value);

        if (gauss_value > threshold) {
            printf("Threshold exceeded! Blinking LED...\n");
            for (int i = 0; i < BLINK_DURATION; ++i) {
                control_led(1); // Turn on LED
                gpioDelay(50);   // 50ms
                control_led(0); // Turn off LED
                gpioDelay(50);   // 50ms
            }
        }

        gpioDelay(SAMPLE_RATE_MS); // Wait for the next sample
    }

    return 0;
}

