    // Assuming 1.65V is 0 Gauss and 3.3V is 1000 Gauss
    double zero_gauss_voltage = 1.65; // V
    double max_gauss_voltage = 1000.0; // Gauss
    double max_adc_value = 32767.0; // 2^15 - 1

    // Scale the ADC value to the range 0-1000 Gauss
    double gauss_value = (adc_value / max_adc_value) * max_gauss_voltage;
    return gauss_value;
}

