    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring magnetic field strength... Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        double gauss_value = convert_to_gauss(adc_value);

        printf("Magnetic field strength: %.2f Gauss\n", gauss_value);

        if (gauss_value > threshold) {
            printf("Threshold exceeded! Blinking LED...\n");
            for (int i = 0; i < BLINK_DURATION; ++i) {
                control_led(1); // Turn on LED
                gpioDelay(50);   // 50ms
                control_led(0); // Turn off LED
                gpioDelay(50);   // 50ms
            }
        }

        gpioDelay(SAMPLE_RATE_MS); // Wait for the next sample
    }

    return 0;
}

