        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(subscribe_result));
            terminate = 1; // Exit on subscription failure
        }
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(result));
        terminate = 1; // Exit on connection failure
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_WARNING, "MQTT disconnected unexpectedly with code %d", rc);
    }
