#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define noise threshold
#define NOISE_THRESHOLD 500

// Define PWM frequency
#define PWM_FREQUENCY 100 // 100 Hz

// Define log file path
#define LOG_FILE "vibration_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
void set_motor_duty_cycle(int gpio, int duty_cycle);
void log_event(int adc_value);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to set the duty cycle of a vibration motor
void set_motor_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    // Calculate PWM range (0-1000 for pigpio)
    int pwm_range = 1000; // Adjust as needed

    // Calculate PWM duty cycle (0-pwm_range)
    int pwm_duty_cycle = (int)(((float)duty_cycle / 100.0) * pwm_range);

    // Set PWM frequency
    gpioSetPWMfrequency(gpio, PWM_FREQUENCY);

    // Set PWM duty cycle
    gpioPWM(gpio, pwm_duty_cycle);
}

// Function to log an event to the log file
void log_event(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - ADC Value: %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the vibration motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Log the event
        log_event(adc_value);

        // Calculate duty cycle based on noise level
        int duty_cycle = 0;
        if (adc_value > NOISE_THRESHOLD) {
            duty_cycle = (int)(((float)adc_value / NOISE_THRESHOLD) * 100.0);
        }

        // Set motor duty cycles
        set_motor_duty_cycle(MOTOR1_GPIO, duty_cycle);
        set_motor_duty_cycle(MOTOR2_GPIO, duty_cycle);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Stop motors
    set_motor_duty_cycle(MOTOR1_GPIO, 0);
    set_motor_duty_cycle(MOTOR2_GPIO, 0);

    // Close SPI device
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Vibration monitoring stopped.\n");

    return 0;
}

