int read_bh1750(int i2c_handle);
int log_data(FILE *fp, int sound_level_db, int light_level_lux, int error_code);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read sound level from MAX9814 via MCP3008
int read_max9814(int spi_handle) {
    char tx_buf[3];
    char rx_buf[3];

    // MCP3008 configuration: start bit, single-ended mode, channel 0, MSB first
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (MAX9814_CHANNEL << 4)); // Single-ended, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for MAX9814\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to read light level from BH1750
int read_bh1750(int i2c_handle) {
    unsigned char buf[2];
    int lux = -1; // Default to error value

    // Send continuous high-resolution mode 2 command
    if (i2cWriteByteData(i2c_handle, 0x00, 0x11) != 0) {
        fprintf(stderr, "Error: I2C write failed for BH1750\n");
        return -1; // Indicate error
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed for BH1750\n");
        return -1; // Indicate error
    }

    // Convert the 2 bytes to lux value
    lux = (buf[0] << 8) | buf[1];
    return lux;
}

