    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    fprintf(stderr, "Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sound_level_db = -1;
        int light_level_lux = -1;
        int error_code = 0;

        // Read sensor data
        sound_level_db = read_max9814(spi_handle);
        light_level_lux = read_bh1750(i2c_handle);

        // Log data
        if (sound_level_db == -1 || light_level_lux == -1) {
            error_code = -1; // Indicate error
        } else {
            error_code = 0; // No error
        }

        if (log_data(log_file, sound_level_db, light_level_lux, error_code) != 0) {
            fprintf(stderr, "Error logging data, but continuing...\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Tamper detection system stopped.\n");
    return 0;
}

