    tx_buffer[1] = (0x08 | channel) << 4; // Start bit + single-ended mode + channel number
    tx_buffer[2] = 0x00;

    // Transfer the data via SPI
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate an error
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate the average of three ADC readings
float calculate_average(int sensor1, int sensor2, int sensor3) {
    if (sensor1 == -1 || sensor2 == -1 || sensor3 == -1) {
        return 0.0; // Return 0 if any sensor reading failed
    }

    return (float)(sensor1 + sensor2 + sensor3) / 3.0;
}

// Function to map the average ADC value to a PWM duty cycle
int map_adc_to_duty_cycle(int average_adc) {
    // Invert the ADC value to map dry soil (high ADC) to high valve opening (high duty cycle)
    // and wet soil (low ADC) to low valve opening (low duty cycle)
    int duty_cycle = PWM_RANGE - (int)(((float)average_adc / 1023.0) * PWM_RANGE);

    // Ensure the duty cycle is within the valid range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    return duty_cycle;
}

// Function to set the valve position using PWM
void set_valve_position(int duty_cycle) {
    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(int sensor1, int sensor2, int sensor3, float average_adc, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d, Sensor3: %d, Average ADC: %.2f, Duty Cycle: %d\n",
            timestamp, sensor1, sensor2, sensor3, average_adc, duty_cycle);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as PWM output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1 = read_mcp3008(0);
        int sensor2 = read_mcp3008(1);
        int sensor3 = read_mcp3008(2);

        // Check for errors during sensor reading
        if (sensor1 == -1 || sensor2 == -1 || sensor3 == -1) {
            fprintf(stderr, "Error: Failed to read sensor data. Skipping average calculation.\n");
            // Skip the average calculation and continue to the next iteration
            continue;
        }

        // Calculate the average ADC value
        float average_adc = calculate_average(sensor1, sensor2, sensor3);

        // Map the average ADC value to a PWM duty cycle
        int duty_cycle = map_adc_to_duty_cycle((int)average_adc);

        // Set the valve position
        set_valve_position(duty_cycle);

        // Log the data
        log_data(sensor1, sensor2, sensor3, average_adc, duty_cycle);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_valve_position(0); // Close the valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Irrigation control system stopped.\n");

    return 0;
}

