}

// Function to perform SPI transfer with retry and exponential backoff
int spi_transfer(int spi_handle, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int retries = 5;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d/%d), result = %d\n", 5 - retries + 1, 5, result);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    return -1; // All retries failed
}

