    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            // Calculate moisture percentage
            float moisture = calculate_moisture(adc_value);
            if (moisture >= 0.0) {
                // Log data
                log_data(moisture);

                // Check moisture level and trigger action if needed
                if (moisture < MOISTURE_THRESHOLD) {
                    printf("Moisture level low (%.2f%%). Consider watering.\n", moisture);
                }
            } else {
                fprintf(stderr, "Error: Could not calculate moisture.\n");
            }
        } else {
            fprintf(stderr, "Error: Could not read ADC value.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

