#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM channel
#define PWM_CHANNEL 0

// Define MCP3008 channel for LDR
#define LDR_CHANNEL 0

// Define calibration file
#define CONFIG_FILE "theremin_config.txt"

// Define error value for distance reading
#define DISTANCE_ERROR -1.0

// Global variables
volatile sig_atomic_t program_running = 1;
int last_valid_distance = 0; // Store the last valid distance
int last_valid_ldr_value = 0; // Store the last valid LDR value
int last_valid_frequency = 440; // Default frequency

// Function prototypes
float read_distance();
int read_ldr();
float map_distance_to_frequency(float distance);
void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int signal);
int load_calibration_data();
int save_calibration_data();
int export_pwm();
int unexport_pwm();
int set_pwm_period(int period_ns);
int set_pwm_range(int range);

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    int start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > 50000) { // Timeout after 50ms
            fprintf(stderr, "Error: Echo pulse timeout\n");
            return DISTANCE_ERROR;
        }
    }

    int echo_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start > 50000) { // Timeout after 50ms
            fprintf(stderr, "Error: Echo pulse timeout\n");
            return DISTANCE_ERROR;
        }
    }

    int echo_end = gpioTick();
    int diff = echo_end - echo_start;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff / 2.0 / 1000000.0 * 34300.0; // cm

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | LDR_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    // Linear mapping from 0-100cm to 220-880Hz
    float frequency = 220.0 + (distance / 100.0) * (880.0 - 220.0);
    return frequency;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to load calibration data from file
int load_calibration_data() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s, using default values.\n", CONFIG_FILE);
        return -1;
    }

    if (fscanf(fp, "%f %f", &last_valid_distance, &last_valid_ldr_value) != 2) {
        fprintf(stderr, "Error: Could not read calibration data from %s, using default values.\n", CONFIG_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration data loaded: Distance = %.2f cm, LDR = %d\n", last_valid_distance, last_valid_ldr_value);
    return 0;
}

// Function to save calibration data to file
int save_calibration_data() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", CONFIG_FILE);
        return -1;
    }

    fprintf(fp, "%.2f %d\n", last_valid_distance, last_valid_ldr_value);
    fclose(fp);
    printf("Calibration data saved to %s\n", CONFIG_FILE);
    return 0;
}

// Function to export PWM channel
int export_pwm() {
    FILE *fp = fopen("/sys/class/pwm/pwmchip0/export", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM export file.\n");
        return -1;
    }
    fprintf(fp, "0");
    fclose(fp);
    printf("PWM channel exported.\n");
    return 0;
}

// Function to unexport PWM channel
int unexport_pwm() {
    FILE *fp = fopen("/sys/class/pwm/pwmchip0/unexport", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM unexport file.\n");
        return -1;
    }
    fprintf(fp, "0");
    fclose(fp);
    printf("PWM channel unexported.\n");
    return 0;
}

// Function to set PWM period
int set_pwm_period(int period_ns) {
    char path[50];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM period file.\n");
        return -1;
    }
    fprintf(fp, "%d", period_ns);
    fclose(fp);
    printf("PWM period set to %d ns.\n", period_ns);
    return 0;
}

// Function to set PWM range
int set_pwm_range(int range) {
    char path[50];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/range", PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM range file.\n");
        return -1;
    }
    fprintf(fp, "%d", range);
    fclose(fp);
    printf("PWM range set to %d.\n", range);
    return 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error: wiringPiSetup failed\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error: wiringPiSPISetup failed\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Export PWM channel
    if (export_pwm() != 0) {
        fprintf(stderr, "Error: Failed to export PWM channel\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM period and range
    if (set_pwm_period(1000000) != 0) { // 1ms period
        fprintf(stderr, "Error: Failed to set PWM period\n");
        unexport_pwm();
        gpioTerminate();
        return 1;
    }
    if (set_pwm_range(1000000) != 0) { // 1ms range
        fprintf(stderr, "Error: Failed to set PWM range\n");
        unexport_pwm();
        gpioTerminate();
        return 1;
    }

    // Load calibration data
    if (load_calibration_data() != 0) {
        fprintf(stderr, "Warning: Could not load calibration data, using default values.\n");
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read distance
        float distance = read_distance();
        if (distance == DISTANCE_ERROR) {
            fprintf(stderr, "Error: Distance reading failed, using last valid value.\n");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        // Read LDR value
        int ldr_value = read_ldr();
        if (ldr_value < 0) {
            fprintf(stderr, "Error: LDR reading failed, using last valid value.\n");
            ldr_value = last_valid_ldr_value;
        } else {
            last_valid_ldr_value = ldr_value;
        }

        // Map distance to frequency
        float frequency = map_distance_to_frequency(distance);

        // Set PWM duty cycle based on LDR value
        int duty_cycle = 0;
        if (ldr_value > 0) {
            duty_cycle = (int)(((float)ldr_value / 1023.0) * 1000000.0); // Map LDR value (0-1023) to duty cycle (0-1000000)
            if (duty_cycle > 1000000) duty_cycle = 1000000; // Limit duty cycle to 1ms
        }

        // Set PWM duty cycle
        set_pwm_duty_cycle(duty_cycle);

        // Print data
        printf("Distance: %.2f cm, Frequency: %.2f Hz, LDR: %d, Duty Cycle: %d\n", distance, frequency, ldr_value, duty_cycle);

        // Delay
        gpioDelay(50); // 50ms delay
    }

    // Clean up
    set_pwm_duty_cycle(0); // Stop PWM
    unexport_pwm(); // Unexport PWM
    gpioTerminate(); // Terminate pigpio
    return 0;
}

