#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PPM_THRESHOLD 50.0
#define PPM_THRESHOLD_LOW 20.0
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8 // GPIO8 (CE0)
#define LOG_FILE "alcohol_log.txt"

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len);
int read_mcp3008(int fd, int channel);
float adc_to_ppm(int adc_value);
int classify_ppm(float ppm);
int log_data(const char *timestamp, int adc_value, float ppm, const char *classification);
void signal_handler(int sig);
int gpio_init(const char *chip_name, int line_num);
int gpio_set_line_direction(struct gpiod_line *line, const char *direction);
int gpio_release(struct gpiod_line *line);
int gpio_close(struct gpiod_chip *chip);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_val = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed hz
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MCP3008 read function
int read_mcp3008(int fd, int channel) {
    uint8_t tx[3];
    uint8_t rx[3];

    // Construct the SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended mode + channel
    tx[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx, rx, 3) != 0) {
        return -1;
    }

    // Extract the ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// ADC to PPM conversion function
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// PPM classification function
int classify_ppm(float ppm) {
    if (ppm > PPM_THRESHOLD) {
        return 1; // Alcohol detected!
    } else if (ppm < PPM_THRESHOLD_LOW) {
        return 0; // Sobriety confirmed
    } else {
        return 2; // Alcohol level within acceptable range
    }
}

// Data logging function
int log_data(const char *timestamp, int adc_value, float ppm, const char *classification) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, ADC: %d, PPM: %.2f, Classification: %s\n", timestamp, adc_value, ppm, classification);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// GPIO initialization function
int gpio_init(const char *chip_name, int line_num) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(line, "alcohol_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// GPIO set line direction function
int gpio_set_line_direction(struct gpiod_line *line, const char *direction) {
    if (gpiod_line_set_direction(line, direction) < 0) {
        perror("Error setting GPIO line direction");
        return -1;
    }
    return 0;
}

// GPIO release function
int gpio_release(struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// GPIO close function
int gpio_close(struct gpiod_chip *chip) {
    if (gpiod_chip_close(chip) < 0) {
        perror("Error closing GPIO chip");
        return -1;
    }
    return 0;
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    int adc_value;
    float ppm;
    int retry_count = 0;
    int spi_retries = 3;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_LINE) != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpio_release(gpio_line);
        gpio_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED_HZ);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        fclose(log_file);
        gpio_release(gpio_line);
        gpio_close(gpio_chip);
        return 1;
    }

    // Main loop
