    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_CE0_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_SCLK_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_MOSI_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_MISO_GPIO, PI_INPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read soil moisture sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_data(-1, -1); // Log error
        } else {
            // Calculate moisture percentage
            int moisture_level = calculate_moisture(adc_value);

            // Control water pump
            control_pump(moisture_level);

            // Log data
            log_data(moisture_level, gpioRead(PUMP_GPIO));
        }

        // Wait for 60 seconds
        gpioDelay(60000); // 60 seconds = 60000 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

