#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor 1 GPIOs
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIOs
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Configuration
#define MCP3008_CHANNEL_1 0
#define MCP3008_CHANNEL_2 1

// PWM Configuration
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_mcp3008(int channel);
float map_logarithmic(int value, int min, int max);
void motor_forward(int motor_enable, int motor_direction);
void motor_backward(int motor_enable, int motor_direction);
void motor_stop(int motor_enable);
void motion_profile(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map logarithmic function
float map_logarithmic(int value, int min, int max) {
    if (value < min || value > max) {
        return 0.0; // Clamp to 0
    }

    float log_value = (float)(value - min) / (max - min);
    float logarithmic_value = log10(1 + log_value); // Base 10 logarithm
    return logarithmic_value * 255.0;
}

// Function to set motor direction
void motor_forward(int motor_enable, int motor_direction) {
    gpioWrite(motor_direction, 1); // Set direction HIGH
}

// Function to set motor direction
void motor_backward(int motor_enable, int motor_direction) {
    gpioWrite(motor_direction, 0); // Set direction LOW
}

// Function to stop motor
void motor_stop(int motor_enable) {
    gpioPWM(motor_enable, 0); // Stop PWM signal
}

// Function to run the motion profile
void motion_profile(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction) {
    float speed_factor1, speed_factor2;
    int speed1, speed2;

    // Accelerate
    for (speed1 = 50; speed1 <= 255; speed1++) {
        speed_factor1 = map_logarithmic(speed1, 50, 255);
        speed2 = map_logarithmic(speed1, 50, 255);
        motor_forward(motor1_enable, motor1_direction);
        motor_backward(motor2_enable, motor2_direction);
        gpioPWM(motor1_enable, (int)speed_factor1);
        gpioPWM(motor2_enable, (int)speed2);
        gpioDelay(100000); // 100ms delay
    }

    // Hold speed
    gpioPWM(motor1_enable, (int)speed_factor1);
    gpioPWM(motor2_enable, (int)speed2);
    gpioDelay(2000000); // 2 seconds

    // Decelerate
    for (speed1 = 255; speed1 >= 50; speed1--) {
        speed_factor1 = map_logarithmic(speed1, 50, 255);
        speed2 = map_logarithmic(speed1, 50, 255);
        motor_stop(motor1_enable);
        motor_stop(motor2_enable);
        gpioPWM(motor1_enable, 0);
