    gpioSetMode(pins.cs, PI_OUTPUT);
    gpioSetMode(pins.mosi, PI_OUTPUT);
    gpioSetMode(pins.miso, PI_INPUT);
    gpioSetMode(pins.sclk, PI_OUTPUT);

    // Ensure CS is initially high
    gpioWrite(pins.cs, 1);

    return 0;
}

