int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Calibrate ambient level by averaging 5 seconds of readings
double calibrate_ambient_level() {
    double sum = 0.0;
    int num_samples = 0;

    printf("Calibrating ambient level... Please wait 5 seconds.\n");
    time_t start_time = time(NULL);

    while (time(NULL) - start_time < CALIBRATION_DURATION) {
        int sample = read_adc(0);
        if (sample >= 0) {
            sum += sample;
            num_samples++;
        } else {
            fprintf(stderr, "Error reading ADC during calibration.\n");
            return 0.0; // Return 0 if there's an error
        }
        gpioDelay(10000); // 10ms delay
    }

    if (num_samples > 0) {
        return sum / num_samples;
    } else {
        fprintf(stderr, "No valid ADC samples during calibration.\n");
        return 0.0; // Return 0 if no valid samples
    }
}

// Check if sound level exceeds threshold
int check_sound_level(double ambient_level, int sample) {
    double threshold = ambient_level * 1.1; // 10% above threshold
    return (sample > threshold);
}

// Control LED state
void control_led(int state) {
    gpioWrite(pins.led, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Cleaning up...\n");
    control_led(0); // Turn off LED
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

