int gpio_request_output(struct gpiod_chip *chip, int pin, struct gpiod_line_request_config *config) {
    int ret = gpiod_chip_get_line(chip, pin);
    if (ret < 0) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_request(line, config, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// GPIO drive low function
int gpio_drive_low(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error driving GPIO line low");
        return -1;
    }
    return 0;
}

// GPIO drive high function
int gpio_drive_high(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Error driving GPIO line high");
        return -1;
    }
    return 0;
}

// GPIO release function
int gpio_release(struct gpiod_line *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, uint32_t timestamp_ns, int raw_adc_value) {
    if (fprintf(fp, "%u|%d\n", timestamp_ns, raw_adc_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED_HZ);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(AUDIO_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip == NULL) {
        perror("Error opening GPIO chip");
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    // Request GPIO line
    struct gpiod_line_request_config config;
    config.consumer = "audio_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpio_request_output(gpio_chip, CS_GPIO_PIN, &config) != 0) {
        fprintf(stderr, "Failed to request GPIO line. Exiting.\n");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Drive CS low
        if (gpio_drive_low(cs_line) != 0) {
            fprintf(stderr, "Failed to drive CS low. Exiting.\n");
            break;
        }

        // Read ADC value
        int raw_adc_value = mcp3008_read_channel(spi_fd, 0);
        if (raw_adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Exiting.\n");
            break;
        }

        // Drive CS high
        if (gpio_drive_high(cs_line) != 0) {
            fprintf(stderr, "Failed to drive CS high. Exiting.\n");
            break;
        }

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }
        uint32_t timestamp_ns = (uint32_t)ts.tv_sec * 1000000000UL + ts.tv_nsec;

        // Log data
        if (log_data(log_file, timestamp_ns, raw_adc_value) != 0) {
            fprintf(stderr, "Failed to log data. Exiting.\n");
            break;
        }

        // Sleep until next sample
        if (nanosleep(&(struct timespec){0, SAMPLE_PERIOD_NS}, NULL) != 0) {
            perror("Error during nanosleep");
            break;
        }
    }

    // Cleanup
    if (cs_line) {
        gpio_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return 0;
}

