#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CS 8

// Define ADXL335 parameters
#define ADXL335_VREF 3.3f
#define ADXL335_SENSITIVITY 0.3f // 300 mV/g
#define ADXL335_ZERO_G 1.5f

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01f
#define MEASUREMENT_NOISE 0.1f

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float P;
} KalmanState;

KalmanState kalman_state = {0.0f, 1.0f};

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
void kalman_filter(float measurement, float *state, float *P);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * ADXL335_VREF;
}

// Function to convert voltage to acceleration
float voltage_to_acceleration(float voltage) {
    return (voltage - ADXL335_ZERO_G) / ADXL335_SENSITIVITY;
}

// Function to implement Kalman filter
void kalman_filter(float measurement, float *state, float *P) {
    // Prediction step
    float predicted_state = *state;
    float predicted_P = *P + PROCESS_NOISE;

    // Update step
    float K = predicted_P / (predicted_P + MEASUREMENT_NOISE);
    float Kalman_gain = K * (1 - K);

    float Kalman_state_new = predicted_state + Kalman_gain * (measurement - predicted_state);
    float Kalman_P_new = (1 - K) * predicted_P + K * MEASUREMENT_NOISE;

    *state = Kalman_state_new;
    *P = Kalman_P_new;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure MCP3008 CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            break; // Exit loop on error
        }

        // Convert ADC values to voltages
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to accelerations
        float x_acceleration = voltage_to_acceleration(x_voltage);
        float y_acceleration = voltage_to_acceleration(y_voltage);
        float z_acceleration = voltage_to_acceleration(z_voltage);

        // Apply Kalman filter
        kalman_filter(x_acceleration, &kalman_state.x, &kalman_state.P);
        kalman_filter(y_acceleration, &kalman_state.x, &kalman_state.P);
        kalman_filter(z_acceleration, &kalman_state.x, &kalman_state.P);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", kalman_state.x, kalman_state.x, kalman_state.x);

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close SPI channel and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

