int read_sensor(int gpio_pin) {
    int value = -1; // Initialize to an invalid value
    struct gpiod_line *line = NULL;

    if (gpio_pin == SENSOR1_PIN) {
        line = sensor1_line;
    } else if (gpio_pin == SENSOR2_PIN) {
        line = sensor2_line;
    } else if (gpio_pin == SENSOR3_PIN) {
        line = sensor3_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio_pin);
        return -1; // Indicate an error
    }

    if (line) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
            return -1; // Indicate an error
        }
    } else {
        fprintf(stderr, "Error: Line %d not initialized\n", gpio_pin);
        return -1; // Indicate an error
    }

    return value;
}

// Function to calculate magnetic field strength
float calculate_magnetic_field(int sensor_value) {
    float voltage = (float)sensor_value * VCC;
    float magnetic_field = (voltage - VQUESCENT) / SENSITIVITY;
    return magnetic_field;
}

// Function to log data to file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            sensor1_mT, sensor2_mT, sensor3_mT);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines as input
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_PIN);

    if (!sensor1_line || !sensor2_line || !sensor3_line) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting sensor1 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting sensor2 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor3_line, "sensor3") < 0) {
        fprintf(stderr, "Error requesting sensor3 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
        } else {
            float sensor1_mT = calculate_magnetic_field(sensor1_value);
            float sensor2_mT = calculate_magnetic_field(sensor2_value);
            float sensor3_mT = calculate_magnetic_field(sensor3_value);

            if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
                fprintf(stderr, "Error logging data, skipping.\n");
            }

            // Check for out-of-range magnetic field values
            if (sensor1_mT > 100.0 || sensor1_mT < -100.0) {
                fprintf(stderr, "Warning: Sensor 1 value out of range: %.3f mT\n", sensor1_mT);
            }
            if (sensor2_mT > 100.0 || sensor2_mT < -100.0) {
                fprintf(stderr, "Warning: Sensor 2 value out of range: %.3f mT\n", sensor2_mT);
            }
            if (sensor3_mT > 100.0 || sensor3_mT < -100.0) {
                fprintf(stderr, "Warning: Sensor 3 value out of range: %.3f mT\n", sensor3_mT);
            }
        }

        usleep(100000); // Sleep for 100 milliseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor3_line) {
        gpiod_line_release(sensor3_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

