#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signum);
}

// Function to initialize the MQTT client
int mqtt_init() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    return 0;
}

// Function to disconnect the MQTT client with exponential backoff
void disconnect_mqtt() {
    int delay = 1;
    while (running) {
        int rc = mosquitto_disconnect(mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Error: Could not disconnect from MQTT broker: %s\n", mosquitto_strerror(rc));
            delay *= 2;
            if (delay > MAX_RECONNECT_DELAY) {
                delay = MAX_RECONNECT_DELAY;
            }
            fprintf(stderr, "Reconnecting in %d seconds...\n", delay);
            gpioDelay(delay * 1000); // Convert seconds to milliseconds
        } else {
            break;
        }
    }
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

// Function to turn the LED on or off
void set_led_state(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Function to parse the JSON payload
int parse_json_payload(const char *payload) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        return -1;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBoolean(led_state)) {
        fprintf(stderr, "Error: 'led_state' is not a boolean.\n");
        cJSON_Delete(json);
        return -1;
    }

    if (cJSON_IsBoolean(led_state)) {
        set_led_state(cJSON_GetBooleanValue(led_state));
    } else {
        fprintf(stderr, "Error: 'led_state' is not a boolean value.\n");
        cJSON_Delete(json);
        return -1;
    }

    cJSON_Delete(json);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_led_state(0); // Turn off the LED on startup

    // Initialize MQTT
    if (mqtt_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1); // -1 means wait indefinitely, 1 means max 1 message processed
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Error: MQTT loop error: %s\n", mosquitto_strerror(rc));
            disconnect_mqtt();
            if (mqtt_init() != 0) {
                running = 0; // Exit if re-initialization fails
            }
        }
    }

    // Clean up
    disconnect_mqtt();
    set_led_state(0); // Turn off the LED
    gpioTerminate();

    return 0;
}

