#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sound sensor
int read_sound_sensor(int pin) {
    return gpioRead(pin);
}

// Function to control the alarm LED
void control_alarm_led(int pin, int state) {
    gpioWrite(pin, state);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Read sound sensor
        int sound_level = read_sound_sensor(SOUND_SENSOR_PIN);

        // Print sound level
        printf("Sound Level: %d\n", sound_level);

        // Control alarm LED if sound detected
        if (sound_level == 0) {
            control_alarm_led(ALARM_LED_PIN, 1); // Turn LED on
            gpioDelay(1000000); // Wait for 1 second (1000000 microseconds)
            control_alarm_led(ALARM_LED_PIN, 0); // Turn LED off
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

