#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "Signal received, exiting gracefully.\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event *event;
    int ret;
    struct timespec ts;
    char timestamp[30];
    FILE *log_file;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for falling-edge event detection
    event = gpiod_line_event_request(line, "vibration-monitor", GPIOD_LINE_EVENT_RISING_EDGE);
    if (!event) {
        perror("Error requesting GPIO line event");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(event);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        ret = gpiod_line_event_wait(event, 0); // Wait indefinitely
        if (ret < 0) {
            perror("Error waiting for GPIO line event");
            break;
        }

        // Read GPIO line
        ret = gpiod_line_event_read(event, &ts);
        if (ret < 0) {
            perror("Error reading GPIO line event");
            break;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

        // Log event
        fprintf(log_file, "%s Vibration detected on GPIO %d\n", timestamp, GPIO_PIN);
        fflush(log_file);

        // Print to stdout
        printf("%s Vibration detected on GPIO %d\n", timestamp, GPIO_PIN);

        // Shutdown
        system("sudo shutdown -h now");

        // Debounce delay
        struct timespec delay = {0, DEBOUNCE_DELAY_MS * 1000000L};
        nanosleep(&delay, NULL);
    }

    // Cleanup
    gpiod_line_release(event);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

