#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_25 0xA1
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_PRESSURE_LSB 0xF8
#define BMP280_REG_PRESSURE_XLSB 0xF9
#define BMP280_REG_TEMPERATURE_MSB 0xFA
#define BMP280_REG_TEMPERATURE_LSB 0xFB
#define BMP280_REG_TEMPERATURE_XLSB 0xFC
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5

// Sea-level pressure (Pa)
#define SEA_LEVEL_PRESSURE 101325.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp280_calib_data *calib);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_register(int handle, uint8_t reg, uint8_t *value);
int read_raw_data(int handle, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
double calculate_altitude(double pressure);
int log_data(double altitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // Bus 1, address 0x76, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read calibration data from BMP280
int read_calibration_data(bmp280_calib_data *calib) {
    uint8_t buffer[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)buffer, 26) != 26) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    calib->dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib->dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
