#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LM35_SENSITIVITY 0.01 // 10 mV/°C
#define CIRCULAR_BUFFER_SIZE 120
#define LOG_INTERVAL 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void update_circular_buffer(float temperature);
void log_to_file();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel number
    tx_buffer[2] = 0x00; // Don't-care byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = voltage / LM35_SENSITIVITY;
    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

// Function to log temperature to file
void log_to_file() {
    FILE *fp = fopen("temp_log.dat", "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temp_log.dat for writing\n");
        return;
    }

    // Write the entire buffer to the file
    fwrite(temperature_buffer, sizeof(float), CIRCULAR_BUFFER_SIZE, fp);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Update circular buffer
        update_circular_buffer(temperature);

        // Log temperature to file
        log_to_file();

        // Print temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Wait for the next reading
        sleep(LOG_INTERVAL);
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

