    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Update circular buffer
        update_circular_buffer(temperature);

        // Log temperature to file
        log_to_file();

        // Print temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Wait for the next reading
        sleep(LOG_INTERVAL);
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

