    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Light: %d lux, Sound: %d\n", timestamp, light, sound);
    fclose(fp);

    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        close(i2c_fd);
        return 1;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        int light = read_bh1750(i2c_fd);
        int sound = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        // Log data
        if (light != -1 && sound != -1) {
            if (log_data(LOG_FILE, light, sound) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close(i2c_fd);
    close(spi_fd);

    printf("Environmental monitoring stopped.\n");

    return 0;
}

