    return ((float)adc_value / 1023.0f) * VREF;
}

// Function to convert voltage to DAC voltage
float voltage_to_dac_voltage(float voltage) {
    return (voltage / VREF) * (MAX_DAC - MIN_DAC) + MIN_DAC;
}

