#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define the GPIO chip and line numbers for the relays
#define GPIO_CHIP "gpiochip0"
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Global variable to store the gpiod_chip_t and gpiod_line_t structures
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;

// Signal handler function
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    if (relay1_line) {
        gpiod_line_set_value(relay1_line, 0);
    }
    if (relay2_line) {
        gpiod_line_set_value(relay2_line, 0);
    }
    if (relay3_line) {
        gpiod_line_set_value(relay3_line, 0);
    }
    if (relay4_line) {
        gpiod_line_set_value(relay4_line, 0);
    }

    // Release the GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to activate a relay
int activate_relay(int pin)
{
    struct gpiod_line *line = NULL;

    if (pin == RELAY1_PIN) {
        line = relay1_line;
    } else if (pin == RELAY2_PIN) {
        line = relay2_line;
    } else if (pin == RELAY3_PIN) {
        line = relay3_line;
    } else if (pin == RELAY4_PIN) {
        line = relay4_line;
    } else {
        fprintf(stderr, "Error: Invalid relay pin: %d\n", pin);
        return -1;
    }

    if (!line) {
        fprintf(stderr, "Error: Could not find line for relay pin: %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting value for line %d: %s\n", pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int pin)
{
    struct gpiod_line *line = NULL;

    if (pin == RELAY1_PIN) {
        line = relay1_line;
    } else if (pin == RELAY2_PIN) {
        line = relay2_line;
    } else if (pin == RELAY3_PIN) {
        line = relay3_line;
    } else if (pin == RELAY4_PIN) {
        line = relay4_line;
    } else {
        fprintf(stderr, "Error: Invalid relay pin: %d\n", pin);
        return -1;
    }

    if (!line) {
        fprintf(stderr, "Error: Could not find line for relay pin: %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting value for line %d: %s\n", pin, strerror(-ret));
        return -1;
    }

    return 0;
}

int main()
{
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the line for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error getting line for relay pin: %d, %d, %d, %d\n", RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines as output
    int ret1 = gpiod_line_request_output(relay1_line, "relay1", 0);
    int ret2 = gpiod_line_request_output(relay2_line, "relay2", 0);
    int ret3 = gpiod_line_request_output(relay3_line, "relay3", 0);
    int ret4 = gpiod_line_request_output(relay4_line, "relay4", 0);

    if (ret1 < 0 || ret2 < 0 || ret3 < 0 || ret4 < 0) {
        fprintf(stderr, "Error requesting line: %s\n", strerror(-ret1));
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate relay 1
        if (activate_relay(RELAY1_PIN) != 0) {
            fprintf(stderr, "Error activating relay 1\n");
            break; // Exit the loop on error
        }
        sleep(1);

        // Deactivate relay 1
        if (deactivate_relay(RELAY1_PIN) != 0) {
            fprintf(stderr, "Error deactivating relay 1\n");
            break; // Exit the loop on error
        }
        sleep(1);

        // Activate relay 2
        if (activate_relay(RELAY2_PIN) != 0) {
            fprintf(stderr, "Error activating relay 2\n");
            break; // Exit the loop on error
        }
        sleep(1);

        // Deactivate relay 2
        if (deactivate_relay(RELAY2_PIN) != 0) {
            fprintf(stderr, "Error deactivating relay 2\n");
            break; // Exit the loop on error
        }
        sleep(1);

        // Activate relay 3
        if (activate_relay(RELAY3_PIN) != 0) {
            fprintf(stderr, "Error activating relay 3\n");
            break; // Exit the loop on error
        }
        sleep(1);

        // Deactivate relay 3
        if (deactivate_relay(RELAY3_PIN) != 0) {
            fprintf(stderr, "Error deactivating relay 3\n");
            break; // Exit the loop on error
        }
        sleep(1);

        // Activate relay 4
        if (activate_relay(RELAY4_PIN) != 0) {
            fprintf(stderr, "Error activating relay 4\n");
            break; // Exit the loop on error
        }
        sleep(1);

        // Deactivate relay 4
        if (deactivate_relay(RELAY4_PIN) != 0) {
            fprintf(stderr, "Error deactivating relay 4\n");
            break; // Exit the loop on error
        }
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler is working)
