void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    if (relay1_line) {
        gpiod_line_set_value(relay1_line, 0);
    }
    if (relay2_line) {
        gpiod_line_set_value(relay2_line, 0);
    }
    if (relay3_line) {
        gpiod_line_set_value(relay3_line, 0);
    }
    if (relay4_line) {
        gpiod_line_set_value(relay4_line, 0);
    }

    // Release the GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

