#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 16
#define SPI_CE0 8
#define SPI_CE1 7
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define sound level threshold
#define SOUND_THRESHOLD 500

// Define debounce delay
#define DEBOUNCE_DELAY 50 // milliseconds

// Define log file path
#define LOG_FILE "sound_events.log"

// Global variables
int spi_handle_ce0, spi_handle_ce1;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
int is_sound_level_exceeded(int adc_value, int threshold);
void control_led(int gpio_pin, int state);
void log_event(const char *timestamp);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to check if sound level exceeds threshold
int is_sound_level_exceeded(int adc_value, int threshold) {
    return adc_value > threshold;
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log an event to the log file
void log_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s - Sound detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close SPI
    spiClose(spi_handle_ce0);
    spiClose(spi_handle_ce1);

    // Terminate pigpio
    gpioTerminate();

    // Turn off LED
    control_led(LED_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_CE1, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Initialize SPI
    spi_handle_ce0 = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle_ce0 < 0) {
        fprintf(stderr, "Error: SPI initialisation failed for CE0: %d\n", spi_handle_ce0);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    spi_handle_ce1 = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE1, 1MHz, Mode 0
    if (spi_handle_ce1 < 0) {
        fprintf(stderr, "Error: SPI initialisation failed for CE1: %d\n", spi_handle_ce1);
        spiClose(spi_handle_ce0);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sound level from both sensors
        int adc_value_ce0 = read_mcp3008(spi_handle_ce0, 0);
        int adc_value_ce1 = read_mcp3008(spi_handle_ce1, 0);

        if (adc_value_ce0 == -1 || adc_value_ce1 == -1) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying...\n");
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        // Check if sound level exceeds threshold
        if (is_sound_level_exceeded(adc_value_ce0, SOUND_THRESHOLD) || is_sound_level_exceeded(adc_value_ce1, SOUND_THRESHOLD)) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event
            log_event(timestamp);

            // Turn on LED
            control_led(LED_PIN, 1);

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY);

            // Turn off LED
            control_led(LED_PIN, 0);
        }

        // Delay before next reading
        gpioDelay(10);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle_ce0);
    spiClose(spi_handle_ce1);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

