#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

// Define GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction, int speed);
void log_rain_reading(int rain_level);
void signal_handler(int signal);

// Function to read the rain sensor value from MCP3008
int read_rain_sensor() {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value;

    // MCP3008 command to read channel 0 (single-ended)
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | 0) << 4; // Single-ended, channel 0
    tx[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the ADC value from the response
    adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to control the motor
void control_motor(int direction, int speed) {
    if (direction == MOTOR_FORWARD) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, speed);
    } else if (direction == MOTOR_REVERSE) {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, speed);
    } else {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 0);
    }
}

// Function to log the rain reading with timestamp
void log_rain_reading(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);

    // Stop the motor
    control_motor(MOTOR_FORWARD, 0);
    control_motor(MOTOR_REVERSE, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int rain_level;
    int motor_forward, motor_reverse;
    int motor_speed;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read rain sensor
        rain_level = read_rain_sensor();
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            // Optionally add retry logic here
            continue; // Skip to the next iteration
        }

        // Log rain reading
        log_rain_reading(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            motor_forward = MOTOR_FORWARD;
            motor_reverse = MOTOR_REVERSE;
            motor_speed = MOTOR_PWM_DUTY;
        } else {
            motor_forward = MOTOR_FORWARD;
            motor_reverse = MOTOR_REVERSE;
            motor_speed = MOTOR_PWM_DUTY;
        }

        // Close window
        control_motor(motor_forward, motor_speed);
        gpioDelay(3000); // Run for 3 seconds

        // Open window
        control_motor(motor_reverse, motor_speed);
        gpioDelay(3000); // Run for 3 seconds

        gpioDelay(1000); // Wait 1 second before next reading
    }

    // Cleanup (should not reach here if signal handler is working)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

