#define DEBOUNCE_TIME 50

// Define LED on time in milliseconds
#define LED_ON_TIME 500

// Define ADC resolution (10 bits)
#define ADC_RESOLUTION 1024

// Global variables
static volatile int running = 1;
static volatile int led_state = 0; // 0: off, 1: on

// Function prototypes
int initialize_gpio();
int configure_adc();
int read_adc();
void control_led(int state);
void detect_clap();
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int mic_pin;
    int led_pin;
    int debounce_time;
    int led_on_time;
    int adc_resolution;
} Config;

Config config = {MIC_DATA_PIN, LED_PIN, DEBOUNCE_TIME, LED_ON_TIME, ADC_RESOLUTION};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADC
    if (configure_adc() != 0) {
        fprintf(stderr, "ADC configuration failed\n");
        gpioTerminate();
        return 1;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc();

        // Detect clap
        detect_clap();

        // Small delay to avoid busy-waiting
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    printf("Clap detector stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(config.mic_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_DATA_PIN as input\n");
        return 1;
    }
    if (gpioSetMode(config.led_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        return 1;
    }
    return 0;
}

