int read_adc() {
    int adc_value = 0;
    int i;

    // Set MIC_DATA_PIN as input
    gpioSetMode(config.mic_pin, PI_INPUT);

    // Read 10 bits of the ADC
    for (i = 0; i < 10; i++) {
        // Wait for the pin to go high
        int timeout = 1000; // Timeout after 1000 attempts
        while (gpioRead(config.mic_pin) == 0 && timeout > 0) {
            gpioDelay(1); // Wait 1 ms
            timeout--;
        }

        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for MIC_DATA_PIN to go high\n");
            return 0; // Return 0 on timeout
        }

        // Measure the duration the pin is high
        int high_duration = 0;
        timeout = 1000; // Timeout after 1000 attempts
        while (gpioRead(config.mic_pin) == 1 && timeout > 0) {
            gpioDelay(1); // Wait 1 ms
            timeout--;
        }

        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for MIC_DATA_PIN to go low\n");
            return 0; // Return 0 on timeout
        }

        high_duration = timeout;

        // Scale the duration to an ADC value (0-1023)
        adc_value += (high_duration > 0) ? (high_duration * 1023) / 1000 : 0; // Scale to 0-1023
    }

    return adc_value;
}

// Control the LED
void control_led(int state) {
    gpioWrite(config.led_pin, state);
}

// Detect clap
void detect_clap() {
    static int last_state = 0; // 0: below threshold, 1: above threshold
    int current_state = gpioRead(config.mic_pin);

    if (current_state == 1 && last_state == 0) {
        // Clap detected
        printf("Clap detected!\n");
        control_led(1); // Turn on LED
        gpioDelay(LED_ON_TIME); // Keep LED on for 500 ms
        control_led(0); // Turn off LED
        gpioDelay(DEBOUNCE_TIME); // Debounce
    }

    last_state = current_state;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

