#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200.0 // mm

// Structure to hold GPIO configuration
typedef struct {
    int pin;
    char path[64];
} gpio_config_t;

// Global variable to store the GPIO configuration
gpio_config_t gpio_config;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float voltage_from_gpio(int gpio_value);
float distance_mm(float voltage);
int log_distance(float distance);
int check_proximity(float distance);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully.\n", signum);
        gpio_unexport(gpio_config.pin);
        exit(0);
    }
}

// Function to export the GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to read the GPIO value
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to convert GPIO value to voltage
float voltage_from_gpio(int gpio_value) {
    if (gpio_value == 0) {
        return 0.0;
    } else {
        return 3.3;
    }
}

// Function to convert voltage to distance (mm)
float distance_mm(float voltage) {
    return 26.0 / voltage - 6.0;
}

// Function to log the distance to a file
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to check proximity and activate/deactivate the feeder
int check_proximity(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
        return 1; // Activate
    } else {
        printf("Feeder Idle\n");
        return 0; // Idle
    }
}

int main() {
    int gpio_value;
    float voltage, distance;
    int retry_count = 0;
    const int max_retries = 3;

    // Initialize GPIO configuration
    gpio_config.pin = GPIO_PIN;
    snprintf(gpio_config.path, sizeof(gpio_config.path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(gpio_config.pin) < 0) {
        fprintf(stderr, "Failed to export GPIO %d. Retrying in 1 second.\n", GPIO_PIN);
        sleep(1);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(gpio_config.pin, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction. Retrying in 1 second.\n", GPIO_PIN);
        sleep(1);
        return 1;
    }

    printf("Pet feeder control system started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read GPIO value
        gpio_value = gpio_read(gpio_config.pin);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Too many retries. Exiting.\n");
                break;
            }
            continue;
        }

        // Convert GPIO value to voltage
        voltage = voltage_from_gpio(gpio_value);

        // Convert voltage to distance
        distance = distance_mm(voltage);

        // Log the distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance. Retrying in 1 second.\n");
            sleep(1);
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Too many retries. Exiting.\n");
                break;
            }
            continue;
        }

        // Check proximity and activate/deactivate feeder
        check_proximity(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin before exiting
    gpio_unexport(gpio_config.pin);

    return 0;
}

