// Function to check proximity and activate/deactivate the feeder
int check_proximity(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
        return 1; // Activate
    } else {
        printf("Feeder Idle\n");
        return 0; // Idle
    }
}

int main() {
    int gpio_value;
    float voltage, distance;
    int retry_count = 0;
    const int max_retries = 3;

    // Initialize GPIO configuration
    gpio_config.pin = GPIO_PIN;
    snprintf(gpio_config.path, sizeof(gpio_config.path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(gpio_config.pin) < 0) {
        fprintf(stderr, "Failed to export GPIO %d. Retrying in 1 second.\n", GPIO_PIN);
        sleep(1);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(gpio_config.pin, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction. Retrying in 1 second.\n", GPIO_PIN);
        sleep(1);
        return 1;
    }

    printf("Pet feeder control system started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read GPIO value
        gpio_value = gpio_read(gpio_config.pin);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Too many retries. Exiting.\n");
                break;
            }
            continue;
        }

        // Convert GPIO value to voltage
        voltage = voltage_from_gpio(gpio_value);

        // Convert voltage to distance
        distance = distance_mm(voltage);

        // Log the distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance. Retrying in 1 second.\n");
            sleep(1);
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Too many retries. Exiting.\n");
                break;
            }
            continue;
        }

        // Check proximity and activate/deactivate feeder
        check_proximity(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin before exiting
    gpio_unexport(gpio_config.pin);

    return 0;
}

