#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define GPIO_CS 8
#define GPIO_DOUT 10
#define GPIO_DIN 9
#define GPIO_CLK 11
#define VREF 3300 // mV
#define SENSITIVITY 100 // mV/mT
#define QUIESCENT_VOLTAGE 1650 // mV
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "magnetic_log.txt"

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static int gpio_chip = -1;
static struct gpiod_chip *gpio_chip_ptr = NULL;
static struct gpiod_line *gpio_cs_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int read_mcp3008(int spi_fd, int channel);
float adc_to_voltage(int adc_value, int vref);
float voltage_to_magnetic_field(float voltage);
int log_data(FILE *fp, long long timestamp, float magnetic_field);
void signal_handler(int sig);
int gpio_init(int chip, int line, struct gpiod_line *line_ptr);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_release(struct gpiod_line *line);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = (mode << 4) | (bits << 0);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// MCP3008 read function
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_MAX_SPEED_HZ;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to voltage conversion function
float adc_to_voltage(int adc_value, int vref) {
    return (float)adc_value * vref / 1023.0;
}

// Voltage to magnetic field conversion function
float voltage_to_magnetic_field(float voltage) {
    float magnetic_field = (voltage - QUIESCENT_VOLTAGE) / (SENSITIVITY / 1000.0);
    return magnetic_field;
}

// Data logging function
int log_data(FILE *fp, long long timestamp, float magnetic_field) {
    if (fprintf(fp, "%lld,%.2f\n", timestamp, magnetic_field) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    keep_running = 0;
}

// GPIO initialization function
int gpio_init(int chip, int line, struct gpiod_line *line_ptr) {
    struct gpiod_chip *chip_ptr = gpiod_chip_open_by_name(chip);
    if (!chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line_ptr = gpiod_chip_get_line(chip_ptr, line);
    if (!*line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    if (gpiod_line_request_output(*line_ptr, "magnetic_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO release function
int gpio_release(struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_chip_ptr != NULL) {
        gpiod_line_release(gpio_cs_line);
        gpiod_chip_close(gpio_chip_ptr);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED_HZ);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = "gpiochip0";
    gpio_cs_line = NULL;
    if (gpio_init(gpio_chip, GPIO_CS, &gpio_cs_line) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping sample.\n");
            sleep(SAMPLE_INTERVAL_MS);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to magnetic field
        float magnetic_field = voltage_to_magnetic_field(voltage);

        // Get timestamp
        long long timestamp = time(NULL);

        // Log data
        if (log_data(log_file, timestamp, magnetic_field) < 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Print magnetic field (optional)
        printf("Magnetic field: %.2f mT\n", magnetic_field);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

