// Structure to hold SPI configuration
typedef struct {
    int ce;
    int mosi;
    int miso;
    int sclk;
    int baud;
} spi_config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x80 | (channel << 4)); // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10-bit)
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert raw ADC value to voltage
float voltage_from_raw(int raw) {
    return ((float)raw / 1023.0) * VREF;
}

// Function to convert voltage to current
float current_from_voltage(float voltage) {
    return (voltage - 2.5) * (50.0 / 2.5);
}

// Function to log data to file
void log_data(float current) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[26];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp + 19, 7, ".%03d", (int)(tv.tv_usec / 1000));

    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
