    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {SPI_CHANNEL, 10, 9, 11, SPI_BAUD};
    spi_handle = spiOpen(spi_config.ce, spi_config.baud, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read ADC value
        int raw_value = read_mcp3008(0);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert to voltage and current
        float voltage = voltage_from_raw(raw_value);
        float current = current_from_voltage(voltage);

        // Validate voltage
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
        }

        // Log data
        log_data(current);

        // Delay
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

