#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 2

// Number of samples for debouncing
#define DEBOUNCE_SAMPLES 5

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;

// Function prototypes
int read_sensor(int gpio_pin);
int debounce(int pin, int samples);
void log_sensor_state(int sensor1_state, int sensor2_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, releasing GPIO resources...\n");
        if (sensor1_line) {
            gpiod_line_release(sensor1_line);
        }
        if (sensor2_line) {
            gpiod_line_release(sensor2_line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    int value = gpiod_line_get_value(sensor1_line ? sensor1_line : sensor2_line);
    if (!sensor1_line) {
        sensor1_line = gpiod_line_get_line(chip, gpio_pin);
        if (!sensor1_line) {
            fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
            return -1;
        }
    }
    if (!sensor2_line) {
        sensor2_line = gpiod_line_get_line(chip, gpio_pin);
        if (!sensor2_line) {
            fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
            return -1;
        }
    }
    return value;
}

// Function to debounce the sensor reading
int debounce(int pin, int samples) {
    int count = 0;
    for (int i = 0; i < samples; i++) {
        int value = read_sensor(pin);
        if (value == -1) {
            return -1; // Indicate error
        }
        if (value == 0) {
            count++;
        }
        usleep(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }
    return (count >= (samples / 2)); // Return 1 if majority is LOW, 0 otherwise
}

// Function to log the sensor state
void log_sensor_state(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %s, Sensor 2: %s\n", timestamp, sensor1_state ? "Object Present" : "No Object", sensor2_state ? "Object Present" : "No Object");

    if (sensor1_state && sensor2_state) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Request the GPIO lines as input
    sensor1_line = gpiod_line_request_input(chip, SENSOR1_PIN, "sensor1");
    if (!sensor1_line) {
        fprintf(stderr, "Error: Could not request GPIO %d as input\n", SENSOR1_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_line_request_input(chip, SENSOR2_PIN, "sensor2");
    if (!sensor2_line) {
        fprintf(stderr, "Error: Could not request GPIO %d as input\n", SENSOR2_PIN);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = debounce(SENSOR1_PIN, DEBOUNCE_SAMPLES);
        int sensor2_state = debounce(SENSOR2_PIN, DEBOUNCE_SAMPLES);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error: Debouncing failed for one or more sensors\n");
        } else {
            log_sensor_state(sensor1_state, sensor2_state);
        }

        sleep(1); // Wait for 1 second
    }

    return 0;
}

