#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/wait.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_FORMAT "jpeg"
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%SZ"

// Global variables
static volatile int running = 1;
static int gpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int detect_motion();
int capture_image();
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }
    gpio_initialized = 1;

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    log_event("GPIO initialized successfully");
    return 0;
}

// Function to detect motion
int detect_motion() {
    static int last_state = 0;
    int current_state = gpioRead(GPIO_PIN);

    if (current_state != last_state) {
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            last_state = current_state;
            return 1; // Motion detected
        }
    }

    return 0; // No motion detected
}

// Function to capture image
int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];
    int status;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Construct filename
    snprintf(filename, sizeof(filename), "/home/pi/security_cam/%s.jpg", TIMESTAMP_FORMAT);

    // Construct command
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 1280 --height 720 --format jpeg --timeout 1000", filename);

    // Execute command
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp("libcamera-still", "libcamera-still", "-o", filename, "--width", "1280", "--height", "720", "--format", IMAGE_FORMAT, (char *)NULL);
        perror("execlp failed");
        exit(1);
    } else if (pid < 0) {
        // Fork failed
        perror("fork failed");
        log_event("Image capture failed: Fork failed");
        return -1;
    } else {
        // Parent process
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) != 0) {
                log_event("Image capture failed: Exit status is not 0");
                return -1;
            }
        } else {
            log_event("Image capture failed: Waitpid returned an error");
            return -1;
        }
    }

    log_event("Image captured successfully");
    return 0;
}

// Function to log events
int log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, stopping...");
}

int main() {
    // Open syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_event("Starting security camera system");

    // Main loop
    while (running) {
        if (detect_motion()) {
            if (capture_image() != 0) {
                log_event("Image capture failed");
            }
        }
        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup
    log_event("Stopping security camera system");
    gpioTerminate();
    closelog();

    return 0;
}

