void cleanup(v4l2_device_t *device);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// V4L2 initialization function
int v4l2_init(v4l2_device_t *device) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the video device
    device->fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (device->fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(device->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying device capabilities");
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(device->fd);
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24; // Request RGB24 format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(device->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting video format");
        close(device->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(device->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(device->fd);
        return -1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(device->fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(device->fd);
        return -1;
    }

    device->buffer_size = buf.length;
    device->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, device->fd, buf.m.offset);
    if (device->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(device->fd);
        return -1;
    }

    return 0;
}

// V4L2 close function
int v4l2_close(v4l2_device_t *device) {
    if (device->fd >= 0) {
        if (munmap(device->buffer, device->buffer_size) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
        close(device->fd);
        device->fd = -1;
        device->buffer = NULL;
        device->buffer_size = 0;
    }
    return 0;
}

// V4L2 set format function
int v4l2_set_format(v4l2_device_t *device, int width, int height, int fps) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24; // Request RGB24 format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(device->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting video format");
        return -1;
    }

    return 0;
}

// V4L2 start capturing function
int v4l2_start_capturing(v4l2_device_t *device) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(device->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(device->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// V4L2 stop capturing function
int v4l2_stop_capturing(v4l2_device_t *device) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(device->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// V4L2 read frame function
int v4l2_read_frame(v4l2_device_t *device, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(device->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (memcpy(buffer, device->buffer + buf.bytesused, buffer_size) < 0) {
        perror("Error copying frame data");
        return -1;
    }

    if (ioctl(device->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// V4L2 write frame function
int v4l2_write_frame(v4l2_device_t *device, const void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(device->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    if (ioctl(device->fd, VIDIOC_STREAMING, &buf) < 0) {
        perror("Error starting stream");
        return -1;
    }

    if (ioctl(device->fd, VIDIOC_SMBUF, &buf) < 0) {
        perror("Error setting SMBUF");
        return -1;
    }

    if (memcpy(device->buffer, buffer, buffer_size) < 0) {
        perror("Error copying frame data");
        return -1;
    }

    if (ioctl(device->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Log timestamp function
int log_timestamp(FILE *log_file, long long timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%lld\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup function
void cleanup(v4l2_device_t *device) {
    if (device->fd >= 0) {
        v4l2_close(device);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    struct timeval tv;
    fd_set readfds;
    int max_fd;
    int i;
    void *buffer = NULL;
    size_t buffer_size = 0;
    long long timestamp;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize V4L2 device
    if (v4l2_init(&device) < 0) {
        fprintf(stderr, "V4L2 initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup(&device);
        return 1;
    }

    // Set up file descriptor set for select()
    FD_ZERO(&readfds);
    FD_SET(device.fd, &readfds);

    // Get the maximum file descriptor
    max_fd = device.fd;

    // Main loop
    while (!terminate) {
        // Use select() to wait for I/O on the video device
        ret = select(max_fd + 1, &readfds, NULL, NULL, NULL);
        if (ret < 0) {
            perror("Error in select()");
            break;
        } else if (ret == 0) {
            // Timeout occurred, no data available
            continue;
        } else {
            // Data is available on the video device
            if (v4l2_read_frame(&device, buffer, buffer_size) == 0) {
                // Get timestamp
                if (gettimeofday(&tv, NULL) == 0) {
                    timestamp = (long long)tv.tv_sec * 1000000LL + (long long)tv.tv_usec;
                    if (log_timestamp(log_file, timestamp) != 0) {
                        fprintf(stderr, "Error logging timestamp.\n");
                    }
                } else {
                    perror("Error getting timestamp");
                }
            } else {
                fprintf(stderr, "Error reading frame.\n");
            }
        }
    }

    // Cleanup and exit
    cleanup(&device);
    return 0;
}

