#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define VIDEO_DEVICE "/dev/video0"
#define MAX_FRAMES 10
#define MAX_FRAGMENT_SIZE 65000
#define MAX_HEADER_SIZE 16
#define MAX_FRAME_SIZE 640 * 480 * 2 // YUYV

// Structure to hold frame data
typedef struct {
    unsigned char *y;
    unsigned char *u;
    unsigned char *v;
} frame_t;

// Structure to hold frame information
typedef struct {
    int index;
    int fragment_index;
    int total_fragment_count;
    int payload_size;
} frame_info_t;

// Global variables
int video_fd = -1;
int socket_fd = -1;
struct sockaddr_in server_addr;
frame_t *frames = NULL;
frame_info_t *frame_info = NULL;
int frame_count = 0;
int fragment_count = 0;
int running = 1;

// Function prototypes
int init_video_device(const char *device);
int init_mmap(int fd, void **map, size_t *size);
int capture_frame(frame_t *frame);
int fragment_frame(frame_t *frame, int index, int fragment_index, int total_fragment_count, int payload_size);
int send_udp_packet(const char *header, const char *data, int data_len);
void signal_handler(int sig);
void cleanup();

// Initialize video device
int init_video_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    // Set the device to YUYV format
    unsigned int format = V4L2_BUF_FORMAT_YUYV;
    if (ioctl(fd, VIDIOC_S_FMT, &format) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize mmap
int init_mmap(int fd, void **map, size_t *size) {
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *size = buf.bytesused;
    *map = mmap(NULL, *size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*map == MAP_FAILED) {
        perror("Error mapping buffer");
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error requeuing buffer");
            return -1;
        }
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        munmap(*map, *size);
        return -1;
    }

    return 0;
}

// Capture a frame
int capture_frame(frame_t *frame) {
    frame->y = (unsigned char *)frame->y + frame->payload_size;
    frame->u = (unsigned char *)frame->u + frame->payload_size;
    frame->v = (unsigned char *)frame->v + frame->payload_size;

    if (ioctl(video_fd, VIDIOC_DQBUF, NULL) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    frame->payload_size = frame->y - frame->u - frame->v;
    frame->y = (unsigned char *)frame->y;
    frame->u = (unsigned char *)frame->u;
    frame->v = (unsigned char *)frame->v;

    return 0;
}

// Fragment a frame
int fragment_frame(frame_t *frame, int index, int fragment_index, int total_fragment_count, int payload_size) {
    if (fragment_index >= total_fragment_count) {
        fprintf(stderr, "Error: Fragment index out of bounds\n");
        return -1;
    }

    // Calculate the start and end addresses of the fragment
    int start = index * MAX_FRAME_SIZE + fragment_index * MAX_FRAGMENT_SIZE;
    int end = start + MAX_FRAGMENT_SIZE;

    // Copy the fragment to the output buffer
    memcpy(frame->y + start, frame->y + index * MAX_FRAME_SIZE + fragment_index * MAX_FRAGMENT_SIZE, MAX_FRAGMENT_SIZE);
    memcpy(frame->u + start, frame->u + index * MAX_FRAME_SIZE + fragment_index * MAX_FRAGMENT_SIZE, MAX_FRAGMENT_SIZE);
    memcpy(frame->v + start, frame->v + index * MAX_FRAME_SIZE + fragment_index * MAX_FRAGMENT_SIZE, MAX_FRAGMENT_SIZE);

    return 0;
}

// Send UDP packet
int send_udp_packet(const char *header, const char *data, int data_len) {
    if (sendto(socket_fd, data, data_len, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    printf("Signal received, stopping...\n");
    running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop streaming
    if (video_fd != -1) {
        ioctl(video_fd, VIDIOC_STREAMOFF, NULL);
    }

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Unmap buffers
    if (frames != NULL) {
        for (int i = 0; i < frame_count; i++) {
            munmap(frames[i].y, MAX_FRAME_SIZE);
            munmap(frames[i].u, MAX_FRAME_SIZE);
            munmap(frames[i].v, MAX_FRAME_SIZE);
        }
        free(frames);
    }

    if (frame_info != NULL) {
        free(frame_info);
    }

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize video device
    video_fd = init_video_device(VIDEO_DEVICE);
    if (video_fd < 0) {
        return 1;
    }

    // Initialize mmap
    frames = (frame_t *)malloc(MAX_FRAMES * sizeof(frame_t));
    frame_info = (frame_info_t *)malloc(MAX_FRAMES * sizeof(frame_info_t));
    if (frames == NULL || frame_info == NULL) {
        perror("Error allocating memory");
        cleanup();
        return 1;
    }

    // Initialize frame information
    for (int i = 0; i < MAX_FRAMES; i++) {
        frames[i].y = (unsigned char *)malloc(MAX_FRAME_SIZE);
        frames[i].u = (unsigned char *)malloc(MAX_FRAME_SIZE);
        frames[i].v = (unsigned char *)malloc(MAX_FRAME_SIZE);
        frame_info[i].index = i;
        frame_info[i].fragment_index = 0;
        frame_info[i].total_fragment_count = 0;
        frame_info[i].payload_size = 0;
    }

    // Create UDP socket
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Error converting IP address");
        cleanup();
        return 1;
    }

    // Start streaming
    printf("Starting streaming...\n");

    while (running) {
        // Capture frame
        if (capture_frame(&frames[frame_count % MAX_FRAMES]) == 0) {
            // Fragment frame
            if (fragment_count < MAX_FRAMES) {
                if (fragment_frame(&frames[frame_count % MAX_FRAMES], frame_count, fragment_count, MAX_FRAMES, MAX_FRAME_SIZE) == 0) {
                    frame_info[frame_count % MAX_FRAMES].total_fragment_count = MAX_FRAMES;
                    frame_info[frame_count % MAX_FRAMES].fragment_index = 0;
                    frame_info[frame_count % MAX_FRAMES].index = frame_count;
                    frame_info[frame_count % MAX_FRAMES].payload_size = MAX_FRAME_SIZE;

                    // Send UDP packet
                    char header[MAX_HEADER_SIZE];
                    snprintf(header, MAX_HEADER_SIZE, "%d,%d,%d,%d",
                             frame_count, fragment_count, MAX_FRAMES, MAX_FRAME_SIZE);

                    if (send_udp_packet(header, frames[frame_count % MAX_FRAMES].y, MAX_FRAME_SIZE) != 0) {
                        running = 0; // Stop if sending fails
                    }

                    fragment_count++;
                } else {
                    running = 0; // Stop if fragmenting fails
                }
            } else {
                running = 0; // Stop if buffer is full
            }
        } else {
            running = 0; // Stop if capturing fails
        }

        frame_count++;
        if (frame_count >= MAX_FRAMES) {
            frame_count = 0;
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

