    if (frame_info != NULL) {
        free(frame_info);
    }

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize video device
    video_fd = init_video_device(VIDEO_DEVICE);
    if (video_fd < 0) {
        return 1;
    }

    // Initialize mmap
    frames = (frame_t *)malloc(MAX_FRAMES * sizeof(frame_t));
    frame_info = (frame_info_t *)malloc(MAX_FRAMES * sizeof(frame_info_t));
    if (frames == NULL || frame_info == NULL) {
        perror("Error allocating memory");
        cleanup();
        return 1;
    }

    // Initialize frame information
    for (int i = 0; i < MAX_FRAMES; i++) {
        frames[i].y = (unsigned char *)malloc(MAX_FRAME_SIZE);
        frames[i].u = (unsigned char *)malloc(MAX_FRAME_SIZE);
        frames[i].v = (unsigned char *)malloc(MAX_FRAME_SIZE);
        frame_info[i].index = i;
        frame_info[i].fragment_index = 0;
        frame_info[i].total_fragment_count = 0;
        frame_info[i].payload_size = 0;
    }

    // Create UDP socket
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Error converting IP address");
        cleanup();
        return 1;
    }

    // Start streaming
    printf("Starting streaming...\n");

    while (running) {
        // Capture frame
        if (capture_frame(&frames[frame_count % MAX_FRAMES]) == 0) {
            // Fragment frame
            if (fragment_count < MAX_FRAMES) {
                if (fragment_frame(&frames[frame_count % MAX_FRAMES], frame_count, fragment_count, MAX_FRAMES, MAX_FRAME_SIZE) == 0) {
                    frame_info[frame_count % MAX_FRAMES].total_fragment_count = MAX_FRAMES;
                    frame_info[frame_count % MAX_FRAMES].fragment_index = 0;
                    frame_info[frame_count % MAX_FRAMES].index = frame_count;
                    frame_info[frame_count % MAX_FRAMES].payload_size = MAX_FRAME_SIZE;

                    // Send UDP packet
                    char header[MAX_HEADER_SIZE];
                    snprintf(header, MAX_HEADER_SIZE, "%d,%d,%d,%d",
                             frame_count, fragment_count, MAX_FRAMES, MAX_FRAME_SIZE);

                    if (send_udp_packet(header, frames[frame_count % MAX_FRAMES].y, MAX_FRAME_SIZE) != 0) {
                        running = 0; // Stop if sending fails
                    }

                    fragment_count++;
                } else {
                    running = 0; // Stop if fragmenting fails
                }
            } else {
                running = 0; // Stop if buffer is full
            }
        } else {
            running = 0; // Stop if capturing fails
        }

        frame_count++;
        if (frame_count >= MAX_FRAMES) {
            frame_count = 0;
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

