#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <syslog.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define IMAGE_SIZE   (IMAGE_WIDTH * IMAGE_HEIGHT * 3) // Assuming RGB24
#define BUFFER_SIZE  (IMAGE_SIZE * 4) // 4 bytes per pixel (RGB24)
#define NUM_BUFFERS  4

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, stopping...");
    stop_flag = 1;
}

int main() {
    int fd, i;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_mmap buf_mmap;
    unsigned char *buffer;
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    openlog("image_capture", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open device %s: %s", DEVICE_NAME, strerror(errno));
        perror("open");
        closelog();
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        syslog(LOG_ERR, "VIDIOC_QUERYCAP failed: %s", strerror(errno));
        perror("VIDIOC_QUERYCAP");
        close(fd);
        closelog();
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        syslog(LOG_ERR, "Device does not support video capture.");
        close(fd);
        closelog();
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        syslog(LOG_ERR, "Device does not support streaming I/O.");
        close(fd);
        closelog();
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        syslog(LOG_ERR, "VIDIOC_S_FMT failed: %s", strerror(errno));
        perror("VIDIOC_S_FMT");
        close(fd);
        closelog();
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        syslog(LOG_ERR, "VIDIOC_REQBUFS failed: %s", strerror(errno));
        perror("VIDIOC_REQBUFS");
        close(fd);
        closelog();
        return 1;
    }

    buffer = calloc(req.count, sizeof(*buffer));
    if (!buffer) {
        syslog(LOG_ERR, "Failed to allocate memory for buffers.");
        perror("calloc");
        close(fd);
        closelog();
        return 1;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            syslog(LOG_ERR, "VIDIOC_QUERYBUF failed: %s", strerror(errno));
            perror("VIDIOC_QUERYBUF");
            close(fd);
            closelog();
            free(buffer);
            return 1;
        }

        buf_mmap.page_length = buf.length;
        buf_mmap.m.offset = 0;
        buf_mmap.m.mem = buffer + buf.m.offset;

        if (ioctl(fd, VIDIOC_MMAP, &buf_mmap) < 0) {
            syslog(LOG_ERR, "VIDIOC_MMAP failed: %s", strerror(errno));
            perror("VIDIOC_MMAP");
            close(fd);
            closelog();
            free(buffer);
            return 1;
        }
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            syslog(LOG_ERR, "VIDIOC_QBUF failed: %s", strerror(errno));
            perror("VIDIOC_QBUF");
            close(fd);
            closelog();
            free(buffer);
            return 1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        syslog(LOG_ERR, "VIDIOC_STREAMON failed: %s", strerror(errno));
        perror("VIDIOC_STREAMON");
        close(fd);
        closelog();
        free(buffer);
        return 1;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("image.jpg", "wb");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open image file for writing.");
        perror("fopen");
        close(fd);
        closelog();
        free(buffer);
        return 1;
    }

    while (!stop_flag) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            syslog(LOG_ERR, "VIDIOC_DQBUF failed: %s", strerror(errno));
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.bytesused > 0) {
            if (fwrite(buffer + buf.bytesused, 1, buf.bytesused, fp) != buf.bytesused) {
                syslog(LOG_ERR, "Failed to write image data to file.");
                perror("fwrite");
                break;
            }
        } else {
            syslog(LOG_WARNING, "Empty frame received, skipping.");
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            syslog(LOG_ERR, "VIDIOC_QBUF failed: %s", strerror(errno));
            perror("VIDIOC_QBUF");
            break;
        }
    }

    fclose(fp);
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        syslog(LOG_ERR, "VIDIOC_STREAMOFF failed: %s", strerror(errno));
        perror("VIDIOC_STREAMOFF");
    }

    for (i = 0; i < req.count; i++) {
        if (munmap(buffer + buf.m.offset, buf.length) < 0) {
            syslog(LOG_ERR, "munmap failed: %s", strerror(errno));
            perror("munmap");
        }
    }

    free(buffer);
    close(fd);
    closelog();

    return 0;
}

