#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos and buttons
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define PAN_LEFT_BUTTON_PIN 6
#define PAN_RIGHT_BUTTON_PIN 7
#define TILT_UP_BUTTON_PIN 8
#define TILT_DOWN_BUTTON_PIN 9

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Define servo pulse width limits (1-2 ms)
#define SERVO_MIN_PULSE_WIDTH 1
#define SERVO_MAX_PULSE_WIDTH 2

// Define servo center point (75)
#define SERVO_CENTER 75

// Global variables for servo positions
int pan_position = SERVO_CENTER;
int tilt_position = SERVO_CENTER;

// Function prototypes
int set_servo_position(int gpio_pin, int position);
int read_button(int gpio_pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to set servo position using PWM
int set_servo_position(int gpio_pin, int position) {
    // Clamp position to valid range
    if (position < 25) position = 25;
    if (position > 125) position = 125;

    // Calculate pulse width (0-1000)
    int pulse_width = (int)(((float)(position - SERVO_CENTER) / (125 - SERVO_CENTER)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);

    // Set PWM duty cycle
    gpioServo(gpio_pin, pulse_width);

    return 0; // Return 0 for success
}

// Function to read button state
int read_button(int gpio_pin) {
    int button_state = gpioRead(gpio_pin);
    if (button_state < 0) {
        fprintf(stderr, "Error reading button on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return button_state;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read button states
        int pan_left_button_state = read_button(PAN_LEFT_BUTTON_PIN);
        int pan_right_button_state = read_button(PAN_RIGHT_BUTTON_PIN);
        int tilt_up_button_state = read_button(TILT_UP_BUTTON_PIN);
        int tilt_down_button_state = read_button(TILT_DOWN_BUTTON_PIN);

        // Update servo positions based on button presses
        if (pan_left_button_state == 0) {
            pan_position -= 5;
            if (pan_position < 25) pan_position = 25;
        }
        if (pan_right_button_state == 0) {
            pan_position += 5;
            if (pan_position > 125) pan_position = 125;
        }
        if (tilt_up_button_state == 0) {
            tilt_position += 5;
            if (tilt_position > 125) tilt_position = 125;
        }
        if (tilt_down_button_state == 0) {
            tilt_position -= 5;
            if (tilt_position < 25) tilt_position = 25;
        }

        // Set servo positions
        set_servo_position(PAN_SERVO_PIN, pan_position);
        set_servo_position(TILT_SERVO_PIN, tilt_position);

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 us
    }

    return 0;
}

