#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>
#include <jpeglib.h>
#include <math.h>

// Configuration
#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define JPEG_QUALITY 75
#define BLUR_RADIUS 2
#define BUFFER_COUNT 4
#define FRAME_TIMEOUT 2 // seconds

// Structure to hold frame data
typedef struct {
    unsigned char *data;
    size_t size;
} frame_t;

// Global variables
int video_fd = -1;
frame_t *frames = NULL;
int buffer_count = 0;
int current_buffer = 0;
int running = 1;

// Function prototypes
int init_camera();
int capture_frame(frame_t *frame);
int apply_blur(frame_t *frame);
int save_jpeg(const frame_t *frame, const char *filename);
void cleanup();
void signal_handler(int sig);

// Box blur kernel
const int kernel[5][5] = {
    {0, 1, 0}, {1, 4, 1}, {0, 1, 0}
};

// Function to apply box blur
void apply_blur(frame_t *frame) {
    int x, y;
    unsigned char *data = frame->data;
    int radius = BLUR_RADIUS;
    int kernel_size = 5;

    for (int i = 0; i < HEIGHT; i += kernel_size) {
        for (int j = 0; j < WIDTH; j += kernel_size) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            int count = 0;

            for (int k = -radius; k <= radius; k++) {
                for (int l = -radius; l <= radius; l++) {
                    int x1 = j + k;
                    int y1 = i + l;

                    if (x1 >= 0 && x1 < WIDTH && y1 >= 0 && y1 < HEIGHT) {
                        sum_r += data[(y1 * WIDTH + x1) * 2];
                        sum_g += data[(y1 * WIDTH + x1) * 2 + 1];
                        sum_b += data[(y1 * WIDTH + x1) * 2 + 2];
                        count++;
                    }
                }
            }

            // Clamp values
            int r = (int)(((float)sum_r / count) * 255.0 / 255.0);
            int g = (int)(((float)sum_g / count) * 255.0 / 255.0);
            int b = (int)(((float)sum_b / count) * 255.0 / 255.0);

            // Set the pixel value in the output frame
            data[(i * WIDTH + j) * 3 + 0] = r;
            data[(i * WIDTH + j) * 3 + 1] = g;
            data[(i * WIDTH + j) * 3 + 2] = b;
        }
    }
}

// Function to save JPEG image
int save_jpeg(const frame_t *frame, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "can't open %s\n", filename);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = frame->size / 3; // RGB24
    cinfo.image_height = frame->size / 3;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = frame->size / 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &frame->data[cinfo.next_scanline * row_stride];
        (void)jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Function to initialize the camera
int init_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the video device
    video_fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (video_fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    // Check capabilities
    if (ioctl(video_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(video_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", VIDEO_DEVICE);
        close(video_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", VIDEO_DEVICE);
        close(video_fd);
        return -1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(video_fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(video_fd);
        return -1;
    }

    // Map the buffers
    frames = calloc(req.count, sizeof(*frames));
    if (!frames) {
        perror("Out of memory");
        close(video_fd);
        return -1;
    }

    for (buffer_count = 0; buffer_count < req.count; ++buffer_count) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = buffer_count;

        if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(video_fd);
            free(frames);
            return -1;
        }

        frames[buffer_count].size = buf.length;
        frames[buffer_count].data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);

        if (frames[buffer_count].data == MAP_FAILED) {
            perror("Error mapping buffer");
            close(video_fd);
            free(frames);
            return -1;
        }
    }

    // Queue the buffers
    for (buffer_count = 0; buffer_count < req.count; ++buffer_count) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = buffer_count;

        if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(video_fd);
            free(frames);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(video_fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(video_fd);
        free(frames);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(frame_t *frame) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    frame->size = buf.bytesused;
    frame->data = frames[buf.index].data;

    if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    running = 0; // Signal the main loop to exit

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ioctl(video_fd, VIDIOC_STREAMOFF, &type);

    // Free buffers
    for (int i = 0; i < buffer_count; i++) {
        munmap(frames[i].data, frames[i].size);
    }
    free(frames);

    // Close the video device
    if (video_fd != -1) {
        close(video_fd);
    }
}

// Signal handler for SIGINT
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        cleanup();
        exit(0);
    }
}

int main() {
    struct timeval tv;
    fd_set rfds;
    int r;
    char filename[32];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize camera
    if (init_camera() < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Allocate memory for frames
    frames = calloc(BUFFER_COUNT, sizeof(*frames));
    if (!frames) {
        perror("Out of memory");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        fd_set rfds;
        struct timeval tv;
        int r;

        // Set up file descriptor set
        FD_ZERO(&rfds);
        FD_SET(video_fd, &rfds);

        // Set timeout
        tv.tv_sec = FRAME_TIMEOUT;
        tv.tv_usec = 0;

        // Wait for a timeout or a signal
        r = select(video_fd + 1, &rfds, NULL, NULL, &tv);

        if (r == -1) {
            perror("select() error");
            cleanup();
            return 1;
        } else if (r == 0) {
            // Timeout occurred
            printf("Timeout waiting for frame\n");
        } else {
            // Frame is available
            if (capture_frame(&frames[current_buffer]) < 0) {
                fprintf(stderr, "Error capturing frame\n");
                cleanup();
                return 1;
            }

            // Apply blur
            apply_blur(&frames[current_buffer]);

            // Generate filename
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            snprintf(filename, sizeof(filename), "capture_%04d%02d%02d_%02d%02d%02d.jpg",
                     tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

            // Save JPEG
            if (save_jpeg(&frames[current_buffer], filename) < 0) {
                fprintf(stderr, "Error saving JPEG image\n");
            } else {
                printf("Saved JPEG image: %s\n", filename);
            }

            // Move to the next buffer
            current_buffer = (current_buffer + 1) % buffer_count;
        }
    }

    // Cleanup resources
    cleanup();

    return 0;
}

