        streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        streamparm.parm.capture.timeperframe.numerator = 1;
        streamparm.parm.capture.timeperframe.denominator = 1; // 1 frame per second
        streamparm.parm.capture.timeperframe.numerator = 0;
        streamparm.parm.capture.timeperframe.denominator = 0; // 0 seconds per frame

        if (ioctl(fd, VIDIOC_S_PARM, &streamparm) < 0) {
            perror("VIDIOC_S_PARM failed");
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Enumerate frame sizes
        if (enum_frame_sizes(fd) < 0) {
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Enumerate frame intervals
        if (enum_frame_intervals(fd) < 0) {
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Print device information
        print_device_info(fd);

        // Free buffers
        for (i = 0; i < req.count; i++) {
            struct v4l2_buffer buf;
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF failed");
            }
        }

        // Queue buffers
        for (i = 0; i < req.count; i++) {
            struct v4l2_buffer buf;
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF failed");
            }
        }

        // Start streaming
        enum_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMON, &enum_buf) < 0) {
            perror("VIDIOC_STREAMON failed");
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Main loop (optional)
        // Read and print frames here
        // For example:
        // struct v4l2_buffer buf;
        // buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        // buf.memory = V4L2_MEMORY_MMAP;
        // buf.index = 0;
        // if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        //     perror("VIDIOC_DQBUF failed");
        // }
        // // Process the frame here
        // if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        //     perror("VIDIOC_QBUF failed");
        // }

        // Stop streaming
        enum_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &enum_buf) < 0) {
            perror("VIDIOC_STREAMOFF failed");
        }

        // Free buffers
        for (i = 0; i < req.count; i++) {
            struct v4l2_buffer buf;
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF failed");
            }
        }

        // Unrequest buffers
        memset(&req, 0, sizeof(req));
        req.count = 0;
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
            perror("VIDIOC_REQBUFS failed");
        }

        // Re-initialize device
        close(fd);
        fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
        if (fd < 0) {
            perror("Failed to open device");
            continue; // Try the next device
        }
        devices[i].fd = fd;
        devices[i].supported = 0; // Initialize supported flags
        if (init_device(fd) < 0) {
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Check autofocus support
        if (check_autofocus_support(fd) < 0) {
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Set format
        memset(&fmt, 0, sizeof(fmt));
        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = devices[0].supported.width;
        fmt.fmt.pix.height = devices[0].supported.height;
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Try MJPEG first
        fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

        if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
            perror("VIDIOC_S_FMT failed");
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Request buffers
        memset(&req, 0, sizeof(req));
        req.count = 1; // Request only one buffer
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
            perror("VIDIOC_REQBUFS failed");
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Start streaming
        enum_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMON, &enum_buf) < 0) {
            perror("VIDIOC_STREAMON failed");
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Enumerate frame sizes
        if (enum_frame_sizes(fd) < 0) {
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Enumerate frame intervals
        if (enum_frame_intervals(fd) < 0) {
            close(fd);
            devices[i].fd = -1;
            devices[i].supported = 0;
            num_devices--;
            continue;
        }

        // Print device information
        print_device_info(fd);

        // Free buffers
        for (i = 0; i < req.count; i++) {
            struct v4l2_buffer buf;
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF failed");
            }
        }

        // Queue buffers
        for (i = 0; i < req.count; i++) {
            struct v4l2_buffer buf;
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF failed");
            }
        }

        // Stop streaming
        enum_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &enum_buf) < 0) {
            perror("VIDIOC_STREAMOFF failed");
        }

        // Unrequest buffers
        memset(&req, 0, sizeof(req));
        req.count = 0;
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
            perror("VIDIOC_REQBUFS failed");
        }

    }

    // Print summary
    printf("Summary:\n");
    for (i = 0; i < num_devices; i++) {
        if (devices[i].fd != -1) {
            printf("Device: %s\n", devices[i].device_name);
            printf("Supported Resolutions:\n");
            printf("  %dx%d\n", devices[i].supported.width, devices[i].supported.height);
            printf("Supported Frame Rates:\n");
            printf("  %d\n", devices[i].supported.framerate);
            printf("Autofocus Support: %s\n", devices[i].supported.autofocus ? "Yes" : "No");
            printf("Frame Intervals:\n");
            printf("  %d\n", devices[i].supported.interval);
            printf("\n");
        }
    }

    return 0;
}

