#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for servos and buttons
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo center position (microseconds)
#define SERVO_CENTER 1500

// Define servo range (microseconds)
#define SERVO_RANGE 1000

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Global variables to store servo positions
int pan_position = SERVO_CENTER;
int tilt_position = SERVO_CENTER;

// Function prototypes
void signal_handler(int signal);
void setup_gpio();
void cleanup_gpio();
void set_servo_position(int gpio, int position);
void update_servo_positions();
void check_buttons();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO pins
void setup_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    // Set GPIO modes for servos
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set GPIO modes for buttons
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable internal pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency for servos
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set servo positions to center
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    printf("GPIO setup complete. Pin assignments:\n");
    printf("  Pan Servo: GPIO %d, Position: %d us\n", PAN_SERVO_PIN, pan_position);
    printf("  Tilt Servo: GPIO %d, Position: %d us\n", TILT_SERVO_PIN, tilt_position);
    printf("  UP Button: GPIO %d\n", UP_BUTTON_PIN);
    printf("  DOWN Button: GPIO %d\n", DOWN_BUTTON_PIN);
    printf("  LEFT Button: GPIO %d\n", LEFT_BUTTON_PIN);
    printf("  RIGHT Button: GPIO %d\n", RIGHT_BUTTON_PIN);
}

// Cleanup GPIO resources
void cleanup_gpio() {
    // Stop PWM on both servo pins
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();
}

// Set servo position using gpioServo
void set_servo_position(int gpio, int position) {
    // Ensure position is within valid range
    if (position < 1000) position = 1000;
    if (position > 2000) position = 2000;

    // Calculate pulse width in microseconds
    int pulse_width = (position - 1000) * 1000 / 1000; // Scale to 1000-2000 range

    // Set PWM duty cycle
    gpioServo(gpio, pulse_width);
}

// Update servo positions based on button input
void update_servo_positions() {
    // Check UP button
    if (gpioRead(UP_BUTTON_PIN) == 0) {
        pan_position += 10;
        if (pan_position > 2000) pan_position = 2000;
        if (pan_position < 1000) pan_position = 1000;
        set_servo_position(PAN_SERVO_PIN, pan_position);
    }

    // Check DOWN button
    if (gpioRead(DOWN_BUTTON_PIN) == 0) {
        pan_position -= 10;
        if (pan_position > 2000) pan_position = 2000;
        if (pan_position < 1000) pan_position = 1000;
        set_servo_position(PAN_SERVO_PIN, pan_position);
    }

    // Check LEFT button
    if (gpioRead(LEFT_BUTTON_PIN) == 0) {
        tilt_position += 10;
        if (tilt_position > 2000) tilt_position = 2000;
        if (tilt_position < 1000) tilt_position = 1000;
        set_servo_position(TILT_SERVO_PIN, tilt_position);
    }

    // Check RIGHT button
    if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
        tilt_position -= 10;
        if (tilt_position > 2000) tilt_position = 2000;
        if (tilt_position < 1000) tilt_position = 1000;
        set_servo_position(TILT_SERVO_PIN, tilt_position);
    }
}

// Check buttons for input
void check_buttons() {
    update_servo_positions();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    setup_gpio();

    // Main loop
    while (1) {
        check_buttons();
        gpioDelay(50); // Delay for 50ms
    }

    return 0;
}

