#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 2000 // milliseconds
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85

// Global variables
static volatile int running = 1;
static char *server_ip = NULL;
static int server_port = 0;
static int socket_fd = -1;
static char *motion_captures_dir = NULL;

// Function prototypes
int initialize_gpio();
int detect_motion();
int capture_image(const char *filename);
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Structure to hold the response data from libcurl
struct MemoryStruct {
  char *memory;
  size_t size;
};

// Callback function to write the response data to memory
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
  size_t realsize = size * nmemb;
  struct MemoryStruct *mem = (struct MemoryStruct *)userp;

  char *ptr = realloc(mem->memory, mem->size + realsize + 1);
  if (ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    return 0;
  }

  mem->memory = ptr;
  memcpy(&(mem->memory[mem->size]), contents, realsize);
  mem->size += realsize;
  mem->memory[mem->size] = 0;

  return realsize;
}

// Function to initialize the GPIO pin
int initialize_gpio() {
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return -1;
  }

  gpioSetMode(GPIO_PIN, PI_INPUT);
  gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

  return 0;
}

// Function to detect motion
int detect_motion() {
  if (gpioRead(GPIO_PIN) == 1) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
    if (gpioRead(GPIO_PIN) == 1) {
      return 1; // Motion detected
    }
  }
  return 0; // No motion
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
  char command[256];
  snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --quality %d --timeout 1000", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
  int status = system(command);
  if (status == -1) {
    fprintf(stderr, "Error executing libcamera-still command: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// Function to send data to the server
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
  CURL *curl;
  CURLcode res;
  struct curl_slist *headers = NULL;
  char json_data[256];

  // Create JSON payload
  snprintf(json_data, sizeof(json_data), "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}", filename, timestamp, motion_status, gpio_pin);

  curl_global_init(CURL_GLOBAL_ALL);
  curl = curl_easy_init();
  if (curl) {
    curl_easy_setopt(curl, CURLOPT_URL, server_ip);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

    // Set content type to application/json
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Set write callback to store the response
    struct MemoryStruct chunk;
    chunk.memory = malloc(1);
    chunk.size = 0;
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
      long response_code;
      curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
      if (response_code == 201) {
        printf("Data sent successfully\n");
      } else {
        fprintf(stderr, "Failed to send data. Response code: %ld\n", response_code);
      }
    }

    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
  } else {
    fprintf(stderr, "curl_easy_init() failed\n");
    curl_global_cleanup();
    return -1;
  }
  curl_global_cleanup();
  return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
  running = 0;
  printf("Signal received, exiting...\n");
}

// Cleanup function to release resources
void cleanup() {
  if (socket_fd != -1) {
    close(socket_fd);
  }
  if (motion_captures_dir != NULL) {
    rmdir(motion_captures_dir);
  }
  gpioTerminate();
  curl_global_cleanup();
}

int main(int argc, char *argv[]) {
  if (argc != 3) {
    fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
    return 1;
  }

  server_ip = argv[1];
  server_port = atoi(argv[2]);

  if (gpioInitialise() < 0) {
    return 1;
  }

  if (initialize_gpio() != 0) {
    gpioTerminate();
    return 1;
  }

  // Create motion_captures directory if it doesn't exist
  if (mkdir("motion_captures", 0777) == -1 && errno != EEXIST) {
    fprintf(stderr, "Error creating motion_captures directory: %s\n", strerror(errno));
    cleanup();
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (running) {
    if (detect_motion()) {
      // Generate timestamp
      time_t rawtime;
      struct tm *timeinfo;
      char timestamp[30];
      time(&rawtime);
      timeinfo = localtime(&rawtime);
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

      // Capture image
      char filename[256];
      snprintf(filename, sizeof(filename), "motion_captures/%s.jpg", timestamp);
      if (capture_image(filename) != 0) {
        fprintf(stderr, "Failed to capture image\n");
        continue; // Skip to the next iteration
      }

      // Send data
      if (send_data(filename, timestamp, 1, GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to send data\n");
      }

      printf("Motion detected, data sent\n");
    }
    gpioDelay(100 * 1000); // Check every 100ms
  }

  cleanup();
  return 0;
}

