#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int detect_motion();
int capture_image(const char *filename);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, cleaning up...");
        terminate = 1;
    }
}

// Initialize GPIO
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Detect motion
int detect_motion() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return 0; // Return 0 to avoid triggering capture on error
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    // Debounce logic
    if (value == 1) {
        struct timespec debounce_ts;
        debounce_ts.tv_sec = 0;
        debounce_ts.tv_nsec = DEBOUNCE_TIME_MS * 1000000; // Convert ms to ns
        nanosleep(&debounce_ts, NULL);

        int debounced_value = gpiod_line_get_value(line);
        if (debounced_value == 1) {
            return 1; // Motion detected
        }
    }

    return 0; // No motion detected
}

// Capture image
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int status = system(command);
    if (status == -1) {
        perror("Error executing libcamera-still");
        return -1;
    }
    return WEXITSTATUS(status);
}

// Log event
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Cleanup resources
void cleanup() {
    log_event("Cleaning up resources...");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("/home/pi/motion_capture.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Starting motion capture program...");

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        log_event("GPIO initialization failed. Exiting.");
        fclose(log_file);
        return 1;
    }

    log_event("GPIO initialized successfully.");

    // Main loop
    while (!terminate) {
        if (detect_motion()) {
            log_event("Motion detected!");
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", t);

            char filename[128];
            snprintf(filename, sizeof(filename), "%s/%s_mmm.jpg", IMAGE_DIR, timestamp);

            int capture_status = capture_image(filename);
            if (capture_status == 0) {
                log_event("Image captured successfully.");
            } else {
                log_event("Image capture failed with status: ");
                log_event( (char*)&capture_status, sizeof(capture_status) );
            }
        }
        usleep(100000); // Check every 100ms
    }

    cleanup();
    log_event("Program terminated.");
    return 0;
}

