#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define neutral angle (90 degrees)
#define NEUTRAL_ANGLE 90

// Define PWM range (500-2500 us)
#define PWM_RANGE 2000

// Global variable to store the current angle
int current_pan_angle = NEUTRAL_ANGLE;
int current_tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
void set_pan_angle(int angle);
void set_tilt_angle(int angle);
void handle_input(char input);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, setting servos to neutral position...\n");
        set_pan_angle(NEUTRAL_ANGLE);
        set_tilt_angle(NEUTRAL_ANGLE);
        gpioTerminate();
        exit(0);
    }
}

// Function to set the pan angle
void set_pan_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Pan angle out of range (0-180). Setting to neutral.\n");
        angle = NEUTRAL_ANGLE;
    }
    int pulse_width = (int)(((float)angle / 180.0) * PWM_RANGE);
    gpioServo(PAN_GPIO, pulse_width);
    current_pan_angle = angle;
}

// Function to set the tilt angle
void set_tilt_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180). Setting to neutral.\n");
        angle = NEUTRAL_ANGLE;
    }
    int pulse_width = (int)(((float)angle / 180.0) * PWM_RANGE);
    gpioServo(TILT_GPIO, pulse_width);
    current_tilt_angle = angle;
}

// Function to handle user input
void handle_input(char input) {
    switch (input) {
        case 'u':
            current_pan_angle += 5;
            if (current_pan_angle > 180) current_pan_angle = 180;
            set_pan_angle(current_pan_angle);
            break;
        case 'd':
            current_pan_angle -= 5;
            if (current_pan_angle < 0) current_pan_angle = 0;
            set_pan_angle(current_pan_angle);
            break;
        case 'l':
            current_tilt_angle -= 5;
            if (current_tilt_angle < 0) current_tilt_angle = 0;
            set_tilt_angle(current_tilt_angle);
            break;
        case 'r':
            current_tilt_angle += 5;
            if (current_tilt_angle > 180) current_tilt_angle = 180;
            set_tilt_angle(current_tilt_angle);
            break;
        case 'q':
            set_pan_angle(NEUTRAL_ANGLE);
            set_tilt_angle(NEUTRAL_ANGLE);
            break;
        default:
            fprintf(stderr, "Error: Invalid input. Please enter u, d, l, r, or q.\n");
            break;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    char input;
    while (1) {
        // Read user input
        input = getchar();

        // Handle input
        if (input != '\n') {
            handle_input(input);
        }

        // Delay to prevent excessive CPU usage
        gpioDelay(100000); // 100 ms
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

