#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define LCD_BACKLIGHT 0x08  // Example backlight control
#define LCD_CLEARDISPLAY 0x01 // Example clear display command
#define LCD_RETURNHOME 0x02  // Example return home command
#define LCD_ENTRYMODESET 0x04 // Example entry mode set command
#define LCD_DISPLAYCONTROL 0x80 // Example display control command
#define LCD_CURSORSHIFT 0x08  // Example cursor shift command
#define LCD_FUNCTIONSET 0x20  // Example function set command

// LCD Commands
#define LCD_SETDDRAMADDR 0x80
#define LCD_CHR 0x40 // Mode - Data
#define LCD_CMD 0x40 // Mode - Command

// LCD Flags
#define LCD_BACKLIGHT_ENABLE 0x04
#define LCD_DISPLAY_ON 0x04
#define LCD_DISPLAY_OFF 0x00
#define LCD_CURSOR_OFF 0x02
#define LCD_CURSOR_ON 0x01
#define LCD_BLINK_OFF 0x00
#define LCD_BLINK_ON 0x08

// Global Variables
volatile int pulse_count = 0;
double flow_rate = 0.0;
double total_volume = 0.0;
int i2c_handle;
int lcd_handle;

// Function Prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
void lcd_init();
void lcd_send_command(unsigned char cmd);
void lcd_send_data(unsigned char data);
void lcd_print_string(const char *str);
void lcd_clear();
void signal_handler(int signal);
void cleanup();

// Function to initialize the LCD
void lcd_init() {
    lcd_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // I2C bus 1, address 0x27, no flags
    if (lcd_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", lcd_handle);
        exit(1);
    }

    // Initialize LCD
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(LCD_FUNCTIONSET | LCD_DISPLAY_ON); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(LCD_DISPLAYCONTROL | LCD_DISPLAY_ON); // Display on, cursor off, blink off
    lcd_send_command(LCD_ENTRYMODESET | LCD_CURSOR_OFF); // Entry mode set - increment cursor
    lcd_clear();

    // Set display address to the top row
    lcd_send_command(LCD_SETDDRAMADDR | 0x00); // DD RAM address
    lcd_send_command(0x00); // Start at column 0
}

// Function to send a command to the LCD
void lcd_send_command(unsigned char cmd) {
    char data[2];
    data[0] = cmd | LCD_BACKLIGHT_ENABLE; // Enable backlight
    i2cWriteDevice(lcd_handle, data, 2);
    gpioDelay(1); // Small delay
    data[0] &= ~LCD_BACKLIGHT_ENABLE; // Disable backlight
    i2cWriteDevice(lcd_handle, data, 2);
    gpioDelay(1); // Small delay
}

// Function to send data to the LCD
void lcd_send_data(unsigned char data) {
    char buffer[2];
    buffer[0] = data | LCD_BACKLIGHT_ENABLE; // Enable backlight
    i2cWriteDevice(lcd_handle, buffer, 2);
    gpioDelay(1); // Small delay
    buffer[0] &= ~LCD_BACKLIGHT_ENABLE; // Disable backlight
    i2cWriteDevice(lcd_handle, buffer, 2);
    gpioDelay(1); // Small delay
}

// Function to print a string to the LCD
void lcd_print_string(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        lcd_send_data(str[i]);
    }
}

// Function to clear the LCD
void lcd_clear() {
