#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

// Define GPIO pins for row anodes
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_rows = sizeof(row_pins) / sizeof(row_pins[0]);

// Define GPIO pins for column cathodes
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_cols = sizeof(col_pins) / sizeof(col_pins[0]);

// Global variables for chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *row_lines[8] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL};
struct gpiod_line *col_lines[8] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL};

// Function to handle signals (Ctrl+C)
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release row lines
    for (int i = 0; i < num_rows; i++) {
        if (row_lines[i] != NULL) {
            gpiod_line_release(row_lines[i]);
        }
    }

    // Release column lines
    for (int i = 0; i < num_cols; i++) {
        if (col_lines[i] != NULL) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Open row lines
    for (int i = 0; i < num_rows; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (row_lines[i] == NULL) {
            perror("Error opening row line");
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "row", 0) < 0) {
            perror("Error requesting row line as output");
            goto cleanup;
        }
    }

    // Open column lines
    for (int i = 0; i < num_cols; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (col_lines[i] == NULL) {
            perror("Error opening column line");
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[i], "col", 0) < 0) {
            perror("Error requesting column line as output");
            goto cleanup;
        }
    }

    return 0;

cleanup:
    // Release previously opened lines
    for (int i = 0; i < num_rows; i++) {
        if (row_lines[i] != NULL) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < num_cols; i++) {
        if (col_lines[i] != NULL) {
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return -1;
}

// Function to set the state of a row
int set_row(int row, int state)
{
    if (row < 0 || row >= num_rows) {
        fprintf(stderr, "Error: Invalid row number: %d\n", row);
        return -1;
    }

    if (state != 0 && state != 1) {
        fprintf(stderr, "Error: Invalid state: %d\n", state);
        return -1;
    }

    if (row_lines[row] == NULL) {
        fprintf(stderr, "Error: Row line not initialized for row %d\n", row);
        return -1;
    }

    if (gpiod_line_set_value(row_lines[row], state) < 0) {
        perror("Error setting row value");
        return -1;
    }

    return 0;
}

// Function to set the state of a column
int set_col(int col, int state)
{
    if (col < 0 || col >= num_cols) {
        fprintf(stderr, "Error: Invalid column number: %d\n", col);
        return -1;
    }

    if (state != 0 && state != 1) {
        fprintf(stderr, "Error: Invalid state: %d\n", state);
        return -1;
    }

    if (col_lines[col] == NULL) {
        fprintf(stderr, "Error: Column line not initialized for column %d\n", col);
        return -1;
    }

    if (gpiod_line_set_value(col_lines[col], state) < 0) {
        perror("Error setting column value");
        return -1;
    }

    return 0;
}

// Function to clear the matrix
void clear_matrix()
{
    for (int i = 0; i < num_rows; i++) {
        set_row(i, 1); // HIGH
    }
    for (int i = 0; i < num_cols; i++) {
        set_col(i, 0); // LOW
    }
    usleep(150000); // 150ms
}

// Function to draw a wave
void draw_wave()
{
    for (int col = 0; col < num_cols; col++) {
        set_col(col, 0); // Set column cathode LOW
        for (int row = 0; row < num_rows; row++) {
            set_row(row, 1); // Set row anode HIGH
        }
        usleep(150000); // 150ms delay
    }
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Wave animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        clear_matrix();
        draw_wave();
    }

    return 0;
}

