    if (result != 4) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Example: Parse the distance data (adjust based on datasheet)
    // Assuming 4 bytes, each representing a target distance
    for (int i = 0; i < num_targets; i++) {
        distances[i] = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
    }

    return 0;
}

// Function to log the distance measurements with an ISO-8601 timestamp
void log_data(int *distances, int num_targets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < num_targets; i++) {
        printf("Target %d: %d mm ", i + 1, distances[i]);
