#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    int distance_register;
    int sample_interval_ms;
} sensor_config_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
int read_distance(int handle, int reg);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read distance from the sensor
int read_distance(int handle, int reg) {
    char buf[2];
    int result = i2cWriteByteData(handle, reg, 0); // Write register address
    if (result < 0) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        return -1;
    }
    result = i2cReadI2CBlockData(handle, reg, buf, 2); // Read two bytes
    if (result < 0) {
        fprintf(stderr, "Failed to read distance data: %s\n", strerror(errno));
        return -1;
    }
    return (buf[0] << 8) | buf[1]; // Combine bytes into 16-bit value
}

// Log data to file
int log_data(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (distance == -1) {
        fprintf(fp, "%s,ERROR\n", timestamp);
    } else {
        fprintf(fp, "%s,%d\n", timestamp, distance);
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, MLX75031_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle, DISTANCE_REG);
        if (distance != -1) {
            log_data(log_file, distance);
        } else {
            fprintf(stderr, "Failed to read distance, attempting to re-open I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = initialize_i2c(I2C_BUS, MLX75031_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

