#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PART_ID 0x00
#define SI1145_COMMAND 0x18

// Si1145 command to set measurement rates and clear IRQ
#define SI1145_INIT_COMMAND 0x01

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t proximity;
    uint16_t ambient_light;
} sensor_data_t;

// Function prototypes
int si1145_read_register(int handle, uint8_t reg);
int si1145_write_register(int handle, uint8_t reg, uint8_t value);
int si1145_init(int handle);
sensor_data_t si1145_read_data(int handle);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to read a register from the Si1145
int si1145_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a register to the Si1145
int si1145_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the Si1145 sensor
int si1145_init(int handle) {
    // Verify PART ID
    int part_id = si1145_read_register(handle, SI1145_PART_ID);
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART ID (0x%02X). Expected 0x45.\n", part_id);
        return -1;
    }

    // Set measurement rates and clear IRQ
    if (si1145_write_register(handle, SI1145_COMMAND, SI1145_INIT_COMMAND) < 0) {
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145
sensor_data_t si1145_read_data(int handle) {
    sensor_data_t data;
    int proximity_low = si1145_read_register(handle, 0x22);
    int proximity_high = si1145_read_register(handle, 0x23);
    int ambient_low = si1145_read_register(handle, 0x24);
    int ambient_high = si1145_read_register(handle, 0x25);

    if (proximity_low < 0 || proximity_high < 0 || ambient_low < 0 || ambient_high < 0) {
        data.proximity = 0; // Set to 0 to indicate error
        data.ambient_light = 0; // Set to 0 to indicate error
        return data;
    }

    data.proximity = (proximity_high << 8) | proximity_low;
    data.ambient_light = (ambient_high << 8) | ambient_low;

    return data;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, data.proximity, data.ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = si1145_read_data(i2c_handle);

        if (data.proximity != 0 && data.ambient_light != 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

