        if (!chip) {
            fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
            return 1;
        }
    }

    // Get GPIO line for sensor
    sensor_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        cleanup();
        return 1;
