            if (log_event(timestamp) != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    printf("Proximity sensor monitoring stopped.\n");
    return 0;
}

