#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define PART_ID 0x00
#define HW_KEY 0x07
#define CH_LIST 0x4F
#define COMMAND 0x30
#define PS1_DATA 0x18
#define ALS_VIS_DATA 0x22

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function prototypes
int si1145_init();
int read_si1145_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    // Verify PART_ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure CH_LIST
    if (i2cWriteByteData(i2c_handle, CH_LIST, 0x07) < 0) {
        fprintf(stderr, "Error writing CH_LIST\n");
        return -1;
    }

    // Configure measurement rates (example values)
    if (i2cWriteByteData(i2c_handle, 0x02, 0x0A) < 0) return -1; // PS1 rate
    if (i2cWriteByteData(i2c_handle, 0x03, 0x0A) < 0) return -1; // ALS_VIS rate

    // Trigger measurements
    if (i2cWriteByteData(i2c_handle, COMMAND, 0x06 | 0x07) < 0) {
        fprintf(stderr, "Error triggering measurements\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(sensor_data_t *data) {
    int ps1_low, ps1_high, als_vis_low, als_vis_high;

    ps1_low = i2cReadByteData(i2c_handle, PS1_DATA);
    if (ps1_low < 0) {
        fprintf(stderr, "Error reading PS1 low byte\n");
        return -1;
    }

    ps1_high = i2cReadByteData(i2c_handle, PS1_DATA + 1);
    if (ps1_high < 0) {
        fprintf(stderr, "Error reading PS1 high byte\n");
        return -1;
    }

    als_vis_low = i2cReadByteData(i2c_handle, ALS_VIS_DATA);
    if (als_vis_low < 0) {
        fprintf(stderr, "Error reading ALS_VIS low byte\n");
        return -1;
    }

    als_vis_high = i2cReadByteData(i2c_handle, ALS_VIS_DATA + 1);
    if (als_vis_high < 0) {
        fprintf(stderr, "Error reading ALS_VIS high byte\n");
        return -1;
    }

    // Convert little-endian to big-endian
    data->proximity = (ps1_high << 8) | ps1_low;
    data->ambient_light = (als_vis_high << 8) | als_vis_low;

    return 0;
}

// Function to log the sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, data.proximity, data.ambient_light);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

