#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_MS 30
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define REMINDER_THRESHOLD 15.0 // cm

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static volatile int echo_rising = 0;
static volatile int echo_falling = 0;
static volatile int echo_stuck = 0;
static volatile int echo_timeout = 0;
static volatile int echo_error = 0;
static volatile int echo_validated = 0;
static volatile int echo_distance = 0.0;
static volatile int echo_validated_distance = 0.0;
static volatile int echo_validated_error = 0;
static volatile int echo_validated_stuck = 0;
static volatile int echo_validated_timeout = 0;
static volatile int echo_validated_error_code = 0;
static volatile int echo_validated_stuck_code = 0;
static volatile int echo_validated_timeout_code = 0;
static volatile int echo_validated_distance_code = 0;
static volatile int echo_validated_error_code_code = 0;

// Mutex for thread safety
pthread_mutex_t echo_mutex = PTHREAD_MUTEX_INITIALIZER;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void *echo_measurement_thread(void *arg);
void log_data();
void send_data_to_server(float distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold echo data
typedef struct {
    uint32_t start_tick;
    uint32_t end_tick;
    int valid;
    float distance;
    int error_code;
    int stuck_code;
    int timeout_code;
    int distance_code;
    int error_code_code;
    int stuck_code_code;
    int timeout_code_code;
    int distance_code_code;
} echo_data_t;

// Global echo data
echo_data_t echo_data;

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin level changes
void echo_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&echo_mutex);
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_rising = 1;
            echo_falling = 0;
            echo_stuck = 0;
            echo_timeout = 0;
            echo_error = 0;
            echo_valid = 0;
        } else if (level == 0) {
            echo_end_tick = tick;
            echo_rising = 0;
            echo_falling = 1;
            echo_stuck = 0;
            echo_timeout = 0;
            echo_error = 0;
            echo_valid = 0;
        } else {
            echo_error = 1;
        }
    }
    pthread_mutex_unlock(&echo_mutex);
}

// Thread function to measure echo pulse width
void *echo_measurement_thread(void *arg) {
    trigger_pulse();
    while (1) {
        pthread_mutex_lock(&echo_mutex);
        if (echo_start_tick != 0 && echo_end_tick != 0) {
            uint32_t pulse_width = echo_end_tick - echo_start_tick;
            float seconds = (float)pulse_width / 1000000.0; // Convert to seconds
            echo_data.distance = (seconds * SPEED_OF_SOUND) / 2.0;
            echo_data.valid = 1;
            echo_data.error_code = 0;
            echo_data.stuck_code = 0;
            echo_data.timeout_code = 0;
            echo_data.distance_code = 0;
            echo_data.error_code_code = 0;
            echo_data.stuck_code_code = 0;
            echo_data.timeout_code_code = 0;
            echo_data.distance_code_code = 0;

            pthread_mutex_unlock(&echo_mutex);
            return NULL; // Exit thread after first measurement
        } else {
            pthread_mutex_unlock(&echo_mutex);
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }
    return NULL;
}

// Function to log data to file
void log_data() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    pthread_mutex_lock(&echo_mutex);
    if (echo_validated) {
        fprintf(log_file, "%s,%.2f,%d,%d,%d,%d,%d\n",
                timestamp, echo_data.distance, echo_data.error_code, echo_data.stuck_code, echo_data.timeout_code, echo_data.distance_code, echo_data.error_code_code);
        fflush(log_file);
    } else {
        fprintf(log_file, "%s,ERROR,0,0,0,0,0\n", timestamp);
        fflush(log_file);
    }
    pthread_mutex_unlock(&echo_mutex);
}

// Function to simulate sending data to a server
void send_data_to_server(float distance) {
    printf("Sending data to server: %.2f cm\n", distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&echo_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
