#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// APDS9960 I2C address
#define APDS9960_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ID 0x92
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_CONFIG1 0x8F
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_BDATAL 0x9C
#define APDS9960_BDATAH 0x9D
#define APDS9960_PDATA 0x9E

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint8_t proximity;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
int i2c_reopen();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to re-open the I2C bus
int i2c_reopen() {
    i2c_handle = i2cOpen(1, APDS9960_ADDR, 0); // Re-open I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the APDS9960 sensor
int initialize_sensor() {
    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Configure sensor registers
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) return -1; // Power on
    gpioDelay(1000); // Wait 1ms

    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03 | 0x02) < 0) return -1; // Enable proximity and color

    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) return -1; // Set ATIME
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) return -1; // Set WTIME
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) return -1; // Set PPULSE
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) return -1; // Enable interrupts
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) return -1; // Enable interrupts
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG1, 0x00) < 0) return -1; // Enable interrupts

    return 0;
}

// Function to read RGB and proximity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    int result;

    result = i2cReadWordData(i2c_handle, APDS9960_CDATAL);
    if (result < 0) {
        fprintf(stderr, "Error reading red data: %d\n", result);
        return -1;
    }
    data->red = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, APDS9960_CDATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading green data: %d\n", result);
        return -1;
    }
    data->green = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, APDS9960_RDATAL);
    if (result < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", result);
        return -1;
    }
    data->blue = (uint16_t)result;

    result = i2cReadByteData(i2c_handle, APDS9960_PDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    data->proximity = (uint8_t)result;

    return 0;
}

// Function to log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.red, data.green, data.blue, data.proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);

            if (sensor_data.proximity > PROXIMITY_THRESHOLD) {
                printf("Proximity value: %u\n", sensor_data.proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Re-initializing...\n");
            if (i2c_reopen() != 0) {
                fprintf(stderr, "Failed to re-open I2C bus. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            if (initialize_sensor() != 0) {
                fprintf(stderr, "Sensor re-initialization failed!\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

