// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    // Reset the device
    if (i2c_write_reg(fd, COMMAND_REG, 0x01) != 0) return -1;
    usleep(10000); // Wait for reset to complete

    // Configure continuous proximity measurement
    if (i2c_write_reg(fd, MEAS_RATE0_REG, 0x0A) != 0) return -1; // 100ms sample rate

