    uint8_t low, high;

    if (i2c_read_reg(fd, PS_DATA0_REG, &low) != 0) return -1;
    if (i2c_read_reg(fd, PS_DATA1_REG, &high) != 0) return -1;

    *proximity = (high << 8) | low;
    return 0;
}

