    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (fprintf(fp, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) != 0) {
        fprintf(stderr, "Error initializing Si1182 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("heartrate.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    uint16_t proximity;
    float bpm;
    while (running) {
        // Read proximity data
        if (read_proximity_data(i2c_fd, &proximity) == 0) {
            // Calculate BPM
            bpm = calculate_bpm(proximity);

            // Validate BPM
            if (bpm >= HEART_RATE_MIN && bpm <= HEART_RATE_MAX) {
                // Log BPM
                if (log_bpm(bpm) != 0) {
                    fprintf(stderr, "Error logging BPM.\n");
                }
            } else {
                fprintf(stderr, "Warning: BPM value out of range: %.2f\n", bpm);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read proximity data.\n");
        }

        usleep(SAMPLE_RATE_MS * 1000); // Sleep for 100ms
    }

    // Close I2C device and CSV file
    close(i2c_fd);
    fclose(fp);

    return 0;
}

