#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L0X Register Addresses
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

// GPIO Pin for interrupt
#define INTERRUPT_GPIO 17

// I2C Bus
#define I2C_BUS 1

// File to log distance measurements
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l0x();
int read_distance();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold VL53L0X configuration
typedef struct {
    int i2c_address;
    int i2c_bus;
    int interrupt_gpio;
    char *log_file;
} sensor_config_t;

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    // Check sensor presence
