#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define CH101_ADDR 0x45

// Define the trigger command (adjust based on datasheet)
#define TRIGGER_CMD 0x01

// Global variables for I2C handle and file pointer
int i2c_handle = -1;
FILE *log_file = NULL;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to trigger the ultrasonic sensor
int trigger_sensor() {
    char buf[1];
    buf[0] = TRIGGER_CMD;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int *distance_mm) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance_mm = (buf[0] << 8) | buf[1];

    // Check for valid range (adjust based on sensor datasheet)
    if (*distance_mm < 0 || *distance_mm > 4000) {
        fprintf(stderr, "Invalid distance reading: %d\n", *distance_mm);
        return -1;
    }

    return 0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log the distance to a file
int log_distance(const char *timestamp, int distance_mm) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and I2C
    if (initialize() != 0) {
        return 1;
    }

    int distance_mm;
    char timestamp[20];

    // Main loop
    while (1) {
        // Trigger the sensor
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Sensor trigger failed, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Wait for a short period
        gpioDelay(50000); // 50ms

        // Read the distance
        if (read_distance(&distance_mm) != 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Get the current timestamp
        get_timestamp(timestamp);

        // Log the distance
        if (log_distance(timestamp, distance_mm) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        // Print the distance to stdout
        printf("%s, %d\n", timestamp, distance_mm);

        // Wait for 200ms
        gpioDelay(200000);
    }

    // The program should never reach here due to the infinite loop
    return 0;
}

