#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Register addresses (replace with actual values from datasheet)
#define REG_WHO_AM_I 0x0F
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_gpio();
int read_distance(float *distance);
int log_distance(float distance);
void control_led(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO for LED control
int init_gpio() {
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED
    return 0;
}

// Read distance from ICU-20201 sensor
int read_distance(float *distance) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, REG_DISTANCE_MSB, buf, 2);
        if (result == 2) {
            // Combine MSB and LSB to get the distance
            int distance_raw = (buf[0] << 8) | buf[1];
            *distance = (float)distance_raw / 10.0; // Convert to cm (adjust scaling as needed)
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries\n");
    return -1; // Failure
}

// Log distance to file with ISO-8601 timestamp
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Control LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    float distance;

    printf("Starting distance measurement...\n");

    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    cleanup();
    return 0;
}

