            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries\n");
    return -1; // Failure
}

// Log distance to file with ISO-8601 timestamp
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Control LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    float distance;

    printf("Starting distance measurement...\n");

    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    cleanup();
    return 0;
}

