int verify_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x41\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I register verified successfully\n");
    return 0;
}

// Read distance measurement from the sensor
int read_distance() {
    int distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (distance < 0) {
        fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
        return -1;
    }
    return distance;
}

