        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance >= 0) {
            control_led(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

