#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_FRAME_SIZE 15
#define DISTANCE_REGISTER 11
#define DISTANCE_REGISTER2 12
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_RATE_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_write_bytes(int fd, unsigned char *data, int len) {
    int result, i;
    for (i = 0; i < len; i++) {
        result = write(fd, &data[i], 1);
        if (result != 1) {
            perror("I2C write failed");
            return -1;
        }
    }
    return 0;
}

int i2c_read_bytes(int fd, unsigned char *data, int len) {
    int result, i;
    for (i = 0; i < len; i++) {
        result = read(fd, &data[i], 1);
        if (result != 1) {
            perror("I2C read failed");
            return -1;
        }
    }
    return 0;
}

int main() {
    int fd, i, result;
    unsigned char command_frame[4] = {COMMAND_FRAME[0], COMMAND_FRAME[1], COMMAND_FRAME[2], COMMAND_FRAME[3]};
    unsigned char response_frame[RESPONSE_FRAME_SIZE];
    int distance;
    float average_distance;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    FILE *log_file;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    printf("I2C device opened successfully.\n");

    while (program_running) {
        // Send command frame
        if (i2c_write_bytes(fd, command_frame, 4) != 0) {
            fprintf(stderr, "Error sending command frame.\n");
            break;
        }

        // Wait for at least 10 ms
        usleep(10000); // 10 ms

        // Read response frame
        if (i2c_read_bytes(fd, response_frame, RESPONSE_FRAME_SIZE) != 0) {
            fprintf(stderr, "Error reading response frame.\n");
            break;
        }

