        if (response_frame[0] != SENSOR_ADDRESS) {
            fprintf(stderr, "Invalid header value: 0x%02X\n", response_frame[0]);
            break;
        }

        // Extract distance data
        distance = (response_frame[DISTANCE_REGISTER2] << 8) | response_frame[DISTANCE_REGISTER];

