// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x()
{
    // No specific initialization needed for VL53L0X in this example
    // The sensor is initialized during the first measurement
    return 0; // Return 0 for success, -1 for failure
}

// Function to read a byte from the VL53L0X sensor
int read_byte(int reg)
{
    int data = i2cReadByteData(i2c_handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1; // Indicate error
    }
    return data;
}

// Function to write a byte to the VL53L0X sensor
int write_byte(int reg, int data)
{
    int result = i2cWriteByteData(i2c_handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to read the distance from the VL53L0X sensor
int read_distance()
{
    // Start a single measurement
    if (write_byte(SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting measurement.\n");
        return -1;
    }

    // Wait for the measurement to complete (polling the interrupt status)
    int timeout = 100; // Timeout in milliseconds
    while (1) {
        int status = read_byte(RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status.\n");
            return -1;
        }
        if (status & 0x01) {
            break; // Measurement complete
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout--;
        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for measurement.\n");
            return -1;
        }
    }

    // Read the distance
    int distance = read_byte(RESULT_RANGE_STATUS);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance.\n");
        return -1;
    }

    // Clear the interrupt
    if (write_byte(SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt.\n");
        return -1;
    }

    return distance;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x() < 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print the distance with timestamp
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

