{
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si1182 sensor
int init_si1182()
{
    // Write to CONFIG register to enable proximity mode
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read proximity data from the Si1182 sensor
int read_proximity_data(int *proximity_value)
{
    // Read LSB and MSB registers
    int lsb = i2cReadByteData(i2c_handle, PROX_DATA_LSB);
    int msb = i2cReadByteData(i2c_handle, PROX_DATA_MSB);

    if (lsb < 0 || msb < 0) {
        fprintf(stderr, "Error reading proximity data: %d %d\n", lsb, msb);
        return -1;
    }

    // Combine LSB and MSB to form 16-bit proximity value
    *proximity_value = (msb << 8) | lsb;

    return 0;
}

