#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define RETRY_COUNT 3

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, closing I2C device and exiting...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

// Function to read distance from MLX75030 sensor
int read_distance(int fd) {
    unsigned char buffer[2];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = read(fd, buffer, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int distance_raw = (buffer[1] << 8) | buffer[0];
            return distance_raw;
        } else {
            fprintf(stderr, "I2C read error: %s (errno: %d). Retrying...\n", strerror(errno), errno);
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Indicate failure
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address via ioctl
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify device response (read a register)
    unsigned char verify_buffer[1];
    if (read(i2c_fd, verify_buffer, 1) != 1) {
        fprintf(stderr, "Error reading verification register.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 sensor found at address 0x%02X\n", MLX75030_ADDR);

    // Main loop
    while (1) {
        int distance_raw = read_distance(i2c_fd);
        if (distance_raw != -1) {
            // Convert raw value to millimeters
            float distance_mm = (float)distance_raw * 0.125;
            printf("Distance: %.2f mm\n", distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        usleep(500000); // Wait 500ms
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

