#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 200000 // 200ms
#define MAX_DISTANCE_US 38000 // 38ms
#define MAX_DISTANCE_CM 400 // Maximum measurable distance in cm

static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int echo_rising_edge = 0;
static volatile int echo_falling_edge = 0;
static volatile int echo_valid = 0;
static volatile int echo_duration = 0;
static volatile int last_tick = 0;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to get current timestamp in ISO 8601 format
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin rising edge
void echo_rising_edge_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) {
        pulse_start = tick;
        echo_rising_edge = 1;
    }
}

// Callback function for echo pin falling edge
void echo_falling_edge_callback(int gpio, int level, uint32_t tick)
{
    if (level == 0) {
        pulse_end = tick;
        echo_falling_edge = 1;
    }
}

// Function to measure the duration of the echo pulse
void measure_pulse_duration()
{
    echo_valid = 0;
    echo_duration = 0;

    if (pulse_start == 0 || pulse_end == 0) {
        return;
    }

    if (pulse_end < pulse_start) {
        // Handle potential tick rollover
        pulse_end = 0;
        return;
    }

    echo_duration = pulse_end - pulse_start;
}

// Function to calculate the distance in centimeters
float calculate_distance(uint32_t pulse_duration)
{
    if (pulse_duration <= 0 || pulse_duration > MAX_DISTANCE_US) {
        return -1.0; // Indicate an invalid reading
    }
    return (pulse_duration * 0.0343) / 2.0;
}

// Function to log the distance reading with a timestamp
void log_distance(float distance)
{
    char timestamp[30];
    get_timestamp(timestamp);
    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callbacks for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge_callback, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge_callback, NULL);

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse duration
        measure_pulse_duration();

        // Calculate the distance
        float distance = calculate_distance(echo_duration);

        // Log the distance
        if (distance >= 0) {
            log_distance(distance);
        } else {
            printf("Error: Invalid distance reading\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second delay
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

