#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <termios.h>
#include <unistd.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_LED 17
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define DISTANCE_THRESHOLD 1.0 // meters
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE 8 + (NUM_RANGE_BINS * 2) // Magic word + range data
#define ALERT_DURATION 2 // seconds
#define LOG_FILE "intrusion_log.csv"

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    int uart_fd;
    FILE *log_file;
    int gpio_led;
} ProgramState;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_radar_data(int fd, unsigned char *buffer, int buffer_size);
int parse_radar_data(const unsigned char *buffer, int buffer_size, float *range_profile);
int detect_intrusion(const float *range_profile, int num_bins, float threshold);
int control_led(int gpio, int state);
int log_intrusion(const char *timestamp, float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;  // Clear size bits
    tty.c_cflag |= CS8;   // 8 data bits
    tty.c_lflag = 0;      // No signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;      // No remapping, no delays
    tty.c_cc[VMIN] = 0;   // Read doesn't block
    tty.c_cc[VTIME] = 5;  // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read radar data from UART
int read_radar_data(int fd, unsigned char *buffer, int buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        // No data available
        return 0;
    }
    return (int)bytes_read;
}

// Parse radar data
int parse_radar_data(const unsigned char *buffer, int buffer_size, float *range_profile) {
    if (buffer_size < DATA_FRAME_SIZE) {
        fprintf(stderr, "Error: Incomplete data frame received (%d bytes, expected %d)\n", buffer_size, DATA_FRAME_SIZE);
        return -1;
    }

    // Verify magic word
    if (buffer[0] != 0x02 || buffer[1] != 0x01 || buffer[2] != 0x04 || buffer[3] != 0x03 ||
        buffer[4] != 0x06 || buffer[5] != 0x05 || buffer[6] != 0x08 || buffer[7] != 0x07) {
        fprintf(stderr, "Error: Invalid magic word\n");
        return -1;
    }

    // Extract range data
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (buffer[8 + (i * 2)] < 0 || buffer[8 + (i * 2) + 1] < 0) {
            fprintf(stderr, "Error: Invalid range data at bin %d\n", i);
            return -1;
        }
        int16_t raw_data = (int16_t)((buffer[8 + (i * 2)] << 8) | buffer[8 + (i * 2) + 1]);
        range_profile[i] = (float)raw_data * RANGE_RESOLUTION;
    }

    return 0;
}

// Detect intrusion
int detect_intrusion(const float *range_profile, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (range_profile[i] < threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Control LED
int control_led(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Log intrusion
int log_intrusion(const char *timestamp, float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char buffer[256]; // Buffer for reading UART data
    float range_profile[NUM_RANGE_BINS];
    time_t current_time;
    struct tm *time_info;
    char timestamp[20]; // ISO 8601 timestamp string

    printf("Radar intrusion detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read data from UART
        int bytes_read = read_radar_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            // Parse radar data
            if (parse_radar_data(buffer, bytes_read, range_profile) == 0) {
                // Detect intrusion
                if (detect_intrusion(range_profile, NUM_RANGE_BINS, DISTANCE_THRESHOLD)) {
                    // Get current timestamp
                    time(&current_time);
                    time_info = localtime(&current_time);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", time_info);

                    // Control LED
                    control_led(GPIO_LED, 1); // Turn LED on
                    gpioDelay(ALERT_DURATION * 1000000); // Wait for alert duration
                    control_led(GPIO_LED, 0); // Turn LED off

                    // Log intrusion
                    if (log_intrusion(timestamp, DISTANCE_THRESHOLD) != 0) {
                        fprintf(stderr, "Error: Failed to log intrusion\n");
                    }
                }
            }
        }
        gpioDelay(10000); // Delay to avoid busy-waiting (10ms)
    }

    // Cleanup
    close(uart_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Radar intrusion detection system stopped.\n");

    return 0;
}

