#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "obstacle_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
int control_buzzer(int state);
int log_event(int sensor_state, int buzzer_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config;

    // Open chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Error getting sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure sensor line as input
    memset(&config, 0, sizeof(config));
    config.consumer = "obstacle_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sensor_line, &config, 0) < 0) {
        perror("Error requesting sensor line");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure buzzer line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "obstacle_buzzer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(buzzer_line, &config, 0) < 0) {
        perror("Error requesting buzzer line");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Control buzzer
int control_buzzer(int state) {
    int ret = gpiod_line_set_value(buzzer_line, state);
    if (ret < 0) {
        perror("Error setting buzzer value");
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(int sensor_state, int buzzer_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Sensor: %d, Buzzer: %d\n", timestamp, sensor_state, buzzer_state);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");

    // Release buzzer line
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Release sensor line
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    int previous_sensor_state = -1; // Initialize to an invalid state
    int current_sensor_state = -1;
    int previous_buzzer_state = -1;
    int current_buzzer_state = -1;

    // Main loop
    while (!terminate) {
        current_sensor_state = read_sensor();
        if (current_sensor_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (current_sensor_state != previous_sensor_state) {
            if (current_sensor_state == 0) {
                // Obstacle detected
                if (current_buzzer_state == -1) {
                    if (control_buzzer(1) < 0) {
                        fprintf(stderr, "Error controlling buzzer, exiting.\n");
                        break;
                    }
                    current_buzzer_state = 1;
                }
            } else {
                // Obstacle removed
                if (current_buzzer_state == -1) {
                    if (control_buzzer(0) < 0) {
                        fprintf(stderr, "Error controlling buzzer, exiting.\n");
                        break;
                    }
                    current_buzzer_state = 0;
                }
            }
            previous_sensor_state = current_sensor_state;
        }

        // Log event
        if (current_sensor_state != previous_sensor_state) {
            if (log_event(current_sensor_state, current_buzzer_state) < 0) {
                fprintf(stderr, "Error logging event, exiting.\n");
                break;
            }
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    cleanup();

    printf("Obstacle detection stopped.\n");
    return 0;
}

