#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_distance();
void log_distance(int distance);
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int alert_gpio;
    float distance_threshold;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set GPIO mode for alert pin
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance() {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, DISTANCE_HIGH_REG);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte: %d\n", high_byte);
        return -1;
    }

    low_byte = i2cReadByteData(i2c_handle, DISTANCE_LOW_REG);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte: %d\n", low_byte);
        return -1;
    }

    // Combine the two bytes into a 16-bit distance value
    int distance = (high_byte << 8) | low_byte;

    return distance;
}

// Function to log distance to file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to trigger GPIO alert
void trigger_alert() {
    gpioWrite(ALERT_GPIO, 1); // Set GPIO high
    gpioDelay(500);           // Wait for 500 ms
    gpioWrite(ALERT_GPIO, 0); // Set GPIO low
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);

            // Check for distance threshold and trigger alert
            if (distance < DISTANCE_THRESHOLD) {
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

