#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_MODE_START 0x007
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014
#define VL53L1X_REG_SYSTEM_MODE_CONFIG 0x0000
#define VL53L1X_REG_SYSTEM_RESET 0x0000

// Distance thresholds (mm)
#define DISTANCE_THRESHOLD_LOW 300
#define DISTANCE_THRESHOLD_MED 600
#define DISTANCE_THRESHOLD_HIGH 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void log_data(int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(2000); // Wait for reset to complete

    // Configure for continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure VL53L1X for continuous ranging\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start VL53L1X ranging\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int *distance) {
    // Poll for data ready
    int data_ready = 0;
    int timeout = 100; // Timeout in milliseconds
    while (!data_ready && timeout > 0) {
        int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error: Failed to read interrupt status\n");
            return -1;
        }
        data_ready = (status & 0x01);
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout--;
    }

    if (!data_ready) {
        fprintf(stderr, "Error: Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }

    *distance = range_status;

    return 0;
}

// Data logging function
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }
    fflush(log_file); // Ensure data is written to disk
}

// Guidance message printing function
void print_guidance(int distance) {
    if (distance < DISTANCE_THRESHOLD_LOW) {
        printf("STOP\n");
    } else if (distance >= DISTANCE_THRESHOLD_LOW && distance <= DISTANCE_THRESHOLD_MED) {
        printf("APPROACH\n");
    } else if (distance >= DISTANCE_THRESHOLD_MED && distance <= DISTANCE_THRESHOLD_HIGH) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    // Main loop
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            log_data(distance);
            print_guidance(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        gpioDelay(100); // Delay for 100 ms
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

