#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define DISTANCE_MIN 50.0
#define DISTANCE_MAX 500.0
#define BLINK_FREQUENCY_MIN 10.0
#define BLINK_FREQUENCY_MAX 1.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
float map_distance_to_frequency(float distance);
void blink_led(float frequency);
void log_data(float distance, float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(float *distance) {
    char cmd[1] = {0x00}; // Example command to trigger measurement
    char buf[2]; // Buffer to store the received data
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d, retries left: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait for measurement (adjust as needed)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C device: %d, retries left: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Convert the received data to distance (example conversion)
        *distance = (float)((buf[0] << 8) | buf[1]) / 10.0; // Example conversion
        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Map distance to blink frequency
float map_distance_to_frequency(float distance) {
    if (distance < DISTANCE_MIN) {
        return BLINK_FREQUENCY_MIN;
    } else if (distance > DISTANCE_MAX) {
        return BLINK_FREQUENCY_MAX;
    } else {
        return BLINK_FREQUENCY_MIN + (distance - DISTANCE_MIN) * (BLINK_FREQUENCY_MAX - BLINK_FREQUENCY_MIN) / (DISTANCE_MAX - DISTANCE_MIN);
    }
}

// Blink LED with given frequency
void blink_led(float frequency) {
    int period_us = 1000000 / frequency; // Period in microseconds
    int half_period_us = period_us / 2;

    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(half_period_us);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(half_period_us);
}

// Log data to stdout
void log_data(float distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %.2f mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;
    float frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            frequency = map_distance_to_frequency(distance);
            blink_led(frequency);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

