#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A
#define MEASURE_CMD 0x01
#define SAMPLE_INTERVAL_MS 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int measurement_command;
    int sample_interval;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_bus, int i2c_address, int measurement_command, int sample_interval);
int read_distance(int i2c_handle);
int log_distance(FILE *log_file, int distance_cm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(int i2c_bus, int i2c_address, int measurement_command, int sample_interval) {
    i2c_handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0x00, measurement_command) < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    gpioDelay(5000); // Wait for measurement (5ms)

    return i2c_handle;
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    char buffer[2];
    int distance_cm;

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", i2c_handle);
        return -1;
    }

    distance_cm = (buffer[0] << 8) | buffer[1];
    return distance_cm;
}

// Function to log distance to a file
int log_distance(FILE *log_file, int distance_cm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for graceful termination
    signal(SIGINT, signal_handler);
