#define DEBOUNCE_TIME 50

// Global variables for sensor states
int sensor1_state = 1; // Initial state: no obstacle detected
int sensor2_state = 1; // Initial state: no obstacle detected

// File pointer for the log file
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio;
    int state;
} sensor_data_t;

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log an event to the log file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the sensors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Open the log file for appending
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR1_GPIO);

        // Debounce sensor 1
        if (sensor1_value != sensor1_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Delay for debounce time
            sensor1_value = read_sensor(SENSOR1_GPIO);
            if (sensor1_value != sensor1_state) {
                sensor1_state = sensor1_value;
                if (sensor1_value == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
            }
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        // Debounce sensor 2
        if (sensor2_value != sensor2_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Delay for debounce time
            sensor2_value = read_sensor(SENSOR2_GPIO);
            if (sensor2_value != sensor2_state) {
                sensor2_state = sensor2_value;
                if (sensor2_value == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
            }
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    return 0;
}

