#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// VL53L5CX register addresses (Example - adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L5CX_REG_SYSRANGE_START 0x0040
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB 0x001E
#define VL53L5CX_REG_RESULT_DISTANCE 0x0020
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0089
#define VL53L5CX_REG_SYSTEM_SEQUENCE_CONFIG 0x0083
#define VL53L5CX_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x0084
#define VL53L5CX_REG_SYSTEM_FIRMWARE_READ 0x0086
#define VL53L5CX_REG_SYSTEM_FIRMWARE_WRITE 0x0087
#define VL53L5CX_REG_SYSTEM_SYSTEM_INTERRUPT_CLEAR 0x0089
#define VL53L5CX_REG_SYSTEM_SYSTEM_SEQUENCE_CONFIG 0x0083
#define VL53L5CX_REG_SYSTEM_SYSTEM_INTERMEASUREMENT_PERIOD 0x0084
#define VL53L5CX_REG_SYSTEM_SYSTEM_FIRMWARE_READ 0x0086
#define VL53L5CX_REG_SYSTEM_SYSTEM_FIRMWARE_WRITE 0x0087

// Configuration values (Example - adjust based on datasheet)
#define VL53L5CX_CONFIG_SYSTEM_INTERMEASUREMENT_PERIOD 0x01 // 100ms
#define VL53L5CX_CONFIG_SYSTEM_SEQUENCE_CONFIG 0x01 // 8x8 zone grid
#define VL53L5CX_CONFIG_SYSTEM_FIRMWARE_READ 0x00
#define VL53L5CX_CONFIG_SYSTEM_FIRMWARE_WRITE 0x00

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int write_i2c_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_i2c_register(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx(int fd) {
    unsigned char model_id, revision_id;

    // Check sensor ID
    if (read_i2c_register(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (read_i2c_register(fd, VL53L5CX_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure sensor (Example - adjust based on datasheet)
    if (write_i2c_register(fd, VL53L5CX_REG_SYSTEM_INTERMEASUREMENT_PERIOD, VL53L5CX_CONFIG_SYSTEM_INTERMEASUREMENT_PERIOD) != 0) {
        fprintf(stderr, "Error writing intermeasurement period\n");
        return -1;
    }
    if (write_i2c_register(fd, VL53L5CX_REG_SYSTEM_SEQUENCE_CONFIG, VL53L5CX_CONFIG_SYSTEM_SEQUENCE_CONFIG) != 0) {
        fprintf(stderr, "Error writing sequence config\n");
        return -1;
    }
    if (write_i2c_register(fd, VL53L5CX_REG_SYSTEM_FIRMWARE_READ, VL53L5CX_CONFIG_SYSTEM_FIRMWARE_READ) != 0) {
        fprintf(stderr, "Error writing firmware read\n");
        return -1;
    }
    if (write_i2c_register(fd, VL53L5CX_REG_SYSTEM_FIRMWARE_WRITE, VL53L5CX_CONFIG_SYSTEM_FIRMWARE_WRITE) != 0) {
        fprintf(stderr, "Error writing firmware write\n");
        return -1;
    }

    return 0;
}

// Function to read distance data from all 64 zones
int read_zone_data(int fd, int *distances) {
    unsigned char range_status;
    unsigned char distance_msb, distance_lsb;

    // Start a single measurement
    if (write_i2c_register(fd, VL53L5CX_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for measurement to complete (adjust timeout as needed)
    usleep(10000); // 10ms

    // Read range status
    if (read_i2c_register(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance data (MSB and LSB)
    if (read_i2c_register(fd, VL53L5CX_REG_RESULT_DISTANCE, &distance_msb) != 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }
    if (read_i2c_register(fd, VL53L5CX_REG_RESULT_DISTANCE + 1, &distance_lsb) != 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
    }

    // Combine MSB and LSB to get the distance value
    int distance = (distance_msb << 8) | distance_lsb;

    // Store distance in the array
    distances[0] = distance;

    // Clear interrupt (optional, depends on application)
    if (write_i2c_register(fd, VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x00) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_vl53l5cx(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize VL53L5CX sensor\n");
        close(i2c_fd);
        return 1;
    }

    int distances[64];

    // Main loop
    while (1) {
        // Read distance data from all zones
        if (read_zone_data(i2c_fd, distances) == 0) {
            // Print the distance values
            for (int i = 0; i < 64; i++) {
                printf("Zone %d: %d mm\n", i, distances[i]);
            }
        } else {
            fprintf(stderr, "Failed to read zone data\n");
        }

        // Wait for 500ms
        usleep(500000); // 500ms
    }

    // Close I2C device (this will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

