// Define the register address for distance measurement
#define DISTANCE_REG 0x00 // Example register address, check MLX75030 datasheet

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read a byte from the I2C device with retry logic
int read_i2c_byte(int handle, int reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d, retries remaining: %d\n", reg, result, retries);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read from I2C after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to write a byte to the I2C device with retry logic
int write_i2c_byte(int handle, int reg, int val) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, val);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d, retries remaining: %d\n", reg, val, result, retries);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to I2C after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to read the distance measurement from the sensor
int read_distance(int handle) {
    int distance = read_i2c_byte(handle, DISTANCE_REG);
    if (distance < 0) {
        return -1; // Indicate error
    }
    return distance;
}

// Function to log the distance measurement with a timestamp
void log_distance(int distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_nsec / 1000000);

    printf("%ld.%03ld: Distance: %d mm\n", ts.tv_sec, milliseconds, distance);
}

// Function to close the I2C device and terminate pigpio
void cleanup(int handle) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the I2C device
    i2c_handle = open_i2c_device(I2C_BUS, MLX75030_ADDR);
    if (i2c_handle < 0) {
        cleanup(-1);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup(i2c_handle);
    return 0;
}

