#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define sensor and buzzer parameters
#define SENSOR1_ADDR 0x29
#define SENSOR2_ADDR 0x2A
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_START              0x0000
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_sensor(int i2c_handle);
int read_distance(int i2c_handle);
void control_buzzer(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_sensor(int i2c_handle) {
    // Example initialization sequence (adjust based on datasheet)
