#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_BUZZER 23
#define MSG_QUEUE_KEY 1234
#define DISTANCE_THRESHOLD 100 // mm
#define MSG_SIZE 20

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RANGING_MODE 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Message structure for inter-process communication
typedef struct {
    long mtype;
    char mtext[MSG_SIZE];
} msgbuf;

// Global variables
int i2c_handle;
int msg_queue_id;
msgbuf *msg_queue;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void activate_buzzer(int gpio_pin, int duration_ms);
void send_distance(int distance);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    int model_id;

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Check model ID
    model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error writing reset command\n");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error writing reset command\n");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure timing budget (50ms)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error writing ranging mode\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error writing system start\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int *distance) {
    int range_status;

    // Read range status
    range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", range_status);
        return -1;
    }

    // Read distance
    int distance_high = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    int distance_low = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);

    if (distance_high < 0 || distance_low < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    *distance = (distance_high << 8) | distance_low;

    return 0;
}

// Activate the buzzer for a specified duration
void activate_buzzer(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn buzzer on
    gpioDelay(duration_ms);
    gpioWrite(gpio_pin, 0); // Turn buzzer off
}

// Send distance reading to the message queue
void send_distance(int distance) {
    if (msg_queue != NULL) {
        msg_queue->mtype = 1; // Message type
        strncpy(msg_queue->mtext, "Distance: ", MSG_SIZE - 1);
        msg_queue->mtext[MSG_SIZE - 1] = '\0'; // Ensure null termination
        msg_queue->mtext[MSG_SIZE] = '\0'; // Ensure null termination
        msg_queue->mtext[MSG_SIZE - 1] = (char)distance; // Append distance
        if (msgsnd(msg_queue_id, msg_queue, MSG_SIZE, 0) == -1) {
            perror("msgsnd");
        }
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (msg_queue != NULL) {
        if (msgctl(msg_queue_id, IPC_RMID, NULL) == -1) {
            perror("msgctl (rmid)");
        }
    }
    gpioTerminate();
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GPIO_BUZZER, PI_OUTPUT);

    // Initialize message queue
    key_t key = MSG_QUEUE_KEY;
    if ((msg_queue_id = msgget(key, IPC_CREAT | 0666)) == -1) {
        perror("msgget");
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("VL53L1X sensor initialized.  Reading distance every 50ms...\n");

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            // Send distance to message queue
            send_distance(distance);

            // Activate buzzer if distance is below threshold
            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer(GPIO_BUZZER, 500);
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

