#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSE_WIDTH 2000 // us
#define SERVO_CLOSE_PULSE_WIDTH 1000 // us
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_TOPIC "gate_status"

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *message);
void signal_handler(int signal);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Helper function to write a byte to an I2C register
int write_i2c_reg(int handle, int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        log_event("Error writing to I2C register");
        return -1;
    }
    return 0;
}

// Helper function to read a byte from an I2C register
int read_i2c_reg(int handle, int reg, char *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        log_event("Error writing to I2C register for reading");
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        log_event("Error reading from I2C register");
        return -1;
    }
    return 0;
}

// VL53L1X initialization function
int init_vl53l1x() {
    char model_id;
    if (read_i2c_reg(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        log_event("Error reading VL53L1X model ID");
        return -1;
    }

    if (model_id != 0xEACC) {
        log_event("Incorrect VL53L1X model ID");
        return -1;
    }

    // Example: Start ranging (adjust based on datasheet)
    if (write_i2c_reg(i2c_handle, VL53L1X_REG_RANGING_START, 0x01) != 0) {
        log_event("Error starting ranging");
        return -1;
    }

    log_event("VL53L1X initialized");
    return 0;
}

// Function to read distance from VL53L1X
int read_distance() {
    char range_status;
    char range_value[2];

    if (read_i2c_reg(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        log_event("Error reading range status");
        return -1;
    }

    if (read_i2c_reg(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, range_value) != 0) {
        log_event("Error reading distance");
        return -1;
    }

    int distance = (range_value[0] << 8) | range_value[1];

    return distance;
}

// Function to open the gate
void open_gate() {
    gpioServo(SERVO_PIN, SERVO_OPEN_PULSE_WIDTH);
    log_event("Gate opened");
}

// Function to close the gate
void close_gate() {
    gpioServo(SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH);
    log_event("Gate closed");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Signal received, terminating...");
    terminate = 1;
}

// MQTT connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_event("MQTT connected to broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_event("MQTT connection error");
    }
}

// MQTT message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Received MQTT message: %s", payload);
        log_event(log_message);

        if (strcmp(payload, "force_open") == 0) {
            open_gate();
        } else if (strcmp(payload, "force_close") == 0) {
            close_gate();
        } else if (strcmp(payload, "status_request") == 0) {
            // Implement status request logic here (e.g., return gate status)
            log_event("Status request received");
        } else {
            log_event("Unknown MQTT command");
        }
    }
}

// MQTT disconnect callback
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_event("MQTT disconnected unexpectedly");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error opening I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    if (init_vl53l1x() != 0) {
        log_event("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_event("Error creating MQTT client");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_event("Error connecting to MQTT broker");
        mosquitto_destroy(mosq);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            log_event("Error reading distance, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        char log_message[64];
        snprintf(log_message, sizeof(log_message), "Distance: %d mm", distance);
        log_event(log_message);

        if (distance <= DISTANCE_THRESHOLD) {
            open_gate();
        } else {
            close_gate();
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

