// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_MS 60
#define TIMEOUT_US 60000
#define NO_OBJECT_TIMEOUT_MS 60
#define NO_OBJECT_TIMEOUT_US 60000
#define MIN_PULSE_WIDTH 100
#define MAX_PULSE_WIDTH 30000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold echo timestamp
typedef struct {
    unsigned int rising_edge_tick;
    unsigned int falling_edge_tick;
} EchoTimestamps;

// Function prototypes
void trigger_pulse(int trig_pin);
void echo_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_distance(unsigned int pulse_width);
void log_data(double distance, const char *timestamp);
void log_warning(const char *message);
void signal_handler(int signal);
void initialize_gpio();
void cleanup_gpio();

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);
}

// Trigger a 10us pulse on the TRIG pin
void trigger_pulse(int trig_pin) {
    gpioWrite(trig_pin, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(trig_pin, 0);
}

// Callback function for ECHO pin
void echo_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) {
        // Rising edge
        if (user_data != NULL) {
            ((EchoTimestamps *)user_data)->rising_edge_tick = tick;
        }
    } else if (level == 0) {
        // Falling edge
        if (user_data != NULL) {
            ((EchoTimestamps *)user_data)->falling_edge_tick = tick;
        }
    }
}

// Calculate distance in centimeters
double calculate_distance(unsigned int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        return -1.0; // Indicate invalid reading
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Log data to stdout and file
void log_data(double distance, const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    }
    printf("%s,%.2f\n", timestamp, distance);
}

// Log a warning message to stdout
void log_warning(const char *message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

