void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
}

