    // Register signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    }

    EchoTimestamps echo_timestamps = {0, 0};

    // Main loop
    while (running) {
        // Trigger pulse
        trigger_pulse(TRIG_PIN);

        // Wait for echo or timeout
        unsigned int start_time = gpioTick();
        while (running) {
            if (echo_timestamps.rising_edge_tick != 0 && echo_timestamps.falling_edge_tick != 0) {
                // Calculate pulse width
                unsigned int pulse_width = echo_timestamps.falling_edge_tick - echo_timestamps.rising_edge_tick;

                // Calculate distance
                double distance = calculate_distance(pulse_width);

                // Get timestamp
                char timestamp[30];
                get_iso8601_timestamp(timestamp);

                // Log data
                if (distance >= 0) {
                    log_data(distance, timestamp);
                } else {
                    log_warning("Invalid distance reading");
                }

                // Reset echo timestamps
                echo_timestamps.rising_edge_tick = 0;
                echo_timestamps.falling_edge_tick = 0;

                // Break out of timeout loop
                break;
            } else if (gpioTick() - start_time > TIMEOUT_US) {
                // Timeout occurred
                log_warning("Timeout waiting for echo");
                echo_timestamps.rising_edge_tick = 0;
                echo_timestamps.falling_edge_tick = 0;
                break;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // No object detected timeout
        if (echo_timestamps.rising_edge_tick == 0 && echo_timestamps.falling_edge_tick == 0) {
            char timestamp[30];
            get_iso8601_timestamp(timestamp);
            log_warning("No object detected within timeout");
        }

        gpioDelay(200); // 200ms delay
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

