#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define DISTANCE_THRESHOLD_FORWARD 100 // mm
#define DISTANCE_THRESHOLD_BACKWARD 300 // mm
#define DISTANCE_THRESHOLD_STOP 0       // mm
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 10 // ms
#define RETRY_DELAY_MULTIPLIER 2

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void motor_control(int distance);
void signal_handler(int signal);

// VL53L1X register sequence (simplified for example)
const unsigned char reset_sequence[] = {0x00};
const unsigned char start_measurement_sequence[] = {0x01};
const unsigned char data_ready_sequence[] = {0x0089};
const unsigned char distance_read_sequence[] = {0x0096, 0x0097};

// Function to write a sequence of bytes to the VL53L1X
int vl53l1x_write_sequence(int i2c_handle, const unsigned char *sequence, int sequence_len) {
    int result, i;
    for (i = 0; i < sequence_len; i++) {
        result = i2cWriteByteData(i2c_handle, sequence[i], sequence[i]);
        if (result < 0) {
            fprintf(stderr, "Error writing to VL53L1X: %d\n", result);
            return -1;
        }
    }
    return 0;
}

// Function to read a sequence of bytes from the VL53L1X
int vl53l1x_read_sequence(int i2c_handle, const unsigned char *sequence, int sequence_len, unsigned char *data, int data_len) {
    int result, i;
    for (i = 0; i < data_len; i++) {
        result = i2cReadByteData(i2c_handle, sequence[i]);
        if (result < 0) {
            fprintf(stderr, "Error reading from VL53L1X: %d\n", result);
            return -1;
        }
        data[i] = (unsigned char)result;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init(int i2c_handle) {
    int retries = 0;
    int result;

    // Soft reset
    result = vl53l1x_write_sequence(i2c_handle, reset_sequence, sizeof(reset_sequence));
    if (result < 0) return -1;
    gpioDelay(1000); // Wait 1 ms

    // Start measurement
    result = vl53l1x_write_sequence(i2c_handle, start_measurement_sequence, sizeof(start_measurement_sequence));
    if (result < 0) return -1;
    gpioDelay(1000); // Wait 1 ms

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle) {
    unsigned char data[2];
    int distance;
    int retries = 0;
    int result;

    // Wait for data ready
    while (1) {
        result = i2cReadByteData(i2c_handle, data_ready_sequence[0]);
        if (result < 0) {
            fprintf(stderr, "Error reading data ready: %d\n", result);
            return -1;
        }
        if ((result & 0x80) == 0) break; // Check bit 7 (data ready)
        gpioDelay(100); // Wait 100 ms
    }

    // Read distance
    result = vl53l1x_read_sequence(i2c_handle, distance_read_sequence, sizeof(distance_read_sequence), data, sizeof(data));
    if (result < 0) return -1;

    distance = (data[0] << 8) | data[1];
    return distance;
}

// Function to control the DC motor
void motor_control(int distance) {
    static int motor_state = 0; // 0: stop, 1: forward, -1: backward

    if (distance < DISTANCE_THRESHOLD_FORWARD && motor_state != -1) {
        // Stop backward
        gpioWrite(GPIO_BACKWARD, 0);
        motor_state = 0;
    } else if (distance > DISTANCE_THRESHOLD_BACKWARD && motor_state != 1) {
        // Stop forward
        gpioWrite(GPIO_FORWARD, 0);
        motor_state = 0;
    } else if (distance >= DISTANCE_THRESHOLD_STOP && motor_state != 0) {
        // Stop
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 0);
        motor_state = 0;
    } else if (distance < DISTANCE_THRESHOLD_FORWARD && motor_state != 1) {
        // Forward
        gpioWrite(GPIO_FORWARD, 1);
        motor_state = 1;
    } else if (distance > DISTANCE_THRESHOLD_BACKWARD && motor_state != -1) {
        // Backward
        gpioWrite(GPIO_BACKWARD, 1);
        motor_state = -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping...\n", signal);
    running = 0;
}

int main() {
    int distance;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR for GPIO24
    gpioSetISRFuncEx(GPIO24, RISING_EDGE, 0, NULL, NULL);

    printf("VL53L1X sensor and motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            motor_control(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Clean up
    gpioTerminate();
    i2cClose(i2c_handle);

    printf("Program terminated.\n");
    return 0;
}

