// I2C Read Function
int i2c_read_reg(int fd, uint8_t reg) {
    int result;
    if (fd < 0) {
        log_event("Error: I2C file descriptor is invalid.");
        return -1;
    }

    result = ioctl(fd, I2C_SLAVE, reg);
    if (result < 0) {
        log_event("Error: Failed to acquire bus access or talk to slave.");
        return -1;
    }

    result = read(fd, &reg, 1);
    if (result != 1) {
        log_event("Error: Failed to read from I2C device.");
        return -1;
    }

    result = ioctl(fd, I2C_SLAVE, reg + 1); // Move to the next register
    if (result < 0) {
        log_event("Error: Failed to acquire bus access or talk to slave.");
        return -1;
    }

    result = read(fd, &reg, 1);
    if (result != 1) {
        log_event("Error: Failed to read from I2C device.");
        return -1;
    }

    return reg;
}

// I2C Write Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result;
    if (fd < 0) {
        log_event("Error: I2C file descriptor is invalid.");
        return -1;
    }

    result = ioctl(fd, I2C_SLAVE, reg);
    if (result < 0) {
        log_event("Error: Failed to acquire bus access or talk to slave.");
        return -1;
    }

    result = write(fd, &value, 1);
    if (result != 1) {
        log_event("Error: Failed to write to I2C device.");
        return -1;
    }

    return 0;
}

// MPR121 Initialization Function
int mpr121_init(int fd) {
    // Soft Reset
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x63) < 0) {
        log_event("Error: Failed to reset MPR121.");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Verify Sensor Presence
    int sensor_address = i2c_read_reg(fd, 0x5A);
    if (sensor_address < 0) {
        log_event("Error: Failed to read sensor address.");
        return -1;
    }

    if (sensor_address != MPR121_ADDR) {
        log_event("Error: MPR121 not found at address 0x5A.");
        return -1;
    }

    // Stop Mode
    if (mpr121_set_electrode_config(fd, 0x00) < 0) {
        log_event("Error: Failed to set MPR121 to stop mode.");
        return -1;
    }

    // Baseline Filtering
    if (mpr121_set_electrode_config(fd, 0x01) < 0) {
        log_event("Error: Failed to set MPR121 to baseline filtering mode.");
        return -1;
    }

    // Auto-Configuration
    if (mpr121_set_electrode_config(fd, 0x0C) < 0) {
        log_event("Error: Failed to set MPR121 to auto-configuration mode.");
        return -1;
    }

    // Enable All Electrodes
    if (mpr121_set_electrode_config(fd, 0x0C) < 0) {
        log_event("Error: Failed to set MPR121 to enable all electrodes.");
        return -1;
    }

    // Threshold Configuration
    if (mpr121_set_electrode_threshold(fd, 0, 0x0B) < 0) {
        log_event("Error: Failed to set threshold for electrode 0.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 1, 0xC8) < 0) {
        log_event("Error: Failed to set threshold for electrode 1.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 2, 0x82) < 0) {
        log_event("Error: Failed to set threshold for electrode 2.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 3, 0xB4) < 0) {
        log_event("Error: Failed to set threshold for electrode 3.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 4, 0x0B) < 0) {
        log_event("Error: Failed to set threshold for electrode 4.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 5, 0xC8) < 0) {
        log_event("Error: Failed to set threshold for electrode 5.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 6, 0x82) < 0) {
        log_event("Error: Failed to set threshold for electrode 6.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 7, 0xB4) < 0) {
        log_event("Error: Failed to set threshold for electrode 7.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 8, 0x0B) < 0) {
        log_event("Error: Failed to set threshold for electrode 8.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 9, 0xC8) < 0) {
        log_event("Error: Failed to set threshold for electrode 9.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 10, 0x82) < 0) {
        log_event("Error: Failed to set threshold for electrode 10.");
        return -1;
    }
    if (mpr121_set_electrode_threshold(fd, 11, 0xB4) < 0) {
        log_event("Error: Failed to set threshold for electrode 11.");
        return -1;
    }

    return 0;
}

// MPR121 Set Electrode Configuration Function
int mpr121_set_electrode_config(int fd, uint8_t config) {
    if (fd < 0) {
        log_event("Error: I2C file descriptor is invalid.");
        return -1;
    }

    if (i2c_write_reg(fd, MPR121_ELECONFIG0, config) < 0) {
        log_event("Error: Failed to write to MPR121_ELECONFIG0.");
        return -1;
    }

    return 0;
}

// MPR121 Set Electrode Threshold Function
int mpr121_set_electrode_threshold(int fd, uint8_t electrode, uint8_t threshold) {
    if (fd < 0) {
        log_event("Error: I2C file descriptor is invalid.");
        return -1;
    }

    uint8_t reg;
    switch (electrode) {
        case 0: reg = MPR121_ELE0_THR; break;
        case 1: reg = MPR121_ELE1_THR; break;
        case 2: reg = MPR121_ELE2_THR; break;
        case 3: reg = MPR121_ELE3_THR; break;
        case 4: reg = MPR121_ELE4_THR; break;
        case 5: reg = MPR121_ELE5_THR; break;
        case 6: reg = MPR121_ELE6_THR; break;
        case 7: reg = MPR121_ELE7_THR; break;
        case 8: reg = MPR121_ELE8_THR; break;
        case 9: reg = MPR121_ELE9_THR; break;
        case 10: reg = MPR121_ELE10_THR; break;
        case 11: reg = MPR121_ELE11_THR; break;
        default: return -1; // Invalid electrode
    }

    if (i2c_write_reg(fd, reg, threshold) < 0) {
        log_event("Error: Failed to write to MPR121_ELE0_THR.");
        return -1;
    }

    return 0;
}

// MPR121 Read Touch Status Function
int mpr121_read_touch_status(int fd) {
    if (fd < 0) {
        log_event("Error: I2C file descriptor is invalid.");
        return -1;
    }

    int status_l = i2c_read_reg(fd, MPR121_ELE0_STATUS_L);
    if (status_l < 0) {
        log_event("Error: Failed to read ELE0_STATUS_L.");
        return -1;
    }

    int status_h = i2c_read_reg(fd, MPR121_ELE0_STATUS_H);
    if (status_h < 0) {
        log_event("Error: Failed to read ELE0_STATUS_H.");
        return -1;
    }

    return (status_h << 8) | status_l;
}

// Set LED Pattern Function
void set_led_pattern(int led1, int led2, int led3, int led4, int pattern) {
    if (gpio_mutex.lock(&gpio_mutex, 0) != 0) {
        log_event("Error: Failed to lock GPIO mutex.");
        return;
    }

    gpio_set_value(led1, (pattern >> 0) & 1);
    gpio_set_value(led2, (pattern >> 1) & 1);
    gpio_set_value(led3, (pattern >> 2) & 1);
    gpio_set_value(led4, (pattern >> 3) & 1);

    if (gpio_mutex.unlock(&gpio_mutex, 0) != 0) {
        log_event("Error: Failed to unlock GPIO mutex.");
    }
}

// Log Event Function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen("art_installation.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Signal Handler Function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, shutting down...");
        terminate = 1;
    }
}

// Cleanup Function
void cleanup() {
    log_event("Cleaning up resources...");

    // Release GPIO lines
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (gpio_lines[i] != NULL) {
            gpio_line_release(gpio_lines[i]);
        }
    }

    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Release GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Unlock GPIO mutex
    if (gpio_mutex != NULL) {
        pthread_mutex_destroy(gpio_mutex);
    }

    log_event("Cleanup complete. Exiting.");
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (gpio_chip == NULL) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO lines
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "art_installation";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, GPIO_PINS[i]);
        if (gpio_lines[i] == NULL) {
            perror("Error getting GPIO line");
            cleanup();
            return 1;
        }

        if (gpiod_line_request(gpio_lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line");
            cleanup();
            return 1;
        }
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        log_event("Error: MPR121 initialization failed.");
        cleanup();
        return 1;
    }

    log_event("MPR121 initialized successfully.");

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            log_event("Error: Failed to read touch status.");
            sleep(POLL_INTERVAL_MS);
            continue;
        }

        // Check if any electrode is active
        bool any_active = false;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if ((touch_status >> i) & 1) {
                any_active = true;
                break;
            }
        }

        if (any_active) {
            // Determine which electrode is active
            int active_electrode = -1;
            for (int i = 0; i < NUM_ELECTRODES; i++) {
                if ((touch_status >> i) & 1) {
                    active_electrode = i;
                    break;
                }
            }

            // Set LED pattern
            if (active_electrode != -1) {
                int led1, led2, led3, led4;
                switch (active_electrode) {
                    case 0: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 1: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 2: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 3: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 4: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 5: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 6: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 7: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 8: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 9: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 10: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    case 11: led1 = LED1; led2 = LED2; led3 = LED3; led4 = LED4; break;
                    default: log_event("Error: Invalid active electrode.");
                        break;
                }

                set_led_pattern(led1, led2, led3, led4, (active_electrode + 1) % 16); // 0-15
            } else {
                log_event("No electrode is currently active.");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    cleanup();
    return 0;
}

