#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define MPR121_ELECTRODE_0 0
#define MPR121_ELECTRODE_1 1
#define MPR121_ELECTRODE_2 2
#define MPR121_ELECTRODE_3 3
#define MPR121_ELECTRODE_4 4
#define MPR121_ELECTRODE_5 5
#define MPR121_ELECTRODE_6 6
#define MPR121_ELECTRODE_7 7
#define MPR121_ELECTRODE_8 8
#define MPR121_ELECTRODE_9 9
#define MPR121_ELECTRODE_10 10
#define MPR121_ELECTRODE_11 11
#define MPR121_ELECTRODE_12 12
#define MPR121_ELECTRODE_13 13
#define MPR121_ELECTRODE_14 14
#define MPR121_ELECTRODE_15 15

#define MPR121_FFI_REG 0x2B
#define MPR121_SFI_REG 0x2C
#define MPR121_ESI_REG 0x2D
#define MPR121_DEBOUNCE_REG 0x2E
#define MPR121_AFE_CONFIG_REG 0x2F
#define MPR121_BASELINE_FILTERING_REG 0x2A

#define MPR121_TOUCH_THRESHOLD_REG 0x41
#define MPR121_RELEASE_THRESHOLD_REG 0x42

#define LED_GPIO 27

#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_write_register(int handle, uint8_t reg, uint8_t value);
int mpr121_read_register(int handle, uint8_t reg);
int mpr121_init(int handle);
int mpr121_read_electrode(int handle, int electrode);
int mpr121_set_electrode_config(int handle, int electrode, uint8_t touch_threshold, uint8_t release_threshold);
int mpr121_read_device_id(int handle);
void led_on(int gpio);
void led_off(int gpio);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to write a register on the MPR121
int mpr121_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a register on the MPR121
int mpr121_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to initialize the MPR121
int mpr121_init(int handle) {
    // Verify device ID
    int device_id = mpr121_read_register(handle, 0x00);
    if (device_id != 0x5A) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_set_electrode_config(handle, i, 0x0A, 0x05) != 0) {
            fprintf(stderr, "Error configuring electrode %d\n", i);
            return -1;
        }
    }

    // Configure baseline filtering
    if (mpr121_write_register(handle, MPR121_BASELINE_FILTERING_REG, 0x10) != 0) {
        fprintf(stderr, "Error configuring baseline filtering\n");
        return -1;
    }

    // Configure AFE
    if (mpr121_write_register(handle, MPR121_AFE_CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Error configuring AFE\n");
        return -1;
    }

    // Configure debounce
    if (mpr121_write_register(handle, MPR121_DEBOUNCE_REG, 0x01) != 0) {
        fprintf(stderr, "Error configuring debounce\n");
        return -1;
    }

    // Configure FFI and SFI
    if (mpr121_write_register(handle, MPR121_FFI_REG, 0x01) != 0) {
        fprintf(stderr, "Error configuring FFI\n");
        return -1;
    }
    if (mpr121_write_register(handle, MPR121_SFI_REG, 0x01) != 0) {
        fprintf(stderr, "Error configuring SFI\n");
        return -1;
    }

    return 0;
}

// Function to read the value of a specific electrode
int mpr121_read_electrode(int handle, int electrode) {
    if (electrode < 0 || electrode > 11) {
        fprintf(stderr, "Error: Invalid electrode number: %d\n", electrode);
        return -1;
    }

    int reg = MPR121_ELECTRODE_0 + electrode;
    int value = mpr121_read_register(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading electrode %d\n", electrode);
        return -1;
    }
    return value;
}

// Function to set the touch and release thresholds for a specific electrode
int mpr121_set_electrode_config(int handle, int electrode, uint8_t touch_threshold, uint8_t release_threshold) {
    int reg = MPR121_ELECTRODE_0 + electrode;
    if (mpr121_write_register(handle, MPR121_TOUCH_THRESHOLD_REG + reg, touch_threshold) != 0) {
        fprintf(stderr, "Error writing touch threshold for electrode %d\n", electrode);
        return -1;
    }
    if (mpr121_write_register(handle, MPR121_RELEASE_THRESHOLD_REG + reg, release_threshold) != 0) {
        fprintf(stderr, "Error writing release threshold for electrode %d\n", electrode);
        return -1;
    }
    return 0;
}

// Function to read the device ID from the MPR121
int mpr121_read_device_id(int handle) {
    int device_id = mpr121_read_register(handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    return device_id;
}

// Function to turn the LED on
void led_on(int gpio) {
    gpioWrite(gpio, 1);
}

// Function to turn the LED off
void led_off(int gpio) {
    gpioWrite(gpio, 0);
}

// Function to log an event to the log file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read electrode 0
        int touch_value = mpr121_read_electrode(i2c_handle, MPR121_ELECTRODE_0);
        if (touch_value >= 0) {
            // Check if electrode is touched
            if (touch_value > 0) {
                printf("Electrode %d touched\n", MPR121_ELECTRODE_0);
                log_event("Electrode 0 touched");
                led_on(LED_GPIO);
                gpioDelay(1000); // 1 second
                led_off(LED_GPIO);
            }
        }

        gpioDelay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

