#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <pthread.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm

// Global variables
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **trigger_line, struct gpiod_line **echo_line);
int trigger_sensor(struct gpiod_line *trigger_line);
long measure_pulse_width(struct gpiod_line *echo_line, long timeout_us);
double calculate_distance(long pulse_width);
int validate_distance(double distance);
int log_distance(double distance);
void signal_handler(int sig);
void cleanup();

// Function to initialize GPIO lines
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **trigger_line, struct gpiod_line **echo_line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *trigger_line = gpiod_chip_get_line(*chip, TRIGGER_PIN);
    if (!*trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(*chip);
        return -1;
    }

    *echo_line = gpiod_chip_get_line(*chip, ECHO_PIN);
    if (!*echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(*trigger_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*trigger_line, "ultrasonic_sensor_trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(*trigger_line);
        gpiod_line_release(*echo_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_input(*echo_line, "ultrasonic_sensor_echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(*trigger_line);
        gpiod_line_release(*echo_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Function to trigger the sensor
int trigger_sensor(struct gpiod_line *trigger_line) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ultrasonic_sensor_trigger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        perror("Error requesting trigger line as output");
        return -1;
    }

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line value");
        return -1;
    }

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line value");
        return -1;
    }

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line value");
        return -1;
    }

    return 0;
}

// Function to measure the pulse width
long measure_pulse_width(struct gpiod_line *echo_line, long timeout_us) {
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for the echo line to go high
    while (1) {
        if (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            break;
        }
        if (timeout_us <= 0) {
            return -1; // Timeout
        }
        usleep(1000); // Check every 1us
    }

    // Wait for the echo line to go low
    while (1) {
        if (gpiod_line_get_value(echo_line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            return pulse_width;
        }
        if (timeout_us <= 0) {
            return -1; // Timeout
        }
        usleep(1000); // Check every 1us
    }

    return -1; // Should not reach here
}

// Function to calculate the distance
double calculate_distance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // cm
}

// Function to validate the distance
int validate_distance(double distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Function to log the distance
int log_distance(double distance) {
    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (distance < 0) {
        fprintf(log_file, "%s,ERROR: Invalid distance reading\n", timestamp);
    } else if (!validate_distance(distance)) {
        fprintf(log_file, "%s,ERROR: Distance out of range: %.2f cm\n", timestamp, distance);
    } else {
        fprintf(log_file, "%s,%.2f cm\n", timestamp, distance);
    }
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&log_mutex);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio(&chip, &trigger_line, &echo_line) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        if (trigger_sensor(trigger_line) < 0) {
            fprintf(stderr, "Sensor trigger failed. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Measure the pulse width
        long pulse_width = measure_pulse_width(echo_line, TIMEOUT_US);
        if (pulse_width < 0) {
            fprintf(stderr, "Sensor timeout or error. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Validate the distance
        if (validate_distance(distance)) {
            // Log the distance
            log_distance(distance);
        } else {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

