#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_PULSE_WIDTH 58.0   // us
#define MAX_PULSE_WIDTH 25000.0 // us
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int pulse_start_tick = 0;
static volatile int pulse_end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        pulse_start_tick = tick;
        echo_received = 1; // Indicate that an echo has been received
    } else if (level == 0) {
        pulse_end_tick = tick;
    }
}

// Function to calculate distance in meters
double calculate_distance(uint32_t pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate an error
    }

    // Handle tick wrap-around
    if (pulse_width > 4294967295) {
        pulse_width -= 4294967296;
    }

    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2e6 for cm/s
    return distance;
}

// Function to log distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
