#include <time.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x0000
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP 0x001E
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP 0x0024
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_SPAD_NB_DETECTED 0x0016
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0 0x001E

// GPIO pin for triggering the sensor
#define TRIGGER_PIN 27

// I2C handle
int i2c_handle;

// Signal handler flags
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x()
{
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        syslog(LOG_ERR, "Failed to read sensor ID");
        return -1;
    }
    if (sensor_id != 0xEA) {
        syslog(LOG_ERR, "Incorrect sensor ID: 0x%02X", sensor_id);
        return -1;
    }

    // Configure continuous mode
    if (i2cWriteByteData(i2c_handle, 0x0018, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        return -1;
    }

    // Configure no timeout
    if (i2cWriteByteData(i2c_handle, 0x0019, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        return -1;
    }

    // Configure start ranging
    if (i2cWriteByteData(i2c_handle, 0x0020, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0020");
        return -1;
    }

    return 0;
}

// Function to read distance and status from the VL53L1X sensor
int read_distance(int *distance, int *status)
{
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 0); // Active-low trigger
    gpioDelay(1); // Small delay
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(TRIGGER_PIN, 0);

    // Read distance and status
    int distance_high = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0);
    int distance_low = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0 + 1);
    int status_byte = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);

    if (distance_high < 0 || distance_low < 0 || status_byte < 0) {
        syslog(LOG_ERR, "Failed to read distance or status");
        return -1;
    }

    // Combine high and low bytes (little-endian)
    *distance = (distance_high << 8) | distance_low;
    *status = status_byte;

    return 0;
}

int main()
{
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1); // Set high initially

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    int distance, status;
    while (!terminate) {
        if (read_distance(&distance, &status) == 0) {
            // Get current timestamp
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

            // Log data to syslog
            syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp, distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

