#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20.0 // cm
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Read model ID
    char model_id[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x010F, model_id, 2) != 2) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id[0] != 0xEA || model_id[1] != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X0x\n", model_id[0]);
        return -1;
    }

    // Set ranging mode to short
    char ranging_mode = 0x00;
    if (i2cWriteI2CBlockData(i2c_handle, 0x0021, &ranging_mode, 1) != 1) {
        fprintf(stderr, "Error writing ranging mode\n");
        return -1;
    }

    // Start ranging
    char start_ranging = 0x01;
    if (i2cWriteI2CBlockData(i2c_handle, 0x0015, &start_ranging, 1) != 1) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char distance_high = 0;
    char distance_low = 0;

    if (i2cReadI2CBlockData(i2c_handle, 0x0089, &distance_high, 1) != 1) {
        fprintf(stderr, "Error reading distance high byte\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, 0x008A, &distance_low, 1) != 1) {
        fprintf(stderr, "Error reading distance low byte\n");
        return -1;
    }

    // Combine high and low bytes to form 16-bit distance
    int distance = (distance_high << 8) | distance_low;

    return distance;
}

// Control gate actuator
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_GPIO, 1); // Open gate
    } else {
        gpioWrite(GATE_GPIO, 0); // Close gate
    }
}

// Log data to file
void log_data(int distance, int gate_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm, Gate: %s\n", timestamp, distance, gate_state ? "Open" : "Closed");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initialize gate to closed state

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            control_gate(distance);
            log_data(distance, gpioRead(GATE_GPIO));
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    gpioTerminate();

    return 0;
}

