#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout
#define MAX_DISTANCE 400.0     // cm
#define MIN_DISTANCE 2.0      // cm
#define MIN_PULSE_WIDTH 500   // us
#define MAX_PULSE_WIDTH 2500  // us
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_MIN_ANGLE 0.0
#define SERVO_MAX_ANGLE 180.0
#define SERVO_CENTER_ANGLE 90.0

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulseWidth);
float calculateServoAngle(float distance);
void setServoAngle(int angle);
void logData(float distance, float servoAngle);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulseIn(int pin, int level, int timeout) {
    long start = gpioTick();
    long end = start;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        if (gpioTick() - start > timeout) {
            return -1; // Timeout
        }
    }
    start = gpioTick();

    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        if (gpioTick() - end > timeout) {
            return -1; // Timeout
        }
    }
    end = gpioTick();

    return end - start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Error: timeout or invalid pulse width
    return (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to calculate the servo angle based on the distance
float calculateServoAngle(float distance) {
    // Non-linear mapping (logarithmic)
    float angle = SERVO_CENTER_ANGLE * (1.0 - log10((distance + MIN_DISTANCE) / MAX_DISTANCE));

    // Clamp the angle to the valid range
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    return angle;
}

// Function to set the servo angle
void setServoAngle(int angle) {
    int pulseWidth = (int)((angle / SERVO_MAX_ANGLE) * (MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, pulseWidth);
}

// Function to log the data to a CSV file
void logData(float distance, float servoAngle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, servoAngle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
    setServoAngle(SERVO_CENTER_ANGLE); // Set servo to center
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance(cm),ServoAngle(deg)\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        triggerSensor();

        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);
        if (pulseWidth < 0) {
            fprintf(stderr, "Error: No echo received or timeout occurred.\n");
            setServoAngle(SERVO_CENTER_ANGLE);
            logData(-1.0, SERVO_CENTER_ANGLE);
        } else {
            float distance = calculateDistance(pulseWidth);
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
                setServoAngle(SERVO_CENTER_ANGLE);
                logData(-1.0, SERVO_CENTER_ANGLE);
            } else {
                float servoAngle = calculateServoAngle(distance);
                setServoAngle((int)servoAngle);
                logData(distance, servoAngle);
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    setServoAngle(SERVO_CENTER_ANGLE);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

