#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 200 // mm
#define BUFFER_SIZE 10

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t distance_buffer;

// Function prototypes
int init_vl53l1x();
int read_distance();
void add_to_buffer(int distance);
int get_average_distance();
void set_led_state(int state);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0; // Initialize to 0
    }
}

// Add a value to the circular buffer
void add_to_buffer(int distance) {
    distance_buffer.buffer[distance_buffer.head] = distance;
    distance_buffer.head = (distance_buffer.head + 1) % BUFFER_SIZE;
    if (distance_buffer.count < BUFFER_SIZE) {
        distance_buffer.count++;
    }
}

// Get the average distance from the buffer
int get_average_distance() {
    if (distance_buffer.count == 0) {
        return 0; // Return 0 if the buffer is empty
    }

    int sum = 0;
    for (int i = 0; i < distance_buffer.count; i++) {
        sum += distance_buffer.buffer[i];
    }
    return sum / distance_buffer.count;
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Recommended initialization sequence (example, adjust as needed)
    // This is a simplified example and may need adjustments based on the datasheet
    char data[2];
    int result;

    // Example: Write a register (replace with actual initialization sequence)
    data[0] = VL53L1X_REG_SYSRANGE_START; // Example register
    data[1] = 0x01; // Example value
    result = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1); // Write 1 byte
    if (result < 0) {
        fprintf(stderr, "Error writing to VL53L1X: %d\n", result);
        return -1;
    }

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    result = i2cReadI2CBlockData(i2c_handle, data[0], data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    if (data[0] != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Enable signal rate check (example)
    data[0] = 0x02; // Example register
    data[1] = 0x01; // Example value
    result = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1); // Write 1 byte
    if (result < 0) {
        fprintf(stderr, "Error writing signal rate check: %d\n", result);
        return -1;
    }

    // Configure cross-talk compensation (example)
    data[0] = 0x03; // Example register
    data[1] = 0x00; // Example value
    result = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1); // Write 1 byte
    if (result < 0) {
        fprintf(stderr, "Error writing cross-talk compensation: %d\n", result);
        return -1;
    }

    // Start ranging (example)
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01;
    result = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1); // Write 1 byte
    if (result < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", result);
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char data[2];
    int result;

    // Read range status (example)
    data[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    result = i2cReadI2CBlockData(i2c_handle, data[0], data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading range status: %d\n", result);
        return -1;
    }

    // Read distance (example)
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    result = i2cReadI2CBlockData(i2c_handle, data[0], data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    return (data[0] << 8) | data[1]; // Combine the two bytes into a 16-bit value
}

// Set the state of the LED
void set_led_state(int state) {
    gpioWrite(GPIO_LED, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    set_led_state(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&distance_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            add_to_buffer(distance);
            int average_distance = get_average_distance();
            printf("Distance: %d mm, Average: %d mm\n", distance, average_distance);

            if (average_distance < DISTANCE_THRESHOLD) {
                set_led_state(1); // Turn on LED
            } else {
                set_led_state(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

