    // Start ranging (example)
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01;
    result = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1); // Write 1 byte
    if (result < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", result);
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char data[2];
    int result;

    // Read range status (example)
    data[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    result = i2cReadI2CBlockData(i2c_handle, data[0], data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading range status: %d\n", result);
        return -1;
    }

    // Read distance (example)
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    result = i2cReadI2CBlockData(i2c_handle, data[0], data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    return (data[0] << 8) | data[1]; // Combine the two bytes into a 16-bit value
}

// Set the state of the LED
void set_led_state(int state) {
    gpioWrite(GPIO_LED, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    set_led_state(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
