        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&distance_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            add_to_buffer(distance);
            int average_distance = get_average_distance();
            printf("Distance: %d mm, Average: %d mm\n", distance, average_distance);

            if (average_distance < DISTANCE_THRESHOLD) {
