            } else {
                set_led_state(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

