#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROXIMITY_REG 0x08
#define THRESHOLD_REG 0x0A
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int threshold = 1000; // Default threshold
int running = 1; // Flag for graceful shutdown

// Mutex for thread safety
pthread_mutex_t mutex;

// Function prototypes
int init_i2c(int bus, int addr);
int read_proximity(int handle);
int write_register(int handle, int reg, int value);
int read_register(int handle, int reg);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity, const char *status);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read proximity value
int read_proximity(int handle) {
    int high_byte, low_byte;

    high_byte = read_register(handle, PROXIMITY_REG);
    low_byte = read_register(handle, PROXIMITY_REG + 1);

    if (high_byte < 0 || low_byte < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

// Function to write to a register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read from a register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity;
    pthread_mutex_lock(&mutex);
    proximity = read_proximity(i2c_handle);
    pthread_mutex_unlock(&mutex);

    if (proximity >= 0) {
        if (proximity <= threshold) {
            log_data(proximity, "SAFE");
        } else {
            log_data(proximity, "ALERT");
        }
    }
}

