void log_data(int proximity, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %d, %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, proximity, status);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default threshold.\n");
            threshold = 1000;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, SI1102_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        i2cClose(i2c_handle);
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    i2cClose(i2c_handle);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();

    printf("Proximity sensor monitoring stopped.\n");

    return 0;
}

