#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000      // 200 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz

// Global variables
volatile int echo_start = 0;
volatile int echo_end = 0;
volatile int echo_valid = 0;
double distance = 0.0;
double frequency = 0.0;

// Function prototypes
void triggerSensor();
double getDistance();
double mapDistanceToFrequency(double distance);
void setFrequency(double frequency);
void echoCallback(int gpio, int level, uint32_t tick);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

// Trigger the HC-SR04 sensor
void triggerSensor() {
    gpioTrigger(TRIGGER_PIN, 10, 1); // 10 us trigger pulse
}

// Get the distance from the HC-SR04 sensor
double getDistance() {
    echo_valid = 0; // Reset echo validity flag
    echo_start = 0;  // Reset echo start time
    echo_end = 0;    // Reset echo end time

    // Wait for echo to start
    int timeout = 0;
    while (echo_start == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (echo_start == 0) {
        return -1.0; // Timeout
    }

    // Wait for echo to end
    timeout = 0;
    while (echo_end == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }

    if (echo_end == 0) {
        return -1.0; // Timeout
    }

    // Calculate pulse width in microseconds
    int pulse_width = echo_end - echo_start;

    // Calculate distance in centimeters
    distance = (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Invalid distance
    }

    return distance;
}

// Map the distance to a frequency using a logarithmic function
double mapDistanceToFrequency(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return 200 * exp(distance / 50.0);
    }
}

// Set the frequency of the PWM output
void setFrequency(double frequency) {
    if (frequency >= MIN_FREQUENCY && frequency <= MAX_FREQUENCY) {
        int range = 1000000; // PWM range (adjust as needed)
        int duty_cycle = (int)(range * 0.5); // 50% duty cycle
        gpioPWM(PWM_PIN, duty_cycle); // Set PWM duty cycle
        frequency = (double)duty_cycle / range * 2000.0; // Convert back to Hz
    } else {
        // Frequency out of range, set to previous valid frequency
        frequency = (double)(100000 / 1000.0); // Set to 100Hz
    }
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start = tick;
    } else if (level == 0) {
        echo_end = tick;
        echo_valid = 1; // Set echo validity flag
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(PWM_PIN, 1000000);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN, 1000); // 1 kHz

    // Set PWM duty cycle (50%)
    gpioPWM(PWM_PIN, 500000); // 50% duty cycle

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Get the distance
        double distance = getDistance();

        // Map the distance to a frequency
        double frequency = mapDistanceToFrequency(distance);

        // Set the frequency
        setFrequency(frequency);

        // Print the distance and frequency (for debugging)
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay
        gpioDelay(50); // 50 ms delay
    }

    return 0;
}

