#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms timeout

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = 0, end_tick = 0;

        // Wait for echo to go high with timeout
        int count = 0;
        while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
            start_tick = gpioTick();
            count++;
        }
        if (count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            gpioTerminate();
            return 1;
        }

        // Wait for echo to go low with timeout
        count = 0;
        while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
            end_tick = gpioTick();
            count++;
        }
        if (count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            gpioTerminate();
            return 1;
        }

        uint32_t pulse_width = end_tick - start_tick;

        double distance = (pulse_width / 2.0) / 29.1;

        if (distance < 2.0 || distance > 400.0) {
            printf("Invalid reading\n");
        } else if (distance < 10.0) {
            printf("Too close!\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        gpioDelay(500); // 500ms delay
    }

    gpioTerminate();
    return 0;
}

