#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor registers
#define ICU20201_REG_MEAS_MODE 0x01
#define ICU20201_REG_RANGE 0x02
#define ICU20201_REG_MEAS_TRIGGER 0x00
#define ICU20201_REG_DISTANCE_HIGH 0x0C
#define ICU20201_REG_DISTANCE_LOW 0x0D

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance();
void log_distance(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    // Set continuous measurement mode
    if (spiWrite(spi_handle, &ICU20201_REG_MEAS_MODE, 1, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x01: %s\n", strerror(errno));
        return -1;
    }

    // Set range to 5m
    if (spiWrite(spi_handle, &ICU20201_REG_RANGE, 1, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x02: %s\n", strerror(errno));
        return -1;
    }

    // Trigger measurement
    if (spiWrite(spi_handle, &ICU20201_REG_MEAS_TRIGGER, 1, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x00: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance() {
    char tx_buf[2];
    char rx_buf[2];

    // Read high byte
    tx_buf[0] = ICU20201_REG_DISTANCE_HIGH;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error reading high byte: %s\n", strerror(errno));
        return -1;
    }
    int high_byte = rx_buf[1];

    // Read low byte
    tx_buf[0] = ICU20201_REG_DISTANCE_LOW;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error reading low byte: %s\n", strerror(errno));
        return -1;
    }
    int low_byte = rx_buf[1];

    // Combine high and low bytes to get the distance
    int distance = (high_byte << 8) | low_byte;

    return distance;
}

// Function to log the distance to a file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

