#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x60
#define ALS_VIS_LSB 0x22
#define ALS_VIS_MSB 0x23

#define I2C_DEVICE "/dev/i2c-1"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int read_als_visible(int fd) {
    uint8_t lsb, msb;
    if (i2c_read(fd, ALS_VIS_LSB, &lsb) != 0) return -1;
    if (i2c_read(fd, ALS_VIS_MSB, &msb) != 0) return -1;

    uint16_t als_visible = (msb << 8) | lsb;
    return als_visible;
}

int log_data(const char *filename, uint16_t als_visible) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%u\n", timestamp, als_visible);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = i2c_open(I2C_DEVICE);
    if (fd < 0) {
        return 1;
    }

    while (program_running) {
        uint16_t als_visible = read_als_visible(fd);
        if (als_visible >= 0) {
            if (log_data("proximity_log.csv", als_visible) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading ALS visible value.\n");
        }

        sleep(5);
    }

    close(fd);
    return 0;
}

