#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define ALS_DATA_REG 0x22
#define ALS_DATA_LEN 2
#define PROX_DATA_REG 0x24
#define PROX_DATA_LEN 2

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_write(int fd, int reg, int val) {
    int result = write(fd, &reg, 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    result = write(fd, &val, 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, int reg, unsigned char *buf, int len) {
    int result = write(fd, &reg, 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    result = read(fd, buf, len);
    if (result != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int si1182_init(int fd) {
    int part_id;

    // Verify Part ID
    if (i2c_read(fd, PART_ID_REG, &part_id, 1) != 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }

    if (part_id != 0x44) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure Measurement Rate
    if (i2c_write(fd, MEAS_RATE_REG, 0x07) != 0) {
        fprintf(stderr, "Error configuring Measurement Rate\n");
        return -1;
    }

    return 0;
}

int si1182_read_ambient_light(int fd, unsigned short *ambient_light) {
    unsigned char buf[ALS_DATA_LEN];
    if (i2c_read(fd, ALS_DATA_REG, buf, ALS_DATA_LEN) != 0) {
        fprintf(stderr, "Error reading ambient light data\n");
        return -1;
    }

    *ambient_light = (buf[1] << 8) | buf[0];
    return 0;
}

int si1182_read_proximity(int fd, unsigned short *proximity) {
    unsigned char buf[PROX_DATA_LEN];
    if (i2c_read(fd, PROX_DATA_REG, buf, PROX_DATA_LEN) != 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    *proximity = (buf[1] << 8) | buf[0];
    return 0;
}

int main() {
    int fd;
    unsigned short ambient_light, proximity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *log_file;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = i2c_open(I2C_BUS, SI1182_ADDR);
    if (fd < 0) {
        return 1;
    }

    if (si1182_init(fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(fd);
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(fd);
        return 1;
    }

    while (program_running) {
        if (si1182_read_ambient_light(fd, &ambient_light) == 0 &&
            si1182_read_proximity(fd, &proximity) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s,%.1f,%u\n", timestamp, ambient_light * 0.1, proximity);
            fflush(log_file);

            printf("%s,%.1f,%u\n", timestamp, ambient_light * 0.1, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100 ms
    }

    fclose(log_file);
    close(fd);

    return 0;
}

