#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define BUZZER_DURATION 500 // ms

// Global variables
static volatile int echo_start = 0;
static volatile int echo_end = 0;
static volatile int echo_valid = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        running = 0;
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end = tick;
        echo_valid = 1; // Set validity flag
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for echo to be valid
        int timeout = 1000; // Timeout after 1ms
        while (!echo_valid && timeout > 0) {
            gpioDelay(1); // Wait 1 us
            timeout--;
        }

        if (!echo_valid) {
            fprintf(stderr, "Timeout waiting for echo\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Calculate pulse width
        uint32_t pulse_width = echo_end - echo_start;

        // Calculate distance
        float distance = (pulse_width * SPEED_OF_SOUND) / 2.0;

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Activate buzzer if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
            gpioDelay(BUZZER_DURATION); // Wait for buzzer duration
            gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        } else {
            gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio

    return 0;
}

