    // Map distance to pulse width (linear mapping)
    float pulse_width = SERVO_MIN_PULSE_WIDTH + (distance * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (SERVO_MAX_DISTANCE - SERVO_MIN_DISTANCE));

