#define VL53L1X_REG_RANGING_MODE 0x0020
#define VL53L1X_REG_TIMING_BUDGET 0x001E
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// VL53L1X initialization sequence
int vl53l1x_init(int i2c_handle) {
    // Check model ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Set ranging mode to short distance
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    // Set timing budget (adjust as needed)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set timing budget\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X
int vl53l1x_read_distance(int i2c_handle) {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        return -1;
    }
    return distance;
}

