    }

    // Cleanup
    printf("Cleaning up...\n");
    servo_set_pulse_width(SERVO_GPIO, SERVO_CLOSE_PULSE_WIDTH); // Close the gate
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

