int init_si7005() {
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00); // Set CONFIG register to 0x00
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to CONFIG register: %d. Retrying...\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to initialize Si7005 after multiple retries.\n");
    return -1; // Failure
}

