    int raw_temperature, raw_humidity;
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Read temperature
        raw_temperature = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temperature < 0) {
            fprintf(stderr, "Error reading temperature: %d. Retrying...\n", raw_temperature);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        // Read humidity
        raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
        if (raw_humidity < 0) {
            fprintf(stderr, "Error reading humidity: %d. Retrying...\n", raw_humidity);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        // Convert raw values to temperature and humidity
        *temperature = (175.72 * raw_temperature) / 65536.0 - 46.85;
        *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read Si7005 data after multiple retries.\n");
    return -1; // Failure
}

