    while (!terminate) {
        // Read temperature and humidity
        if (read_si7005(&temperature, &humidity) == 0) {
            // Print the readings
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // Delay in microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
