#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not reset MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Set sample rate divider to 7 (125 Hz)
    if (i2cWriteByteData(i2c_handle, 0x19, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range to ±250 deg/s
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Read MPU-6050 data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[14];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14);

    if (result < 0) {
        fprintf(stderr, "Error: Could not read MPU-6050 data\n");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x  = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y  = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z  = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Print MPU-6050 data
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    printf("Accel: X=%6d, Y=%6d, Z=%6d  |  Gyro: X=%6d, Y=%6d, Z=%6d\n",
           accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (1) {
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            print_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read MPU-6050 data. Retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

