        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC checksum failure\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    uint16_t raw_humidity = (buffer[3] << 8) | buffer[4];

    data->temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    data->humidity = -6.0 + 125.0 * raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (data->humidity < 0.0) data->humidity = 0.0;
    if (data->humidity > 100.0) data->humidity = 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sht40(&sensor_data) == 0) {
