#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, unsigned char *buf, int len) {
    int bytes_written = write(fd, buf, len);
    if (bytes_written < 0) {
        perror("Error writing to I2C device");
        return -1;
    }
    return bytes_written;
}

int i2c_read(int fd, unsigned char *buf, int len) {
    int bytes_read = read(fd, buf, len);
    if (bytes_read < 0) {
        perror("Error reading from I2C device");
        return -1;
    }
    return bytes_read;
}

int i2c_ioctl(int fd, unsigned char *buf, int len) {
    int bytes_written = write(fd, buf, len);
    if (bytes_written < 0) {
        perror("Error writing to I2C device (ioctl)");
        return -1;
    }
    return bytes_written;
}

int sht40_read(int fd, float *temperature, float *humidity) {
    unsigned char cmd[1] = {MEASURE_CMD};
    unsigned char data[6];

    if (i2c_ioctl(fd, cmd, 1) < 0) {
        fprintf(stderr, "Failed to send measurement command.\n");
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    usleep(10000); // 10ms

    if (i2c_read(fd, data, 6) < 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    // CRC validation
    if (data[0] != data[2] || data[3] != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert raw data
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = 100.0 * raw_humidity / 65535.0;

    return 0;
}

int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    int fd;
    float temperature, humidity;
    unsigned char cmd[1] = {MEASURE_CMD};
    unsigned char data[6];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    fd = i2c_open(I2C_BUS);
    if (fd < 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        if (sht40_read(fd, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds...\n");
            // Attempt to re-open the I2C device
            i2c_close(fd);
            fd = i2c_open(I2C_BUS);
            if (fd < 0) {
                fprintf(stderr, "Failed to re-open I2C device. Exiting.\n");
                program_running = 0; // Exit loop if re-opening fails
            }
        }

        sleep(5);
    }

    // Close I2C device and log file on exit
    i2c_close(fd);

    return 0;
}

