#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define CONTINUOUS_MEASUREMENT_CMD 0x21
#define CONTINUOUS_MEASUREMENT_CMD_LENGTH 2
#define MEASUREMENT_DATA_LENGTH 6
#define RETRY_COUNT 3
#define MAX_RETRIES 10 // Exponential backoff limit

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Structure for sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int length);
sensor_data_t process_data(uint8_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SDP31
int send_command(int handle, uint16_t command) {
    uint8_t cmd[2];
    cmd[0] = (command >> 8) & 0xFF;
    cmd[1] = command & 0xFF;

    int retries = 0;
    int delay_ms = 1;
    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) == 2) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write failed (attempt %d/%d), retrying in %d ms...\n", retries + 1, RETRY_COUNT, delay_ms);
        gpioDelay(delay_ms * 1000); // pigpioDelay takes microseconds
        retries++;
        delay_ms *= 2; // Exponential backoff
        if (delay_ms > MAX_RETRIES) {
            delay_ms = MAX_RETRIES;
        }
    }
    fprintf(stderr, "I2C write failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read data from SDP31
int read_data(int handle, uint8_t *data, int length) {
    int retries = 0;
    int delay_ms = 1;
    while (retries < RETRY_COUNT) {
        if (i2cReadDevice(handle, (char *)data, length) == length) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d), retrying in %d ms...\n", retries + 1, RETRY_COUNT, delay_ms);
        gpioDelay(delay_ms * 1000); // pigpioDelay takes microseconds
        retries++;
        delay_ms *= 2; // Exponential backoff
        if (delay_ms > MAX_RETRIES) {
            delay_ms = MAX_RETRIES;
        }
    }
    fprintf(stderr, "I2C read failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// Process raw data to pressure and temperature
sensor_data_t process_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure_pa = (float)raw_pressure / 60.0;
    sensor_data.temperature_c = (float)raw_temperature / 200.0;

    return sensor_data;
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t data[MEASUREMENT_DATA_LENGTH];
    sensor_data_t sensor_data;
    while (running) {
        // Read data from sensor
        if (read_data(i2c_handle, data, MEASUREMENT_DATA_LENGTH) == 0) {
            // Process data
            sensor_data = process_data(data);

            // Log data
            if (log_data(log_file, sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait 100 ms
        gpioDelay(100 * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

