        if (result == count) {
            return result;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }
