float read_temperature(int handle) {
    char buf[2];
    int raw_temp;

    // Send temperature measurement command
    if (i2c_write_retry(handle, (char *)&TEMP_CMD, 1) != 1) {
        fprintf(stderr, "Failed to send temperature command.\n");
        return -1000.0; // Indicate error
    }

    // Wait for measurement to complete (polling)
    gpioDelay(20000); // Wait 20 ms

