#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define TRIGGER_MEASUREMENT 0x362F
#define DATA_LENGTH 9

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_write(int fd, unsigned char *data, int length);
int i2c_read(int fd, unsigned char *data, int length);
unsigned char crc8(const unsigned char *data, int length);
sensor_data_t read_sdp800(int fd);
void log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int length) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int length) {
    if (write(fd, data, length) != length) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int length) {
    if (read(fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from SDP800 sensor
sensor_data_t read_sdp800(int fd) {
    unsigned char data[DATA_LENGTH];
    sensor_data_t sensor_data;
    unsigned char *pressure_data = data;
    unsigned char *temperature_data = data + 3;
    unsigned char *scale_data = data + 6;

    // Trigger continuous measurement
    unsigned char trigger_data[2] = {(TRIGGER_MEASUREMENT >> 8) & 0xFF, TRIGGER_MEASUREMENT & 0xFF};
    if (i2c_write(fd, trigger_data, 2) != 0) {
        fprintf(stderr, "Error triggering measurement.\n");
        sensor_data.pressure = -1.0; // Indicate error
        sensor_data.temperature = -1.0;
        return sensor_data;
    }

    // Wait for measurement (adjust as needed)
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 45000 * 1000; // 45 ms
    nanosleep(&delay, NULL);

    // Read 9 bytes of data
    if (i2c_read(fd, data, DATA_LENGTH) != 0) {
        fprintf(stderr, "Error reading data from sensor.\n");
        sensor_data.pressure = -1.0; // Indicate error
        sensor_data.temperature = -1.0;
        return sensor_data;
    }

    // Validate CRC for pressure
    unsigned char pressure_crc = crc8(data, 3);
    if (pressure_crc != data[2]) {
        fprintf(stderr, "Pressure CRC error: calculated 0x%02X, received 0x%02X\n", pressure_crc, data[2]);
        sensor_data.pressure = -1.0; // Indicate error
    } else {
        sensor_data.pressure = (float)((int16_t)((data[0] << 8) | data[1])) / 10.0; // Pa
    }

    // Validate CRC for temperature
    unsigned char temperature_crc = crc8(temperature_data, 3);
    if (temperature_crc != temperature_data[2]) {
        fprintf(stderr, "Temperature CRC error: calculated 0x%02X, received 0x%02X\n", temperature_crc, temperature_data[2]);
        sensor_data.temperature = -1.0; // Indicate error
    } else {
        sensor_data.temperature = (float)((int16_t)((temperature_data[0] << 8) | temperature_data[1])) / 200.0; // °C
    }

    // Validate CRC for scale factor
    unsigned char scale_crc = crc8(scale_data, 3);
    if (scale_crc != scale_data[2]) {
        fprintf(stderr, "Scale factor CRC error: calculated 0x%02X, received 0x%02X\n", scale_crc, scale_data[2]);
        sensor_data.pressure = -1.0; // Indicate error
    } else {
        sensor_data.pressure = (float)((int16_t)((data[0] << 8) | data[1])) / 10.0; // Pa
    }

    return sensor_data;
}

// Function to log data to file
void log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature) < 0) {
        perror("Error writing to log file");
    }
    fflush(fp); // Ensure data is written immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    fflush(log_file);

    // Main loop
    while (program_running) {
        sensor_data_t sensor_data = read_sdp800(i2c_fd);

        if (sensor_data.pressure != -1.0 && sensor_data.temperature != -1.0) {
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log.\n");
        }

        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&delay, NULL);
    }

    // Close resources before exiting
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

