    unsigned char temperature_crc = crc8(temperature_data, 3);
    if (temperature_crc != temperature_data[2]) {
        fprintf(stderr, "Temperature CRC error: calculated 0x%02X, received 0x%02X\n", temperature_crc, temperature_data[2]);
        sensor_data.temperature = -1.0; // Indicate error
    } else {
        sensor_data.temperature = (float)((int16_t)((temperature_data[0] << 8) | temperature_data[1])) / 200.0; // °C
    }

    // Validate CRC for scale factor
    unsigned char scale_crc = crc8(scale_data, 3);
    if (scale_crc != scale_data[2]) {
        fprintf(stderr, "Scale factor CRC error: calculated 0x%02X, received 0x%02X\n", scale_crc, scale_data[2]);
        sensor_data.pressure = -1.0; // Indicate error
    } else {
        sensor_data.pressure = (float)((int16_t)((data[0] << 8) | data[1])) / 10.0; // Pa
    }

    return sensor_data;
}

// Function to log data to file
void log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature) < 0) {
        perror("Error writing to log file");
    }
    fflush(fp); // Ensure data is written immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    fflush(log_file);

    // Main loop
    while (program_running) {
        sensor_data_t sensor_data = read_sdp800(i2c_fd);

        if (sensor_data.pressure != -1.0 && sensor_data.temperature != -1.0) {
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log.\n");
        }

        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&delay, NULL);
    }

    // Close resources before exiting
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

