    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command(i2c_handle, MEASURE_CMD) != 0) {
            log_error("Failed to send measurement command");
        } else {
            // Wait for conversion (at least 15ms)
            gpioDelay(15000); // 15ms

            // Read sensor data
            uint8_t data[3];
            if (read_sensor_data(i2c_handle, data, 3) != 0) {
                log_error("Failed to read sensor data");
            } else {
                // Validate CRC
                uint8_t crc = calculate_crc(data, 2);
                if (crc != data[2]) {
                    log_error("CRC mismatch");
                } else {
                    // Convert raw value to Celsius
                    uint16_t raw_value = (data[0] << 8) | data[1];
                    float temperature = convert_to_celsius(raw_value);

                    // Log the data
                    log_data(temperature);
                }
            }
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    fclose(log_file);
    fclose(error_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

