#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define PRESSURE_SCALE_FACTOR 240.0
#define TEMPERATURE_SCALE 200.0
#define TEMPERATURE_OFFSET -45.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int validate_crc(unsigned char *data, int len, unsigned char polynomial) {
    unsigned char crc = 0;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
