#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
float read_temperature();
float read_humidity();
void control_fan(float temperature);
void add_to_buffer(CircularBuffer *cb, float value);
void print_buffer(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from Si7021
float read_temperature() {
    char cmd = 0xE3;
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            gpioDelay(10); // Wait for measurement
            result = i2cReadDevice(i2c_handle, buf, 2);
            if (result == 2) {
                uint16_t raw_temp = (buf[0] << 8) | buf[1];
                return 175.72 * raw_temp / 65536.0 - 46.85;
            } else {
                fprintf(stderr, "I2C read error (temp): %d\n", result);
            }
        } else {
            fprintf(stderr, "I2C write error (temp): %d\n", result);
        }
        gpioDelay(1000); // Wait before retry
    }
    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -999.0; // Indicate error
}

// Read humidity from Si7021
float read_humidity() {
    char cmd = 0xE5;
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            gpioDelay(10); // Wait for measurement
            result = i2cReadDevice(i2c_handle, buf, 2);
            if (result == 2) {
                uint16_t raw_humidity = (buf[0] << 8) | buf[1];
                return 125.0 * raw_humidity / 65536.0 - 6.0;
            } else {
                fprintf(stderr, "I2C read error (humidity): %d\n", result);
            }
        } else {
            fprintf(stderr, "I2C write error (humidity): %d\n", result);
        }
        gpioDelay(1000); // Wait before retry
    }
    fprintf(stderr, "Failed to read humidity after %d retries.\n", RETRY_COUNT);
    return -999.0; // Indicate error
}

// Control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Print the contents of the circular buffer
void print_buffer(CircularBuffer *cb) {
    printf("Temperature and Humidity Log:\n");
    for (int i = 0; i < cb->count; ++i) {
        int index = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Timestamp: %ld, Temperature: %.2f, Humidity: %.2f\n", time(NULL), cb->buffer[index], cb->buffer[index]);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer log_buffer = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        float temperature = read_temperature();
        float humidity = read_humidity();

        // Check for sensor-absent conditions
        if (temperature == -999.0 && humidity == -999.0) {
            fprintf(stderr, "Sensor-absent condition detected. Exiting.\n");
            cleanup();
            return 1;
        }

        // Control the fan
        control_fan(temperature);

        // Add to circular buffer
        add_to_buffer(&log_buffer, temperature);
        add_to_buffer(&log_buffer, humidity);

        // Print the buffer
        print_buffer(&log_buffer);

        // Wait for 2 seconds
        gpioDelay(2000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

