#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// Start Periodic Measurement command
#define START_PERIODIC_MEASUREMENT 0x21B1

// Data Ready command
#define DATA_READY 0xE4B8

// Read Measurement command
#define READ_MEASUREMENT 0xEC05

// Stop Periodic Measurement command
#define STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
int verify_crc(uint16_t data, uint8_t crc);
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify CRC checksum
int verify_crc(uint16_t data, uint8_t crc) {
    uint8_t polynomial = CRC_POLYNOMIAL;
    uint8_t crc_calculated = 0xFF;
    uint8_t data_bytes[2];

    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t ready_data[2];
    uint8_t read_data_bytes[9];

    // Wait for data ready
    while (1) {
        if (send_command(DATA_READY) != 0) {
            fprintf(stderr, "Failed to send data ready command\n");
            return -1;
        }
        gpioDelay(1000); // Wait 1ms

        if (read_data(ready_data, 2) != 0) {
            fprintf(stderr, "Failed to read data ready\n");
            return -1;
        }

        if ((ready_data[0] << 8) | ready_data[1] == 0xE4B8) {
            break;
        }
    }

    // Read measurement data
    if (send_command(READ_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send read measurement command\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    if (read_data(read_data_bytes, 9) != 0) {
        fprintf(stderr, "Failed to read measurement data\n");
        return -1;
    }

    // Verify CRC for CO2
    if (!verify_crc(read_data_bytes[0], read_data_bytes[1])) {
        fprintf(stderr, "CRC error for CO2\n");
        return -1;
    }

    // Verify CRC for Temperature
    if (!verify_crc(read_data_bytes[2], read_data_bytes[3])) {
        fprintf(stderr, "CRC error for Temperature\n");
        return -1;
    }

    // Verify CRC for Humidity
    if (!verify_crc(read_data_bytes[4], read_data_bytes[5])) {
        fprintf(stderr, "CRC error for Humidity\n");
        return -1;
    }

    data->co2 = (read_data_bytes[0] << 8) | read_data_bytes[1];
    data->temperature = (read_data_bytes[2] << 8) | read_data_bytes[3];
    data->humidity = (read_data_bytes[4] << 8) | read_data_bytes[5];

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

