        if (send_command(DATA_READY) != 0) {
            fprintf(stderr, "Failed to send data ready command\n");
            return -1;
        }
        gpioDelay(1000); // Wait 1ms

        if (read_data(ready_data, 2) != 0) {
            fprintf(stderr, "Failed to read data ready\n");
            return -1;
        }

        if ((ready_data[0] << 8) | ready_data[1] == 0xE4B8) {
