    if (!verify_crc(read_data_bytes[0], read_data_bytes[1])) {
        fprintf(stderr, "CRC error for CO2\n");
        return -1;
    }

    // Verify CRC for Temperature
    if (!verify_crc(read_data_bytes[2], read_data_bytes[3])) {
        fprintf(stderr, "CRC error for Temperature\n");
        return -1;
    }

    // Verify CRC for Humidity
    if (!verify_crc(read_data_bytes[4], read_data_bytes[5])) {
        fprintf(stderr, "CRC error for Humidity\n");
        return -1;
    }

    data->co2 = (read_data_bytes[0] << 8) | read_data_bytes[1];
    data->temperature = (read_data_bytes[2] << 8) | read_data_bytes[3];
