#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define GPIO_LED 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL 5 // seconds

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int get_data_ready_status();
int read_measurement(uint8_t *data);
int validate_crc(uint16_t data);
int stop_periodic_measurement();
int read_sensor_data(uint8_t *data);
void log_data(uint16_t co2, float temperature, float humidity);
void control_led(uint16_t co2);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    uint8_t command[2] = {(0x21B1 >> 8) & 0xFF, 0x21B1 & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to get data ready status
int get_data_ready_status() {
    uint8_t command[2] = {(0xE4B8 >> 8) & 0xFF, 0xE4B8 & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write data ready status command: %d\n", result);
        return -1;
    }
    uint8_t data[2];
    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Function to read measurement data
int read_measurement(uint8_t *data) {
    uint8_t command[2] = {(0xEC05 >> 8) & 0xFF, 0xEC05 & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 0) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(uint16_t data) {
    uint8_t crc = 0xFF;
    uint8_t bit;
    uint8_t byte;

    for (int i = 0; i < 8; i++) {
        crc ^= (data & 0x01);
        data >>= 1;
        if (crc & 0x80) {
            crc = 0xFF - (crc << 1);
        } else {
            crc <<= 1;
        }
    }

    if (crc != 0) {
        fprintf(stderr, "CRC check failed for data 0x%04X\n", data);
        return -1;
    }

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    uint8_t command[2] = {(0x3F86 >> 8) & 0xFF, 0x3F86 & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    if (read_measurement(data) != 0) {
        return -1;
    }

    if (validate_crc(data[0] << 8 | data[1]) != 0) {
        return -1;
    }
    if (validate_crc(data[2] << 8 | data[3]) != 0) {
        return -1;
    }
    if (validate_crc(data[4] << 8 | data[5]) != 0) {
        return -1;
    }
    if (validate_crc(data[6] << 8 | data[7]) != 0) {
        return -1;
    }
    if (validate_crc(data[8] << 8 | data[9]) != 0) {
        return -1;
    }

    return 0;
}

// Function to log data to the circular buffer
void log_data(uint16_t co2, float temperature, float humidity) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to control the LED based on CO2 level
void control_led(uint16_t co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SCD40 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Check if data is ready
        int data_ready = get_data_ready_status();
        if (data_ready < 0) {
            fprintf(stderr, "Error getting data ready status, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        if (data_ready & 1) {
            uint8_t data[9];
            if (read_sensor_data(data) == 0) {
                uint16_t co2 = (data[0] << 8) | data[1];
                float temperature = -45 + 175 * ((float)data[3] / 65535.0);
                float humidity = 100 * ((float)data[5] / 65535.0);

                printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);

                log_data(co2, temperature, humidity);
                control_led(co2);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Wait for the measurement interval
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement during shutdown\n");
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    printf("SCD40 sensor monitoring stopped.\n");

    return 0;
}

