#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL 5 // seconds
#define TIMEOUT_MS 50
#define MAX_RETRIES 3
#define MAX_TEMPERATURE 150.0
#define MIN_TEMPERATURE -40.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure pulse width
long measure_pulse_width(int gpio, int level, uint64_t tick, void *user_data) {
    uint64_t start_tick = tick;
    while (gpioRead(gpio) != level) {
        if (gpioTick() - tick > TIMEOUT_MS * 1000) {
            return 0; // Timeout
        }
    }
    uint64_t end_tick = gpioTick();
    return end_tick - start_tick;
}

// Function to read temperature from TMP05
float read_temperature(int gpio) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        long th = 0, tl = 0;
        int high_count = 0;
        int total_count = 0;

        // Measure high pulse width
        gpioSetMode(gpio, PI_INPUT);
        gpioSetAlertFunc(gpio, measure_pulse_width);
        gpioSetAlertFuncEx(gpio, measure_pulse_width, NULL, NULL); // Use alert function for both rising and falling edges

        uint64_t start_time = gpioTick();
        while (high_count < 1000) { // Measure for 1 second
            total_count += gpioTick() - start_time;
            if (gpioTick() - start_time > SAMPLE_INTERVAL * 1000) break;
        }
        th = total_count;

        gpioSetAlertFunc(gpio, NULL); // Disable alert function

        // Measure total cycle width
        gpioSetMode(gpio, PI_INPUT);
        gpioSetAlertFunc(gpio, measure_pulse_width);
        gpioSetAlertFuncEx(gpio, measure_pulse_width, NULL, NULL); // Use alert function for both rising and falling edges

        uint64_t start_time_total = gpioTick();
        while (total_count < 1000) { // Measure for 1 second
            total_count += gpioTick() - start_time_total;
            if (gpioTick() - start_time_total > SAMPLE_INTERVAL * 1000) break;
        }
        tl = total_count;

        gpioSetAlertFunc(gpio, NULL); // Disable alert function

        if (tl == 0) {
            fprintf(stderr, "Error: Total cycle width is zero. Retrying...\n");
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate temperature
        float temperature = 4215.0 - (2143.0 * (float)th / (float)tl);
        return temperature;
    }

    fprintf(stderr, "Error: Max retries reached. Sensor malfunction.\n");
    return -273.15; // Return absolute zero as an error value
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    char log_entry[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (temperature > MIN_TEMPERATURE && temperature < MAX_TEMPERATURE) {
        snprintf(log_entry, sizeof(log_entry), "%s, %.2f\n", timestamp, temperature);
        FILE *fp = fopen("temperature_log.txt", "a");
        if (fp != NULL) {
            fprintf(fp, "%s", log_entry);
            fclose(fp);
        } else {
            fprintf(stderr, "Error opening temperature_log.txt for writing.\n");
        }
    } else {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature = read_temperature(GPIO_PIN);
        if (temperature > -273.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error: Invalid temperature reading.\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

