#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x24
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define LOG_FILE "environmental_data.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int read_sht35(int handle, float *temperature, float *humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
float apply_simulated_offset(float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c(I2C_BUS, SHT35_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature, humidity;
        time_t now = time(NULL);
        struct tm *tstruct = gmtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            temperature = apply_simulated_offset(temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read data from SHT35 sensor
int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (retry %d): %d\n", retries + 1, i2cWriteDevice(handle, (char *)cmd, 2));
            retries++;
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }

        gpioDelay(15000); // Wait at least 15 ms

        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "I2C read failed (retry %d): %d\n", retries + 1, i2cReadDevice(handle, (char *)data, 6));
            retries++;
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }

        // CRC validation
        uint8_t temp_crc = crc8(data, 2);
        uint8_t hum_crc = crc8(data + 3, 2);

        if (temp_crc != data[2] || hum_crc != data[5]) {
            fprintf(stderr, "CRC validation failed (retry %d).\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }

        // Convert data
        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_humidity = (data[3] << 8) | data[4];

        *temperature = convert_temperature(raw_temp);
        *humidity = convert_humidity(raw_humidity);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT35 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + (175.0 * (float)raw_temp / 65535.0);
}

// Convert raw humidity data to %RH
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Apply simulated offset
float apply_simulated_offset(float temperature, float humidity) {
    float offset_temp = 2.0 + (2.0 * sin((time_t)time(NULL) / 3600.0 + 1.0));
    float offset_humidity = 5.0 + (5.0 * sin((time_t)time(NULL) / 3600.0 + 1.0));

    return temperature + offset_temp;
}

// Log data to file
int log_data(float temperature, float humidity) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

