    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, uint8_t *data) {
    if (i2cWriteByte(i2c_handle, MEASURE_CMD) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command.\n");
        return -1;
    }
    gpioDelay(45000); // Wait for conversion (45ms)

    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error: Failed to read data from sensor. Read %d bytes, expected 9.\n", bytes_read);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(data, 1) != data[1] || crc8(data + 2, 1) != data[3] ||
        crc8(data + 4, 1) != data[6] || crc8(data + 5, 1) != data[8]) {
        fprintf(stderr, "Error: CRC checksums invalid.\n");
        return -1;
    }

    return 0;
}

