#define MEASURE_CMD 0x2400
#define CSV_FILE "environment.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t crc);
sensor_data_t read_sensor_data(int handle);
char* get_iso8601_timestamp();
int write_to_csv(const char *timestamp, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Read sensor data
sensor_data_t read_sensor_data(int handle) {
    uint8_t data[6];
    if (send_command(handle, MEASURE_CMD) != 0) {
        sensor_data_t error_data = {0.0, 0.0};
        return error_data;
    }
    gpioDelay(15); // Wait for measurement (datasheet specifies 12.1ms for high repeatability)

    if (read_data(handle, data, 6) != 0) {
        sensor_data_t error_data = {0.0, 0.0};
        return error_data;
    }

    // Validate CRC
    if (!validate_crc(data, 2, data[2]) || !validate_crc(data + 3, 2, data[5])) {
        sensor_data_t error_data = {0.0, 0.0};
        return error_data;
    }

    // Convert raw data to temperature and humidity
    int16_t raw_temperature = (data[0] << 8) | data[1];
    int16_t raw_humidity = (data[3] << 8) | data[4];

    sensor_data_t sensor_data;
    sensor_data.temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    sensor_data.humidity = 100.0 * raw_humidity / 65535.0;

    return sensor_data;
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Write data to CSV file
int write_to_csv(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is empty or doesn't contain a header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c(I2C_BUS, SHT35_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data(i2c_handle);

        if (sensor_data.temperature != 0.0) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Write data to CSV file
            if (write_to_csv(timestamp, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to write data to CSV\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

