#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define RESET_CMD 0xFE
#define HUMIDITY_CMD 0xF5
#define TEMPERATURE_CMD 0xF3
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write(int fd, const unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
unsigned char calculate_crc(const unsigned char *data, int len);
int si7021_reset(int fd);
int si7021_read_humidity(int fd, float *humidity);
int si7021_read_temperature(int fd, float *temperature);
void log_data(float temperature, float humidity);
void signal_handler(int signum);
void cleanup();

// CRC-8 checksum calculation
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, const unsigned char *data, int len) {
    int bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    int bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Si7021 reset function
int si7021_reset(int fd) {
    unsigned char reset_data[1] = {RESET_CMD};
    if (i2c_write(fd, reset_data, 1) != 0) {
        fprintf(stderr, "Error resetting Si7021\n");
        return -1;
    }
    return 0;
}

// Si7021 read humidity function
int si7021_read_humidity(int fd, float *humidity) {
    unsigned char humidity_data[3];
    unsigned char cmd = HUMIDITY_CMD;

    if (i2c_write(fd, &cmd, 1) != 0) {
        fprintf(stderr, "Error sending humidity command\n");
        return -1;
    }

    // Wait for data to be ready (polling with a timeout)
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    int timeout = 100; // 100ms timeout
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
