#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define PRESSURE_OFFSET 1000.0
#define TEMPERATURE_OFFSET 45.0
#define SAMPLE_INTERVAL_US 1000000 // 1 second
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw pressure to Pascals
float convert_pressure(uint16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR - PRESSURE_OFFSET;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / TEMPERATURE_SCALE_FACTOR - TEMPERATURE_OFFSET;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    size_t elements_written = fwrite(&pressure, sizeof(float), 1, fp);
    elements_written += fwrite(&temperature, sizeof(float), 1, fp);
    if (elements_written != 2) {
        fprintf(stderr, "Error writing data to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen("airflow.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t data[9];
    while (!terminate) {
        // Read sensor data with retries
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(i2c_handle, data, 9) == 0) {
                // Validate CRC
                uint8_t pressure_crc = crc8(data, 2);
                uint8_t temperature_crc = crc8(data + 3, 2);

                if (pressure_crc == data[2] && temperature_crc == data[5]) {
                    // Convert data
                    uint16_t raw_pressure = (data[0] << 8) | data[1];
                    uint16_t raw_temperature = (data[3] << 8) | data[4];

                    float pressure = convert_pressure(raw_pressure);
                    float temperature = convert_temperature(raw_temperature);

                    // Log data
                    if (log_data(fp, pressure, temperature) != 0) {
                        break; // Exit retry loop if logging fails
                    }
                    break; // Exit retry loop if data read is successful
                } else {
                    fprintf(stderr, "CRC validation failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
            }
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping this sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US); // Wait for 1 second
    }

    // Close file and I2C
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

