#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int *raw_data);
float convert_to_flow_rate(int raw_data);
void set_fan_speed(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    int raw_data;
    float flow_rate;
} sensor_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data.raw_data) == 0) {
            sensor_data.flow_rate = convert_to_flow_rate(sensor_data.raw_data);
            set_fan_speed(sensor_data.flow_rate);
            log_data(sensor_data.flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0.0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 100); // Set PWM range to 100 for percentage

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_sensor_data(int *raw_data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return 1;
    }

    // Combine the two bytes into a 16-bit value
    *raw_data = (buffer[0] << 8) | buffer[1];

    // Mask off the status bits (MSB and LSB)
    *raw_data = (*raw_data & 0x3FFF); // 14-bit data

    return 0;
}

float convert_to_flow_rate(int raw_data) {
    // Linear transfer function
    float flow_rate = (float)(raw_data - 1638) * (10.0 / 14745.0);
    return flow_rate;
}

void set_fan_speed(float flow_rate) {
    // Linear mapping from 0 SLPM to 100% duty cycle
    float duty_cycle = flow_rate / 10.0;
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    gpioPWM(FAN_GPIO, (int)(duty_cycle * 100)); // pigpioPWM takes 0-100
}

void log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

