#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_register(int reg, uint8_t *value);
int write_register(int reg, uint8_t value);
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // I2C bus 1, address 0x5D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the LPS33HW sensor
int init_sensor() {
    uint8_t who_am_i;

    if (read_register(CTRL_REG1, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1: block data update, 10 Hz output rate, active mode
    if (write_register(CTRL_REG1, 0xB0) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read a register from the LPS33HW
int read_register(int reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Write a register to the LPS33HW
int write_register(int reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read pressure data from the LPS33HW
int read_pressure(int32_t *pressure) {
    uint8_t xl, l, h;

    if (read_register(PRESS_OUT_XL, &xl) != 0) return -1;
    if (read_register(PRESS_OUT_L, &l) != 0) return -1;
    if (read_register(PRESS_OUT_H, &h) != 0) return -1;

    *pressure = (int32_t)((h << 16) | (l << 8) | xl);
    return 0;
}

// Read temperature data from the LPS33HW
int read_temperature(int16_t *temperature) {
    uint8_t l, h;

    if (read_register(TEMP_OUT_L, &l) != 0) return -1;
    if (read_register(TEMP_OUT_H, &h) != 0) return -1;

    *temperature = (int16_t)((h << 8) | l);
    return 0;
}

// Convert raw pressure data to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature data to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int32_t raw_pressure;
    int16_t raw_temperature;
    float pressure_hpa, temperature_celsius;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&raw_pressure) == 0 && read_temperature(&raw_temperature) == 0) {
            // Convert data
            pressure_hpa = convert_pressure(raw_pressure);
            temperature_celsius = convert_temperature(raw_temperature);

            // Log data
