#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD 28.0
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void update_led(float average_temperature);
void signal_handler(int signal);
void cleanup();
void init_circular_buffer(CircularBuffer *cb);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from STLM75 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // Swap bytes (little-endian to big-endian)
    uint16_t swapped_temp = (buf[1] << 8) | buf[0];

    // Right-shift by 7 bits and divide by 2
    *temperature = (float)(swapped_temp >> 7) / 2.0;

    return 0;
}

// Update LED based on average temperature
void update_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    float sum = 0.0;
    int count = 0;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            // Update circular buffer
            temp_buffer.buffer[temp_buffer.head] = temperature;
            temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
            if (temp_buffer.count < BUFFER_SIZE) {
                temp_buffer.count++;
            }

            // Calculate running average
            sum += temperature;
            count++;
            if (count == BUFFER_SIZE) {
                float average_temperature = sum / BUFFER_SIZE;
                update_led(average_temperature);
                printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
                sum = 0.0;
                count = 0;
            }
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

