void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SCD30 sensor
int initialize_scd30() {
    uint8_t cmd[2];
    uint8_t data[2];

    // Start continuous measurement with ambient pressure compensation disabled
    cmd[0] = (CMD_START_CONT_MEAS >> 8) & 0xFF;
    cmd[1] = CMD_START_CONT_MEAS & 0xFF;
    data[0] = 0x00; // Argument 1
    data[1] = 0x00; // Argument 2

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(log_file, "Error writing start continuous measurement command: %d\n", i2c_handle);
        return -1;
    }
    if (crc8(data, 2, 0xFF) != 0) {
        fprintf(log_file, "Error writing start continuous measurement command (CRC): %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read data from SCD30 sensor
SCD30_Data read_scd30_data() {
    SCD30_Data data;
    uint8_t cmd[2];
    uint8_t read_data[18];
    int retries = 3;

    // Poll for data ready
    while (retries > 0) {
        cmd[0] = (CMD_GET_DATA_READY >> 8) & 0xFF;
        cmd[1] = CMD_GET_DATA_READY & 0xFF;
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(log_file, "Error writing get data ready command: %d\n", i2c_handle);
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }
        gpioDelay(1000); // Wait 1ms

        if (i2cReadDevice(i2c_handle, (char *)read_data, 2) != 0) {
            fprintf(log_file, "Error reading data ready status: %d\n", i2c_handle);
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        if (read_data[0] != 0x00) {
            fprintf(log_file, "Data not ready (status = 0x%02X): %d\n", read_data[0], i2c_handle);
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        break; // Data ready
    }

    if (retries == 0) {
        fprintf(log_file, "Failed to get data ready after multiple retries: %d\n", i2c_handle);
        data.co2 = 0; // Indicate error
        data.temperature = 0;
        data.humidity = 0;
        data.crc_co2 = 0;
        data.crc_temperature = 0;
        data.crc_humidity = 0;
        return data;
    }

    // Read measurement data
    cmd[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_READ_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(log_file, "Error writing read measurement command: %d\n", i2c_handle);
        data.co2 = 0; // Indicate error
        data.temperature = 0;
        data.humidity = 0;
        data.crc_co2 = 0;
        data.crc_temperature = 0;
        data.crc_humidity = 0;
        return data;
    }

    if (i2cReadDevice(i2c_handle, (char *)read_data, 18) != 0) {
        fprintf(log_file, "Error reading measurement data: %d\n", i2c_handle);
        data.co2 = 0; // Indicate error
        data.temperature = 0;
        data.humidity = 0;
        data.crc_co2 = 0;
        data.crc_temperature = 0;
        data.crc_humidity = 0;
        return data;
    }

    // Verify CRC
    if (crc8((uint8_t *)read_data, 16, 0xFF) != read_data[16]) {
        fprintf(log_file, "CRC error for humidity: %d\n", i2c_handle);
        data.humidity = 0; // Indicate error
    } else if (crc8((uint8_t *)(read_data + 17), 16, 0xFF) != read_data[17]) {
        fprintf(log_file, "CRC error for temperature: %d\n", i2c_handle);
        data.temperature = 0; // Indicate error
    } else if (crc8((uint8_t *)(read_data + 34), 16, 0xFF) != read_data[35]) {
        fprintf(log_file, "CRC error for CO2: %d\n", i2c_handle);
        data.co2 = 0; // Indicate error
    } else {
        data.co2 = (read_data[0] << 8) | read_data[1];
        data.temperature = (read_data[2] << 8) | read_data[3];
        data.humidity = (read_data[4] << 8) | read_data[5];
    }

    return data;
}

// Log data to file
void log_data(SCD30_Data data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Drive ventilation system
void drive_ventilation(int co2_ppm) {
    if (co2_ppm < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2_ppm < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (initialize_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        SCD30_Data data = read_scd30_data();

        if (data.co2 != 0) {
            log_data(data);
            drive_ventilation(data.co2);
        } else {
            fprintf(log_file, "Error reading sensor data\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

