        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len);
    if (crc != data[len]) {
        fprintf(stderr, "CRC checksum mismatch!\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    sensor_data.temperature = (float)raw_temperature / 200.0;

    return sensor_data;
}

// Function to log the sensor data
void log_data(const sensor_data_t *data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f C\n", data->pressure, data->temperature);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and I2C
    if (initialize() != 0) {
        return 1;
    }

    // Send continuous measurement command
    if (send_command(CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        if (read_data(data) == 0) {
            // Validate CRC checksums
            if (validate_crc(data, 3) == 0 && validate_crc(data + 6, 3) == 0) {
                sensor_data_t sensor_data = convert_data(data);
                log_data(&sensor_data);
            } else {
                fprintf(stderr, "CRC validation failed, skipping data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Close I2C connection and terminate pigpio
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

