#define I2C_DEVICE "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define MEASURE_CONFIG 0x00

int i2c_fd = -1; // Global file descriptor for I2C

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the HDC1000 sensor
int init_hdc1000(int fd) {
    unsigned char config_data[2];
    config_data[0] = CONFIG_REG;
    config_data[1] = MEASURE_CONFIG; // Enable temperature and humidity measurement

    if (write(fd, config_data, 2) != 2) {
        perror("Failed to write to configuration register");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int read_hdc1000(int fd, float *temperature, float *humidity) {
    unsigned char data[4];
    unsigned char temp_reg = TEMP_REG;
    unsigned char humid_reg = HUMID_REG;

    // Write temperature register address
    if (write(fd, &temp_reg, 1) != 1) {
        perror("Failed to write temperature register address");
        return -1;
    }

    // Wait for conversion (at least 20ms)
    usleep(20000); // 20ms

    // Read temperature and humidity data
    if (read(fd, data, 4) != 4) {
        perror("Failed to read temperature and humidity data");
        return -1;
    }

    // Combine the two bytes for each measurement
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[2] << 8) | data[3];

    // Convert raw values to temperature and humidity
    *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

// Function to log the temperature and humidity readings
void log_reading(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (init_hdc1000(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize HDC1000 sensor\n");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    // Main loop to read and log temperature and humidity
    while (1) {
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            log_reading(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity\n");
        }

        sleep(5);
    }

    // The program should never reach here due to the signal handler
    close(i2c_fd);
    return 0;
}

