    }
    gpioTerminate();
    exit(0);
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle) {
    int pressure = i2cReadWordData(i2c_handle, PRESSURE_REGISTER);
    if (pressure < 0) {
        fprintf(stderr, "Error reading pressure: %d\n", pressure);
        return -1; // Indicate an error
    }
    return pressure;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
