        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int pressure = read_pressure(i2c_handle);
        if (pressure >= 0) {
            // Get current time
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Print timestamp and pressure value
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Pressure: %d\n", timestamp, pressure);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
        }

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

