// I2C address of the ICP-10101 sensor
#define I2C_ADDR 0x63

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Measurement command for high-precision mode
#define MEASURE_CMD 0x40

// Number of calibration coefficients to read
#define NUM_CALIBRATION_COEFFICIENTS 4

// Structure to hold calibration coefficients
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c2;
    uint16_t c3;
} calibration_coefficients_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_calibration_coefficients(calibration_coefficients_t *coeffs);
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, const calibration_coefficients_t *coeffs);
double compensate_pressure(int32_t raw_pressure, const calibration_coefficients_t *coeffs);
int trigger_measurement();
int read_measurement(int32_t *temperature, int32_t *pressure);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration coefficients from the sensor
int read_calibration_coefficients(calibration_coefficients_t *coeffs) {
    char buf[NUM_CALIBRATION_COEFFICIENTS * 2]; // Each coefficient is 2 bytes
    int result = i2cReadDevice(i2c_handle, buf, NUM_CALIBRATION_COEFFICIENTS * 2);
    if (result != NUM_CALIBRATION_COEFFICIENTS * 2) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

