#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PRESSURE_REG_MSB 0xAA
#define PRESSURE_REG_LSB 0xAB
#define PRESSURE_REG_CMD 0x00 // Command register for pressure measurement
#define PRESSURE_REG_STATUS 0x01 // Status register for pressure measurement
#define PRESSURE_REG_DATA 0x02 // Pressure data register

#define PRESSURE_SCALE_FACTOR 0.1 // kPa per unit

int i2c_fd = -1; // Global file descriptor for I2C

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to trigger a pressure measurement
int trigger_measurement(int fd) {
    // Send command to trigger pressure measurement (example command)
    if (write(fd, PRESSURE_REG_CMD, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the pressure value from the sensor
int read_pressure(int fd, unsigned short *pressure) {
    unsigned char msb, lsb;

    // Read MSB
    if (write(fd, PRESSURE_REG_DATA, 1) != 1) {
        perror("Error writing to I2C device (MSB select)");
        return -1;
    }
    if (read(fd, &msb, 1) != 1) {
        perror("Error reading from I2C device (MSB)");
        return -1;
    }

    // Read LSB
    if (write(fd, PRESSURE_REG_DATA + 1, 1) != 1) {
        perror("Error writing to I2C device (LSB select)");
        return -1;
    }
    if (read(fd, &lsb, 1) != 1) {
        perror("Error reading from I2C device (LSB)");
        return -1;
    }

    *pressure = (msb << 8) | lsb;
    return 0;
}

// Function to convert the raw pressure value to kPa
float convert_to_kPa(unsigned short raw_pressure) {
    return (float)raw_pressure * PRESSURE_SCALE_FACTOR;
}

// Function to log the pressure reading with a timestamp
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        unsigned short raw_pressure;
        if (trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Error triggering measurement. Continuing.\n");
            sleep(1);
            continue;
        }

        if (read_pressure(i2c_fd, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading pressure. Continuing.\n");
            sleep(1);
            continue;
        }

        float pressure_kPa = convert_to_kPa(raw_pressure);
        log_pressure(pressure_kPa);

        sleep(1);
    }

    return 0;
}

