#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define LOG_FILE "pressure_log.txt"
#define SLEEP_MS 45

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_write(int fd, const unsigned char *buf, int len);
int i2c_read(int fd, unsigned char *buf, int len);
int send_measurement_command(int fd);
int read_sensor_data(int fd, unsigned char *data);
sensor_data_t process_sensor_data(const unsigned char *data);
int validate_crc(const unsigned char *data, int len);
int log_data(float pressure, float temperature);
void signal_handler(int sig);

// I2C open function
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, const unsigned char *buf, int len) {
    if (write(fd, buf, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Send measurement command function
int send_measurement_command(int fd) {
    unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    if (i2c_write(fd, command, 2) != 0) {
        fprintf(stderr, "Failed to send measurement command.\n");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, unsigned char *data) {
    unsigned char cmd[2] = {0x00, 0x00}; // Dummy command to trigger read
    if (i2c_write(fd, cmd, 2) != 0) {
        fprintf(stderr, "Failed to send read command.\n");
        return -1;
    }
    usleep(10000); // Wait for sensor to prepare data (10ms)

    if (i2c_read(fd, data, 9) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }
    return 0;
}

// Process sensor data function
sensor_data_t process_sensor_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    // Extract raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Validate CRC
    if (!validate_crc(data, 2) || !validate_crc(data + 2, 2)) {
        fprintf(stderr, "CRC validation failed.\n");
        sensor_data.pressure = -1.0; // Indicate error
        sensor_data.temperature = -1.0;
        return sensor_data;
    }

    // Convert raw values to physical units
    sensor_data.pressure = (float)raw_pressure / PRESSURE_SCALE;
    sensor_data.temperature = (float)raw_temperature / TEMPERATURE_SCALE;

    return sensor_data;
}

// Validate CRC function
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Log data function
int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Send measurement command
    if (send_measurement_command(i2c_fd) != 0) {
