void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Read pressure data from the sensor
int read_pressure(int handle) {
    char buffer[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(handle, PRESSURE_REG, buffer, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int raw_value = (buffer[0] << 8) | buffer[1];
            return raw_value;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Convert raw pressure value to kPa
float convert_to_kPa(int raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Log data to CSV file
void log_data(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Check if pressure is within safe range
void check_pressure_range(float pressure_kPa) {
    if (pressure_kPa < MIN_PRESSURE || pressure_kPa > MAX_PRESSURE) {
        fprintf(stderr, "Warning: Pressure %.2f kPa is outside safe range (%.2f - %.2f kPa).\n", pressure_kPa, MIN_PRESSURE, MAX_PRESSURE);
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, MLX90821_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open pressure_log.csv\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created (size 0) and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Main loop
    while (!terminate) {
        // Read pressure
        int raw_pressure = read_pressure(i2c_handle);
        if (raw_pressure >= 0) {
            // Convert to kPa
            float pressure_kPa = convert_to_kPa(raw_pressure);

            // Log data
            log_data(pressure_kPa);

            // Check pressure range
            check_pressure_range(pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

