#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define SENT_GPIO 4
#define PULSE_GPIO 17
#define LED_GPIO 27

// Define SENT parameters
#define SENT_TICK_TIME 3
#define SENT_SYNCH_PULSE 56
#define SENT_STATUS_NIBBLE 8
#define SENT_DATA_NIBBLES 3
#define SENT_CHECKSUM_NIBBLE 4

// Define linear transfer function parameters
#define SCALE 0.1
#define OFFSET 0.0

// Define timeout and error threshold
#define TIMEOUT_US 100000 // 100ms
#define ERROR_THRESHOLD 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data[SENT_DATA_NIBBLES];
    unsigned int checksum;
} SENT_Data;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int read_sent_data(SENT_Data *data);
float convert_to_pressure(unsigned int raw_value);
void log_pressure(float pressure);
void log_error(const char *message);
void blink_led(int duration_ms);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetMode(PULSE_GPIO, PI_OUTPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    gpioWrite(LED_GPIO, 0); // Turn off LED initially

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Read SENT data from the sensor
int read_sent_data(SENT_Data *data) {
    unsigned int start_time, end_time;
    unsigned int pulse_width;
    int i;

    // Wait for the synchronization pulse
    while (gpioRead(SENT_GPIO) == 0 && running) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    start_time = gpioTick();

    while (gpioRead(SENT_GPIO) == 1 && running) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    end_time = gpioTick();

    if (end_time - start_time > TIMEOUT_US) {
        log_error("Timeout waiting for data");
        return 1; // Timeout
    }

    // Read the status nibble
    for (i = 0; i < SENT_STATUS_NIBBLE; i++) {
        while (gpioRead(SENT_GPIO) == 0 && running) {
            gpioDelay(1);
        }
        start_time = gpioTick();
        while (gpioRead(SENT_GPIO) == 1 && running) {
            gpioDelay(1);
        }
        end_time = gpioTick();
        if (end_time - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for status nibble");
            return 1; // Timeout
        }
        pulse_width = end_time - start_time;
        if (pulse_width < ERROR_THRESHOLD || pulse_width > (TIMEOUT_US * 9 / SENT_STATUS_NIBBLE)) { // 12-271 us
            log_error("Invalid status nibble pulse width");
            return 1; // Error
        }
        data->status = (unsigned int)pulse_width;
    }

    // Read the data nibbles
    for (i = 0; i < SENT_DATA_NIBBLES; i++) {
        for (int j = 0; j < SENT_DATA_NIBBLES; j++) {
            while (gpioRead(SENT_GPIO) == 0 && running) {
                gpioDelay(1);
            }
            start_time = gpioTick();
            while (gpioRead(SENT_GPIO) == 1 && running) {
                gpioDelay(1);
            }
            end_time = gpioTick();
            if (end_time - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data nibble");
                return 1; // Timeout
            }
            pulse_width = end_time - start_time;
            if (pulse_width < ERROR_THRESHOLD || pulse_width > (TIMEOUT_US * 9 / SENT_DATA_NIBBLES)) { // 12-271 us
                log_error("Invalid data nibble pulse width");
                return 1; // Error
            }
            data->data[j] = (unsigned int)pulse_width;
        }
    }

    // Read the checksum nibble
    for (i = 0; i < SENT_CHECKSUM_NIBBLE; i++) {
        while (gpioRead(SENT_GPIO) == 0 && running) {
            gpioDelay(1);
        }
        start_time = gpioTick();
        while (gpioRead(SENT_GPIO) == 1 && running) {
            gpioDelay(1);
        }
        end_time = gpioTick();
        if (end_time - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for checksum nibble");
            return 1; // Timeout
        }
        pulse_width = end_time - start_time;
        if (pulse_width < ERROR_THRESHOLD || pulse_width > (TIMEOUT_US * 9 / SENT_CHECKSUM_NIBBLE)) { // 12-271 us
            log_error("Invalid checksum nibble pulse width");
            return 1; // Error
        }
        data->checksum = (unsigned int)pulse_width;
    }

    return 0;
}

// Convert raw data to pressure (Pa)
float convert_to_pressure(unsigned int raw_value) {
    return (float)raw_value * SCALE + OFFSET;
}

// Log pressure reading to file
void log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Log error message to stderr
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
}

// Blink LED for error indication
void blink_led(int duration_ms) {
    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(duration_ms);
    gpioWrite(LED_GPIO, 0); // Turn off LED
}

int main() {
    SENT_Data sent_data;
    unsigned int raw_value;
    float pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read SENT data
        if (read_sent_data(&sent_data) == 0) {
            // Validate checksum
            unsigned int checksum = 0;
            for (int i = 0; i < SENT_DATA_NIBBLES; i++) {
                checksum += sent_data.data[i];
            }
            if (checksum % 16 != sent_data.checksum % 16) {
                log_error("Checksum error");
                blink_led(500); // Blink LED for 500ms
            } else {
                // Convert to pressure
                raw_value = (sent_data.status << 3) | (sent_data.data[0] >> 5);
                pressure = convert_to_pressure(raw_value);

                // Log pressure
                log_pressure(pressure);

                // Blink LED for valid reading
                blink_led(200); // Blink LED for 200ms
            }
        } else {
            log_error("Failed to read SENT data");
            blink_led(500); // Blink LED for 500ms
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    cleanup_gpio();

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Pressure monitoring stopped.\n");

    return 0;
}

