#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_REG_MSB 0x01
#define TEMP_REG_LSB 0x02
#define TEMP_REG_XLSB 0x03
#define DEVICE_ID_REG 0x0F
#define DEVICE_ID_VALUE 0x0117
#define FILENAME "greenhouse_temps.dat"
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
float read_temperature();
int write_temperature(float temp);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    char *filename;
    int sleep_interval;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%04X)\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }
    return 0;
}

// Read temperature
float read_temperature() {
    int raw_temp_msb = i2cReadByteData(i2c_handle, TEMP_REG_MSB);
    int raw_temp_lsb = i2cReadByteData(i2c_handle, TEMP_REG_LSB);
    int raw_temp_xlsb = i2cReadByteData(i2c_handle, TEMP_REG_XLSB);

    if (raw_temp_msb < 0 || raw_temp_lsb < 0 || raw_temp_xlsb < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -999.0; // Indicate error
    }

    int raw_temp = (raw_temp_msb << 8) | (raw_temp_lsb << 4) | (raw_temp_xlsb >> 4);

    // Convert to Celsius (TMP117 datasheet)
    float temperature = raw_temp * 0.0078125;
    return temperature;
}

// Write temperature to file
int write_temperature(float temp) {
    size_t bytes_written = fwrite(&temp, sizeof(float), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature != -999.0) {
            if (write_temperature(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping write\n");
        }
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

