    return handle;
}

// Write I2C command
int write_i2c_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Failed to write command 0x%02x: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Read I2C data
int read_i2c_data(int handle, uint8_t *data, int length) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, length);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t *data, int length, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc != 0);
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (raw_temp / 65535.0);
}

// Convert raw humidity to relative humidity
float convert_humidity(uint16_t raw_hum) {
    return -6.0 + 125.0 * (raw_hum / 65535.0);
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SHT40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (write_i2c_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for conversion (at least 8.5 ms)
        gpioDelay(8500); // 8500 us = 8.5 ms

        // Read data
        uint8_t data[DATA_LENGTH];
        if (read_i2c_data(i2c_handle, data, DATA_LENGTH) != 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        // Validate CRC checksums
        if (validate_crc(data, 2, CRC_POLYNOMIAL) != 0 || validate_crc(data + 3, 2, CRC_POLYNOMIAL) != 0) {
            fprintf(stderr, "CRC checksum validation failed\n");
            break;
        }

        // Convert raw data to temperature and humidity
        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_hum = (data[3] << 8) | data[4];

        float temperature = convert_temperature(raw_temp);
        float humidity = convert_humidity(raw_hum);

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds = 5000000 us
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

