#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define LOG_FILE "temperature_log.dat"

// Structure to hold the circular buffer and its state
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    int i2c_handle;
} TemperatureData;

// Global variable to store the TemperatureData instance
TemperatureData data;

// Function prototypes
int initialize_i2c();
float read_temperature(int i2c_handle);
void add_to_buffer(TemperatureData *data, float temperature);
void save_buffer_to_file(TemperatureData *data);
void signal_handler(int signal);

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    data.i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (data.i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", data.i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature from the TMP117 sensor
float read_temperature(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1000.0; // Indicate an error
    }

    // Convert the two bytes to a signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert the raw temperature to Celsius
    float temperature = raw_temp * 0.0078125;

    return temperature;
}

// Function to add a temperature reading to the circular buffer
void add_to_buffer(TemperatureData *data, float temperature) {
    data->buffer[data->head] = temperature;
    data->head = (data->head + 1) % BUFFER_SIZE;
    if (data->count < BUFFER_SIZE) {
        data->count++;
    }
}

// Function to save the contents of the circular buffer to a file
void save_buffer_to_file(TemperatureData *data) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    size_t elements_written = fwrite(data->buffer, sizeof(float), data->count, fp);
    if (elements_written != data->count) {
        fprintf(stderr, "Failed to write all elements to file\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    save_buffer_to_file(&data);
    i2cClose(data.i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize the circular buffer
    data.head = 0;
    data.count = 0;

    // Main loop
    while (1) {
        // Read the temperature
        float temperature = read_temperature(data.i2c_handle);

        // Check for errors during temperature reading
        if (temperature > -999.0) {
            // Add the temperature to the buffer
            add_to_buffer(&data, temperature);

            // Save the buffer to file
            save_buffer_to_file(&data);

            // Print the temperature to the console
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        // Wait for 5 seconds
        time_sleep(5.0);
    }

    return 0;
}

