#include <errno.h>

// Constants
#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define MEASURE_CMD 0x7866
#define LOG_FILE "shtc3_environment.log"
#define SLEEP_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHTC3 sensor
int read_shtc3(int i2c_handle, uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading SHTC3 data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate sensor data
int validate_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Temperature range validation
    if (sensor_data->temperature < -40.0 || sensor_data->temperature > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", sensor_data->temperature);
        return -1;
    }

    // Humidity range validation
    if (sensor_data->humidity < 0.0 || sensor_data->humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f\n", sensor_data->humidity);
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    sensor_data.temperature = 175.0 * (data[0] * 256 + data[1]) / 65535.0 - 45.0;
    sensor_data.humidity = 100.0 * (data[3] * 256 + data[4]) / 65535.0;
    return sensor_data;
}

// Function to log data to file
void log_data(const sensor_data_t *sensor_data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data->temperature, sensor_data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        sensor_data_t sensor_data;

        // Send measurement command
        if (i2cWriteDevice(i2c_handle, (char *)MEASURE_CMD, 2) != 0) {
            fprintf(stderr, "Error writing to I2C device\n");
            break;
        }

        // Wait for measurement (at least 12.4 ms)
        gpioDelay(12500); // 12.5 ms

        // Read data from sensor
        if (read_shtc3(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Validate data
        if (validate_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Data validation failed\n");
            break;
        }

        // Log data
        log_data(&sensor_data);

        // Print data to stdout
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);

        // Sleep for specified interval
        gpioDelay(SLEEP_INTERVAL * 1000000); // Convert seconds to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

