    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Temperature: %.4f C\n", s, temperature);
    fclose(fp);
    return 0;
}

