    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int i2c_init_attempts = 0;
    while (i2c_init_attempts < 3) {
        if (initialize_i2c() == 0) {
            printf("I2C initialized successfully.\n");
            break;
        } else {
            fprintf(stderr, "I2C initialization failed. Attempt %d/3\n", i2c_init_attempts + 1);
            i2c_init_attempts++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to initialize I2C after multiple attempts. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    float temperature;
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

