int read_sensor_data(int *raw_flow, int *raw_temp);
SensorData convert_data(int raw_flow, int raw_temp);
int log_data(SensorData data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *raw_flow, int *raw_temp) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    *raw_temp = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Convert raw data to SLPM and Celsius
SensorData convert_data(int raw_flow, int raw_temp) {
    SensorData data;
    data.flow_rate = ((float)raw_flow / 16384.0) - 0.1 / 0.8 * 25.0;
    data.temperature = ((float)raw_temp / 4096.0) - 0.1 / 0.8 * 80.0 - 40.0;
    return data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, data.flow_rate, data.temperature);
