    if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
        sensor_data = convert_data(raw_flow, raw_temp);
        log_data(sensor_data);
    } else {
        fprintf(stderr, "Failed to read initial sensor data. Attempting re-initialization.\n");
        i2cClose(i2c_handle);
        gpioDelay(1000); // Wait 1 second before re-initializing
        if (initialize_i2c() != 0) {
