        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 1); // Ensure line is initially high
    return 0;
}

// Read DHT11 sensor data
DHT11Data read_dht11() {
    DHT11Data data = {0.0, 0.0, 0};
    int i, j;
    unsigned int pulse_widths[5] = {0};
    unsigned int data_bits[40] = {0};
    unsigned int checksum = 0;
    int bit_index = 0;

    // Send start signal
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(40); // 40us

    // Read response
    unsigned int start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            data.status = 1; // Timeout
            return data;
        }
    }
    start_time = gpioTick();

    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            data.status = 1; // Timeout
            return data;
        }
    }
    start_time = gpioTick();

    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            data.status = 1; // Timeout
            return data;
        }
