#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define LOG_FILE "sht31d_data.log"

int i2c_handle;
FILE *log_file;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT31-D
int read_sht31d(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries--;
            gpioDelay(15); // Wait before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to I2C device after multiple retries.\n");
        return -1; // Indicate failure
    }

    gpioDelay(15); // Wait for measurement (at least 15ms)

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries--;
            gpioDelay(15); // Wait before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from I2C device after multiple retries.\n");
        return -1; // Indicate failure
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1; // Indicate failure
    }

    // Convert raw data to temperature and humidity
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = 100.0 * raw_humidity / 65535.0;

    return 0; // Indicate success
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        if (read_sht31d(i2c_handle, &sensor_data.temperature, &sensor_data.humidity) == 0) {
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    return 0;
}

