        return -1;
    }
    return 0;
}

// Read a register
int read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Write a register
int write_register(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

