#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"
#define SLEEP_DURATION_MS 1000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t status;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {(CONTINUOUS_MEASUREMENT_CMD >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    char buffer[9];

    // Send continuous measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return -1;
    }

    // Wait for measurement (45ms)
    gpioDelay(45000); // 45ms

    // Read 9 bytes of data
    if (i2cReadDevice(i2c_handle, buffer, 9) != 9) {
        fprintf(stderr, "Error: Failed to read from I2C device.\n");
        return -1;
    }

    // Validate CRC for pressure
    uint8_t pressure_crc = buffer[0];
    uint8_t pressure_data = buffer[1];
    if (crc8(&pressure_data, 1) != pressure_crc) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temperature_crc = buffer[3];
    uint8_t temperature_data = buffer[2];
    if (crc8(&temperature_data, 1) != temperature_crc) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    // Validate CRC for status
    uint8_t status_crc = buffer[6];
    uint8_t status_data = buffer[5];
    if (crc8(&status_data, 1) != status_crc) {
        fprintf(stderr, "Error: Status CRC mismatch.\n");
        return -1;
    }

    // Assign data to struct
    data->pressure = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->status = buffer[5];

    return 0;
}

// Function to process sensor data
void process_sensor_data(const sensor_data_t *data, float *pressure_pa, float *temperature_c) {
    *pressure_pa = (float)data->pressure / PRESSURE_SCALE_FACTOR;
    *temperature_c = (float)data->temperature / TEMPERATURE_SCALE_FACTOR;
}

// Function to log data to file
void log_data(float pressure_pa, float temperature_c) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float pressure_pa, temperature_c;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Process sensor data
            process_sensor_data(&sensor_data, &pressure_pa, &temperature_c);

            // Log data
            log_data(pressure_pa, temperature_c);

            // Check pressure threshold
            if (pressure_pa > PRESSURE_THRESHOLD) {
                fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa).\n", pressure_pa);
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_DURATION_MS);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

