#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0625
#define TEMP_OFFSET 0
#define HYSTERESIS_HIGH 28.0
#define HYSTERESIS_LOW 27.0

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
float read_temperature(int fd);
int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_cleanup(struct gpiod_chip *chip, struct gpiod_line *line);
void signal_handler(int sig);
int init_i2c(const char *bus, int addr);
void cleanup_i2c(int fd);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register address)");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return buf[0];
}

// Temperature reading function
float read_temperature(int fd) {
    int16_t raw_temp;
    int msb, lsb;

    msb = i2c_read_reg(fd, TEMP_REG);
    lsb = i2c_read_reg(fd, TEMP_REG + 1);

    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading temperature registers\n");
        return -1000.0; // Indicate error
    }

    raw_temp = (msb << 8) | lsb;
    float temp = (float)raw_temp * TEMP_SCALE + TEMP_OFFSET;
    return temp;
}

// GPIO initialization function
int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request(*line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }
    return 0;
}

// GPIO value setting function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

// GPIO cleanup function
int gpio_cleanup(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C cleanup function
void cleanup_i2c(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, STTS2004_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup_i2c(i2c_fd);
        return 1;
    }

    gpio_line = NULL;
    if (gpio_init(&gpio_chip, &gpio_line) == -1) {
        cleanup_i2c(i2c_fd);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(i2c_fd);
        if (temperature > -999.0) { // Check for valid temperature reading
            int led_value = (temperature > HYSTERESIS_HIGH) ? 1 : (temperature < HYSTERESIS_LOW) ? 0 : 1;
            gpio_set_value(gpio_line, led_value);
            printf("Temperature: %.2f °C, LED: %d\n", temperature, led_value);
        } else {
            fprintf(stderr, "Error reading temperature, skipping LED control\n");
        }
        sleep(1);
    }

    // Cleanup
    cleanup_i2c(i2c_fd);
    gpio_set_value(gpio_line, 0); // Turn off LED
    gpio_cleanup(gpio_chip, gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

