#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define SCALE_FACTOR_ADDR 0x00
#define SCALE_FACTOR_SIZE 3
#define PRESSURE_ADDR 0x00
#define PRESSURE_SIZE 2
#define TEMPERATURE_ADDR 0x02
#define TEMPERATURE_SIZE 2
#define CRC_ADDR 0x04
#define CRC_SIZE 1
#define MEASUREMENT_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the scale factor from the sensor
int read_scale_factor(int16_t *scale_factor) {
    char buf[SCALE_FACTOR_SIZE];
    if (read_data(buf, SCALE_FACTOR_SIZE) != 0) {
        return -1;
    }
    *scale_factor = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to read the differential pressure and temperature from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t raw_data[9];
    if (read_data(raw_data, 9) != 0) {
        return -1;
    }

    // CRC validation
    uint8_t pressure_crc = raw_data[2];
    uint8_t temperature_crc = raw_data[5];
    uint8_t scale_factor_crc = raw_data[6];

    if (crc8(&raw_data[0], 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC error\n");
        return -1;
    }
    if (crc8(&raw_data[3], 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }
    if (crc8(&raw_data[0], 2) != scale_factor_crc) {
        fprintf(stderr, "Scale Factor CRC error\n");
        return -1;
    }

    // Convert raw data to physical values
    int16_t raw_pressure = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    int16_t raw_temperature = (int16_t)((raw_data[3] << 8) | raw_data[4]);
    int16_t scale_factor_raw = (int16_t)((raw_data[6] << 8) | raw_data[7]);

    data->differential_pressure = (float)raw_pressure / (float)scale_factor_raw;
    data->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

// Function to log the sensor data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa, %.2f C\n", timestamp, data.differential_pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(CONTINUOUS_MEASUREMENT_CMD) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

