int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature_c;
    float humidity_pct;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t command, uint16_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int validate_sensor();
void log_data(sensor_data_t data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry
int read_sensor_data(uint8_t command, uint16_t *data) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, &command, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing command 0x%02X: %d, retry %d\n", command, result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(20 * 1000); // Wait for measurement (at least 20ms)

        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading data: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * (float)raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125 * (float)raw_humidity / 65536.0 - 6;
}

// Validate sensor by reading electronic ID
int validate_sensor() {
    uint8_t id;
    uint16_t data;

    if (read_sensor_data(SI7021_ELECTRONIC_ID, &data) != 0) {
        return -1;
    }

    id = (uint8_t)data;

    if (id != 0x40) {
        log_error("Invalid sensor ID.  Check I2C connection.");
        return -1;
    }

    return 0;
}

// Log data to file and stdout
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature_c, data.humidity_pct);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening environment.log: %s\n", strerror(errno));
    }

    printf("%s,%.2f,%.2f\n", timestamp, data.temperature_c, data.humidity_pct);
}

// Log error to file and stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,ERROR,%s\n", timestamp, message);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening environment.log: %s\n", strerror(errno));
    }

    fprintf(stderr, "%s,ERROR,%s\n", timestamp, message);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Validate sensor
    if (validate_sensor() != 0) {
        cleanup();
        return 1;
    }

    printf("Si7021 sensor initialized. Logging data to environment.log and stdout.\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_temp, raw_humidity;
        sensor_data_t data;

        // Read temperature
        if (read_sensor_data(MEASURE_TEMP_NO_HOLD, &raw_temp) == 0) {
            data.temperature_c = convert_temperature(raw_temp);
        } else {
            data.temperature_c = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(MEASURE_HUMIDITY_NO_HOLD, &raw_humidity) == 0) {
            data.humidity_pct = convert_humidity(raw_humidity);
        } else {
            data.humidity_pct = -999.0; // Indicate error
        }

        // Log data
        log_data(data);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

