        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from HDC1080
int read_hdc1080(float *temperature, float *humidity) {
    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, TEMP_REG, 0x00) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for measurement to complete (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature data
    char temp_data[2];
    if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, temp_data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }
    int16_t raw_temp = (temp_data[0] << 8) | temp_data[1];

    // Read humidity data
    char humid_data[2];
    if (i2cReadI2CBlockData(i2c_handle, HUMID_REG, humid_data, 2) != 2) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }
    int16_t raw_humidity = (humid_data[0] << 8) | humid_data[1];

    // Convert raw values to temperature and humidity
    *temperature = (float)raw_temp / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

