#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xE000
#define CSV_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"
#define BUFFER_SIZE 100
#define LOGGING_INTERVAL 60 // seconds

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_i2c();
int send_command(int handle, unsigned short command);
int read_data(int handle, unsigned char *data, int count);
int validate_crc(unsigned char *data, int length, unsigned char crc);
int read_sensor_data(int handle, int *co2, float *temperature, float *humidity);
void *logging_thread(void *arg);
void log_error(const char *message);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to send a command to the SCD40
int send_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send command");
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        log_error("Failed to read data");
        return -1;
    }
    return 0;
}

// Function to validate CRC checksum
int validate_crc(unsigned char *data, int length, unsigned char crc) {
    unsigned char crc_calculated = 0xFF;
    for (int i = 0; i < length; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

// Function to read sensor data
int read_sensor_data(int handle, int *co2, float *temperature, float *humidity) {
    unsigned char data[9];
    if (read_data(handle, data, 9) != 0) {
        return -1;
    }

    // Validate CRC for CO2
    if (!validate_crc(data, 2, data[2])) {
        log_error("CO2 CRC validation failed");
        return -1;
    }

    // Validate CRC for Temperature
    if (!validate_crc(data + 3, 2, data[5])) {
        log_error("Temperature CRC validation failed");
        return -1;
    }

    // Validate CRC for Humidity
    if (!validate_crc(data + 6, 2, data[8])) {
        log_error("Humidity CRC validation failed");
        return -1;
    }

    *co2 = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * (*co2) / 65535.0;
    *humidity = 100.0 * (*co2) / 65535.0;

    return 0;
}

// Function to log errors
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

// Function to write data to CSV file
void *logging_thread(void *arg) {
    while (running) {
        sleep(LOGGING_INTERVAL);
        pthread_mutex_lock(&buffer_mutex);
        FILE *fp = fopen(CSV_FILE, "a");
        if (fp == NULL) {
            log_error("Failed to open CSV file for writing");
            pthread_mutex_unlock(&buffer_mutex);
            continue;
        }

        fprintf(fp, "timestamp,co2,temperature,humidity\n");
        for (int i = 0; i < BUFFER_SIZE; i++) {
            int index = (buffer_index + i) % BUFFER_SIZE;
            struct tm tm = *localtime(&circular_buffer[index].timestamp);
            fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%.2f,%.2f,%.2f\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                    circular_buffer[index].co2, circular_buffer[index].temperature, circular_buffer[index].humidity);
        }
        fclose(fp);
        pthread_mutex_unlock(&buffer_mutex);
    }
    pthread_exit(NULL);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send start periodic measurement command
    if (send_command(i2c_handle, START_PERIODIC_MEASUREMENT) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int co2, temperature, humidity;
    while (running) {
        gpioDelay(5000); // Wait 5 seconds

        if (read_sensor_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            circular_buffer[buffer_index].timestamp = time(NULL);
            circular_buffer[buffer_index].co2 = co2;
            circular_buffer[buffer_index].temperature = temperature;
            circular_buffer[buffer_index].humidity = humidity;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            log_error("Failed to read sensor data");
        }
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, STOP_PERIODIC_MEASUREMENT) != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Join logging thread
    pthread_join(logging_thread_id, NULL);

    // Flush any remaining data to CSV file
    pthread_mutex_lock(&buffer_mutex);
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "timestamp,co2,temperature,humidity\n");
        for (int i = 0; i < BUFFER_SIZE; i++) {
            int index = (buffer_index + i) % BUFFER_SIZE;
            struct tm tm = *localtime(&circular_buffer[index].timestamp);
            fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%.2f,%.2f,%.2f\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                    circular_buffer[index].co2, circular_buffer[index].temperature, circular_buffer[index].humidity);
        }
        fclose(fp);
    }
    pthread_mutex_unlock(&buffer_mutex);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

