#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define LOG_FILE "sdp810_log.txt"
#define SLEEP_MS 1000 // Sleep for 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len);
    if (crc != data[len]) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", crc, data[len]);
        return -1;
    }
    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure_Pa = (float)raw_pressure * 500.0 / 1000.0; // Scale factor is 500Pa
    sensor_data.temperature_C = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    return sensor_data;
}

// Function to log data to a file
int log_data(FILE *log_file, float pressure_Pa, float temperature_C) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error getting local time.\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.3f,%.3f\n", timestamp, pressure_Pa, temperature_C) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    uint8_t data[9];
    sensor_data_t sensor_data;
    while (!terminate) {
        // Send continuous measurement command
        if (i2cWriteByteData(i2c_handle, 0, CONTINUOUS_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Error writing to I2C.\n");
            break;
        }
        gpioDelay(45); // Wait at least 45ms

        // Read data from the sensor
        if (read_sdp810(i2c_handle, data) == 0) {
            // Validate CRC-8 checksums
            if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0 || validate_crc(data + 6, 2) != 0) {
                fprintf(stderr, "CRC validation failed, skipping reading.\n");
                continue;
            }

            // Convert raw data to physical units
            sensor_data = convert_data(data);

            // Log the data
            if (log_data(log_file, sensor_data.pressure_Pa, sensor_data.temperature_C) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(SLEEP_MS); // Sleep for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

