#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ICP_10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define CALIB_DATA_START 0x05
#define CALIB_DATA_LENGTH 4
#define MEASURE_CMD 0x00
#define DATA_LENGTH 6

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int16_t c0, c1, c2, c3;

// Function prototypes
int init_pigpio();
int init_i2c();
int verify_sensor_identity();
int read_calibration_data();
int trigger_measurement();
int read_data(int *pressure, int *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int32_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify sensor identity
int verify_sensor_identity() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != 0x08) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x08)\n", who_am_i);
        return -1;
    }

    printf("Sensor identity verified: 0x%02X\n", who_am_i);
    return 0;
}

// Read calibration data
int read_calibration_data() {
    char buffer[CALIB_DATA_LENGTH];
    if (i2cReadI2CBlockData(i2c_handle, CALIB_DATA_START, buffer, CALIB_DATA_LENGTH) < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }

    c0 = (int16_t)((buffer[0] << 8) | buffer[1]);
    c1 = (int16_t)((buffer[2] << 8) | buffer[3]);
    c2 = (int16_t)((buffer[4] << 8) | buffer[5]);

    printf("Calibration data read: c0=0x%04X, c1=0x%04X, c2=0x%04X\n", c0, c1, c2);
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    if (i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD) < 0) {
        fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete
    return 0;
}

// Read data from sensor
int read_data(int *pressure, int *temperature) {
    char buffer[DATA_LENGTH];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, DATA_LENGTH) < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    *pressure = (int32_t)((buffer[0] << 16) | (buffer[1] << 8) | buffer[2]);
    *temperature = (int32_t)((buffer[3] << 16) | (buffer[4] << 8) | buffer[5]);

    return 0;
}

// Convert raw pressure to hPa
float convert_pressure(int32_t raw_pressure) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (float)raw_pressure / 100.0; // Example conversion
}

// Convert raw temperature to Celsius
float convert_temperature(int32_t raw_temperature) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (float)raw_temperature / 100.0; // Example conversion
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (data_file == NULL) {
        fprintf(stderr, "Data file is not open\n");
        return -1;
    }

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(data_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    if (verify_sensor_identity() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file in append mode
    data_file = fopen("environmental_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int pressure_raw, temperature_raw;
    float pressure_hpa, temperature_celsius;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed, skipping this sample\n");
            gpioDelay(5000); // Wait 5 seconds before next attempt
            continue;
        }

        // Read data
        if (read_data(&pressure_raw, &temperature_raw) != 0) {
            fprintf(stderr, "Data read failed, skipping this sample\n");
            gpioDelay(5000); // Wait 5 seconds before next attempt
            continue;
        }

        // Convert data
        pressure_hpa = convert_pressure(pressure_raw);
        temperature_celsius = convert_temperature(temperature_raw);

        // Log data
        if (log_data(pressure_hpa, temperature_celsius) != 0) {
            fprintf(stderr, "Data logging failed\n");
        }

        // Print data to stdout
        printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure_hpa, temperature_celsius);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C connection and file
    i2cClose(i2c_handle);
    fclose(data_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

