    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    if (verify_sensor_identity() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file in append mode
    data_file = fopen("environmental_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int pressure_raw, temperature_raw;
    float pressure_hpa, temperature_celsius;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed, skipping this sample\n");
            gpioDelay(5000); // Wait 5 seconds before next attempt
            continue;
        }

        // Read data
        if (read_data(&pressure_raw, &temperature_raw) != 0) {
            fprintf(stderr, "Data read failed, skipping this sample\n");
            gpioDelay(5000); // Wait 5 seconds before next attempt
            continue;
        }

        // Convert data
        pressure_hpa = convert_pressure(pressure_raw);
        temperature_celsius = convert_temperature(temperature_raw);

        // Log data
        if (log_data(pressure_hpa, temperature_celsius) != 0) {
            fprintf(stderr, "Data logging failed\n");
        }

        // Print data to stdout
        printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure_hpa, temperature_celsius);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C connection and file
    i2cClose(i2c_handle);
    fclose(data_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

