        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    *raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    return 0;
}

