static int verify_crc(uint8_t *data, uint8_t crc)
{
    uint8_t polynomial = 0x31; // Example polynomial
    uint8_t crc_calculated = 0;
    for (int i = 0; i < 6; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

