        if (!verify_crc(pressure_data, pressure_crc) || !verify_crc(temperature_data, temperature_crc)) {
            fprintf(stderr, "CRC verification failed\n");
            break;
        }

        // Calculate pressure and temperature
        float pressure = calculate_pressure(raw_pressure, raw_temperature);
        float temperature = calculate_temperature(raw_temperature);

        // Control LED blinking frequency
        int led_frequency = control_led_blinking((int)pressure, (int)temperature);

