#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_TEMP_THRESHOLD 30.0
#define OBJECT_TEMP_THRESHOLD 28.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_raw_temperature(int reg);
float convert_to_celsius(int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
int control_fan(float object_temp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw temperature data from the sensor
int read_raw_temperature(int reg) {
    int raw_temp = -1;
    int retries = 3;
    while (retries > 0) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            return raw_temp;
        } else {
            fprintf(stderr, "I2C read error, retrying... (%d retries left)\n", retries);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1; // Indicate failure
}

// Convert raw temperature data to Celsius
float convert_to_celsius(int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

