        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (ambient_temp < -273.0 || object_temp < -273.0) {
        fprintf(log_file, "%s,Invalid temperature reading\n", timestamp);
        fflush(log_file);
