#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define I2C_BUS 1
#define PORT 8080
#define MAX_RETRIES 3

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Global variables for graceful shutdown
int server_fd = 0;
int i2c_handle = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sht40_data(int i2c_handle, sensor_data_t *data);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
int create_html_page(float temperature, float humidity, char *html_buffer, size_t buffer_size);
int handle_client(int client_socket);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40_data(int i2c_handle, sensor_data_t *data) {
    unsigned char cmd[1] = {MEASURE_CMD};
    unsigned char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(10000); // Wait for measurement (at least 10ms)

        if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Convert raw data
        unsigned short raw_temp = (buffer[0] << 8) | buffer[1];
        unsigned short raw_humidity = (buffer[3] << 8) | buffer[4];

        data->temperature = convert_temperature(raw_temp);
        data->humidity = convert_humidity(raw_humidity);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw temperature data to Celsius
float convert_temperature(unsigned short raw_temp) {
    return -45.0 + 175.0 * (raw_temp / 65535.0);
}

// Convert raw humidity data to percentage
float convert_humidity(unsigned short raw_humidity) {
    return -6.0 + 125.0 * (raw_humidity / 65535.0);
}

// Create HTML page with temperature and humidity data
int create_html_page(float temperature, float humidity, char *html_buffer, size_t buffer_size) {
    snprintf(html_buffer, buffer_size, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Temperature: %.2f &deg;C, Humidity: %.2f %%</h1></body></html>", temperature, humidity);
    return 0;
}

// Handle client connection
int handle_client(int client_socket) {
    char html_buffer[256];
    sensor_data_t sensor_data;

    if (read_sht40_data(i2c_handle, &sensor_data) == 0) {
        create_html_page(sensor_data.temperature, sensor_data.humidity, html_buffer, sizeof(html_buffer));
        send(client_socket, html_buffer, strlen(html_buffer), 0);
    } else {
        const char *error_message = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\n\r\nError reading sensor data";
        send(client_socket, error_message, strlen(error_message), 0);
    }

    close(client_socket);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Accept connections and handle them
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_socket = accept(server_fd, (struct sockaddr *)&client_address, NULL);
        if (client_socket < 0) {
            perror("accept");
            continue; // Continue listening for new connections
        }

        handle_client(client_socket);
    }

    // Clean up resources
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Server shutdown complete.\n");
    return 0;
}

