#define TEMP_LSB 0x01
#define HUMID_MSB 0x02
#define HUMID_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor for temperature and humidity measurement
    // Heater disabled, 14-bit resolution
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    // Trigger a one-shot measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the HDC2010
int read_hdc2010(sensor_data_t *data) {
    unsigned char buf[4];
    int retries = 3;
    int result;

    // Wait for measurement to complete (bit 0 of MEASUREMENT_CONFIG is set)
    while (1) {
        result = i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG);
        if (result < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG register\n");
            return -1;
        }
        if ((result & 0x01) == 0) {
            break; // Bit 0 is set, measurement is complete
        }
        gpioDelay(1000); // Wait 1 ms
        if (retries > 0) {
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        } else {
            fprintf(stderr, "Timeout waiting for measurement to complete\n");
            return -1;
        }
    }

    // Read temperature and humidity data
    if (i2cReadI2CBlockData(i2c_handle, TEMP_MSB, (char *)buf, 4) < 0) {
