#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define the continuous measurement command
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for the I2C handle
int i2c_handle;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int i2c_bus, int i2c_address);
int send_command(int i2c_handle, uint16_t command);
int read_data(int i2c_handle, uint8_t *data, int data_length);
int verify_crc(uint8_t *data, int data_length);
int read_sensor_data(int i2c_handle, int16_t *pressure, int16_t *temperature);
void log_data(int16_t pressure, int16_t temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the I2C connection
    i2c_handle = open_i2c_connection(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Send the continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Failed to send continuous measurement command. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &read_sensor_data->pressure, &read_sensor_data->temperature) != 0) {
            fprintf(stderr, "Failed to read sensor data. Continuing.\n");
            continue; // Continue to the next iteration
        }

        // Log the data
        log_data(read_sensor_data.pressure, read_sensor_data.temperature);

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    return 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C connection
int open_i2c_connection(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to send a command to the sensor
int send_command(int i2c_handle, uint16_t command) {
    uint8_t buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)buffer, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int i2c_handle, uint8_t *data, int data_length) {
    int result = i2cReadDevice(i2c_handle, (char *)data, data_length);
    if (result != data_length) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to verify the CRC checksum
int verify_crc(uint8_t *data, int data_length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < data_length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != 0) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int16_t *pressure, int16_t *temperature) {
    uint8_t data[6];
    if (read_data(i2c_handle, data, 6) != 0) {
        return -1;
    }

    // Verify CRC for pressure
    if (verify_crc(data, 2) != 0) {
        return -1;
    }

    // Verify CRC for temperature
    if (verify_crc(data + 3, 2) != 0) {
        return -1;
    }

    // Extract pressure and temperature values
    *pressure = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (int16_t)((data[3] << 8) | data[4]);

    return 0;
}

// Function to log the data
void log_data(int16_t pressure, int16_t temperature) {
    printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

