#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_RATE 1 // Hz
#define TARGET_TEMP_FILE "profile.txt"
#define MAX_TEMP 100.0
#define MIN_TEMP 50.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID parameters
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;
float integral = 0.0;
float previous_error = 0.0;

// Function prototypes
int read_max6675();
float convert_to_celsius(int raw_temp);
float calculate_pid(float setpoint, float actual_temp);
void set_relay_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void load_target_temperature_profile();
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_max6675() {
    char tx_buf[2] = {0x00, 0x00}; // Dummy data for reading
    char rx_buf[2];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    int raw_temp = (rx_buf[0] << 8) | rx_buf[1];
    return raw_temp;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    // Check for open circuit
    if (raw_temp & 0x0001) {
        fprintf(stderr, "Error: Thermocouple open circuit\n");
        return -273.15; // Return absolute zero as error indicator
    }

    // Extract temperature data (bits 3-14)
    raw_temp = raw_temp >> 3; // Shift right by 3 bits

    // Check for negative temperature (bit 14 is set)
    if (raw_temp & 0x0001) {
        raw_temp = -(raw_temp & 0x3FFF); // Mask and negate
    }

    return raw_temp * 0.25; // Each bit is 0.25 degrees Celsius
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temp) {
    float error = setpoint - actual_temp;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set the relay duty cycle
void set_relay_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;
    gpioPWM(RELAY_GPIO, (int)(duty_cycle * 255.0)); // pigpio PWM range is 0-255
}

// Function to log data to CSV file
void log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load target temperature profile from file
void load_target_temperature_profile() {
    FILE *fp = fopen(TARGET_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open target temperature profile file\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Parse the line (time_seconds,target_temp_celsius)
        char *token = strtok(line, ",");
        if (token != NULL) {
            int time_seconds = atoi(token);
            token = strtok(NULL, ",");
            if (token != NULL) {
                float target_temp_celsius = atof(token);
                // Validate temperature range
                if (target_temp_celsius >= MIN_TEMP && target_temp_celsius <= MAX_TEMP) {
                    // Add target temperature to the profile
                    // This is a simplified example; a more robust implementation
