#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_COMMAND 0xAC
#define MEASUREMENT_COMMAND_HIGH 0x33
#define MEASUREMENT_COMMAND_LOW 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_SEC 5

// Global variables
