// AHT20 Initialization Function
int aht20_init(int i2c_handle) {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int result;

    result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for initialization to complete
    return 0;
}

