#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TRIGGER_MEASUREMENT 0xE5
#define SERVER_URL "http://api.example.com/humidity"
#define RETRY_COUNT 3
#define BACKOFF_DELAY 1 // seconds

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_write_byte(int fd, unsigned char data) {
    unsigned char buf[2];
    buf[0] = data;
    if (write(fd, buf, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, unsigned char *data) {
    unsigned char buf[2];
    if (write(fd, (unsigned char[]){0x00}, 1) != 1) {
        syslog(LOG_ERR, "I2C write (dummy) failed: %s", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    *data = (buf[0] << 8) | buf[1];
    return 0;
}

int read_humidity(int fd) {
    unsigned char data[2];
    if (i2c_write_byte(fd, TRIGGER_MEASUREMENT) != 0) {
        syslog(LOG_ERR, "Failed to trigger measurement");
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 85ms)

    if (i2c_read_word(fd, &data[0]) != 0) {
        syslog(LOG_ERR, "Failed to read humidity data");
        return -1;
    }

    unsigned int raw_humidity = data[0];
    unsigned int raw_temperature = data[1];

    // Check for CRC error (not implemented here, but can be added)
    // if (crc_check(raw_humidity, raw_temperature) != 0) {
    //     syslog(LOG_ERR, "CRC check failed");
    //     return -1;
    // }

    return (int)(((float)raw_humidity / 65536.0) * 100.0);
}

int post_humidity(float humidity) {
    int sockfd;
    struct sockaddr_in servaddr;
    char json_data[50];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Default HTTP port

    if (inet_pton(AF_INET, SERVER_URL, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", SERVER_URL);
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    if (send(sockfd, json_data, strlen(json_data), 0) < 0) {
        syslog(LOG_ERR, "POST request failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    int i2c_fd;
    float humidity;
    int retry;

    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            i2c_fd = open(I2C_DEVICE, O_RDWR);
            if (i2c_fd < 0) {
                syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
                retry++;
                sleep(BACKOFF_DELAY * retry);
            } else {
                break;
            }
        }

        if (i2c_fd < 0) {
            syslog(LOG_ERR, "Failed to open I2C device after multiple retries");
            sleep(60 * RETRY_COUNT); // Wait before retrying
            continue;
        }

        humidity = read_humidity(i2c_fd);
        if (humidity < 0) {
            syslog(LOG_ERR, "Failed to read humidity");
            close(i2c_fd);
            sleep(60);
            continue;
        }

        if (post_humidity(humidity) != 0) {
            syslog(LOG_ERR, "Failed to post humidity data");
        }

        close(i2c_fd);
        sleep(60);
    }

    closelog();
    return 0;
}

