// BMP280 control register
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x2
#define BMP280_OVERSAMPLING_PRES 5 // x16

// Forced mode
#define BMP280_FORCED_MODE 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int read_pressure_thresholds(double *pressure_high, double *pressure_low);
void log_pressure_breach(double pressure);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize BMP280 sensor
int init_bmp280() {
    // Verify chip ID
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CHIPID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Configure sensor
    char ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRES << 2) | BMP280_FORCED_MODE;
    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 1) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }

    return 0;
}

// Read calibration data from BMP280
int read_calibration_data() {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data block\n");
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (data[3] << 8) | (int8_t)data[2];
    dig_T3 = (data[5] << 8) | (int8_t)data[4];
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (data[9] << 8) | (int8_t)data[8];
    dig_P3 = (data[11] << 8) | (int8_t)data[10];
    dig_P4 = (data[13] << 8) | (int8_t)data[12];
    dig_P5 = (data[15] << 8) | (int8_t)data[14];
    dig_P6 = (data[17] << 8) | (int8_t)data[16];
    dig_P7 = (data[19] << 8) | (int8_t)data[18];
    dig_P8 = (data[21] << 8) | (int8_t)data[20];
    dig_P9 = (data[23] << 8) | (int8_t)data[22];

    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_F7, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    var1 = (((double)raw_temperature / 16384.0) - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;
    return p;
}

// Read pressure threshold values
int read_pressure_thresholds(double *pressure_high, double *pressure_low) {
    // Placeholder for reading pressure thresholds from a file or database
    // In a real application, this function would read the thresholds from a file or database
    // For this example, we'll just hardcode some values
    *pressure_high = 1020.0; // hPa
    *pressure_low = 980.0;   // hPa
    return 0;
}

// Log pressure breach
void log_pressure_breach(double pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt\n");
        return;
    }

    fprintf(fp, "%s Pressure breach: %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (init_bmp280() != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    double pressure_high, pressure_low;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, temperature);

            // Read pressure thresholds
            if (read_pressure_thresholds(&pressure_high, &pressure_low) == 0) {
                // Check for pressure breaches
                if (pressure > pressure_high || pressure < pressure_low) {
                    log_pressure_breach(pressure);
                }
            } else {
                fprintf(stderr, "Error reading pressure thresholds\n");
            }
        } else {
            fprintf(stderr, "Error reading raw data, retrying...\n");
        }

        // Wait 2 seconds
        gpioDelay(2000); // pigpio's delay function
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

