    char ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRES << 2) | BMP280_FORCED_MODE;
    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 1) {
