#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdbool.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define GPIO_CHIP "gpiochip4"
#define LOG_FILE_PREFIX "sensor_log_"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
static volatile sig_atomic_t program_running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(int address);
int read_temperature(int fd, float *temperature);
int read_humidity(int fd, float *humidity);
int read_pir(int gpio_line);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
void signal_handler(int sig);
void cleanup();

// Helper function to write a command to the I2C device
int write_i2c(int fd, unsigned char reg, unsigned char data)
{
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Helper function to read data from the I2C device
int read_i2c(int fd, unsigned char reg, unsigned char *data, int len)
{
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the I2C bus
int init_i2c(int address) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read temperature from TMP117 sensor
int read_temperature(int fd, float *temperature) {
    unsigned char data[2];
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (write_i2c(fd, 0x00, 0x00) != 0) {
            fprintf(stderr, "Error writing to temperature register, retrying...\n");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        if (read_i2c(fd, 0x00, data, 2) != 0) {
            fprintf(stderr, "Error reading temperature data, retrying...\n");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        int raw_temp = (data[0] << 8) | data[1];
        *temperature = (float)raw_temp * 0.0078125;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1; // Failure
}

// Function to read humidity from AHT20 sensor
int read_humidity(int fd, float *humidity) {
    unsigned char data[7];
    int retries = 3;
    int delay_ms = 10;

    // Initiate measurement
    if (write_i2c(fd, 0xBE, 0x08) != 0) {
        fprintf(stderr, "Error writing init command, retrying...\n");
        retries--;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
        continue;
    }
    usleep(10000); // Wait for initialization

    if (write_i2c(fd, 0xAC, 0x33) != 0) {
        fprintf(stderr, "Error writing measure command, retrying...\n");
        retries--;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
        continue;
    }
    usleep(10000); // Wait for measurement

    if (read_i2c(fd, 0xAC, data, 7) != 0) {
        fprintf(stderr, "Error reading humidity data, retrying...\n");
        retries--;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
        continue;
    }

    // Check for busy bit
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy, retrying...\n");
        retries--;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
        continue;
    }

    // Convert data
    unsigned int raw_humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4));
    *humidity = ((float)raw_humidity / 0x100000) * 100;

    return 0;
}

// Function to read PIR sensor state
int read_pir(int gpio_line) {
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        perror("Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Function to log data to a CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (pir_line != NULL) {
        gpiod_line_release(pir_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        perror("Failed to get PIR GPIO line");
        cleanup();
        return 1;
    }

    gpiod_line_request(pir_line, "sensor_logger", GPIOD_LINE_REQUEST_DIRECTION_INPUT);

    // Initialize I2C
    i2c_fd = init_i2c(TMP117_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize AHT20
    i2c_fd = init_i2c(AHT20_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Create log file name
    time_t now = time(NULL);
    char log_file_name[64];
    strftime(log_file_name, sizeof(log_file_name), "%Y-%m-%d", localtime(&now));
    char log_file_path[128];
    snprintf(log_file_path, sizeof(log_file_path), "%s%s.csv", LOG_FILE_PREFIX, log_file_name);

    // Open log file
    log_file = fopen(log_file_path, "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");

    // Main loop
    while (program_running) {
        float temperature, humidity;
        int motion_detected;

        // Read sensor data
        if (read_temperature(i2c_fd, &temperature) != 0) {
            fprintf(stderr, "Failed to read temperature, using previous value.\n");
        }
        if (read_humidity(i2c_fd, &humidity) != 0) {
            fprintf(stderr, "Failed to read humidity, using previous value.\n");
        }
        motion_detected = read_pir(pir_line);

        // Log data
        if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

