int read_pir(int gpio_line) {
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        perror("Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Function to log data to a CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (pir_line != NULL) {
        gpiod_line_release(pir_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        perror("Failed to get PIR GPIO line");
        cleanup();
        return 1;
    }

    gpiod_line_request(pir_line, "sensor_logger", GPIOD_LINE_REQUEST_DIRECTION_INPUT);

    // Initialize I2C
    i2c_fd = init_i2c(TMP117_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize AHT20
    i2c_fd = init_i2c(AHT20_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Create log file name
    time_t now = time(NULL);
    char log_file_name[64];
    strftime(log_file_name, sizeof(log_file_name), "%Y-%m-%d", localtime(&now));
    char log_file_path[128];
    snprintf(log_file_path, sizeof(log_file_path), "%s%s.csv", LOG_FILE_PREFIX, log_file_name);

    // Open log file
    log_file = fopen(log_file_path, "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");

    // Main loop
    while (program_running) {
        float temperature, humidity;
        int motion_detected;

        // Read sensor data
        if (read_temperature(i2c_fd, &temperature) != 0) {
            fprintf(stderr, "Failed to read temperature, using previous value.\n");
        }
        if (read_humidity(i2c_fd, &humidity) != 0) {
            fprintf(stderr, "Failed to read humidity, using previous value.\n");
        }
        motion_detected = read_pir(pir_line);

        // Log data
        if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

