#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control parameters
#define MOTOR_FORWARD_DURATION 5 // seconds
#define MOTOR_STOP_DURATION 1 // seconds

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *rain_line = NULL;
static struct gpiod_line *ena_line = NULL;
static struct gpiod_line *in1_line = NULL;
static struct gpiod_line *in2_line = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int forward);
int stop_motor();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, shutting down...");
        program_running = 0;
    }
}

// Log event function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Initialize GPIO lines
int initialize_gpio() {
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Error opening GPIO chip.");
        return -1;
    }

    // Request rain sensor line
    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!rain_line) {
        log_event("Error getting rain sensor line.");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request ENA line
    ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    if (!ena_line) {
        log_event("Error getting ENA line.");
        gpiod_line_release(rain_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request IN1 line
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (!in1_line) {
        log_event("Error getting IN1 line.");
        gpiod_line_release(rain_line);
        gpiod_line_release(ena_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request IN2 line
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!in2_line) {
        log_event("Error getting IN2 line.");
        gpiod_line_release(rain_line);
        gpiod_line_release(ena_line);
        gpiod_line_release(in1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure lines as inputs/outputs
    config.consumer = "rain_sensor";
    if (gpiod_line_request(rain_line, &config, 0) < 0) {
        log_event("Error requesting rain sensor line.");
        gpiod_line_release(rain_line);
        gpiod_line_release(ena_line);
        gpiod_line_release(in1_line);
        gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "motor_ena";
    if (gpiod_line_request(ena_line, &config, 0) < 0) {
        log_event("Error requesting ENA line.");
        gpiod_line_release(rain_line);
        gpiod_line_release(ena_line);
        gpiod_line_release(in1_line);
        gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "motor_in1";
    if (gpiod_line_request(in1_line, &config, 0) < 0) {
        log_event("Error requesting IN1 line.");
        gpiod_line_release(rain_line);
        gpiod_line_release(ena_line);
        gpiod_line_release(in1_line);
        gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "motor_in2";
    if (gpiod_line_request(in2_line, &config, 0) < 0) {
        log_event("Error requesting IN2 line.");
        gpiod_line_release(rain_line);
        gpiod_line_release(ena_line);
        gpiod_line_release(in1_line);
        gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    log_event("GPIO lines initialized successfully.");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    int value = gpiod_line_get_value(rain_line);
    if (value < 0) {
        log_event("Error reading rain sensor value.");
        return -1; // Indicate error
    }
    return value;
}

// Control motor direction
int control_motor(int forward) {
    if (forward) {
        // Forward
        if (gpiod_line_set_value(in1_line, 1) < 0) {
            log_event("Error setting IN1 value.");
            return -1;
        }
        if (gpiod_line_set_value(in2_line, 0) < 0) {
            log_event("Error setting IN2 value.");
            return -1;
        }
    } else {
        // Stop
        if (gpiod_line_set_value(in1_line, 0) < 0) {
            log_event("Error setting IN1 value.");
            return -1;
        }
        if (gpiod_line_set_value(in2_line, 0) < 0) {
            log_event("Error setting IN2 value.");
            return -1;
        }
    }
    return 0;
}

// Stop motor
int stop_motor() {
    if (gpiod_line_set_value(in1_line, 0) < 0) {
        log_event("Error setting IN1 value to stop.");
        return -1;
    }
    if (gpiod_line_set_value(in2_line, 0) < 0) {
        log_event("Error setting IN2 value to stop.");
        return -1;
    }
    return 0;
}

// Cleanup GPIO resources
void cleanup() {
    log_event("Cleaning up GPIO resources...");
    if (rain_line) {
        gpiod_line_release(rain_line);
    }
    if (ena_line) {
        gpiod_line_release(ena_line);
    }
    if (in1_line) {
        gpiod_line_release(in1_line);
    }
    if (in2_line) {
        gpiod_line_release(in2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    log_event("GPIO cleanup complete.");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        log_event("GPIO initialization failed, exiting.");
        return 1;
    }

    log_event("Program started.");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected < 0) {
            log_event("Error reading rain sensor, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        if (rain_detected == 0) {
            log_event("Rain detected!");
            if (control_motor(1) == 0) { // Forward
                sleep(MOTOR_FORWARD_DURATION);
                if (stop_motor() == 0) {
                    log_event("Motor stopped.");
                } else {
                    log_event("Error stopping motor.");
                }
            } else {
                log_event("Error controlling motor.");
            }
        } else {
            log_event("No rain detected.");
        }

        sleep(2); // Poll every 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

