#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define CPU load sampling interval (milliseconds)
#define SAMPLE_INTERVAL_MS 500

// Global variable to store CPU usage
volatile double cpu_usage = 0.0;

// Function prototypes
void signal_handler(int signal);
void cleanup();
void set_led_color(int red, int green, int blue);
void update_cpu_usage();

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to turn off the LED and terminate pigpio
void cleanup() {
    set_led_color(0, 0, 0); // Turn off the LED
    gpioTerminate();       // Terminate pigpio
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Common-anode LED, so invert the values
    int r = 255 - red;
    int g = 255 - green;
    int b = 255 - blue;

    gpioPWM(RED_PIN, r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN, b);
}

// Function to update CPU usage
void update_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    double cpu_usage_temp;

    // Read CPU statistics from /proc/stat
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return;
    }

    // Read the first line (cpu  0   user   0   nice   0   system   0   idle    0   iowait  0   irq     0   softirq  0   steal    0   guest    0   guest_nice 0)
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice, &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 13) {
        fclose(fp);
        return;
    }
    fclose(fp);

    // Calculate the differences
    unsigned long long diff_user = user - prev_user;
    unsigned long long diff_nice = nice - prev_nice;
    unsigned long long diff_system = system - prev_system;
    unsigned long long diff_idle = idle - prev_idle;
    unsigned long long diff_iowait = iowait - prev_iowait;
    unsigned long long diff_irq = irq - prev_irq;
    unsigned long long diff_softirq = softirq - prev_softirq;
    unsigned long long diff_steal = steal - prev_steal;
    unsigned long long diff_guest = guest - prev_guest;
    unsigned long long diff_guest_nice = guest_nice - prev_guest_nice;

    // Calculate total CPU time
    unsigned long long total_user = diff_user + diff_nice;
    unsigned long long total_system = diff_system + diff_idle + diff_iowait + diff_irq + diff_softirq + diff_steal;
    unsigned long long total_idle = diff_idle;
    unsigned long long total_iowait = diff_iowait;

    // Calculate CPU usage
    cpu_usage_temp = (double)(total_user + total_system) / (double)(total_user + total_system + total_idle + total_iowait);

    // Update global CPU usage
    cpu_usage = cpu_usage_temp;

    // Calculate the color based on CPU usage
    int red, green, blue;
    if (cpu_usage < 0.5) {
        red = 0;
        green = (int)(cpu_usage * 2.55); // Scale to 0-255
        blue = 255;
    } else if (cpu_usage < 1.0) {
        green = 255;
        blue = (int)((cpu_usage - 0.5) * 2.55); // Scale to 0-255
        red = 0;
    } else {
        red = (int)((cpu_usage - 1.0) * 2.55); // Scale to 0-255
        blue = 0;
        green = 255;
    }

    // Set the LED color
    set_led_color(red, green, blue);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        update_cpu_usage();
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    return 0;
}

