    if (read_calibration_data(&calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize UDP socket
    if (init_udp_socket() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

