// Constants
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define BUFFER_SIZE 20
#define TEMP_THRESHOLD 60.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} Reading;

Reading circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
void set_fan_speed(int duty_cycle);
void update_pwm(int duty_cycle);
void log_reading(float temperature, int duty_cycle);
void signal_handler(int signal);
void print_buffer();

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char tx_buffer[4] = {0x00, 0x00, 0x00, 0x00}; // Dummy data for reading
    char rx_buffer[4];

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract thermocouple temperature (bits 31:18, signed 14-bit)
    int16_t raw_temp = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    // Check for fault bits
    if (rx_buffer[3] & 0x07) {
        fprintf(stderr, "MAX31855 Fault: OC=%d, SCG=%d, SCV=%d\n", rx_buffer[3] & 0x01, rx_buffer[3] & 0x02, rx_buffer[3] & 0x04);
        return -1; // Indicate fault
    }

    return 0; // Indicate success
}

// Function to set fan speed using hardware PWM
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to update PWM duty cycle based on temperature
void update_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    if (*temperature < 25.0) {
        duty_cycle = (int)((*temperature / 25.0) * 255.0);
    } else if (*temperature < 40.0) {
        duty_cycle = 255 - (int)(((40.0 - *temperature) / 10.0) * 255.0);
    } else if (*temperature < 60.0) {
        duty_cycle = 255 - (int)(((60.0 - *temperature) / 20.0) * 255.0);
    } else {
        duty_cycle = 255;
    }

    set_fan_speed(duty_cycle);
}

// Function to log reading to circular buffer
void log_reading(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    circular_buffer[buffer_index].timestamp = now;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature and Duty Cycle Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", time_str, circular_buffer[index].temperature, circular_buffer[index].duty_cycle);
    }
    printf("----------------------------------------\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    int duty_cycle = 0;

    // Main loop
    while (!terminate) {
        if (read_max31855(spi_handle, &temperature) == 0) {
            update_pwm(duty_cycle);
            log_reading(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    set_fan_speed(0); // Stop the fan
    spiClose(spi_handle);
    gpioTerminate();
    print_buffer();

    return 0;
}

