#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define LOG_FILE "rtd_log.csv"
#define NUM_SENSORS 2

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// RTD Constants
#define RTD_NOMINAL 100.0  // Nominal resistance of the RTD
#define RTD_RREF 430.0    // Reference resistance
#define RREF 430.0         // Reference resistance

// Global Variables
static int spi_fd = -1;
static int chip_select_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int max31865_init(int spi_fd);
int read_rtd_data(int spi_fd, float *rtd_resistance);
float rtd_to_temperature(float rtd_resistance);
int log_data(float temperatures[], int num_sensors);
void signal_handler(int sig);
void cleanup();

// SPI Initialization Function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = (mode & 0x03) << 4;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_val = (bits & 0x03) << 2;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed hz
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer Function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MAX31865 Initialization Function
int max31865_init(int spi_fd) {
    // Configure MAX31865 for 3-wire RTD mode with bias voltage enabled
    uint8_t config_data[2] = {0x80, 0x00}; // Example configuration, adjust as needed
    if (spi_transfer(spi_fd, config_data, NULL, 2) != 0) {
        fprintf(stderr, "Error configuring MAX31865\n");
        return -1;
    }

    return 0;
}

// Read RTD Data Function
int read_rtd_data(int spi_fd, float *rtd_resistance) {
    uint8_t rtd_msb_reg = MAX31865_RTD_MSB_REG;
    uint8_t rtd_lsb_reg = MAX31865_RTD_LSB_REG;

    if (spi_transfer(spi_fd, &rtd_msb_reg, NULL, 1) != 0) return -1;
    if (spi_transfer(spi_fd, &rtd_lsb_reg, NULL, 1) != 0) return -1;

    uint8_t rtd_msb = 0;
    uint8_t rtd_lsb = 0;

    if (spi_transfer(spi_fd, &rtd_msb_reg, &rtd_msb, 1) != 0) return -1;
    if (spi_transfer(spi_fd, &rtd_lsb_reg, &rtd_lsb, 1) != 0) return -1;

    // Combine MSB and LSB to get the RTD resistance value
    *rtd_resistance = ((rtd_msb << 8) | rtd_lsb) >> 1; // Shift right by 1 bit

    return 0;
}

// RTD to Temperature Function
float rtd_to_temperature(float rtd_resistance) {
    float temperature = (rtd_resistance / RREF - 1.0) / (RTD_NOMINAL / RREF);
    temperature = temperature * 100.0; // Convert to Celsius
    return temperature;
}

// Log Data Function
int log_data(float temperatures[], int num_sensors) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s", timestamp);
    for (int i = 0; i < num_sensors; i++) {
        fprintf(log_file, ",%.2f", temperatures[i]);
    }
    fprintf(log_file, "\n");
    fflush(log_file);

    return 0;
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (chip != NULL) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init(spi_fd) < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Open chip and get CS line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (cs_line == NULL) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Request chip select line
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "rtd_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return 1;
    }

    // Main loop
    float temperatures[NUM_SENSORS];
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            float rtd_resistance;
            if (read_rtd_data(spi_fd, &rtd_resistance) == 0) {
                temperatures[i] = rtd_to_temperature(rtd_resistance);
            } else {
                temperatures[i] = -999.0; // Indicate error
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
            }
        }

        log_data(temperatures, NUM_SENSORS);
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

