    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        if (bme280_read_data(i2c_fd, &temperature, &humidity, &pressure) == 0) {
            if (log_data(log_file, temperature, humidity, pressure) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read BME280 data\n");
        }

        sleep(5);
    }

    // Cleanup
    fclose(log_file);
    close(i2c_fd);

    return 0;
