// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Oversampling setting (OSS)
#define OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 10 Hz = 600 samples)
#define BUFFER_SIZE 600

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure data
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_data_t;

// Circular buffer structure
typedef struct {
    pressure_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
circular_buffer_t pressure_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *cal);
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
