float calculate_rolling_average(circular_buffer_t *buffer);
void trigger_alert(float pressure, float rolling_average);
void signal_handler(int signal);
void timer_callback();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *cal) {
    char buffer[22];
    if (i2cReadI2CBlockData(i2c_handle, 0xAA, buffer, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal->ac1 = (buffer[0] << 8) | buffer[1];
    cal->ac2 = (buffer[2] << 8) | buffer[3];
    cal->ac3 = (buffer[4] << 8) | buffer[5];
    cal->ac4 = (buffer[6] << 8) | buffer[7];
    cal->ac5 = (buffer[8] << 8) | buffer[9];
    cal->ac6 = (buffer[10] << 8) | buffer[11];
    cal->b1 = (buffer[12] << 8) | buffer[13];
    cal->b2 = (buffer[14] << 8) | buffer[15];
    cal->mb = (buffer[16] << 8) | buffer[17];
    cal->mc = (buffer[18] << 8) | buffer[19];
    cal->md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure from BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, buf[0]) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_temp, int raw_pressure, bmp180_calibration_data_t cal) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    x1 = (((long)raw_temp - (long)cal.ac6) * (long)cal.ac5) >> 15;
    x2 = ((long)cal.mc << 11) / (x1 + cal.md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (cal.b2 * (b6 * b6) >> 12) >> 11;
    x2 = (cal.ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)cal.ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = (cal.ac3 * b6) >> 13;
    x2 = (cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (cal.ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (float)p / 100.0; // Convert to hPa
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, time_t timestamp, float pressure) {
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].pressure = pressure;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the rolling average of pressure readings
float calculate_rolling_average(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->data[i].pressure;
    }
    return sum / buffer->count;
}

// Function to trigger an alert if the pressure deviates significantly
void trigger_alert(float pressure, float rolling_average) {
    if (pressure > rolling_average + 5.0 || pressure < rolling_average - 5.0) {
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        printf("Alert: Pressure deviation detected!\n");
    } else {
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;
    float pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        pressure = calculate_pressure(raw_temp, raw_pressure, calibration_data);
        time_t now = time(NULL);
        add_to_buffer(&pressure_buffer, now, pressure);
        float rolling_average = calculate_rolling_average(&pressure_buffer);
        trigger_alert(pressure, rolling_average);
    } else {
        fprintf(stderr, "Error reading sensor data\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alert pin
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Initially LOW

    // Initialize circular buffer
    pressure_buffer.head = 0;
    pressure_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up hardware timer
    if (gpioSetTimerFuncEx(0, 50, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set up timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up
    gpioSetTimerFuncEx(0, 50, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

