    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *cal) {
    unsigned char data[22];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0xAA, (char *)data, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    cal->ac1 = (data[0] << 8) | data[1];
    cal->ac2 = (data[2] << 8) | data[3];
    cal->ac3 = (data[4] << 8) | data[5];
    cal->ac4 = (data[6] << 8) | data[7];
    cal->ac5 = (data[8] << 8) | data[9];
    cal->ac6 = (data[10] << 8) | data[11];
    cal->b1 = (data[12] << 8) | data[13];
    cal->b2 = (data[14] << 8) | data[15];
    cal->mb = (data[16] << 8) | data[17];
    cal->mc = (data[18] << 8) | data[19];
    cal->md = (data[20] << 8) | data[21];

    return 0;
