    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms (minimum)

    buf[0] = BMP180_REG_MSB;
    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature read address: %d\n", result);
        return -1;
    }

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2);
    if (result != 2) {
