        fprintf(stderr, "Error writing pressure command: %d\n", result);
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion (datasheet)

    buf[0] = BMP180_REG_MSB;
    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure read address: %d\n", result);
        return -1;
    }

    char data[3];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", result);
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp, bmp180_calibration_data_t cal) {
    long x1 = (((long)raw_temp - (long)cal.ac6) * (long)cal.ac5) >> 15;
    long x2 = ((long)cal.mc << 11) / (x1 + cal.md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temp, bmp180_calibration_data_t cal) {
    long x1 = (((long)raw_temp - (long)cal.ac6) * (long)cal.ac5) >> 15;
    long x2 = ((long)cal.mc << 11) / (x1 + cal.md);
