#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define DUTY_CYCLE_RANGE 255

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping fan and exiting...\n", signal);
}

int read_cpu_temperature() {
    FILE *fp;
    int temperature = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temperature) != 1) {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temperature / 1000; // Convert to Celsius
}

int calculate_duty_cycle(int temperature) {
    if (temperature < 40) {
        return 0;
    } else if (temperature > 70) {
        return DUTY_CYCLE_RANGE;
    } else {
        return (temperature - 40) * (DUTY_CYCLE_RANGE / 30);
    }
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

int log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %d°C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
    return 0;
}

int main() {
    int temperature, duty_cycle;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, DUTY_CYCLE_RANGE);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        temperature = read_cpu_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature. Continuing...\n");
            sleep(5);
            continue;
        }

        duty_cycle = calculate_duty_cycle(temperature);
        result = set_fan_speed(duty_cycle);
        if (result != 0) {
            fprintf(stderr, "Failed to set fan speed. Continuing...\n");
        }

        log_data(temperature, duty_cycle);

        sleep(5);
    }

    // Stop the fan
    gpioPWM(FAN_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Fan control program stopped.\n");
    return 0;
}

