#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP280 Registers
#define BMP280_ADDR_76 0x76
#define BMP280_ADDR_77 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LENGTH 26
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_STATUS_REG 0xF3
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_PRESS_LSB_REG 0xF8
#define BMP280_PRESS_XLSB_REG 0xF9
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_TEMP_LSB_REG 0xFB
#define BMP280_TEMP_XLSB_REG 0xFC

// Oversampling settings
#define OVERSAMPLING_TEMP 1
#define OVERSAMPLING_PRESS 1

// Global variables
static int i2c_fd = -1;
static int bmp280_address = BMP280_ADDR_76;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Function prototypes
int i2c_setup(int address);
int bmp280_read_calibration_data(int fd, bmp280_calib_data *calib);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double bmp280_compensate_pressure(int32_t raw_pressure, bmp280_calib_data calib, double t_fine);
int log_data(double temperature, double pressure);
void signal_handler(int sig);
int verify_bmp280_address(int fd);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// I2C setup function
int i2c_setup(int address) {
    int fd;
    char filename[20];

    snprintf(filename, 19, "/dev/i2c-%d", 1); // I2C bus 1

    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// BMP280 read calibration data function
int bmp280_read_calibration_data(int fd, bmp280_calib_data *calib) {
    uint8_t data[BMP280_CALIB_LENGTH];
    int i;

    if (read(fd, data, BMP280_CALIB_LENGTH) != BMP280_CALIB_LENGTH) {
