// Temperature Conversion
float convert_to_celsius(int16_t raw_temp) {
    return (float)raw_temp / 256.0;
}

// Circular Buffer Initialization
void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Circular Buffer Add
void add_reading(CircularBuffer *buffer, float temperature) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->readings[buffer->head].temperature = temperature;
    buffer->readings[buffer->head].timestamp = time(NULL);
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

