float calculate_running_average(CircularBuffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->readings[i].temperature;
    }
    float average = sum / buffer->count;
    pthread_mutex_unlock(&buffer->mutex);
    return average;
