void *data_acquisition_thread(void *arg) {
    while (running) {
        int raw_temp = read_lm75(i2c_fd);
        if (raw_temp < 0) {
            fprintf(stderr, "Error reading LM75 in data acquisition thread. Retrying...\n");
            sleep(1); // Wait before retrying
