    }
    pthread_exit(NULL);
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = false;
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (buffer.mutex != PTHREAD_MUTEX_INITIALIZER) {
        pthread_mutex_destroy(&buffer.mutex);
