#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/heater"
#define LOG_FILE "heater.log"
#define TARGET_TEMPERATURE 25.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define MAX_TEMP 80.0
#define MIN_TEMP 15.0
#define MAX_RTD 32767
#define MIN_RTD 0
#define MAX_RTD_RESISTANCE 430.0
#define MIN_RTD_RESISTANCE 10.0

// Global variables
static volatile int running = 1;
static int spi_handle;
static struct mosquitto *mosq = NULL;
static FILE *log_file = NULL;
static double target_temperature = TARGET_TEMPERATURE;
static double kp = KP;
static double ki = KI;
static double kd = KD;

// Structure to hold PID parameters
typedef struct {
    double kp;
    double ki;
    double kd;
} PIDParams;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_spi();
int initialize_mqtt();
int read_config(const char *filename);
int read_max31865();
double rtd_to_resistance(int rtd_code);
double resistance_to_temperature(double rtd_resistance);
double pid_control(double setpoint, double actual_temperature, PIDParams *pid_params);
int publish_temperature(double temperature);
int log_message(const char *message);
int read_max31865();
void cleanup();
int read_config(const char *filename);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // 1 kHz
    gpioSetPWMrange(HEATER_GPIO, 1000);
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_message("SPI initialisation failed");
        return -1;
    }
    return 0;
}

// Initialize MQTT
int initialize_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_message("MQTT initialisation failed");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("MQTT connection failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq);
    return 0;
}

// Read configuration from JSON file
int read_config(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    json_t *kp_json = json_object_get(root, "kp");
    json_t *ki_json = json_object_get(root, "ki");
    json_t *kd_json = json_object_get(root, "kd");

    if (!json_is_real(target_temp_json) || !json_is_real(kp_json) || !json_is_real(ki_json) || !json_is_real(kd_json)) {
        fprintf(stderr, "Error: Invalid config file format\n");
        json_decref(root);
        return -1;
    }

    target_temperature = json_real_value(target_temp_json);
    kp = json_real_value(kp_json);
    ki = json_real_value(ki_json);
    kd = json_real_value(kd_json);

    json_decref(root);
    return 0;
}

// Read temperature and fault status from MAX31865
int read_max31865() {
    char buf[4];
    int rtd_code = 0;
    int fault = 0;

    if (spiRead(spi_handle, buf, 4) != 4) {
        log_message("SPI read failed");
        return -1;
    }

    rtd_code = ((int)buf[0] << 8) | (int)buf[1];
    fault = ((int)buf[3] & 0x07) >> 0; // Extract fault bits

    if (fault & 0x01) {
        log_message("MAX31865 Fault: Open circuit");
    } else if (fault & 0x02) {
        log_message("MAX31865 Fault: Over-voltage");
    } else if (fault & 0x04) {
        log_message("MAX31865 Fault: Under-voltage");
    }

    return rtd_code;
}

// Convert RTD code to resistance
double rtd_to_resistance(int rtd_code) {
    return (double)rtd_code / 32768.0 * MAX_RTD_RESISTANCE;
}

// Convert resistance to temperature using Callendar-Van Dusen equation
double resistance_to_temperature(double rtd_resistance) {
    // R0 = 100 ohms
    double A = 0.0039083;
    double B = -0.0000005775;
    double R0 = 100.0;

    double R = R0 * (1 + A * rtd_resistance + B * rtd_resistance * rtd_resistance);
    double temperature = (R - R0) / (R0 * 0.0039083); // Simplified equation

    return temperature;
}

// PID control loop
double pid_control(double setpoint, double actual_temperature, PIDParams *pid_params) {
    double error = setpoint - actual_temperature;
    double integral = 0;
    double derivative = 0;

    integral += error;
    derivative = error - pid_params->ki * integral;

    double output = pid_params->kp * error + pid_params->ki * integral + pid_params->kd * derivative;

    return output;
}

// Publish temperature to MQTT
int publish_temperature(double temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("MQTT publish failed");
        return -1;
    }
    return 0;
}

// Log messages to file
int log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    log_message("Cleaning up...");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioPWM(HEATER_GPIO, 0); // Turn off heater
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting heater control program...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        log_message("SPI initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        log_message("MQTT initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Read configuration
    if (read_config("heater_config.json") != 0) {
        log_message("Failed to read config file, using defaults");
    }

    // Main loop
    while (running) {
        // Read temperature and fault status
        int rtd_code = read_max31865();
        if (rtd_code < 0) {
            log_message("Failed to read RTD code, exiting");
            break;
        }

        // Convert RTD code to resistance
        double rtd_resistance = rtd_to_resistance(rtd_code);

        // Convert resistance to temperature
        double temperature = resistance_to_temperature(rtd_resistance);

        // PID control
        double pid_output = pid_control(target_temperature, temperature, &pid_params);

        // Convert PID output to PWM duty cycle
        int duty_cycle = (int)pid_output;

        // Clamp duty cycle to 0-1000
        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 1000) {
            duty_cycle = 1000;
        }

        // Set PWM duty cycle
        gpioPWM(HEATER_GPIO, duty_cycle);

        // Publish temperature
        if (publish_temperature(temperature) != 0) {
            log_message("Failed to publish temperature");
        }

        // Failsafe shutoff
        if (temperature > MAX_TEMP || rtd_code < MIN_RTD || rtd_code > MAX_RTD || fault) {
            log_message("Failsafe triggered, shutting down heater");
            gpioPWM(HEATER_GPIO, 0); // Turn off heater
            break;
        }

        // Wait 100 ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    log_message("Exiting");
    return 0;
}

