}

// Read temperature and fault status from MAX31865
int read_max31865() {
    char buf[4];
    int rtd_code = 0;
    int fault = 0;

    if (spiRead(spi_handle, buf, 4) != 4) {
        log_message("SPI read failed");
        return -1;
    }

    rtd_code = ((int)buf[0] << 8) | (int)buf[1];
    fault = ((int)buf[3] & 0x07) >> 0; // Extract fault bits

    if (fault & 0x01) {
        log_message("MAX31865 Fault: Open circuit");
    } else if (fault & 0x02) {
        log_message("MAX31865 Fault: Over-voltage");
    } else if (fault & 0x04) {
        log_message("MAX31865 Fault: Under-voltage");
    }

    return rtd_code;
}

// Convert RTD code to resistance
double rtd_to_resistance(int rtd_code) {
    return (double)rtd_code / 32768.0 * MAX_RTD_RESISTANCE;
}

// Convert resistance to temperature using Callendar-Van Dusen equation
double resistance_to_temperature(double rtd_resistance) {
    // R0 = 100 ohms
    double A = 0.0039083;
    double B = -0.0000005775;
    double R0 = 100.0;

    double R = R0 * (1 + A * rtd_resistance + B * rtd_resistance * rtd_resistance);
    double temperature = (R - R0) / (R0 * 0.0039083); // Simplified equation

    return temperature;
}

// PID control loop
double pid_control(double setpoint, double actual_temperature, PIDParams *pid_params) {
    double error = setpoint - actual_temperature;
    double integral = 0;
    double derivative = 0;

    integral += error;
    derivative = error - pid_params->ki * integral;

    double output = pid_params->kp * error + pid_params->ki * integral + pid_params->kd * derivative;

    return output;
}

// Publish temperature to MQTT
int publish_temperature(double temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("MQTT publish failed");
        return -1;
    }
    return 0;
}

// Log messages to file
int log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    log_message("Cleaning up...");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioPWM(HEATER_GPIO, 0); // Turn off heater
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting heater control program...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        log_message("SPI initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        log_message("MQTT initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Read configuration
    if (read_config("heater_config.json") != 0) {
        log_message("Failed to read config file, using defaults");
    }

    // Main loop
    while (running) {
        // Read temperature and fault status
        int rtd_code = read_max31865();
        if (rtd_code < 0) {
            log_message("Failed to read RTD code, exiting");
            break;
        }

        // Convert RTD code to resistance
        double rtd_resistance = rtd_to_resistance(rtd_code);

        // Convert resistance to temperature
        double temperature = resistance_to_temperature(rtd_resistance);

        // PID control
        double pid_output = pid_control(target_temperature, temperature, &pid_params);

        // Convert PID output to PWM duty cycle
        int duty_cycle = (int)pid_output;

        // Clamp duty cycle to 0-1000
        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 1000) {
            duty_cycle = 1000;
        }

        // Set PWM duty cycle
        gpioPWM(HEATER_GPIO, duty_cycle);

        // Publish temperature
        if (publish_temperature(temperature) != 0) {
            log_message("Failed to publish temperature");
        }

        // Failsafe shutoff
        if (temperature > MAX_TEMP || rtd_code < MIN_RTD || rtd_code > MAX_RTD || fault) {
            log_message("Failsafe triggered, shutting down heater");
            gpioPWM(HEATER_GPIO, 0); // Turn off heater
            break;
        }

        // Wait 100 ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    log_message("Exiting");
    return 0;
}

