// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            perror("I2C read error");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            perror("I2C write error");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Read calibration data from BMP180
int read_calibration_data(int fd) {
    ac1 = (i2c_read_reg(fd, BMP180_REG_CAL_AC1) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC1 + 1);
    ac2 = (i2c_read_reg(fd, BMP180_REG_CAL_AC2) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC2 + 1);
    ac3 = (i2c_read_reg(fd, BMP180_REG_CAL_AC3) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC3 + 1);
    ac4 = (i2c_read_reg(fd, BMP180_REG_CAL_AC4) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC4 + 1);
    ac5 = (i2c_read_reg(fd, BMP180_REG_CAL_AC5) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC5 + 1);
    ac6 = (i2c_read_reg(fd, BMP180_REG_CAL_AC6) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC6 + 1);
    b1 = (i2c_read_reg(fd, BMP180_REG_CAL_B1) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_B1 + 1);
    b2 = (i2c_read_reg(fd, BMP180_REG_CAL_B2) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_B2 + 1);
    mb = (i2c_read_reg(fd, BMP180_REG_CAL_MB) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MB + 1);
    mc = (i2c_read_reg(fd, BMP180_REG_CAL_MC) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MC + 1);
    md = (i2c_read_reg(fd, BMP180_REG_CAL_MD) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MD + 1);

    return 0;
}

// Read raw temperature value
int read_raw_temperature(int fd) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Failed to write temperature conversion command.\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms
    return (i2c_read_reg(fd, BMP180_REG_MSB) << 8) | i2c_read_reg(fd, BMP180_REG_LSB);
}

// Read raw pressure value
int read_raw_pressure(int fd) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Failed to write pressure conversion command.\n");
        return -1;
    }
    usleep(2 + (3 << BMP180_OSS)) ; // Wait for conversion
    int msb = i2c_read_reg(fd, BMP180_REG_MSB);
    int lsb = i2c_read_reg(fd, BMP180_REG_LSB);
    int xlsb = i2c_read_reg(fd, BMP180_REG_XLSB);

    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
