    if (b7 < 0x80000000) {
        pressure = (b7 * 2) / b4;
    } else {
        pressure = (b7 / b4) * 2;
    }

    x1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    x1_pressure = (x1_pressure * 3038) / pow(2, 16);
    x2_pressure = (-7357 * pressure) / pow(2, 16);
    pressure = pressure + (x1_pressure + x2_pressure + 3791) / pow(2, 4);

    return pressure / 100.0; // Convert to hPa
}

// Check if temperature or pressure is outside the breach thresholds
int check_breaches(double temperature, double pressure) {
    return (temperature > 30.0 || pressure < 950.0);
}

// Log a breach to the log file
void log_breach(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
