            sleep(1);
            continue;
        }

        // Calculate temperature and pressure
        double temperature = calculate_temperature(ut);
        double pressure = calculate_pressure(up, ut);

        // Check for breaches
        if (check_breaches(temperature, pressure)) {
            log_breach(temperature, pressure);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close resources before exiting
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

