int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read pressure from BMP180
double read_pressure() {
    char buf[2];
    int ut, up;
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Read uncompensated temperature (UT)
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 2) != 2) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1.0;
    }
    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature register address\n");
        return -1.0;
    }
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading uncompensated temperature\n");
        return -1.0;
    }
    ut = (buf[0] << 8) | buf[1];

    // Read uncompensated pressure (UP)
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 2) != 2) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1.0;
    }
    gpioDelay(26000); // Wait 26ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure register address\n");
        return -1.0;
    }
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading uncompensated pressure\n");
        return -1.0;
    }
    up = ((up << 16) | (up << 8) | up) >> (8 - OSS);

