int set_heater_duty_cycle(int duty_cycle);
int log_data(float thermocouple_temp, float duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Function to read data from MAX31855
int read_max31855(float *internal_temp, float *thermocouple_temp) {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return 1;
    }

    // Check for fault bits
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        *thermocouple_temp = NAN; // Not a Number
        *internal_temp = NAN;
        return 1;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        *thermocouple_temp = NAN;
        *internal_temp = NAN;
        return 1;
    }
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        *thermocouple_temp = NAN;
        *internal_temp = NAN;
        return 1;
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_raw = ((buffer[0] << 8) | buffer[1]) >> 2;
    *thermocouple_temp = thermocouple_raw * 0.25;

    // Extract internal temperature (bits 15:4)
    int16_t internal_raw = ((buffer[2] << 8) | buffer[3]) >> 4;
    *internal_temp = internal_raw * 0.0625;

    return 0;
}

// Function to calculate duty cycle using PI controller
float calculate_duty_cycle(float thermocouple_temp, float target_temperature, float Kp, float Ki, float *integral, float *previous_duty_cycle) {
    float error = target_temperature - thermocouple_temp;
    *integral += error;

    // Anti-windup
    float integral_limit = 100.0; // Adjust as needed
    if (*integral > integral_limit) *integral = integral_limit;
    if (*integral < -integral_limit) *integral = -integral_limit;

    float output = Kp * error + Ki * (*integral);

    // Limit duty cycle to 0-100%
    float duty_cycle = (output / 100.0) * MAX_DUTY_CYCLE;
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    *previous_duty_cycle = duty_cycle;
    return duty_cycle;
}

// Function to set heater duty cycle
int set_heater_duty_cycle(int duty_cycle) {
    gpioPWM(HEATER_GPIO, duty_cycle * 1000); // pigpio uses 0-1000 for PWM
    return 0;
}

// Function to log data to CSV file
int log_data(float thermocouple_temp, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, thermocouple_temp, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    set_heater_duty_cycle(0); // Turn off heater
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config = {
        .target_temperature = TARGET_TEMPERATURE,
        .heater_gpio = HEATER_GPIO,
        .spi_channel = SPI_CHANNEL,
        .spi_baud = SPI_BAUD,
        .log_file = LOG_FILE,
        .Kp = 1.0, // PI controller gains
        .Ki = 0.1
    };

    // Parse command-line arguments
    if (argc > 1) {
        config.target_temperature = atof(argv[1]);
    }

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float thermocouple_temp, internal_temp;
    float duty_cycle;
    float integral = 0.0;
    float previous_duty_cycle = 0.0;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(&internal_temp, &thermocouple_temp) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(thermocouple_temp, config.target_temperature, config.Kp, config.Ki, &integral, &previous_duty_cycle);

            // Set heater duty cycle
            set_heater_duty_cycle((int)duty_cycle);

            // Log data
            log_data(thermocouple_temp, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature, setting duty cycle to 0%%\n");
            set_heater_duty_cycle(0);
            log_data(NAN, 0.0); // Log error
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

