#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp_milli;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s\n", TEMP_FILE);
        return -1; // Indicate error
    }

    if (fread(buffer, 1, sizeof(buffer) - 1, fp) <= 0) {
        fprintf(stderr, "Error: Could not read temperature from file %s\n", TEMP_FILE);
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    buffer[sizeof(buffer) - 1] = '\0'; // Ensure null termination
    temp_milli = atoi(buffer);

    return temp_milli;
}

// Function to set RGB LED color using PWM
void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Invert for common-anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common-anode
    gpioPWM(BLUE_PIN, 255 - blue);  // Invert for common-anode
}

// Function to map temperature to RGB color
void map_temperature_to_rgb(int temperature, int *red, int *green, int *blue) {
    if (temperature < 40000) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temperature >= 40000 && temperature <= 59999) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    int temperature, red, green, blue;
    int temp_milli;
    int prev_temp = 0; // Store the previous temperature for temperature hysteresis

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(BLUE_PIN, 1000); // 1 kHz

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Mood light started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read CPU temperature
        temp_milli = read_cpu_temp();
        if (temp_milli == -1) {
            // Error reading temperature, skip this cycle
            gpioDelay(500000); // 0.5 seconds
            continue;
        }

        // Convert temperature to Celsius
        temperature = temp_milli / 1000;

        // Map temperature to RGB color
        map_temperature_to_rgb(temperature, &red, &green, &blue);

        // Set RGB LED color
        set_rgb_color(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, red, green, blue);

        // Hysteresis: Avoid rapid color changes
        if (temperature > prev_temp) {
            gpioDelay(100000); // 0.1 seconds
        }
        prev_temp = temperature;

        // Wait for 0.5 seconds
        gpioDelay(500000);
    }

    // Clean up and exit
    set_rgb_color(255, 255, 255); // Turn off LED
    gpioTerminate();
    printf("Mood light stopped.\n");
    return 0;
}

