#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>

// Configuration
#define DHT22_GPIO 4 // GPIO pin connected to DHT22 data line
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY 5 // seconds

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_gpio();
SensorData read_dht22();
int validate_checksum(unsigned char data[], int checksum);
int send_http_post(SensorData data);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to write received data
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the received data here if needed
    return real_size;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl_easy_setopt(curl_easy_init(), CURLOPT_WRITEFUNCTION, write_callback);

    // Main loop
    while (running) {
        SensorData data = read_dht22();

        if (data.temperature != -1000.0) { // Check for error value
            if (send_http_post(data) != 0) {
                fprintf(stderr, "Failed to send HTTP POST request.\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor data.\n");
        }

        sleep(60); // Read sensor data every 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;
    return 0;
}

// Read data from DHT22 sensor using bit-banging
SensorData read_dht22() {
    SensorData data = {-1000.0, -1000.0}; // Initialize with error values
    int i, j;
    unsigned char data_buffer[5] = {0, 0, 0, 0, 0};
    unsigned char checksum_buffer[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_count = 0;
    int bit_index = 0;
    int byte_index = 0;
    unsigned char last_state = 1; // Assume initial state is HIGH

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for LOW signal
        while (gpioRead(DHT22_GPIO) == 1) {
            // Wait for the signal to go LOW
        }

        // Measure HIGH duration
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpioRead(DHT22_GPIO) == 0) {
            // Wait for the signal to go HIGH
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Determine bit value based on duration
        if (duration > 40) {
            data_buffer[byte_index] |= (1 << (7 - bit_count));
        }
        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Read checksum
    for (i = 0; i < 8; i++) {
        // Wait for LOW signal
        while (gpioRead(DHT22_GPIO) == 1) {
            // Wait for the signal to go LOW
        }

        // Measure HIGH duration
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpioRead(DHT22_GPIO) == 0) {
            // Wait for the signal to go HIGH
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Determine bit value based on duration
        if (duration > 40) {
            checksum_buffer[byte_index] |= (1 << (7 - bit_count));
        }
        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Validate checksum
    if (validate_checksum(data_buffer, checksum_buffer) != 0) {
        fprintf(stderr, "Checksum validation failed.\n");
        return data; // Return error value
    }

    // Convert data to temperature and humidity
    data.humidity = (float)(((data_buffer[0] << 8) | data_buffer[1])) / 10.0;
    data.temperature = (float)(((data_buffer[2] << 8) | data_buffer[3])) / 10.0;
    if (data_buffer[2] & 0x80) {
        data.temperature *= -1;
    }

    return data;
}

// Validate checksum
int validate_checksum(unsigned char data[], int checksum) {
    unsigned char calculated_checksum = 0;
    for (int i = 0; i < 40; i++) {
        calculated_checksum += data[i];
    }
    calculated_checksum &= 0xFF; // Keep only the last 8 bits

    if (calculated_checksum != checksum) {
        return 1; // Checksum mismatch
    }
    return 0; // Checksum valid
}

// Send HTTP POST request using libcurl
int send_http_post(SensorData data) {
    CURL *curl;
    CURLcode res;
    char json_payload[100]; // Adjust size as needed

    // Format JSON payload
    snprintf(json_payload, sizeof(json_payload), "{\"temperature\": %.2f, \"humidity\": %.2f}", data.temperature, data.humidity);

    // Initialize libcurl
    curl = curl_easy_init();
    if (curl) {
        // Set URL
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);

        // Set POST data
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        // Set content type
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));
        curl_easy_setopt(curl, CURLOPT_CONTENTTYPE, "application/json");

        // Set write callback (optional)
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        // Perform request
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Check response code (optional)
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code != 200) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        // Clean up
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize libcurl.\n");
        return 1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (pigpio_initialized) {
        gpioTerminate();
    }
    curl_global_cleanup();
}

