// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Oversampling setting (OSS)
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile unsigned int last_interrupt_time = 0;
static volatile int running = 1;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_bmp180();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temp, int raw_pressure);
void log_pressure(double pressure);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);

// Function to initialize the BMP180 sensor
int init_bmp180() {
    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }

    // Verify calibration data (example checks)
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || b1 == 0 || b2 == 0 || mb == 0 || mc == 0 || md == 0) {
        fprintf(stderr, "Error: Invalid calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, 0xAA, data, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data block.\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf+1, 1) != 1) {
        fprintf(stderr, "Error: Failed to write temperature command.\n");
        return -1;
    }

    gpioDelay(26); // Wait for conversion (26ms)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf+1, 1) != 1) {
        fprintf(stderr, "Error: Failed to write temperature read command.\n");
        return -1;
    }

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature data.\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf+1, 1) != 1) {
        fprintf(stderr, "Error: Failed to write pressure command.\n");
        return -1;
    }

    gpioDelay(26); // Wait for conversion (26ms)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf+1, 1) != 1) {
        fprintf(stderr, "Error: Failed to write pressure read command.\n");
        return -1;
    }

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure data.\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate pressure in hPa using the BMP180 compensation algorithm
double calculate_pressure(int raw_temp, int raw_pressure) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x1 = ((long)mc << 11) / (b5 + md);
    b6 = b5 + x1 - 4000;
    x2 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    x3 = ((long)ac2 * b6) >> 11;
    b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((long)ac3 * b6) >> 13;
    x2 = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (double)p / 100.0; // Convert to hPa
}

// Function to log pressure data to a file
void log_pressure(double pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open pressure_log.txt for writing.\n");
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    unsigned int current_time = tick;

    // Debounce the interrupt
    if (current_time - last_interrupt_time < DEBOUNCE_TIME) {
        return;
    }

    last_interrupt_time = current_time;

    // Toggle logging state
    logging_enabled = !logging_enabled;

    if (logging_enabled) {
        printf("Logging started.\n");
    } else {
        printf("Logging stopped.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C connection. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP180 sensor
    if (init_bmp180() != 0) {
        fprintf(stderr, "Error: BMP180 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set interrupt handler.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 data logger started. Press the button on GPIO%d to toggle logging.\n", INTERRUPT_PIN);

    // Main loop
    while (running) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            double pressure;

            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                pressure = calculate_pressure(raw_temp, raw_pressure);
                log_pressure(pressure);
                printf("Pressure: %.2f hPa\n", pressure);
            } else {
                fprintf(stderr, "Error: Failed to read pressure data.\n");
            }
        }
        gpioDelay(2000); // Sample every 2 seconds
    }

    // Cleanup (should not reach here if signal handler is working)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

