#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int log_fd = -1;

// Function prototypes
int read_cpu_temp();
int set_fan_speed(int state);
int log_event(const char *message);
int validate_state(int state);
int get_max_state();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
        set_fan_speed(0); // Stop the fan
        if (log_fd != -1) {
            log_event("Program terminated.");
        }
        exit(0);
    }
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000; // Convert to millidegrees Celsius
    } else {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to set fan speed using sysfs
int set_fan_speed(int state) {
    int fd;
    char buffer[2];

    fd = open(FAN_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open fan file");
        return -1;
    }

    if (state != 0 && state != 1 && state != 2 && state != 3) {
        fprintf(stderr, "Invalid fan state: %d\n", state);
        close(fd);
        return -1;
    }

    if (state == 0) {
        snprintf(buffer, sizeof(buffer), "%d", 0);
    } else if (state == 1) {
        snprintf(buffer, sizeof(buffer), "%d", 1);
    } else if (state == 2) {
        snprintf(buffer, sizeof(buffer), "%d", 2);
    } else {
        snprintf(buffer, sizeof(buffer), "%d", 3);
    }

    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to fan file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log events with timestamps
int log_event(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fd != -1) {
        dprintf(log_fd, "%s: %s\n", timestamp, message);
    } else {
        fprintf(stderr, "%s: %s\n", timestamp, message);
    }
    return 0;
}

// Function to validate the fan state
int validate_state(int state) {
    return (state >= 0 && state <= 3);
}

// Function to get the maximum allowed fan state
int get_max_state() {
    FILE *fp;
    char buffer[10];
    int max_state = 0;

    fp = fopen("/sys/class/thermal/cooling_device0/max_state", "r");
    if (fp == NULL) {
        perror("Failed to open max_state file");
        return 0; // Default to 0 if max_state file is unavailable
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        max_state = atoi(buffer);
    } else {
        perror("Failed to read max_state");
    }

    fclose(fp);
    return max_state;
}

int main() {
    int current_temp, fan_state, max_state;
    int temp_range, fan_range;
    int temp, fan;
    int i;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return 1;
    }

    // Get the maximum allowed fan state
    max_state = get_max_state();

    // Main loop
    while (program_running) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            log_event("Failed to read CPU temperature, using previous value.");
            // Consider using a default temperature or exiting if read fails consistently
            continue; // Skip to the next iteration
        }

        // Validate temperature range
        if (temp < 0 || temp > 100000) {
            log_event("Invalid CPU temperature, skipping fan control.");
            sleep(5);
            continue;
        }

        // Determine fan speed based on temperature
        if (temp < 45000) {
            fan = 0;
        } else if (temp < 55000) {
            fan = 1;
        } else if (temp < 65000) {
            fan = 2;
        } else {
            fan = 3;
        }

        // Validate fan state
        if (!validate_state(fan)) {
            log_event("Invalid fan state, using previous value.");
            fan = (max_state == 0) ? 0 : (max_state == 3) ? 3 : (max_state == 2) ? 2 : 1; // Default to 1 if invalid
        }

        // Set fan speed
        if (set_fan_speed(fan) == -1) {
            log_event("Failed to set fan speed.");
        }

        // Log event
        char message[100];
        snprintf(message, sizeof(message), "Temperature: %d°C, Fan Speed: %d", temp, fan);
        log_event(message);

        // Wait 5 seconds
        sleep(5);
    }

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    return 0;
}

