            log_event("Invalid CPU temperature, skipping fan control.");
            sleep(5);
            continue;
        }

        // Determine fan speed based on temperature
        if (temp < 45000) {
            fan = 0;
        } else if (temp < 55000) {
            fan = 1;
        } else if (temp < 65000) {
            fan = 2;
        } else {
            fan = 3;
        }

        // Validate fan state
        if (!validate_state(fan)) {
            log_event("Invalid fan state, using previous value.");
            fan = (max_state == 0) ? 0 : (max_state == 3) ? 3 : (max_state == 2) ? 2 : 1; // Default to 1 if invalid
        }

        // Set fan speed
        if (set_fan_speed(fan) == -1) {
            log_event("Failed to set fan speed.");
        }

        // Log event
        char message[100];
        snprintf(message, sizeof(message), "Temperature: %d°C, Fan Speed: %d", temp, fan);
        log_event(message);

        // Wait 5 seconds
        sleep(5);
    }

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    return 0;
}

