#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define TARGET_TEMPERATURE 50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // 0-1000 for 0-100%
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
double calculate_pid(double current_temperature, double target_temperature, double *integral, double *previous_error);
void set_heater_pwm(double pid_output);
void log_data(double temperature, double pwm_duty_cycle, double pid_output);
void handle_spi_error(int error_code, const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        handle_spi_error(result, "SPI read failed");
        return -273.15; // Return absolute zero on error
    }

    // Check for fault bits
    if (buffer[3] & 0x04) {
        handle_spi_error(0, "Thermocouple open circuit");
        return -273.15;
    } else if (buffer[3] & 0x02) {
        handle_spi_error(0, "Thermocouple short to GND");
        return -273.15;
    } else if (buffer[3] & 0x01) {
        handle_spi_error(0, "Thermocouple short to VCC");
        return -273.15;
    }

    // Extract temperature data (bits 31:18 are temperature)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double current_temperature, double target_temperature, double *integral, double *previous_error) {
    double error = target_temperature - current_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double pid_output) {
    // Clamp PID output to 0-1000
    int duty_cycle = (int)(pid_output * 10.0); // Scale PID output to 0-100
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, double pwm_duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, temperature, pwm_duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle SPI errors
void handle_spi_error(int error_code, const char *message) {
    fprintf(stderr, "SPI Error: %s (Code: %d)\n", message, error_code);
    fprintf(log_file, "SPI Error: %s (Code: %d)\n", message, error_code);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    double current_temperature, pid_output;
    int duty_cycle;

    while (running) {
        current_temperature = read_temperature();

        if (current_temperature > MAX_TEMP || current_temperature < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", current_temperature);
            fprintf(log_file, "Temperature out of range: %.2f\n", current_temperature);
            fflush(log_file);
            gpioPWM(HEATER_GPIO, 0); // Disable heater
            running = 0; // Exit loop
        }

        pid_output = calculate_pid(current_temperature, TARGET_TEMPERATURE, &integral, &previous_error);
        duty_cycle = (int)(pid_output * 10.0); // Scale PID output to 0-100
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        set_heater_pwm(pid_output);
        log_data(current_temperature, duty_cycle, pid_output);

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

