#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
float read_cpu_temp();
float map_temp_to_duty(float temp);
void set_fan_speed(int duty_cycle);
void log_data(float temp, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down...\n", signal);
    set_fan_speed(0); // Turn off the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s\n", TEMP_FILE);
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file %s\n", TEMP_FILE);
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to map temperature to PWM duty cycle
int map_temp_to_duty(float temp) {
    int duty_cycle;

    if (temp < 40.0) {
        duty_cycle = 0;
    } else if (temp > 70.0) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)((temp - 40.0) * (100.0 / (70.0 - 40.0)));
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(FAN_GPIO, duty_cycle * 255 / 100); // pigpio uses 0-255 range
}

// Function to log data to file
void log_data(float temp, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temp, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate(); // Terminate pigpio before exiting
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error: Could not read CPU temperature. Using previous value.\n");
            // Consider implementing a fallback temperature or logging the error
        } else {
            duty_cycle = map_temp_to_duty(temperature);
            set_fan_speed(duty_cycle);
            log_data(temperature, duty_cycle);
        }

        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

