#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_COMMAND 0x3608
#define LOG_FILE "flow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int handle;
    int address;
    float flow_rate;
} sensor_t;

// Function prototypes
int init_i2c(int bus, int addr);
int send_command(int handle, int command);
int read_data(int handle, char *buffer, int count);
float calculate_flow_rate(int raw_value);
int validate_crc(char *data, int length);
void log_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Send a command to the sensor
int send_command(int handle, int command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error sending command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate flow rate from raw value
float calculate_flow_rate(int raw_value) {
    return (float)raw_value * 0.01;
}

// Validate CRC checksum
int validate_crc(char *data, int length) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < length - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
