#include <string.h>

// Define GPIO pins for the rotary encoder
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
volatile int pulse_count = 0;
volatile int last_state = 0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void initialize_gpio();
void handle_interrupt(int gpio, int level, uint32_t tick, void *user_data);
void update_state(int *current_state, int *previous_state, int sensor_a_value, int sensor_b_value);
float calculate_angle(int pulse_count);
void log_data(int current_state, float angle);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor_a;
    int sensor_b;
} sensor_data_t;

// Function to initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);

    // Enable pull-up resistors (internal pull-ups are enabled by default on Raspberry Pi)
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    // Set up interrupt handlers for both sensors
    if (gpioSetISRFuncEx(SENSOR_A_PIN, RISING_EDGE, 0, handle_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor A\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetISRFuncEx(SENSOR_B_PIN, RISING_EDGE, 0, handle_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor B\n");
        gpioTerminate();
        exit(1);
    }
}

// Interrupt handler function
void handle_interrupt(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *data = (sensor_data_t *)user_data;
    int sensor_a_value = gpioRead(SENSOR_A_PIN);
    int sensor_b_value = gpioRead(SENSOR_B_PIN);

    update_state(&data->sensor_a, &data->previous_sensor_a, sensor_a_value, sensor_b_value);
    update_state(&data->sensor_b, &data->previous_sensor_b, sensor_a_value, sensor_b_value);

    // Increment pulse count if a valid pulse is detected
    if (sensor_a_value != gpioRead(SENSOR_A_PIN) || sensor_b_value != gpioRead(SENSOR_B_PIN)) {
        pulse_count++;
    }
}

// Function to update the state of the rotary encoder
void update_state(int *current_state, int *previous_state, int sensor_a_value, int sensor_b_value) {
    int a_diff = sensor_a_value - previous_state->sensor_a;
    int b_diff = sensor_b_value - previous_state->sensor_b;

    if (a_diff != 0 && b_diff != 0) {
        *current_state = (a_diff + b_diff + 4) % 4; // Quadrature encoding
    } else if (a_diff != 0) {
        *current_state = a_diff; // Clockwise/Counter-clockwise
    } else if (b_diff != 0) {
        *current_state = 2 - b_diff; // Counter-clockwise/Counter-clockwise
    } else {
        *current_state = 3; // Idle state
    }

    *previous_state = *current_state;
}

// Function to calculate the normalized angular position
float calculate_angle(int pulse_count) {
    return (float)pulse_count / 360.0 * 360.0;
}

// Function to log data to a file
void log_data(int current_state, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f\n", timestamp, current_state, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data = {0, 0};
    int previous_state = 0;

    // Main loop
    while (running) {
        // Calculate angle
        float angle = calculate_angle(pulse_count);

        // Log data
        log_data(previous_state, angle);

        // Update previous state
        previous_state = (int)((float)pulse_count / 360.0 * 360.0);

        // Sleep for a short period
        gpioDelay(10000); // 10ms
    }

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

