#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO 17
#define RED_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_fifo_data(uint16_t *red, uint16_t *ir);
int process_data(uint16_t red, uint16_t ir);
int control_led(int state);
int log_data(uint16_t red, uint16_t ir);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from FIFO
int read_fifo_data(uint16_t *red, uint16_t *ir) {
    char buf[4];
    int bytes_read = i2cReadI2CBlockData(i2c_fd, FIFO_DATA_REG, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    *red = (buf[0] << 8) | buf[1];
    *ir = (buf[2] << 8) | buf[3];

    return 0;
}

// Process data (crude thresholding)
int process_data(uint16_t red, uint16_t ir) {
    if (ir > RED_THRESHOLD) {
        return 1; // IR exceeds threshold
    } else {
        return 0; // IR below threshold
    }
}

// Control LED
int control_led(int state) {
    gpioWrite(LED_GPIO, state);
    return 0;
}

// Log data to file
int log_data(uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        return 1;
    }

    uint16_t red, ir;
