#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define PULSES_PER_REVOLUTION 1
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void *rpm_calculator_thread(void *arg);
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to pass data to the RPM calculator thread
typedef struct {
    int gpio_pin;
    int sample_interval_sec;
} thread_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Create the RPM calculator thread
    thread_data_t thread_data = {GPIO_PIN, SAMPLE_INTERVAL_SEC};
    pthread_t rpm_thread;
    if (pthread_create(&rpm_thread, NULL, rpm_calculator_thread, &thread_data) != 0) {
        perror("Failed to create RPM calculator thread");
        cleanup();
        return 1;
    }

    // Main loop: read sensor data and log RPM
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    // Wait for the RPM calculator thread to finish
    pthread_join(rpm_thread, NULL);

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register ISR for rising edges
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void *rpm_calculator_thread(void *arg) {
    thread_data_t *data = (thread_data_t *)arg;
    int rpm = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time >= 1.0) {
            // Calculate RPM
            rpm = pulse_count * PULSES_PER_REVOLUTION * 60.0; // pulses/rev * 60 sec/min
            if (rpm == 0) {
                rpm = 0.0;
            }

            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log RPM value with timestamp
            pthread_mutex_lock(&pulse_mutex);
            int current_pulse_count = pulse_count;
            pulse_count = 0; // Reset pulse count
            pthread_mutex_unlock(&pulse_mutex);

            fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
            fflush(log_file); // Flush the buffer immediately

            // Reset the timer
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
    }

    pthread_exit(NULL);
}

void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down...\n", signal);
    running = 0;
}

