#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define RED_REG 0x04
#define IR_REG 0x06
#define LED_GPIO 17
#define THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *red, uint16_t *ir);
int log_data(FILE *fp, uint16_t red, uint16_t ir);
int control_led(int gpio, int state);
void signal_handler(int signal);

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Indicate failure
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Indicate failure
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *red, uint16_t *ir) {
    int red_result, ir_result, retries = 3;

    while (retries > 0) {
        red_result = i2c_read_register(fd, RED_REG);
        if (red_result >= 0) {
            *red = (uint16_t)red_result;
        } else {
            fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
            *red = 0; // Set to 0 to avoid further issues
        }

        ir_result = i2c_read_register(fd, IR_REG);
        if (ir_result >= 0) {
            *ir = (uint16_t)ir_result;
        } else {
            fprintf(stderr, "Error reading IR data: %s\n", strerror(errno));
            *ir = 0; // Set to 0 to avoid further issues
        }

        if (*red > 0 && *ir > 0) {
            return 0; // Success
        }

        retries--;
        gpioDelay(1000); // Wait 1ms before retrying
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries\n");
    return -1; // Indicate failure
}

// Log data function
int log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u\n", timestamp, red, ir) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Control LED function
int control_led(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    uint16_t red, ir;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sensor_data(i2c_fd, &red, &ir);
        if (result == 0) {
            // Log data
            if (log_data(log_file, red, ir) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Control LED
            if (ir > THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_GPIO, 0); // Turn LED off
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

