#define GPIO_CHIP "gpiochip0"
#define AUDIO_INPUT_PIN 17
#define AUDIO_OUTPUT_PIN 18

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *audio_input_line = NULL;
static struct gpiod_line *audio_output_line = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    struct gpiod_line_request_config input_config;
    struct gpiod_line_request_config output_config;

    // Request audio input line for input
    if (gpiod_chip_open_by_name(chip, &chip) < 0) {
        perror("Error opening GPIO chip");
        return -1;
    }

    audio_input_line = gpiod_chip_get_line(chip, AUDIO_INPUT_PIN);
    if (!audio_input_line) {
        perror("Error getting audio input line");
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "audio_input";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(audio_input_line, &input_config, 0) < 0) {
        perror("Error requesting audio input line");
        gpiod_line_release(audio_input_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request audio output line for output
    audio_output_line = gpiod_chip_get_line(chip, AUDIO_OUTPUT_PIN);
    if (!audio_output_line) {
        perror("Error getting audio output line");
        gpiod_line_release(audio_input_line);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "audio_output";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(audio_output_line, &output_config, 0) < 0) {
        perror("Error requesting audio output line");
        gpiod_line_release(audio_input_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to log audio events to a file
int log_audio_event()
{
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("Error opening audio_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s LEVEL\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to set the gain level
int set_gain_level(int gain_level)
{
    if (gain_level != 0 && gain_level != 1) {
        fprintf(stderr, "Invalid gain level. Must be 0 or 1.\n");
        return -1;
    }

    if (gain_level == 1) {
        if (gpiod_line_set_value(audio_output_line, 1) < 0) {
            perror("Error setting audio output line value");
            return -1;
        }
    } else {
        if (gpiod_line_set_value(audio_output_line, 0) < 0) {
            perror("Error setting audio output line value");
            return -1;
        }
    }
    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Poll for rising edge on audio input pin
        if (gpiod_line_get_value(audio_input_line) == 1) {
            if (log_audio_event() < 0) {
                fprintf(stderr, "Error logging audio event.\n");
            }
            usleep(10000); // Debounce and prevent multiple logs
        } else {
            usleep(10000); // Check every 10ms
        }
    }

    // Clean up GPIO resources
    if (audio_output_line) {
        gpiod_line_release(audio_output_line);
    }
    if (audio_input_line) {
        gpiod_line_release(audio_input_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

