#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define FLOW_LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a command to the sensor
int write_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read flow data from the sensor
int read_flow_data(int handle, uint16_t *flow_rate) {
    char buf[3];
    int result = i2cReadDevice(handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow data: %s\n", strerror(errno));
        return -1;
    }

    // Validate CRC
    uint8_t crc = crc8(buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    // Combine MSB and LSB to form the 16-bit flow rate
    *flow_rate = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to convert raw flow rate to uL/min
float convert_to_uL_min(uint16_t raw_flow_rate) {
    return (float)raw_flow_rate / 1000.0;
}

// Function to log the flow rate to a CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open!\n");
        return -1;
    }

    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,flow_rate_uL_min\n");
    }
    fflush(log_file);

    // Initialize the sensor
    if (write_command(i2c_handle, MEASURE_CMD) != 0) {
        fprintf(stderr, "Failed to initialize sensor. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_flow_rate;
    float flow_rate_uL_min;

    // Main loop
    while (!terminate) {
        if (read_flow_data(i2c_handle, &raw_flow_rate) == 0) {
            flow_rate_uL_min = convert_to_uL_min(raw_flow_rate);
            if (log_flow_rate(flow_rate_uL_min) != 0) {
                fprintf(stderr, "Failed to log flow rate.\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    printf("Closing I2C connection...\n");
    i2cClose(i2c_handle);
    printf("Closing log file...\n");
    fclose(log_file);
    printf("Terminating pigpio...\n");
    gpioTerminate();

    return 0;
}

