#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define TVOC_REG 0x00
#define ECO2_REG 0x05
#define IAQ_INDEX_REG 0x06 // Dummy register, not used in this example

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_iaq(uint16_t tvoc, uint16_t eco2);
int log_data(float iaq, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-VZ-89TE
int read_sensor_data(sensor_data_t *data) {
    char buf[7];
    int result = i2cReadI2CBlockData(i2c_handle, TVOC_REG, buf, 7);

    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->tvoc = (buf[1] << 8) | buf[0];
    data->eco2 = (buf[5] << 8) | buf[4];

    return 0;
}

// Calculate IAQ index
float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0 - (tvoc / 10.0) - ((eco2 - 400) / 50.0);
