#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_NS 100000000 // 100 ms

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "Signal received, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio_line()
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the sensor value
int read_sensor()
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to check for tamper events
void check_tamper_event()
{
    int sensor_value = read_sensor();
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor, exiting.\n");
        exit(EXIT_FAILURE);
    }

    if (sensor_value == 1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long elapsed_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        if (elapsed_ms >= 5000) {
            printf("INTRUSION DETECTED! Sensor touched for %ld ms\n", elapsed_ms);
        }
    }
}

// Function to cleanup resources
void cleanup()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    fprintf(stderr, "Cleanup complete.\n");
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize the GPIO line
    if (init_gpio_line() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        check_tamper_event();
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        nanosleep(&ts, NULL);
    }

    // Cleanup resources before exiting
    cleanup();

    return EXIT_SUCCESS;
}

