#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // bits
#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define CAPTURE_FILE "audio_capture.pcm"
#define BUFFER_SIZE 1024

// Global variables
static volatile int keep_running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *lrb_pin = NULL;
static snd_pcm_t *pcm_handle = NULL;
static FILE *capture_file = NULL;

// Function prototypes
int init_gpio();
int init_alsa(snd_pcm_t **pcm_handle);
int capture_audio(snd_pcm_t *pcm_handle, FILE *capture_file);
int write_to_file(FILE *capture_file, int16_t *buffer, int num_samples);
void cleanup();
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    lrb_pin = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!lrb_pin) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "audio_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(lrb_pin, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Capture audio
int capture_audio(snd_pcm_t *pcm_handle, FILE *capture_file) {
    int16_t *buffer = (int16_t *)malloc(BUFFER_SIZE * sizeof(int16_t));
    if (!buffer) {
        perror("Error allocating buffer");
        return -1;
    }

    int err = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
    if (err == -EPIPE) {
        /* EPIPE means overrun */
        fprintf(stderr, "Overrun occurred\n");
        snd_pcm_prepare(pcm_handle);
    } else if (err < 0) {
        fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
        free(buffer);
        return -1;
    }

    if (write_to_file(capture_file, buffer, BUFFER_SIZE) < 0) {
        fprintf(stderr, "Error writing to file\n");
        free(buffer);
        return -1;
    }

    free(buffer);
    return 0;
}

// Write to file
int write_to_file(FILE *capture_file, int16_t *buffer, int num_samples) {
    size_t bytes_written = fwrite(buffer, sizeof(int16_t), num_samples, capture_file);
    if (bytes_written != num_samples) {
        fprintf(stderr, "Error writing to file: wrote %zu samples, expected %d\n", bytes_written, num_samples);
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    if (capture_file) {
        fclose(capture_file);
    }

    if (lrb_pin) {
        gpiod_line_release(lrb_pin);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    if (init_alsa(&pcm_handle) < 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup();
        return 1;
    }

    capture_file = fopen(CAPTURE_FILE, "wb");
    if (!capture_file) {
        perror("Error opening capture file");
        cleanup();
        return 1;
    }

    printf("Capturing audio to %s...\n", CAPTURE_FILE);

    while (keep_running) {
        if (capture_audio(pcm_handle, capture_file) < 0) {
            fprintf(stderr, "Audio capture failed\n");
            break;
        }
    }

    printf("Audio capture complete\n");

    cleanup();

    return 0;
}

