#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static volatile int flame_detected = 0;
static volatile unsigned int flame_start_time = 0;
static volatile unsigned int flame_duration = 0;
static volatile int fan_duty_cycle = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int duty_cycle);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to control the fan using PWM
void control_fan(int duty_cycle) {
    gpioPWM(FAN_PIN, duty_cycle);
}

// Function to log events to a file
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_PIN, 0); // Stop the fan
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_state = read_flame_sensor();

        if (flame_state == 0 && !flame_detected) {
            // Flame detected
            flame_detected = 1;
            flame_start_time = gpioTick();
            printf("Flame detected!\n");
            log_event("Flame detected");
        } else if (flame_state == 1 && flame_detected) {
            // Flame ended
            flame_detected = 0;
            flame_duration = gpioTick() - flame_start_time;
            printf("Flame ended.\n");
            log_event("Flame ended");

            // Calculate fan duty cycle based on flame duration
            if (flame_duration > 0) {
                // Exponential curve: duty_cycle = 0 + (1 - exp(-t / t_max)) * 80
                // t_max = 5 seconds (50ms * 100Hz)
                const float t_max = 5.0; // 5 seconds
                const float t = (float)flame_duration / 1000000.0; // Convert microseconds to seconds
                fan_duty_cycle = (int)(0 + (1 - exp(-t / t_max)) * 80);
                if (fan_duty_cycle < 0) fan_duty_cycle = 0;
                if (fan_duty_cycle > 80) fan_duty_cycle = 80;
            } else {
                fan_duty_cycle = 0;
            }
            control_fan(fan_duty_cycle);
        }

        gpioDelay(50000); // 50ms delay
    }

    cleanup();
    return 0;
}

