#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01
#define CONFIG_VALUE 0xC810 // Continuous conversion mode, 100ms, auto range
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *data);
float calculate_lux(uint16_t data);
int log_data(float lux);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int config_value;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *data) {
    int result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }
    *data = (uint16_t)result;
    return 0;
}

// Calculate lux value
float calculate_lux(uint16_t data) {
    int exponent = (data >> 12) & 0x0F;
    int mantissa = data & 0x0FFF;
    return 0.01 * (float)(2.0 * exponent) * mantissa;
}

// Log data to file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f lux\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t sensor_data;
    float lux;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            lux = calculate_lux(sensor_data);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

