#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

static volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO chip and line resources
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} gpio_resources_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize GPIO resources
int init_gpio_resources(gpio_resources_t *resources) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    resources->chip = chip;
    resources->line = line;

    return 0;
}

// Function to request GPIO line as input with bias pulled up
int request_gpio_line(gpio_resources_t *resources) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(resources->line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        return -1;
    }

    struct gpiod_line_settings settings;
    memset(&settings, 0, sizeof(settings));
    settings.direction = GPIOD_LINE_DIRECTION_INPUT;
    settings.pull_up_enable = 1;
    settings.pull_up_value = 1; // Enable pull-up resistor

    if (gpiod_line_set_settings(resources->line, &settings) < 0) {
        fprintf(stderr, "Error setting GPIO line %d settings: %s\n", GPIO_LINE, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the flame detection status
int read_flame_detection(gpio_resources_t *resources) {
    int value = gpiod_line_get_value(resources->line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the flame detection status with a timestamp
void log_flame_detection(int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Flame Detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
}

// Function to cleanup GPIO resources
void cleanup_gpio_resources(gpio_resources_t *resources) {
    if (resources->line) {
        gpiod_line_release(resources->line);
    }
    if (resources->chip) {
        gpiod_chip_close(resources->chip);
    }
}

int main() {
    gpio_resources_t resources = {NULL, NULL};

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO resources
    if (init_gpio_resources(&resources) < 0) {
        return 1;
    }

    // Request GPIO line as input
    if (request_gpio_line(&resources) < 0) {
        cleanup_gpio_resources(&resources);
        return 1;
    }

    // Main loop to read and log flame detection status
    while (program_running) {
        int flame_detected = read_flame_detection(&resources);
        if (flame_detected < 0) {
            break; // Exit loop on error
        }

        log_flame_detection(flame_detected);
        sleep(1); // Wait for 1 second
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio_resources(&resources);

    return 0;
}

