#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define CHANNELS {2, 3, 4, 5, 6, 7, 8, 9}

// Global variables for signal handling
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[8] = {NULL};
static volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO lines
int initialize_gpio()
{
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    // Request each line
    for (int i = 0; i < 8; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, CHANNELS[i]);
        if (!line) {
            fprintf(stderr, "Error getting line %d\n", CHANNELS[i]);
            return -1;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(line, &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %d\n", CHANNELS[i]);
            return -1;
        }
        lines[i] = line;
    }

    return 0;
}

// Function to read the sensor state
int read_sensor_state()
{
    int state = 0;
    for (int i = 0; i < 8; i++) {
        if (gpiod_line_get_value(lines[i]) == 1) {
            state |= (1 << i);
        }
    }
    return state;
}

// Function to log the sensor state
void log_sensor_state(int state)
{
    printf("Channel States: ");
    for (int i = 0; i < 8; i++) {
        printf("%d", (state >> i) & 1);
        if (i < 7) printf(", ");
    }
    printf("\n");
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    // Release lines
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int state = read_sensor_state();
        log_sensor_state(state);
        usleep(100000); // 100 ms
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

