#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 output channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure each GPIO pin as an input with pull-down resistor
    for (int i = 0; i < num_channels; i++) {
        int pin = gpio_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", pin);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log the sensor data
    while (1) {
        // Get current time in milliseconds
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Read the state of each channel
        for (int i = 0; i < num_channels; i++) {
            int pin = gpio_pins[i];
            int state = gpioRead(pin);

            // Log the state of the channel with a timestamp
            printf("[%d ms] CH%d=%d ", timestamp_ms, i + 1, state);
        }
        printf("\n");

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // The program should never reach here, but include gpioTerminate() for safety
    gpioTerminate();
    return 0;
}

