#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read sensor values and log them
    while (program_running) {
        // Read sensor values
        int sensor1_value = gpioRead(SENSOR1_GPIO);
        int sensor2_value = gpioRead(SENSOR2_GPIO);

        // Get current timestamp
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log sensor values to the console
        printf("[%s] Sensor 1: %s, Sensor 2: %s\n", timestamp, sensor1_value == 0 ? "LOW" : "HIGH", sensor2_value == 0 ? "LOW" : "HIGH");

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

