#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO lines for the TTP226 sensor array
const int gpio_lines[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variable to store the gpiod chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL};

// Function to handle Ctrl+C signal
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release all line resources
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release chip resources
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize the GPIO chip
int initialize_gpio(struct gpiod_chip **chip_ptr)
{
    *chip_ptr = gpiod_chip_open_by_name("gpiochip0");
    if (*chip_ptr == NULL) {
        perror("Error opening GPIO chip");
        return -1;
    }

    return 0;
}

// Function to request a GPIO line
int request_gpio_line(struct gpiod_chip *chip, int line_number, struct gpiod_line **line_ptr)
{
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_number);
    if (line == NULL) {
        perror("Error getting GPIO line");
        return -1;
    }

    *line_ptr = line;
    if (gpiod_line_request(line, "touch_sensor", 0) < 0) {
        perror("Error requesting GPIO line");
        return -1;
    }

    return 0;
}

// Function to read the state of a single GPIO line
int read_gpio_line(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line");
        return -1;
    }
    return value;
}

// Function to log the sensor data to the console
void log_sensor_data(int channel_states[8])
{
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
           buf,
           channel_states[0],
           channel_states[1],
           channel_states[2],
           channel_states[3],
           channel_states[4],
           channel_states[5],
           channel_states[6],
           channel_states[7]);
}

int main()
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO chip
    if (initialize_gpio(&chip) != 0) {
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (request_gpio_line(chip, gpio_lines[i], &lines[i]) != 0) {
            // Error already printed in request_gpio_line
            goto cleanup;
        }
    }

    // Main loop
    while (1) {
        int channel_states[8];

        // Read sensor data
        for (int i = 0; i < num_channels; i++) {
            channel_states[i] = read_gpio_line(lines[i]);
            if (channel_states[i] < 0) {
                // Error already printed in read_gpio_line
                goto cleanup;
            }
        }

        // Log sensor data
        log_sensor_data(channel_states);

        // Wait for 50 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 ms
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release all line resources
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release chip resources
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return 1;
}

