        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", TILT_SENSOR_GPIO);
        } else {
            if (sensor_value == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

