#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PART_ID 0x00
#define SI1145_HW_KEY 0x07
#define SI1145_CHLIST 0x01
#define SI1145_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float uv_index;
    int als_visible;
} sensor_data_t;

// Function prototypes
int init_si1145();
int read_si1145_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Verify PART ID
    status = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading PART ID: %s\n", strerror(errno));
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", status);
        return -1;
    }

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, SI1145_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    // Configure CHLIST
    status = i2cWriteByteData(i2c_handle, SI1145_CHLIST, 0x77); // Enable UV and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing CHLIST: %s\n", strerror(errno));
        return -1;
    }

    // Trigger measurements
    status = i2cWriteByteData(i2c_handle, SI1145_ALS_FORCE, 0x06);
    if (status < 0) {
        fprintf(stderr, "Error triggering measurements: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read UV index and Visible ALS data from the Si1145
int read_si1145_data(sensor_data_t *data) {
    int status;
    uint8_t buffer[4];

    // Read 4 bytes of data (UV index, Visible ALS, IR ALS, Ambient Light)
    status = i2cReadI2CBlockData(i2c_handle, 0x22, (char *)buffer, 4);
    if (status < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    // Extract UV index and Visible ALS data
    data->uv_index = (float)((uint16_t)buffer[0] << 8 | buffer[1]) / 100.0;
    data->als_visible = (int)((uint16_t)buffer[2] << 8 | buffer[3]);

    return 0;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, data.uv_index, data.als_visible);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    sensor_data_t sensor_data;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Print data to console
            printf("UV Index: %.2f, Visible ALS: %d\n", sensor_data.uv_index, sensor_data.als_visible);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

