#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define START_MEASUREMENT_COMMAND 0x3608
#define READ_COMMAND 0x00
#define LOG_FILE "flow_log.txt"
#define SLEEP_INTERVAL_SEC 1

// Global variables
int i2c_fd = -1;
int gpio_chip = -1;
struct gpiod_chip *gpio_chip_ptr = NULL;
struct gpiod_line *gpio_line_ptr = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *device);
int i2c_write(int fd, uint8_t command, uint8_t *data, int len);
int i2c_read(int fd, uint8_t *data, int len);
int i2c_close(int fd);
int gpio_init(const char *chip_name, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_get_value(struct gpiod_line *line);
int gpio_close(struct gpiod_line *line);
int read_flow_rate(int i2c_fd, int i2c_address, float *flow_rate);
float convert_flow_rate(int raw_flow);
float calculate_average_flow(float flow1, float flow2);
void log_flow_rate(float average_flow);
void alarm_control(float average_flow);
void signal_handler(int signal);
void cleanup();

// I2C functions
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t command, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, 0x36) < 0) { // Assuming 0x36 is the default I2C address
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (write(fd, data, len) != len) {
        perror("Error writing data to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, 0x36) < 0) { // Assuming 0x36 is the default I2C address
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &READ_COMMAND, 1) != 1) {
        perror("Error writing read command to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int i2c_close(int fd) {
    close(fd);
    return 0;
}

// GPIO functions
int gpio_init(const char *chip_name, int pin) {
    int ret = 0;
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    gpio_chip_ptr = gpiod_chip_get_line(chip, pin);
    if (!gpio_chip_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    ret = gpiod_line_request(gpio_chip_ptr, "alarm", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(gpio_chip_ptr);
        return -1;
    }
    return 0;
}

int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int gpio_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

int gpio_close(struct gpiod_line *line) {
    gpiod_line_release(line);
    return 0;
}

// Flow rate reading functions
int read_flow_rate(int i2c_fd, int i2c_address, float *flow_rate) {
    uint8_t data[9];
    int raw_flow;
    int ret;

    // Send start measurement command
    ret = i2c_write(i2c_fd, START_MEASUREMENT_COMMAND, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Error sending start measurement command for address 0x%02x\n", i2c_address);
        return -1;
    }

    // Wait for 100ms
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100ms
    nanosleep(&ts, NULL);

    // Read 9 bytes of data
    ret = i2c_read(i2c_fd, data, 9);
    if (ret < 0) {
        fprintf(stderr, "Error reading data from address 0x%02x\n", i2c_address);
        return -1;
    }

    // Extract flow rate from data
    raw_flow = (data[0] << 8) | data[1];

    // CRC validation
    uint8_t crc = data[2];
    uint8_t polynomial = 0x31;
    uint8_t initial_value = 0xFF;
    for (int i = 0; i < 8; i++) {
        if ((crc & 0x80) != 0) {
            initial_value ^= polynomial;
        }
        crc <<= 1;
        if ((crc & 0x80) != 0) {
            crc ^= polynomial;
        }
    }

    if (crc != initial_value) {
        fprintf(stderr, "CRC validation failed for address 0x%02x\n", i2c_address);
        return -1;
    }

    // Convert to ml/min
    *flow_rate = convert_flow_rate(raw_flow);

    return 0;
}

float convert_flow_rate(int raw_flow) {
    return raw_flow * 0.036;
}

// Alarm control function
void alarm_control(float average_flow) {
    int gpio_value = (average_flow < 0.5) ? 1 : 0;
    if (gpio_set_value(gpio_line_ptr, gpio_value) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
    }
}

// Logging function
void log_flow_rate(float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.4f\n", timestamp, average_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (gpio_chip_ptr != NULL) {
        gpio_close(gpio_line_ptr);
        gpiod_chip_close(gpio_chip_ptr);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    float flow1, flow2, average_flow;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    ret = gpio_init(GPIO_CHIP, GPIO_PIN);
    if (ret < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Starting flow monitoring...\n");

    while (program_running) {
        // Read flow rates from sensors
        ret = read_flow_rate(i2c_fd, 0x36, &flow1);
        if (ret < 0) {
            fprintf(stderr, "Error reading flow rate from sensor 0x36\n");
        }

        ret = read_flow_rate(i2c_fd, 0x37, &flow2);
        if (ret < 0) {
            fprintf(stderr, "Error reading flow rate from sensor 0x37\n");
        }

        // Calculate average flow rate
        if (flow1 >= 0 && flow2 >= 0) {
            average_flow = calculate_average_flow(flow1, flow2);
        } else {
            average_flow = 0.0; // Or some other default value
        }

        // Log flow rate
        log_flow_rate(average_flow);

        // Control alarm
        alarm_control(average_flow);

        // Sleep for 1 second
        sleep(SLEEP_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

