#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_MS 50

// Structure to hold sensor data and timestamp
typedef struct {
    time_t timestamp;
    int sensor_value;
} SensorData;

// Circular buffer
SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int sensor_value);
void print_buffer();
void signal_handler(int signal);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            time_t current_time = time(NULL);
            add_to_buffer(current_time, sensor_value);
            printf("Obstacle detected! Timestamp: %ld\n", current_time);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    return 0;
}

// Initialize pigpio and configure GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    return 0;
}

// Read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Add data to the circular buffer
void add_to_buffer(time_t timestamp, int sensor_value) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].sensor_value = sensor_value;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Obstacle Detection Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&circular_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Sensor Value: %d\n", timestamp_str, circular_buffer[index].sensor_value);
    }
    printf("--- Obstacle Detection Log ---\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nExiting program...\n");
    print_buffer();
    gpioTerminate();
    exit(0);
}

