#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_BUS 1
#define D7S_ADDR 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define X_LSB 0x2A
#define X_MSB 0x2B
#define Y_LSB 0x2C
#define Y_MSB 0x2D
#define Z_LSB 0x2E
#define Z_MSB 0x2F
#define SCALE_FACTOR 0.0009765625

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd;
    FILE *fp;
    time_t rawtime;
    struct tm *info;
    char timestamp[30];
    uint8_t x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;
    int16_t x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;
    int operating_status;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg(i2c_fd, MODE_CONTROL, 0x10) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Wait for sensor to become active
    int timeout = 1; // 1 second timeout
    while (timeout > 0) {
        if (i2c_read_reg(i2c_fd, OPERATING_STATUS, &operating_status) == 0) {
            if (operating_status & 0x01) {
                break; // Sensor active
            }
        } else {
            timeout--;
            usleep(100000); // 100ms
        }
    }

    if (operating_status != 0x01) {
        fprintf(stderr, "Error: Sensor did not become active within 1 second.\n");
        close(i2c_fd);
        return 1;
    }

    fp = fopen("fan_health.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening fan_health.csv: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }
    rewind(fp);

    while (program_running) {
        // Read sensor data
        if (i2c_read_block(i2c_fd, X_LSB, (uint8_t *)x_lsb, 2) != 0) {
            fprintf(stderr, "Error reading X data\n");
            continue; // Retry
        }
        if (i2c_read_block(i2c_fd, Y_LSB, (uint8_t *)y_lsb, 2) != 0) {
            fprintf(stderr, "Error reading Y data\n");
            continue; // Retry
        }
        if (i2c_read_block(i2c_fd, Z_LSB, (uint8_t *)z_lsb, 2) != 0) {
            fprintf(stderr, "Error reading Z data\n");
            continue; // Retry
        }

        x_raw = (int16_t)((x_msb << 8) | x_lsb);
        y_raw = (int16_t)((y_msb << 8) | y_lsb);
        z_raw = (int16_t)((z_msb << 8) | z_lsb);

        // Convert to g
        x_g = x_raw * SCALE_FACTOR;
        y_g = y_raw * SCALE_FACTOR;
        z_g = z_raw * SCALE_FACTOR;

        // Get timestamp
        time(&rawtime);
        info = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", info);

        // Log data to CSV file
        fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
        fflush(fp); // Ensure data is written to disk

        usleep(500000); // 500ms
    }

    fclose(fp);
    close(i2c_fd);

    return 0;
}

