    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }
    rewind(fp);

    while (program_running) {
        // Read sensor data
        if (i2c_read_block(i2c_fd, X_LSB, (uint8_t *)x_lsb, 2) != 0) {
            fprintf(stderr, "Error reading X data\n");
            continue; // Retry
        }
        if (i2c_read_block(i2c_fd, Y_LSB, (uint8_t *)y_lsb, 2) != 0) {
            fprintf(stderr, "Error reading Y data\n");
            continue; // Retry
        }
        if (i2c_read_block(i2c_fd, Z_LSB, (uint8_t *)z_lsb, 2) != 0) {
            fprintf(stderr, "Error reading Z data\n");
            continue; // Retry
        }

        x_raw = (int16_t)((x_msb << 8) | x_lsb);
        y_raw = (int16_t)((y_msb << 8) | y_lsb);
        z_raw = (int16_t)((z_msb << 8) | z_lsb);

        // Convert to g
        x_g = x_raw * SCALE_FACTOR;
        y_g = y_raw * SCALE_FACTOR;
        z_g = z_raw * SCALE_FACTOR;

        // Get timestamp
        time(&rawtime);
        info = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", info);

        // Log data to CSV file
        fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
        fflush(fp); // Ensure data is written to disk

        usleep(500000); // 500ms
    }

    fclose(fp);
    close(i2c_fd);

    return 0;
}

