    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read sensor values
int read_sensors(int sensor1_pin, int sensor2_pin) {
    int sensor1_value = gpioRead(sensor1_pin);
    int sensor2_value = gpioRead(sensor2_pin);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate error
    }

    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0; // Return 1 if either sensor detects an obstacle
}

