void control_led(int led_pin, int obstacle_detected) {
    if (obstacle_detected) {
        gpioWrite(led_pin, 1); // Turn LED ON
    } else {
        gpioWrite(led_pin, 0); // Turn LED OFF
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int obstacle_detected = read_sensors(SENSOR_1_PIN, SENSOR_2_PIN);

        if (obstacle_detected == 1) {
            control_led(LED_PIN, 1);
        } else {
            control_led(LED_PIN, 0);
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Obstacle avoidance system stopped.\n");

    return 0;
}

