#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the stall duration threshold (in seconds)
#define STALL_DURATION 2

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio);
int is_stalled(int sensor1_value, int sensor2_value);
int log_stall(const char *timestamp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to determine if a stall has occurred
int is_stalled(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log a stall event to a file
int log_stall(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    fprintf(fp, "%s\n", timestamp);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
        fclose(fp);
        return -1; // Indicate an error
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, exit the loop
            program_running = 0;
            break;
        }

        // Check for stall condition
        if (is_stalled(sensor1_value, sensor2_value)) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the stall event
            if (log_stall(timestamp) == 0) {
                printf("Stall detected and logged at %s\n", timestamp);
            } else {
                fprintf(stderr, "Failed to log stall event.\n");
            }

            // Wait for the specified duration
            gpioDelay(STALL_DURATION * 1000000); // Convert seconds to microseconds
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100000); // 100ms
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

