#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170-Q1 Register Addresses
#define TMAG5170_REG_DEVICE_ID 0x00
#define TMAG5170_REG_X_AXIS 0x01
#define TMAG5170_REG_Y_AXIS 0x03
#define TMAG5170_REG_Z_AXIS 0x05
#define TMAG5170_REG_CONFIG 0x06

// Configuration values
#define CONFIG_CONTINUOUS_CONVERSION 0x01
#define CONFIG_X_AXIS_EN 0x01
#define CONFIG_Y_AXIS_EN 0x02
#define CONFIG_Z_AXIS_EN 0x04
#define CONFIG_50MT_RANGE 0x00

// Scaling factor for 50 mT range (LSB/mT)
#define SCALE_FACTOR 0.005

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int verify_device_id();
int configure_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_millitesla(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0); // I2C bus 1, address 0x0E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Device ID verification function
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, TMAG5170_REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read device ID: %s\n", strerror(errno));
        return -1;
    }

    if (device_id != 0x8D) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x8D)\n", device_id);
        return -1;
    }

    return 0;
}

// Sensor configuration function
int configure_sensor() {
    int status = i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, CONFIG_CONTINUOUS_CONVERSION | CONFIG_X_AXIS_EN | CONFIG_Y_AXIS_EN | CONFIG_Z_AXIS_EN | CONFIG_50MT_RANGE);
    if (status < 0) {
        fprintf(stderr, "Failed to write to config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Sensor data reading function
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    int status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_X_AXIS);
    if (status < 0) {
        fprintf(stderr, "Failed to read X axis data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_Y_AXIS);
    if (status < 0) {
        fprintf(stderr, "Failed to read Y axis data: %s\n", strerror(errno));
        return -1;
    }
    *y = (int16_t)status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_Z_AXIS);
    if (status < 0) {
        fprintf(stderr, "Failed to read Z axis data: %s\n", strerror(errno));
        return -1;
    }
    *z = (int16_t)status;

    return 0;
}

// Data conversion function
float convert_to_millitesla(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Data logging function
int log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file and write header
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    int16_t x_raw, y_raw, z_raw;
    float x_mT, y_mT, z_mT;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to millitesla
            x_mT = convert_to_millitesla(x_raw);
            y_mT = convert_to_millitesla(y_raw);
            z_mT = convert_to_millitesla(z_raw);

            // Log data
            if (log_data(x_mT, y_mT, z_mT) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

