    status = i2cReadWordData(i2c_handle, TMAG5170_REG_X_AXIS);
    if (status < 0) {
        fprintf(stderr, "Failed to read X axis data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_Y_AXIS);
    if (status < 0) {
        fprintf(stderr, "Failed to read Y axis data: %s\n", strerror(errno));
        return -1;
    }
    *y = (int16_t)status;

    status = i2cReadWordData(i2c_handle, TMAG5170_REG_Z_AXIS);
    if (status < 0) {
        fprintf(stderr, "Failed to read Z axis data: %s\n", strerror(errno));
        return -1;
    }
    *z = (int16_t)status;

    return 0;
}

// Data conversion function
float convert_to_millitesla(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Data logging function
int log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file and write header
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    int16_t x_raw, y_raw, z_raw;
    float x_mT, y_mT, z_mT;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to millitesla
            x_mT = convert_to_millitesla(x_raw);
            y_mT = convert_to_millitesla(y_raw);
            z_mT = convert_to_millitesla(z_raw);

            // Log data
            if (log_data(x_mT, y_mT, z_mT) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

