#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_WINDOW_MS 1000
#define DEBOUNCE_MS 5

static volatile int pulse_count = 0;
static volatile int running = 1;

// Function to handle rising edge interrupts
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user; // unused
    pulse_count++;
}

// Function to calculate RPM
double calculate_rpm(int pulses)
{
    return (double)pulses / SAMPLE_WINDOW_MS * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, rpm);
    fclose(fp);
}

// Signal handler for clean shutdown
void signal_handler(int signal)
{
    (void)signal; // unused
    running = 0;
    printf("Caught signal, exiting gracefully...\n");
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt callback
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0)
    {
        fprintf(stderr, "Error setting up interrupt callback\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running)
    {
        // Disable interrupt callback temporarily
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

        // Calculate RPM
        double rpm = calculate_rpm(pulse_count);

        // Log RPM
        log_rpm(rpm);

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count
        pulse_count = 0;

        // Re-enable interrupt callback
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL);

        // Wait for 1 second
        gpioDelay(SAMPLE_WINDOW_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    gpioTerminate();
    return 0;
}

