#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

// Mutex to protect shared state
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure to hold sensor state
typedef struct {
    int sensor_a_state;
    int sensor_b_state;
    char current_direction[10];
} sensor_state_t;

// Global sensor state
sensor_state_t sensor_state = {0, 0, ""};

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void *rotation_detection_thread(void *arg);
void log_rotation(const char *direction);
void signal_handler(int signal);

// Function to get current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + 19, 11, ".%03ldZ", ts.tv_nsec / 1000000);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create thread for rotation detection
    pthread_t rotation_thread;
    if (pthread_create(&rotation_thread, NULL, rotation_detection_thread, NULL) != 0) {
        perror("Failed to create rotation detection thread");
        gpioTerminate();
        return 1;
    }

    // Main loop (wait for signal)
    while (1) {
        pthread_join(rotation_thread, NULL);
        sleep(1); // Sleep to avoid busy-spinning
    }

    return 0;
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&state_mutex);
    if (level == 0) { // Falling edge
        sensor_state.sensor_a_state = 1;
    } else {
        sensor_state.sensor_a_state = 0;
    }
    pthread_mutex_unlock(&state_mutex);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&state_mutex);
    if (level == 0) { // Falling edge
        sensor_state.sensor_b_state = 1;
    } else {
        sensor_state.sensor_b_state = 0;
    }
    pthread_mutex_unlock(&state_mutex);
}

// Thread function for rotation detection
void *rotation_detection_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning

    // Main loop
    while (1) {
        pthread_mutex_lock(&state_mutex);
        int sensor_a_state = sensor_state.sensor_a_state;
        int sensor_b_state = sensor_state.sensor_b_state;
        pthread_mutex_unlock(&state_mutex);

        // Determine direction based on sensor states
        if (sensor_a_state && !sensor_b_state) {
            // Sensor A is high, Sensor B is low
            if (sensor_state.current_direction[0] == '\0') {
                // First edge, determine direction
                if (sensor_a_state == 1) {
                    strcpy(sensor_state.current_direction, "CW");
                } else {
                    strcpy(sensor_state.current_direction, "CCW");
                }
            }
        } else if (!sensor_a_state && sensor_b_state) {
            // Sensor A is low, Sensor B is high
            if (sensor_state.current_direction[0] == '\0') {
                // First edge, determine direction
                if (sensor_a_state == 0) {
                    strcpy(sensor_state.current_direction, "CW");
                } else {
                    strcpy(sensor_state.current_direction, "CCW");
                }
            }
        }

        // Log rotation event
        if (sensor_state.current_direction[0] != '\0') {
            char timestamp[30];
            get_iso8601_timestamp(timestamp);
            log_rotation(sensor_state.current_direction);
            sensor_state.current_direction[0] = '\0'; // Clear direction after logging
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return NULL;
}

// Function to log rotation event to file
void log_rotation(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[30];
    get_iso8601_timestamp(timestamp);
    fprintf(fp, "%s: %s\n", timestamp, direction);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);

    // Flush log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fclose(fp);
    }

    // Destroy mutex
    pthread_mutex_destroy(&state_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

