                    strcpy(sensor_state.current_direction, "CW");
                } else {
                    strcpy(sensor_state.current_direction, "CCW");
                }
            }
        }

        // Log rotation event
        if (sensor_state.current_direction[0] != '\0') {
            char timestamp[30];
            get_iso8601_timestamp(timestamp);
            log_rotation(sensor_state.current_direction);
            sensor_state.current_direction[0] = '\0'; // Clear direction after logging
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return NULL;
}

// Function to log rotation event to file
void log_rotation(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[30];
    get_iso8601_timestamp(timestamp);
    fprintf(fp, "%s: %s\n", timestamp, direction);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);

    // Flush log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fclose(fp);
    }

    // Destroy mutex
    pthread_mutex_destroy(&state_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

