#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 200

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int request_line(int gpio, int mode);
int read_line(int gpio);
int write_line(int gpio, int value);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to request a GPIO line
int request_line(int gpio, int mode) {
    int handle = gpioLine(gpio, mode);
    if (handle < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d line mode %d", gpio, mode);
        return -1;
    }
    return handle;
}

// Function to read a GPIO line
int read_line(int gpio) {
    return gpioRead(gpio);
}

// Function to write a value to a GPIO line
int write_line(int gpio, int value) {
    gpioWrite(gpio, value);
    return 0; // pigpio's write function doesn't return anything, so always return 0
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
}

int main() {
    // Open system log
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Touch sensor application started");

    // Main loop
    while (program_running) {
        int touch_detected = read_line(TOUCH_SENSOR_PIN);

        if (touch_detected == 1) {
            syslog(LOG_INFO, "Touch detected on GPIO %d", TOUCH_SENSOR_PIN);
            write_line(LED_PIN, 1); // Turn on LED
        } else {
            write_line(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    syslog(LOG_INFO, "Touch sensor application stopped");
    closelog();

    return 0;
}

