#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initialize LED to LOW

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED
void toggle_led() {
    gpioWrite(LED_PIN, !gpioRead(LED_PIN));
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            toggle_led();
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "GPIO resources released. Exiting.\n");

    return 0;
}

