#define LED_2_GPIO 22
#define BUFFER_SIZE 100
#define DEBOUNCE_DELAY_MS 50

// Structure to hold sensor data
typedef struct {
    int pin;
    int led_pin;
    int state;
    int last_state;
    int timestamp;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} circular_buffer_t;

circular_buffer_t log_buffer;

// Function prototypes
