void set_sensor_mode(int gpio, int mode);
void set_led_mode(int gpio, int mode);
void set_sensor_pin(int gpio, int pin);
void set_led_pin(int gpio, int pin);
void set_sensor_state(int gpio, int state);
void set_led_state(int gpio, int state);
int read_sensor(int gpio);
void add_to_buffer(circular_buffer_t *buffer, int pin, int state);
void print_log_buffer(circular_buffer_t *buffer);
void signal_handler(int signal);

