    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize circular buffer
    log_buffer.head = 0;
    log_buffer.tail = 0;
    log_buffer.count = 0;
    log_buffer.overflow_count = 0;

    // Main loop
    while (1) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Update LED states based on sensor states
        set_led_state(LED_1_GPIO, sensor1_state);
