#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define LED_1_GPIO 27
#define LED_2_GPIO 22
#define BUFFER_SIZE 100
#define DEBOUNCE_DELAY_MS 50

// Structure to hold sensor data
typedef struct {
    int pin;
    int led_pin;
    int state;
    int last_state;
    int timestamp;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} circular_buffer_t;

circular_buffer_t log_buffer;

// Function prototypes
int initialize_gpio();
void set_sensor_mode(int gpio, int mode);
void set_led_mode(int gpio, int mode);
void set_sensor_pin(int gpio, int pin);
void set_led_pin(int gpio, int pin);
void set_sensor_state(int gpio, int state);
void set_led_state(int gpio, int state);
int read_sensor(int gpio);
void add_to_buffer(circular_buffer_t *buffer, int pin, int state);
void print_log_buffer(circular_buffer_t *buffer);
void signal_handler(int signal);

int main() {
    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize circular buffer
    log_buffer.head = 0;
    log_buffer.tail = 0;
    log_buffer.count = 0;
    log_buffer.overflow_count = 0;

    // Main loop
    while (1) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Update LED states based on sensor states
        set_led_state(LED_1_GPIO, sensor1_state);
        set_led_state(LED_2_GPIO, sensor2_state);

        // Add events to the circular buffer
        add_to_buffer(&log_buffer, SENSOR_1_GPIO, sensor1_state);
        add_to_buffer(&log_buffer, SENSOR_2_GPIO, sensor2_state);

        // Delay for debouncing
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    return 0;
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Set GPIO mode (input or output)
void set_sensor_mode(int gpio, int mode) {
    gpioSetMode(gpio, PI_INPUT);
}

// Set LED mode (output)
void set_led_mode(int gpio, int mode) {
    gpioSetMode(gpio, PI_OUTPUT);
}

// Set sensor pin
void set_sensor_pin(int gpio, int pin) {
    gpioSetPullUpDown(gpio, PI_PUD_DOWN); // Use pull-down resistor
}

// Set LED pin
void set_led_pin(int gpio, int pin) {
    gpioSetMode(gpio, PI_OUTPUT);
}

// Set sensor state (0 or 1)
void set_sensor_state(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Set LED state (0 or 1)
void set_led_state(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Read sensor state
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Add event to the circular buffer
