// Si1182 I2C address
#define SI1182_ADDR 0x28

// Si1182 register addresses
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HR_REG 0x02
#define SPO2_REG 0x04

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the Si1182 sensor
int init_si1182() {
    // Verify sensor presence
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect PART_ID value: 0x%02X\n", part_id);
        return -1;
    }

    // Configure the sensor for continuous measurement
    int config_value = 0x07; // Example configuration value
    int write_result = i2cWriteByteData(i2c_handle, CONFIG_REG, config_value);
    if (write_result < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", write_result);
        return -1;
    }

    return 0;
}

// Function to read heart rate data from the sensor
int read_heart_rate() {
    int hr_value = i2cReadByteData(i2c_handle, HR_REG);
    if (hr_value < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", hr_value);
        return -1;
    }
    return hr_value;
}

// Function to read SpO2 data from the sensor
int read_spo2() {
    int spo2_value = i2cReadByteData(i2c_handle, SPO2_REG);
    if (spo2_value < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", spo2_value);
        return -1;
    }
    return spo2_value;
}

// Function to log data to a file
void log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1182() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int heart_rate = read_heart_rate();
        int spo2 = read_spo2();

        // Log the data
        if (heart_rate >= 0 && spo2 >= 0) {
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

