static volatile int running = 1;
static FILE *log_file = NULL;
static int alarm_active = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type, int sensor_number);
int activate_alarm();
int deactivate_alarm();
int check_tilt_status(int sensor1_state, int sensor2_state);
void generate_iso8601_timestamp(char *timestamp);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Log event to file
int log_event(const char *event_type, int sensor_number) {
    char timestamp[32];
    generate_iso8601_timestamp(timestamp);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }

    fprintf(log_file, "%s - %s - Sensor %d\n", timestamp, event_type, sensor_number);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Activate alarm (set GPIO HIGH)
int activate_alarm() {
    if (alarm_active) return 0; // Already active, do nothing
    gpioWrite(ALARM_PIN, 1);
    alarm_active = 1;
    return 0;
}

// Deactivate alarm (set GPIO LOW)
int deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
    alarm_active = 0;
    return 0;
}

// Check tilt status and log events
int check_tilt_status(int sensor1_state, int sensor2_state) {
    static int sensor1_tilted = 0;
    static int sensor2_tilted = 0;
    static time_t sensor1_start_time = 0;
    static time_t sensor2_start_time = 0;
    time_t current_time = time(NULL);

    if (sensor1_state == 1 && sensor2_state == 1) {
        // Both sensors are tilted
        if (!sensor1_tilted) {
            if (log_event("Tilt Start", 1) != 0) {
                fprintf(stderr, "Error logging tilt start event for sensor 1.\n");
            }
            if (log_event("Tilt Start", 2) != 0) {
                fprintf(stderr, "Error logging tilt start event for sensor 2.\n");
            }
            sensor1_tilted = 1;
            sensor2_tilted = 1;
            sensor1_start_time = current_time;
            sensor2_start_time = current_time;
        } else {
            // Both sensors have been tilted for the duration
            if (log_event("Threshold Exceeded", 1) != 0) {
                fprintf(stderr, "Error logging threshold exceeded event for sensor 1.\n");
            }
            if (log_event("Threshold Exceeded", 2) != 0) {
                fprintf(stderr, "Error logging threshold exceeded event for sensor 2.\n");
            }
            activate_alarm();
            gpioDelay(ALARM_DURATION * 1000); // Delay for alarm duration
            deactivate_alarm();
            sensor1_tilted = 0;
            sensor2_tilted = 0;
        }
    } else if (sensor1_state == 0 && sensor2_state == 0) {
        // Both sensors are no longer tilted
        if (sensor1_tilted) {
            if (log_event("Tilt End", 1) != 0) {
                fprintf(stderr, "Error logging tilt end event for sensor 1.\n");
            }
            if (log_event("Tilt End", 2) != 0) {
                fprintf(stderr, "Error logging tilt end event for sensor 2.\n");
            }
            sensor1_tilted = 0;
            sensor2_tilted = 0;
        }
    } else if (sensor1_state == 1 && sensor2_state == 0) {
        // Sensor 1 is tilted, but sensor 2 is not
        if (log_event("Sensor 1 Tilted", 1) != 0) {
            fprintf(stderr, "Error logging sensor 1 tilted event.\n");
        }
    } else if (sensor1_state == 0 && sensor2_state == 1) {
        // Sensor 2 is tilted, but sensor 1 is not
        if (log_event("Sensor 2 Tilted", 2) != 0) {
            fprintf(stderr, "Error logging sensor 2 tilted event.\n");
        }
    }

    return 0;
}

// Generate ISO-8601 timestamp
void generate_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_state = read_sensor(SENSOR_1_PIN);
        int sensor2_state = read_sensor(SENSOR_2_PIN);

        if (sensor1_state == PI_HIGH || sensor2_state == PI_HIGH) {
            check_tilt_status(sensor1_state, sensor2_state);
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

