#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x1F
#define CTRL2_REG 0x20
#define ACCEL_X_LSB 0x28
#define ACCEL_X_MSB 0x29
#define ACCEL_Y_LSB 0x2A
#define ACCEL_Y_MSB 0x2B
#define ACCEL_Z_LSB 0x2C
#define ACCEL_Z_MSB 0x2D
#define LED_GPIO 17
#define THRESHOLD 500.0f
#define LED_ON_TIME 1.0f
#define LED_OFF_TIME 0.0f
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Function prototypes
int init_d7s();
int read_accel_data(AccelData *data);
float calculate_magnitude(AccelData data);
int check_threshold(float magnitude);
void control_led(int on);
void log_event(float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the D7S sensor
int init_d7s() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        // Verify sensor presence by reading CTRL1 register
        char buf[1];
        buf[0] = CTRL1_REG;
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to CTRL1 register during initialization.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error reading CTRL1 register during initialization.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (buf[0] & 0x01) {
            fprintf(stderr, "Sensor not detected (CTRL1 register value: 0x%02X).\n", buf[0]);
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Clear power-down bit
        buf[0] = 0x01; // Set bit 0 to 1 to clear power-down
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error clearing power-down bit during initialization.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error reading after clearing power-down bit during initialization.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        printf("D7S sensor initialized successfully.\n");
        return 0; // Initialization successful
    }

    fprintf(stderr, "D7S sensor initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Read accelerometer data from the D7S sensor
int read_accel_data(AccelData *data) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        char buf[1];
        char read_buf[6];

        // Set register address for X, Y, and Z LSB
        buf[0] = ACCEL_X_LSB;
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to register address for X, Y, and Z LSB.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (i2cReadDevice(i2c_handle, read_buf, 6) != 0) {
            fprintf(stderr, "Error reading accelerometer data.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Combine LSB and MSB for each axis
        int16_t x = (read_buf[1] << 8) | read_buf[0];
        int16_t y = (read_buf[3] << 8) | read_buf[2];
        int16_t z = (read_buf[5] << 8) | read_buf[4];

        // Convert to g-force units (assuming 1g = 9.81 m/s^2)
        data->x = (float)x / 32768.0f * 9.81f; // 32768 is 2^15
        data->y = (float)y / 32768.0f * 9.81f;
        data->z = (float)z / 32768.0f * 9.81f;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read accelerometer data after multiple retries.\n");
    return -1; // Failure
}

// Calculate the Euclidean magnitude of the acceleration vector
float calculate_magnitude(AccelData data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Check if the magnitude exceeds the threshold
int check_threshold(float magnitude) {
    return (magnitude > THRESHOLD) ? 1 : 0;
}

// Control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log the event to a file
void log_event(float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s, Peak Vibration: %.2f g\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the D7S sensor
    if (init_d7s() != 0) {
        fprintf(stderr, "D7S sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    AccelData accel_data;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accel_data(&accel_data) == 0) {
            // Calculate magnitude
            float magnitude = calculate_magnitude(accel_data);

            // Check threshold
            if (check_threshold(magnitude)) {
                printf("Threshold exceeded! Magnitude: %.2f g\n", magnitude);

                // Control LED
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME * 1000000); // Wait for LED_ON_TIME seconds
                control_led(0); // Turn off LED

                // Log event
                log_event(magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

