#define SENSOR_4_PIN 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input or output
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);
    gpioSetMode(SENSOR_4_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Read sensor data
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);
        int sensor3_value = read_sensor(SENSOR_3_PIN);
        int sensor4_value = read_sensor(SENSOR_4_PIN);

        // Control LED based on sensor readings
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
            control_led(LED_PIN, 1); // Turn LED ON
        } else {
            control_led(LED_PIN, 0); // Turn LED OFF
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

