        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

