#define SENSOR3_PIN 4
#define SENSOR4_PIN 17
#define SENSOR5_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[5] = {NULL, NULL, NULL, NULL, NULL};
static int num_lines = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(int pin);
int log_event(int pin);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, exiting...");
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    num_lines = 5; // Number of sensor lines

    sensor_lines[0] = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor_lines[0]) {
        syslog(LOG_ERR, "Failed to get line for sensor 1");
        cleanup();
        return -1;
    }

    sensor_lines[1] = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor_lines[1]) {
        syslog(LOG_ERR, "Failed to get line for sensor 2");
        cleanup();
        return -1;
    }

    sensor_lines[2] = gpiod_chip_get_line(chip, SENSOR3_PIN);
    if (!sensor_lines[2]) {
        syslog(LOG_ERR, "Failed to get line for sensor 3");
        cleanup();
        return -1;
    }

    sensor_lines[3] = gpiod_chip_get_line(chip, SENSOR4_PIN);
    if (!sensor_lines[3]) {
        syslog(LOG_ERR, "Failed to get line for sensor 4");
        cleanup();
        return -1;
    }

    sensor_lines[4] = gpiod_chip_get_line(chip, SENSOR5_PIN);
    if (!sensor_lines[4]) {
        syslog(LOG_ERR, "Failed to get line for sensor 5");
        cleanup();
        return -1;
    }

    // Request lines for input
    for (int i = 0; i < num_lines; i++) {
        if (!gpiod_line_request(sensor_lines[i], "flame_monitor", GPIOD_LINE_REQUEST_DIRECTION_INPUT)) {
