        return -1;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", buf, pin, pin);
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");
    for (int i = 0; i < num_lines; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    exit(0);
}

int main(void) {
    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Flame sensor monitoring started");

    // Main loop
    while (program_running) {
        for (int i = 0; i < num_lines; i++) {
            int value = read_sensor(i + 1);
            if (value < 0) {
                syslog(LOG_ERR, "Error reading sensor %d, retrying...", i + 1);
                continue; // Skip to the next sensor
            }

            if (value == 0) { // Flame detected (LOW signal)
                if (log_event(i + 1) != 0) {
                    syslog(LOG_ERR, "Error logging event for sensor %d", i + 1);
                }
                usleep(DEBOUNCE_TIME_MS * 1000); // Debounce
            }
        }
        sleep(1); // Poll every second
    }

    cleanup();
    return 0;
}

