#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define NUM_CHANNELS 8

// Define the number of milliseconds to poll
#define POLL_INTERVAL_MS 50

// Global variables for GPIO lines
struct gpiod_line *lines[8];
struct gpiod_chip *chip;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize a GPIO line
int init_gpio_line(int channel, int pin)
{
    char line_name[20];
    snprintf(line_name, sizeof(line_name), "gpio%d-%d", channel, pin);

    struct gpiod_line *line = gpiod_chip_open_by_name(chip, line_name);
    if (line == NULL) {
        fprintf(stderr, "Error opening line %s: %s\n", line_name, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(line, "touch_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting line %s: %s\n", line_name, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return line;
}

// Function to read the state of a single channel
int read_channel(int channel, int pin)
{
    struct gpiod_line *line = lines[channel];
    if (line == NULL) {
        fprintf(stderr, "Error: Line for channel %d not initialized.\n", channel);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    return value;
}

// Function to log a touch event
void log_touch_event(int channel, int pin, int state)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    printf("%s - Channel %d (Pin %d): %s\n", timestamp, channel, pin, state ? "Touched" : "Released");
}

int main()
{
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Initialize GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = init_gpio_line(i, i + 5); // Pin numbers start at 5
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to initialize line %d, exiting.\n", i);
            // Attempt to release any previously initialized lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = read_channel(i, i + 5);
            if (state < 0) {
                fprintf(stderr, "Error reading channel %d, exiting.\n", i);
                // Attempt to release any previously initialized lines
                for (int j = 0; j < i; j++) {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }

            if (state != read_channel(i, i + 5)) { // Check if the state has changed
                log_touch_event(i, i + 5, state);
            }
        }

        // Wait for the next poll interval
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);
    }

    // This point should not be reached due to the infinite loop, but included for completeness
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

