#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_GAIN 0x00
#define ALS_INTEGRATION_TIME 0x00
#define ALS_CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_LOW 100
#define LUX_THRESHOLD_MED 500
#define LUX_THRESHOLD_HIGH 1000
#define LUX_THRESHOLD_HIGH2 1000
#define LUX_THRESHOLD_HIGH3 2000
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_veml7700();
int read_als_data(uint16_t *als_data);
float calculate_lux(uint16_t als_data);
int set_led_brightness(int brightness);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure VEML7700 sensor
int config_veml7700() {
    uint16_t config_value = (ALS_GAIN << 11) | (ALS_INTEGRATION_TIME << 6);
    char buf[3];
    buf[0] = ALS_CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // High byte
    buf[2] = config_value & 0xFF;       // Low byte

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write config to VEML7700: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read ambient light data from VEML7700
int read_als_data(uint16_t *als_data) {
    char buf[1];
    buf[0] = ALS_DATA_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ALS_DATA_REG: %s\n", strerror(errno));
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
        return -1;
    }

    *als_data = (read_buf[1] << 8) | read_buf[0];
    return 0;
}

// Calculate lux value from raw ALS data
float calculate_lux(uint16_t als_data) {
    return als_data * 0.0576;
}

// Set LED brightness using hardware PWM
int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;

    gpioPWM(LED_GPIO, brightness);
    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    set_led_brightness(0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (config_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint16_t als_data;
    float lux;
    int brightness;

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ALS data
        if (read_als_data(&als_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(als_data);

            // Adaptive brightness control
            if (lux < LUX_THRESHOLD_LOW) {
                brightness = 100;
            } else if (lux < LUX_THRESHOLD_MED) {
                brightness = 75;
            } else if (lux < LUX_THRESHOLD_HIGH) {
                brightness = 50;
            } else if (lux < LUX_THRESHOLD_HIGH2) {
                brightness = 25;
            } else {
                brightness = 0;
            }

            // Set LED brightness
            set_led_brightness(brightness);

            // Log data
            log_data(lux, brightness, 0);
        } else {
            log_data(0.0, 0, -1); // Log error
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

