#define TOUCH_PIN_3 4
#define TOUCH_PIN_4 5
#define TOUCH_PIN_5 6
#define TOUCH_PIN_6 7
#define TOUCH_PIN_7 8
#define TOUCH_PIN_8 9
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile int last_touch_time[8] = {0}; // Array to store last touch time for each channel
static volatile int all_released = 1; // Flag to indicate if all channels are released

// Function prototypes
int initialize_gpio();
int read_touch_channel(int gpio_pin);
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signal);
        control_led(0); // Turn off LED
        gpioTerminate(); // Release pigpio resources
        running = 0; // Stop the main loop
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

