    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel);
    fclose(fp);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
