    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int any_touched = 0;
        for (int i = 1; i <= 8; i++) {
            int touch_state = read_touch_channel(i);
            if (touch_state == 1) {
                any_touched = 1;
                last_touch_time[i - 1] = time(NULL); // Update last touch time
            } else {
                last_touch_time[i - 1] = 0; // Reset last touch time if released
            }
        }

        // Check if all channels are released
        if (any_touched && all_released) {
            control_led(1); // Turn on LED
        } else if (!any_touched && all_released) {
            control_led(0); // Turn off LED
        }

        all_released = 0; // Reset the flag if any channel is touched

        // Debounce and log touch events
        for (int i = 1; i <= 8; i++) {
            if (last_touch_time[i - 1] != 0 && (time(NULL) - last_touch_time[i - 1]) * 1000 >= DEBOUNCE_TIME) {
                log_touch_event(i);
                last_touch_time[i - 1] = time(NULL); // Reset last touch time after logging
            }
        }

        gpioDelay(50); // Wait 50 ms
    }

    return 0;
}

