#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int configure_opt3001(int handle);
int read_opt3001(int handle, unsigned int *exponent, unsigned int *mantissa);
float calculate_lux(unsigned int exponent, unsigned int mantissa);
int log_data(float lux_value);
void print_lux(float lux_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to configure the OPT3001 sensor
int configure_opt3001(int handle) {
    int result = i2cWriteWordData(handle, CONFIG_REG, (CONFIG_WORD >> 8) & 0xFF); // MSB
    if (result < 0) {
        fprintf(stderr, "Failed to write MSB to config register: %d\n", result);
        return -1;
    }
    result = i2cWriteWordData(handle, CONFIG_REG + 1, CONFIG_WORD & 0xFF); // LSB
    if (result < 0) {
        fprintf(stderr, "Failed to write LSB to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the result register from the OPT3001
int read_opt3001(int handle, unsigned int *exponent, unsigned int *mantissa) {
    int result = i2cReadWordData(handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read result register: %d\n", result);
        return -1;
    }

    // Byte-swap the 16-bit values
    *exponent = (result >> 12) & 0x0FFF; // Exponent (bits 15-12)
    *mantissa = (result >> 4) & 0x0FFF;   // Mantissa (bits 11-0)

    return 0;
}

// Function to calculate lux value
float calculate_lux(unsigned int exponent, unsigned int mantissa) {
    return mantissa * 0.01 * (2.0 * pow(2.0, exponent));
}

// Function to log data to a file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, lux_value);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to print lux value to stdout
void print_lux(float lux_value) {
    printf("Lux: %.2f\n", lux_value);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, OPT3001_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned int exponent, mantissa;
    float lux_value;
    int read_result;

    // Main loop
    while (!terminate) {
        // Wait for conversion to complete (at least 100ms)
        gpioDelay(100000); // 100 ms

        // Read result register
        read_result = read_opt3001(i2c_handle, &exponent, &mantissa);
        if (read_result == 0) {
            // Calculate lux value
            lux_value = calculate_lux(exponent, mantissa);

            // Log data
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Print lux value
            print_lux(lux_value);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

