    float lux_value;
    int read_result;

    // Main loop
    while (!terminate) {
        // Wait for conversion to complete (at least 100ms)
        gpioDelay(100000); // 100 ms

        // Read result register
        read_result = read_opt3001(i2c_handle, &exponent, &mantissa);
        if (read_result == 0) {
            // Calculate lux value
            lux_value = calculate_lux(exponent, mantissa);

            // Log data
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Print lux value
            print_lux(lux_value);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

