#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to log a touch event to the file
void log_touch_event(const char *event_type) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for log entry.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
    free(timestamp);
}

// Function to handle touch events
void handle_touch_event(int event) {
    if (event == 0) { // Touch detected (LOW signal)
        log_touch_event("Detected");
    } else if (event == 1) { // Touch released (HIGH signal)
        log_touch_event("Released");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to release GPIO resources
void release_resources() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int ret;
    struct gpiod_line_event event;
    struct timespec debounce_delay = {0, DEBOUNCE_MS * 1000000L}; // 50ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        release_resources();
        return 1;
    }

    // Request GPIO line for input
    ret = gpiod_line_request_input(line, "touch_sensor", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for input");
        release_resources();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        release_resources();
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        ret = gpiod_line_event_read(line, &event, 1);
        if (ret < 0) {
            perror("Failed to read GPIO line event");
            release_resources();
            return 1;
        }

        if (ret > 0) {
            handle_touch_event(event.value);
        }

        nanosleep(&debounce_delay, NULL);
    }

    // Release resources before exiting
    release_resources();
    fprintf(stderr, "Touch sensor monitoring stopped.\n");
    return 0;
}

