#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define COMMAND 0x3608
#define SAMPLE_INTERVAL_MS 1000
#define RAW_TO_ML_PER_UNIT 90.0
#define MIN_FLOW 0.0
#define MAX_FLOW 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
    float flow_rate;
    char status[20];
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, sensor_data_t *data);
float convert_raw_to_ml(int16_t raw_flow);
void log_data(FILE *fp, float flow_rate, const char *status);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[4];
    int result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    data->raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    data->crc = buf[3];

    return 0;
}

// Convert raw flow data to ml/min
float convert_raw_to_ml(int16_t raw_flow) {
    return (float)raw_flow / RAW_TO_ML_PER_UNIT;
}

// Log data to file
void log_data(FILE *fp, float flow_rate, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(fp); // Ensure data is written immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Send start measurement command
    if (send_command(i2c_handle, COMMAND) != 0) {
        cleanup();
        return 1;
    }

    // Wait for at least 2 ms
    gpioDelay(2000); // 2 ms

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Validate CRC
            uint8_t crc_calculated = 0;
            for (int i = 0; i < 15; i++) {
                crc_calculated ^= sensor_data.raw_flow[i];
                crc_calculated = crc_calculated & 0x01;
                if (crc_calculated) {
                    crc_calculated = 0xFF;
                }
                crc_calculated = (crc_calculated << 1) | 0x31;
            }

            if (crc_calculated != sensor_data.crc) {
                strcpy(sensor_data.status, "CRC_ERROR");
                log_data(log_file, 0.0, sensor_data.status);
            } else {
                // Convert raw data to ml/min
                sensor_data.flow_rate = convert_raw_to_ml(sensor_data.raw_flow);

                // Validate flow rate
                if (sensor_data.flow_rate < MIN_FLOW || sensor_data.flow_rate > MAX_FLOW) {
                    strcpy(sensor_data.status, "INVALID");
                    log_data(log_file, sensor_data.flow_rate, sensor_data.status);
                } else {
                    strcpy(sensor_data.status, "OK");
                    log_data(log_file, sensor_data.flow_rate, sensor_data.status);
                }
            }
        } else {
            // Attempt recovery by re-initializing I2C
            fprintf(stderr, "I2C read failed, attempting recovery...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C recovery failed, exiting...\n");
                terminate = 1; // Exit loop if recovery fails
            } else {
                // Send start measurement command again
                if (send_command(i2c_handle, COMMAND) != 0) {
                    fprintf(stderr, "I2C recovery failed, sending command again...\n");
                    i2cClose(i2c_handle);
                    if (initialize_i2c() != 0) {
                        fprintf(stderr, "I2C recovery failed, exiting...\n");
                        terminate = 1; // Exit loop if recovery fails
                    } else {
                        // Wait for at least 2 ms
                        gpioDelay(2000); // 2 ms
                    }
                }
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

