// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define I2C address for BH1750 light sensor
#define BH1750_I2C_ADDR 0x23

// Define I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static FILE *log_file = NULL;
static int i2c_fd = -1;
static bool running = true;

// Function prototypes
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **left, struct gpiod_line **middle, struct gpiod_line **right);
int init_i2c(int *fd);
int read_sensor(struct gpiod_line *line);
int read_bh1750(int fd);
int log_data(FILE *fp, int left, int middle, int right, int light_level);
void signal_handler(int sig);
void cleanup();

// Function to initialize GPIO lines
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **left, struct gpiod_line **middle, struct gpiod_line **right) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *left = gpiod_chip_get_line(*chip, LEFT_SENSOR_PIN);
    if (!*left) {
        perror("Error getting left sensor line");
        gpiod_chip_close(*chip);
        return -1;
    }

    *middle = gpiod_chip_get_line(*chip, MIDDLE_SENSOR_PIN);
    if (!*middle) {
        perror("Error getting middle sensor line");
        gpiod_chip_close(*chip);
        gpiod_line_release(*left);
        return -1;
    }

    *right = gpiod_chip_get_line(*chip, RIGHT_SENSOR_PIN);
    if (!*right) {
        perror("Error getting right sensor line");
        gpiod_chip_close(*chip);
        gpiod_line_release(*left);
        gpiod_line_release(*middle);
        return -1;
    }

    if (gpiod_line_request_input(*left, "left_sensor") < 0) {
        perror("Error requesting left sensor line as input");
        gpiod_chip_close(*chip);
        gpiod_line_release(*left);
        gpiod_line_release(*middle);
        gpiod_line_release(*right);
        return -1;
    }

    if (gpiod_line_request_input(*middle, "middle_sensor") < 0) {
        perror("Error requesting middle sensor line as input");
        gpiod_chip_close(*chip);
        gpiod_line_release(*left);
        gpiod_line_release(*middle);
        gpiod_line_release(*right);
        return -1;
    }

    if (gpiod_line_request_input(*right, "right_sensor") < 0) {
        perror("Error requesting right sensor line as input");
        gpiod_chip_close(*chip);
        gpiod_line_release(*left);
        gpiod_line_release(*middle);
        gpiod_line_release(*right);
        return -1;
    }

    return 0;
}

// Function to initialize I2C
int init_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(*fd);
        return -1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Function to read BH1750 light sensor
int read_bh1750(int fd) {
    unsigned char buf[2];
    int light_level = -1;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    usleep(200000); // 200ms

    // Read two bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert the data to lux value
    light_level = (buf[0] << 8) | buf[1];
    return light_level;
}

// Function to log data to CSV file
int log_data(FILE *fp, int left, int middle, int right, int light_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

