void cleanup() {
    printf("Cleaning up...\n");

    if (log_file) {
        fclose(log_file);
    }

    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

