    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right,light_level\n");
    }
    rewind(log_file);

    // Main loop
    while (running) {
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);
        int light_level = read_bh1750(i2c_fd);

        if (left_value == -1 || middle_value == -1 || right_value == -1 || light_level == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        if (log_data(log_file, left_value, middle_value, right_value, light_level) != 0) {
            fprintf(stderr, "Error logging data. Retrying.\n");
