#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DEBOUNCE_DELAY_MS 50

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp as a string
char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a flame event to a file
int log_flame_event(const char *timestamp)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s - Flame detected\n", timestamp);
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to print an alert message to stdout
void print_alert(const char *timestamp)
{
    printf("ALERT: Flame detected at %s\n", timestamp);
}

// Function to request the GPIO line for input
int request_gpio_line()
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to release the GPIO line
void release_gpio_line()
{
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
}

// Function to initialize the GPIO chip
int init_gpio_chip()
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }
    return 0;
}

// Function to initialize the GPIO line
int init_gpio_line()
{
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, GPIO_CHIP);
        return -1;
    }
    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    if (init_gpio_chip() < 0) {
        return 1;
    }

    // Initialize GPIO line
    if (init_gpio_line() < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for input
    if (request_gpio_line() < 0) {
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Open log file
    log_file = fopen("flame_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state = 1; // Assume no flame initially
    struct timespec debounce_delay = {0, DEBOUNCE_DELAY_MS * 1000000L}; // 50ms

    while (keep_running) {
        int current_state = gpiod_line_get_value(line);

        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            break;
        }

        if (current_state == 0 && last_state == 1) {
            // Flame detected (active-low)
            char *timestamp = get_timestamp();
            print_alert(timestamp);
            log_flame_event(timestamp);

            // Debounce delay
            nanosleep(&debounce_delay, NULL);
        }

        last_state = current_state;
        usleep(1000); // Check every 1ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    release_gpio_line();
    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

