#define TOUCH_PIN 23
#define LED_PIN 24

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the touch event to a file
int log_touch_event(const char *timestamp, int led_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, LED State: %d\n", timestamp, led_state);
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to handle the touch event
void handle_touch_event() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return;
    }

    int led_state = (led_line->current_value == 1) ? 0 : 1; // Toggle the LED state
    if (led_line->current_value == 1) {
        led_state = 1;
    } else {
        led_state = 0;
    }

    if (log_touch_event(timestamp, led_state) != 0) {
        fprintf(stderr, "Failed to log touch event.\n");
    }

    gpiod_line_set_value(led_line, led_state);
    free(timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    keep_running = 0;

    if (chip) {
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

