        gpiod_chip_close(chip);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line events for rising edges on the touch pin
    if (gpiod_line_request_rising_edge(touch_line, "touch_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request rising edge for line %d: %s\n", TOUCH_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line events for falling edges on the LED pin
    if (gpiod_line_request_falling_edge(led_line, "led_control", 0) < 0) {
        fprintf(stderr, "Failed to request falling edge for line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Touch sensor and LED control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        if (gpiod_line_event_wait(touch_line, 1000) < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            break;
        }

        handle_touch_event();
    }

    // Cleanup resources before exiting
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

