#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18

// Define log file name
#define LOG_FILE "alert_log.txt"

// Global variables for signal handling
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **flame_line, struct gpiod_line **buzzer_line);
int read_flame_sensor(struct gpiod_line *flame_line);
int activate_buzzer(struct gpiod_line *buzzer_line, int duration_ms);
int log_event(const char *message);
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *flame_line, struct gpiod_line *buzzer_line);
void signal_handler(int signum);

// Function to initialize GPIO lines
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **flame_line, struct gpiod_line **buzzer_line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *flame_line = gpiod_chip_get_line(*chip, FLAME_SENSOR_GPIO);
    if (!*flame_line) {
        perror("Error getting flame sensor line");
        gpiod_chip_close(*chip);
        return -1;
    }

    *buzzer_line = gpiod_chip_get_line(*chip, BUZZER_GPIO);
    if (!*buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_line_release(*flame_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request flame sensor line as input
    if (gpiod_line_request_input(*flame_line, "flame_sensor") < 0) {
        perror("Error requesting flame sensor line as input");
        gpiod_line_release(*flame_line);
        gpiod_line_release(*buzzer_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request buzzer line as output
    if (gpiod_line_request_output(*buzzer_line, "buzzer", 0) < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_line_release(*flame_line);
        gpiod_line_release(*buzzer_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *flame_line) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        perror("Error reading flame sensor value");
        return -1;
    }
    return value;
}

// Function to activate the buzzer for a specified duration
int activate_buzzer(struct gpiod_line *buzzer_line, int duration_ms) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Error setting buzzer value to HIGH");
        return -1;
    }
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Error setting buzzer value to LOW");
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to cleanup GPIO resources
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *flame_line, struct gpiod_line *buzzer_line) {
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Signal received, cleaning up...\n");

    // Cleanup GPIO resources
    cleanup_gpio(chip, flame_line, buzzer_line);

    // Turn off the buzzer
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(&chip, &flame_line, &buzzer_line) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Log system start event
    log_event("System started");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor(flame_line);
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (flame_detected == 0) { // Flame detected (active-low)
            log_event("Flame detected!");
            activate_buzzer(buzzer_line, 2000); // Activate buzzer for 2 seconds
        }

        usleep(500000); // Sleep for 500 ms
    }

    // Log system stop event
    log_event("System stopped");

    return 0;
}

