}

// Function to log the touch event to a file
void log_touch_event() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Warning: Log file is not open, skipping log entry.\n");
    }
    free(timestamp);
}

// Function to toggle the LED state
void toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
}

// Function to handle the touch event
void handle_touch() {
    toggle_led();
    log_touch_event();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(LED_PIN, 0); // Turn off the LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

