        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // Store the last known state of the touch pin
    unsigned long last_debounce_time = 0; // Store the last time the touch pin was debounced

    // Main loop
    while (running) {
        int current_state = gpioRead(TOUCH_PIN);

        if (current_state == 0 && last_state == 1) { // Rising edge (LOW to HIGH)
            unsigned long now = gpioTick();
            if (now - last_debounce_time > DEBOUNCE_DELAY_MS * 1000) { // Debounce
                handle_touch();
                last_debounce_time = now;
            }
        }

        last_state = current_state;
        gpioDelay(10); // Poll every 10 ms
    }

    return 0;
}

