    int gpio;
    int current_state;
    int last_state;
} sensor_data_t;

// Global variables
FILE *log_file = NULL;
sensor_data_t sensor1, sensor2, sensor3;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
void log_event(int sensor_id, int state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for SENSOR1_GPIO\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up for SENSOR1_GPIO\n");
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for SENSOR2_GPIO\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up for SENSOR2_GPIO\n");
        return 1;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting mode for SENSOR3_GPIO\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up for SENSOR3_GPIO\n");
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int state = gpioRead(gpio);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log an event to the log file
void log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, state ? "Magnet Present" : "Magnet Removed");
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensor data
    sensor1.gpio = SENSOR1_GPIO;
    sensor1.current_state = read_sensor(SENSOR1_GPIO);
    sensor1.last_state = sensor1.current_state;

    sensor2.gpio = SENSOR2_GPIO;
    sensor2.current_state = read_sensor(SENSOR2_GPIO);
    sensor2.last_state = sensor2.current_state;

    sensor3.gpio = SENSOR3_GPIO;
    sensor3.current_state = read_sensor(SENSOR3_GPIO);
    sensor3.last_state = sensor3.current_state;

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_new_state = read_sensor(SENSOR1_GPIO);
        int sensor2_new_state = read_sensor(SENSOR2_GPIO);
        int sensor3_new_state = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reads
        if (sensor1_new_state == -1 || sensor2_new_state == -1 || sensor3_new_state == -1) {
            // Log the error to stderr
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
            gpioDelay(100); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Update last states
        sensor1.last_state = sensor1_new_state;
        sensor2.last_state = sensor2_new_state;
        sensor3.last_state = sensor3_new_state;

        // Log state changes
        if (sensor1_new_state != sensor1.last_state) {
            log_event(1, sensor1_new_state);
        }
        if (sensor2_new_state != sensor2.last_state) {
            log_event(2, sensor2_new_state);
        }
        if (sensor3_new_state != sensor3.last_state) {
            log_event(3, sensor3_new_state);
        }

        gpioDelay(100); // Wait 100 ms
    }

    return 0;
}

