#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5
#define LOG_FILE "heart_rate.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int led_current;
    int averaging;
    int enable;
} sensor_config_t;

// Function prototypes
int init_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int *heart_rate);
float calculate_bpm(int heart_rate);
float moving_average(float new_value, float *buffer, int size, int *index);
int log_data(float bpm);
void signal_handler(int signal);
int verify_sensor_address(int i2c_handle, int expected_address);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to verify the sensor address
int verify_sensor_address(int i2c_handle, int expected_address) {
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != expected_address) {
        fprintf(stderr, "Incorrect PART_ID address: 0x%02X (expected 0x%02X)\n", part_id, expected_address);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1182 sensor
int init_sensor(int i2c_handle) {
    // Verify sensor address
    if (verify_sensor_address(i2c_handle, SI1182_ADDR) != 0) {
        fprintf(stderr, "Sensor initialization failed: Sensor address verification failed.\n");
        return -1;
    }

    // Configure the sensor
    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error writing LED current register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing averaging register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing enable register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read heart-rate data from the sensor
int read_sensor_data(int i2c_handle, int *heart_rate) {
    int raw_data = i2cReadWordData(i2c_handle, HEART_RATE_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading heart-rate register: %s\n", strerror(errno));
        return -1;
    }
    *heart_rate = raw_data;
    return 0;
}

// Function to calculate BPM from raw heart-rate data
float calculate_bpm(int heart_rate) {
    return (float)heart_rate * 0.5;
}

// Function to implement a moving average filter
float moving_average(float new_value, float *buffer, int size, int *index) {
    buffer[*index] = new_value;
    *index = (*index + 1) % size;
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

// Function to log data to a file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor address
    if (verify_sensor_address(i2c_handle, SI1182_ADDR) != 0) {
        fprintf(stderr, "Sensor initialization failed: Sensor address verification failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize moving average buffer
    float bpm_buffer[MOVING_AVG_SIZE] = {0.0};
    int bpm_buffer_index = 0;

    // Main loop
    while (!terminate) {
        int heart_rate;
        if (read_sensor_data(i2c_handle, &heart_rate) == 0) {
            float bpm = calculate_bpm(heart_rate);
