#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("Caught signal, exiting gracefully...\n");
}

int init_gpio()
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_get_value(line) < 0) {
        perror("Error getting initial GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_flame_sensor()
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1;
    }
    return value;
}

int log_flame_event()
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
    fflush(log_file);

    return 0;
}

int cleanup()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

int main()
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int value = read_flame_sensor();
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value. Retrying.\n");
            usleep(100000); // 100ms
            continue;
        }

        if (value == 0) { // Flame detected (active-low)
            printf("FLAME DETECTED\n");
            if (log_flame_event() < 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        }

        usleep(100000); // 100ms delay
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

