#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {5, 6, 7, 8, 9, 10, 11, 12}

// Define GPIO chip for display output
#define DISPLAY_CHIP "gpiochip0"
#define DISPLAY_LINE 17

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Define stabilization delay in milliseconds
#define STABILIZATION_DELAY 200

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[8];
static struct gpiod_line *display_line = NULL;
static volatile int running = 1;

// Function prototypes
int init_gpio(void);
int read_sensor(int channel);
void update_output(int counter);
void log_touch_event(int channel, int counter);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        running = 0;
        cleanup();
        exit(0);
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config[8];

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request lines for each sensor channel
    for (int i = 0; i < 8; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!line) {
            perror("Error getting line");
            return -1;
        }

        config[i].consumer = "touch_counter";
        config[i].request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
        config[i].flags = 0;

        if (gpiod_line_request(line, &config[i], 0) < 0) {
            perror("Error requesting line");
            return -1;
        }
        lines[i] = line;
    }

    // Request display line
    config[0].consumer = "touch_counter";
    config[0].request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config[0].flags = 0;

    if (gpiod_line_request(display_line, &config[0], 0) < 0) {
        perror("Error requesting display line");
        return -1;
    }

    // Stabilization delay
    struct timespec delay = {0, STABILIZATION_DELAY * 1000000L};
    nanosleep(&delay, NULL);

    return 0;
}

// Read sensor value
int read_sensor(int channel) {
    int value = gpiod_line_get_value(lines[channel]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", channel, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Update output GPIO
void update_output(int counter) {
    int display_value = 0;
    for (int i = 0; i < 8; i++) {
        display_value |= (counter & (1 << i)) << i;
    }
    if (gpiod_line_set_value(display_line, display_value) < 0) {
        fprintf(stderr, "Error setting display value: %s\n", strerror(errno));
    }
}

// Log touch event
void log_touch_event(int channel, int counter) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open touch_log.txt\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter);
    fclose(fp);
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Release display line
    if (display_line) {
        gpiod_line_release(display_line);
    }

    // Release sensor lines
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch counter started. Press Ctrl+C to exit.\n");

    int counter = 0;
    struct timespec delay = {0, 10 * 1000000L}; // 10 ms

    while (running) {
        for (int i = 0; i < 8; i++) {
            int sensor_value = read_sensor(i);
            if (sensor_value < 0) {
                // Error reading sensor, skip this channel
                continue;
            }

            if (sensor_value == 1) {
                // Rising edge detected
                counter++;
                if (counter > 255) {
                    counter = 0;
                }

                log_touch_event(i, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                nanosleep(&delay, NULL);
            }
        }

        update_output(counter);
        nanosleep(&delay, NULL);
    }

    cleanup();
    printf("Touch counter stopped.\n");
    return 0;
}

