#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Define the log file name
#define LOG_FILE "tracking_log.csv"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;
struct gpiod_line *sensor3_line = NULL;
struct gpiod_line *sensor4_line = NULL;

// Function prototypes
int init_gpio(struct gpiod_chip *chip, int pin);
int read_sensor(struct gpiod_line *line);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4);
void cleanup_gpio(struct gpiod_chip *chip);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        cleanup_gpio(chip);
        exit(0);
    }
}

// Initialize a GPIO line for input
int init_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }

    if (gpiod_line_request_input(line, "sensor%d", pin) < 0) {
        fprintf(stderr, "Error: Could not request input for line %d\n", pin);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Read the value of a sensor
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read value from line %d\n", line->line->id);
        return -1;
    }
    return value;
}

// Log data to a CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error: Could not write to file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

