    if (init_gpio(chip, SENSOR1_PIN) < 0 ||
        init_gpio(chip, SENSOR2_PIN) < 0 ||
        init_gpio(chip, SENSOR3_PIN) < 0 ||
        init_gpio(chip, SENSOR4_PIN) < 0) {
        cleanup_gpio(chip);
        return 1;
    }

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup_gpio(chip);
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }
    rewind(fp);

    // Main loop
    while (1) {
        // Read sensor values
        sensor1_value = read_sensor(sensor1_line);
        sensor2_value = read_sensor(sensor2_line);
        sensor3_value = read_sensor(sensor3_line);
        sensor4_value = read_sensor(sensor4_line);

        // Log the data
        if (log_data(fp, sensor1_value, sensor2_value, sensor3_value, sensor4_value) < 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait for 100 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&ts, NULL);
    }

    // The program should never reach here, but cleanup is important
    fclose(fp);
    cleanup_gpio(chip);

    return 0;
}

