#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO17_PIN 17
#define GPIO18_PIN 18
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/tilt_events.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *gpio17_line = NULL;
static struct gpiod_line *gpio18_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "Signal received, exiting gracefully...\n");
}

// Function to initialize GPIO lines
int init_gpio()
{
    struct gpiod_line_request_config config;

    // Request GPIO17 as input with active-low pull-up
    config.consumer = "tilt_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0; // No special flags

    gpio17_line = gpiod_chip_get_line(chip, GPIO17_PIN);
    if (!gpio17_line) {
        fprintf(stderr, "Error: Could not get GPIO%d line\n", GPIO17_PIN);
        return -1;
    }

    if (gpiod_line_request(gpio17_line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO%d line for input\n", GPIO17_PIN);
        return -1;
    }

    // Request GPIO18 as input with active-low pull-up
    config.consumer = "tilt_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0; // No special flags

    gpio18_line = gpiod_chip_get_line(chip, GPIO18_PIN);
    if (!gpio18_line) {
        fprintf(stderr, "Error: Could not get GPIO%d line\n", GPIO18_PIN);
        return -1;
    }

    if (gpiod_line_request(gpio18_line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO%d line for input\n", GPIO18_PIN);
        return -1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin)
{
    int value = gpiod_line_get_value(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read GPIO%d value\n", gpio_pin);
        return -1;
    }
    return value;
}

// Function to log tilt event
void log_tilt_event(int gpio_pin)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, gpio_pin);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize GPIO lines
    if (init_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        cleanup_gpio();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int last_gpio17_value = 1; // Initialize to inactive state (pull-up)
    int last_gpio18_value = 1; // Initialize to inactive state (pull-up)

    // Main loop
    while (!terminate) {
        int gpio17_value = read_sensor(GPIO17_PIN);
        int gpio18_value = read_sensor(GPIO18_PIN);

        if (gpio17_value < 0 || gpio18_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor values, retrying...\n");
            struct timespec sleep_time;
            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = 100 * 1000 * 1000; // 100ms
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Debounce and log events
        if (gpio17_value == 0 && last_gpio17_value == 1) {
            log_tilt_event(1);
            struct timespec sleep_time;
            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = DEBOUNCE_MS * 1000 * 1000; // 50ms
            nanosleep(&sleep_time, NULL);
        }
        if (gpio18_value == 0 && last_gpio18_value == 1) {
            log_tilt_event(2);
            struct timespec sleep_time;
            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = DEBOUNCE_MS * 1000 * 1000; // 50ms
            nanosleep(&sleep_time, NULL);
        }

        last_gpio17_value = gpio17_value;
        last_gpio18_value = gpio18_value;

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    fprintf(stderr, "Exiting.\n");
    return EXIT_SUCCESS;
}

