#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "obstacle_log.csv"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_init(void);
int read_sensor(int gpio_pin);
int control_led(int gpio_pin, int state);
int log_data(time_t timestamp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// GPIO initialization function
int gpio_init(void) {
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request sensor lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Error getting sensor 1 line");
        gpiod_chip_close(chip);
        return -1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Error getting sensor 2 line");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure sensor lines as input with pull-up resistor
    config.consumer = "sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

