#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125 // 8 kHz sampling rate

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;
    int last_state = 0; // 0 = LOW, 1 = HIGH
    struct timespec ts;

    // Initialize pigpio
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", result);
        return 1;
    }

    // Set GPIO modes
    result = gpioSetMode(MIC_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set MIC_PIN mode: %d\n", result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set LED_PIN mode: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sound peak detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_state = gpioRead(MIC_PIN);

        if (current_state == 1 && last_state == 0) {
            // Peak detected
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Peak detected at: %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            // Trigger LED
            gpioWrite(LED_PIN, 1);
            gpioDelay(100000); // 100 ms
            gpioWrite(LED_PIN, 0);
        }

        last_state = current_state;
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

