#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor values
int read_sensors(int *left, int *center, int *right) {
    *left = gpioRead(LEFT_SENSOR_PIN);
    *center = gpioRead(CENTER_SENSOR_PIN);
    *right = gpioRead(RIGHT_SENSOR_PIN);

    if (*left < 0 || *center < 0 || *right < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1;
    }

    return 0;
}

// Function to log the sensor data
void log_data(int left, int center, int right) {
    printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int left, center, right;

    // Main loop
    while (program_running) {
        if (read_sensors(&left, &center, &right) == 0) {
            log_data(left, center, right);
        } else {
            fprintf(stderr, "Error reading sensors, retrying...\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

