#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x49

// Si1175 register addresses
#define SI1175_REG_ALS_VIS_LSB 0x24
#define SI1175_REG_ALS_VIS_MSB 0x25

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the Si1175 sensor
int16_t read_si1175_als_visible() {
    int lsb, msb;

    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB from Si1175: %d\n", lsb);
        return -1; // Indicate error
    }

    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB from Si1175: %d\n", msb);
        return -1; // Indicate error
    }

    return (int16_t)((msb << 8) | lsb);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int16_t als_visible = read_si1175_als_visible();

        if (als_visible >= 0) {
            printf("Raw ALS Visible: %d\n", als_visible);
        } else {
            fprintf(stderr, "Failed to read ALS visible data.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

