#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the TTP226 sensors
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variables for chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8] = {NULL};

// Function prototypes
int init_gpio(void);
int request_lines(struct gpiod_chip *chip, struct gpiod_line **lines, int num_lines);
int read_sensor(struct gpiod_line *line);
void log_data(int *channels);
void cleanup(int signum);

// Signal handler for graceful shutdown
void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Initialize GPIO chip
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Request GPIO lines as inputs
int request_lines(struct gpiod_chip *chip, struct gpiod_line **lines, int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Error requesting line %d: %s\n", sensor_pins[i], strerror(errno));
            return -1;
        }
        lines[i] = line;
        if (gpiod_line_request_input(line, "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting input for line %d: %s\n", sensor_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Log sensor data with timestamp
void log_data(int *channels) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("[%s] ", buf);
    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, channels[i]);
    }
    printf("\n");
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Request GPIO lines
    if (request_lines(chip, lines, num_channels) != 0) {
        cleanup(0);
        return 1;
    }

    // Main loop
    int sensor_values[num_channels];
    while (1) {
        for (int i = 0; i < num_channels; i++) {
            sensor_values[i] = read_sensor(lines[i]);
            if (sensor_values[i] < 0) {
                cleanup(0);
                return 1;
            }
        }
        log_data(sensor_values);
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200 * 1000 * 1000; // 200 ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

