    float t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            *r = (int)(v * 255);
            *g = (int)(t * 255);
            *b = (int)(p * 255);
            break;
        case 1:
            *r = (int)(q * 255);
            *g = (int)(v * 255);
            *b = (int)(p * 255);
            break;
        case 2:
            *r = (int)(p * 255);
            *g = (int)(v * 255);
            *b = (int)(t * 255);
            break;
        case 3:
            *r = (int)(p * 255);
            *g = (int)(q * 255);
            *b = (int)(v * 255);
            break;
        case 4:
            *r = (int)(t * 255);
            *g = (int)(p * 255);
            *b = (int)(v * 255);
            break;
        default: // case 5:
            *r = (int)(v * 255);
            *g = (int)(p * 255);
            *b = (int)(q * 255);
            break;
    }
}

// Function to fade between two colors
void fade_to_color(int target_hue, int target_step) {
    float h = (float)current_hue / 360.0;
    float s = SATURATION;
    float v = VALUE;
    int r, g, b;

    hsv_to_rgb(h, s, v, &r, &g, &b);

    // Invert the RGB values for common-anode LED
    r = 255 - r;
    g = 255 - g;
    b = 255 - b;

    // Calculate the target RGB values
    h = (float)target_hue / 360.0;
    float s = SATURATION;
    float v = VALUE;
    hsv_to_rgb(h, s, v, &target_r, &target_g, &target_b);

    target_r = 255 - target_r;
    target_g = 255 - target_g;
    target_b = 255 - target_b;

    // Linear interpolation
    for (int i = 0; i < NUM_STEPS; ++i) {
        current_hue = (int)((h + (float)i / NUM_STEPS) * 360.0);
        current_step = i;
        gpioPWM(RED_PIN, (int)(((float)r + (float)target_r) / 2.0 * (PWM_RANGE / 2.0)));
        gpioPWM(GREEN_PIN, (int)(((float)g + (float)target_g) / 2.0 * (PWM_RANGE / 2.0)));
        gpioPWM(BLUE_PIN, (int)(((float)b + (float)target_b) / 2.0 * (PWM_RANGE / 2.0)));
        gpioDelay(50000 / NUM_STEPS); // Delay for each step (50ms)
    }
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed random number generator with /dev/urandom
    srand(time(NULL));

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes for PWM output
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", RED_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GREEN_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", BLUE_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO %d", RED_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO %d", GREEN_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO %d", BLUE_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM range
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GPIO %d", RED_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GPIO %d", GREEN_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GPIO %d", BLUE_PIN);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Generate a new hue
        current_hue = generate_hue();

        // Fade to the new color
        fade_to_color(current_hue, current_step);

        // Wait for the fade duration
        sleep(FADE_DURATION);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    closelog();

    return 0;
}

