#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO Pin for LED
#define LED_PIN 17

// Global variables
int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *led_line;
int running = 1;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int i2c_read_word(int fd, uint8_t reg);
int init_tcs34725(int fd);
int read_tcs34725(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *clear_calibrated, float *red_calibrated, float *green_calibrated, float *blue_calibrated);
void control_led(int gpio_chip, int gpio_line, int red_value, int threshold);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg | TCS34725_COMMAND_BIT;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write (byte) failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg | TCS34725_COMMAND_BIT;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (byte for read) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write word function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg | TCS34725_COMMAND_BIT;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("I2C write (word) failed");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg | TCS34725_COMMAND_BIT;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (byte for read) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    uint16_t value = (buf[0] << 8) | buf[1];
    return value;
}

// TCS34725 initialization function
int init_tcs34725(int fd) {
    // Power on
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) != 0) return -1;
    usleep(100000); // Wait for power-on

    // Set integration time (ATIME)
    if (i2c_write_byte(fd, TCS34725_ATIME, 0x00) != 0) return -1; // 154ms

    // Set gain (CONTROL)
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x00) != 0) return -1; // 1x gain

    // Verify sensor ID
    int sensor_id = i2c_read_byte(fd, TCS34725_ID);
    if (sensor_id != 0x44) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    return 0;
}

// TCS34725 read data function
int read_tcs34725(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    *clear = i2c_read_word(fd, TCS34725_CDATA);
    *red = i2c_read_word(fd, TCS34725_RDATA);
    *green = i2c_read_word(fd, TCS34725_GDATA);
    *blue = i2c_read_word(fd, TCS34725_BDATA);

    if (*clear == -1 || *red == -1 || *green == -1 || *blue == -1) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    return 0;
}

// Data calibration function
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *clear_calibrated, float *red_calibrated, float *green_calibrated, float *blue_calibrated) {
    // Calibration factors (example values, adjust based on your sensor)
    float clear_offset = 0.0;
    float clear_gain = 1.0;
    float red_offset = 0.0;
    float red_gain = 1.0;
    float green_offset = 0.0;
    float green_gain = 1.0;
    float blue_offset = 0.0;
    float blue_gain = 1.0;

    *clear_calibrated = (float)(clear - clear_offset) * clear_gain;
    *red_calibrated = (float)(red - red_offset) * red_gain;
    *green_calibrated = (float)(green - green_offset) * green_gain;
    *blue_calibrated = (float)(blue - blue_offset) * blue_gain;
}

// LED control function
void control_led(int gpio_chip, int gpio_line, int red_value, int threshold) {
    if (red_value > threshold) {
        gpiod_line_set_value(gpio_line, 1); // HIGH
    } else {
        gpiod_line_set_value(gpio_line, 0); // LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "tcs34725_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) != 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725
    if (init_tcs34725(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    uint16_t clear, red, green, blue;
    float clear_calibrated, red_calibrated, green_calibrated, blue_calibrated;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_tcs34725(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate data
            calibrate_data(clear, red, green, blue, &clear_calibrated, &red_calibrated, &green_calibrated, &blue_calibrated);

            // Display calibrated values
            printf("Calibrated: C=%6.2f, R=%6.2f, G=%6.2f, B=%6.2f\n", clear_calibrated, red_calibrated, green_calibrated, blue_calibrated);

            // Control LED
            control_led(chip, led_line, (int)red_calibrated, 200);
        } else {
            fprintf(stderr, "Failed to read sensor data, re-initializing...\n");
            // Attempt to re-initialize the sensor
            if (init_tcs34725(i2c_fd) != 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
            }
        }

        usleep(200000); // 200 ms
    }

    // Cleanup
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

