#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x20
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define LUX_MIN 10.0
#define LUX_MAX 300.0

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int init_spi(int speed, int mode, int bits);
int read_bh1750(int fd);
float calculate_lux(int raw_value);
int map_lux_to_brightness(float lux);
int send_apa102_frame(int fd, uint8_t start_frame, uint8_t *led_frames, int num_leds, uint8_t end_frame);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", sig);
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize SPI
int init_spi(int speed, int mode, int bits) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode_bits[3] = {0, mode, 0};
    if (ioctl(fd, SPI_IOC_WR_MODE, mode_bits) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits_bits[3] = {0, bits, 0};
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, bits_bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed_bits[3] = {0, speed, 0};
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, speed_bits) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from BH1750 sensor
int read_bh1750(int fd) {
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 120ms)
    usleep(120000); // 120ms

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Calculate lux value
float calculate_lux(int raw_value) {
    return (float)raw_value / 1.2;
}

// Map lux value to APA102 brightness (0-31)
int map_lux_to_brightness(float lux) {
    if (lux < LUX_MIN) {
        return 0;
    } else if (lux > LUX_MAX) {
        return 31;
    } else {
        return (int)((lux - LUX_MIN) * (31.0 / (LUX_MAX - LUX_MIN)));
    }
}

// Send APA102 frame
int send_apa102_frame(int fd, uint8_t start_frame, uint8_t *led_frames, int num_leds, uint8_t end_frame) {
    uint8_t frame[32 + num_leds * 4 + 1]; // Start frame + LED frames + End frame
    frame[0] = start_frame;
    memcpy(frame + 1, led_frames, num_leds * 4); // 4 bytes per LED (0xE0 | brightness | blue | green | red)
    frame[1 + num_leds * 4] = end_frame;

    uint8_t tx_buf[32 + num_leds * 4 + 1];
    memcpy(tx_buf, frame, 32 + num_leds * 4 + 1);

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)NULL, // Don't need to receive anything
        .len = 32 + num_leds * 4 + 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_SPEED, SPI_MODE, SPI_BITS_PER_WORD);
    if (spi_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    uint8_t led_frames[NUM_LEDS * 4];
    int raw_value;
    float lux;
    int brightness;

    printf("Starting main loop...\n");

    while (!terminate) {
        // Read raw value from BH1750
        raw_value = read_bh1750(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading BH1750, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate lux value
        lux = calculate_lux(raw_value);

        // Map lux to brightness
        brightness = map_lux_to_brightness(lux);

        // Send APA102 frame
        for (int i = 0; i < NUM_LEDS; i++) {
            led_frames[i * 4] = 0xE0 | brightness; // Global brightness
            led_frames[i * 4 + 1] = 0x00;       // Blue
            led_frames[i * 4 + 2] = 0x00;       // Green
            led_frames[i * 4 + 3] = 0x00;       // Red
        }

        if (send_apa102_frame(spi_fd, 0xE0, led_frames, NUM_LEDS, 0xFF) < 0) {
            fprintf(stderr, "Error sending APA102 frame, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        usleep(500000); // 500ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return 0;
}

