#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_LEDS 30
#define NUM_SENSORS 3
#define MAX_SENSORS 3 // Maximum number of sensors to check
#define MAX_I2C_ADDR 0x77 // Maximum I2C address (0x77 - 0x23)
#define MAX_I2C_RETRIES 3
#define MAX_I2C_DELAY_MS 100
#define MAX_SPI_DELAY_MS 100
#define MAX_BRIGHTNESS 31
#define MIN_BRIGHTNESS 0
#define AVG_DELAY_MS 100
#define SMOOTHING_FACTOR 0.1 // Adjust for faster/slower fade

// Global variables
int spi_handle;
int i2c_handles[NUM_SENSORS];
int num_sensors_found = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750(int i2c_handle);
int read_bh1750(int i2c_handle);
float average_lux(int *sensor_values, int num_sensors);
int map_lux_to_brightness(float average_lux);
void fade_brightness(int brightness, int target_brightness, int delay_ms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize BH1750 sensor
int init_bh1750(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x00, 0x21) != 0) { // One-Time High-Resolution Mode 2
        fprintf(stderr, "Error: Failed to initialize BH1750 at handle %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(180); // Wait for measurement (at least 180ms)
    return 0;
}

// Read data from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read data from BH1750 at handle %d\n", i2c_handle);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Average lux readings from multiple sensors
float average_lux(int *sensor_values, int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] >= 0) {
            sum += sensor_values[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Return 0 if no valid sensors
    }
}

