// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// GPIO pin for WS2812B
#define WS2812B_GPIO 18

// I2C bus
#define I2C_BUS 1

// VEML7700 integration time (ms)
#define VEML7700_INTEGRATION_TIME 100

// VEML7700 gain
#define VEML7700_GAIN 1 // 1/8

// Lux range for gamma correction
#define LUX_MAX 120000.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 800000 // 800 kHz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_als_data(uint16_t *als_data);
float calculate_lux(uint16_t als_data);
float gamma_correct(float lux);
int set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    uint8_t config_data[2];
    config_data[0] = VEML7700_CONFIG;
    config_data[1] = 0x00; // Integration time 100ms, gain 1/8

    int result = i2cWriteDevice(i2c_handle, (char *)config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read ALS data from VEML7700 sensor
int read_als_data(uint16_t *als_data) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS data register: %s\n", strerror(errno));
        return -1;
    }

    *als_data = (buffer[1] << 8) | buffer[0];
    return 0;
}

// Calculate lux value from raw ALS data
float calculate_lux(uint16_t als_data) {
    return als_data * 0.0288; // lux = raw * 0.0288
}

// Apply gamma correction to lux value
float gamma_correct(float lux) {
    return 255 * pow(lux / LUX_MAX, 1.0 / 2.2);
}

// Set LED brightness using PWM
int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    gpioPWM(WS2812B_GPIO, brightness);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(WS2812B_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(WS2812B_GPIO, 255);

    uint16_t als_data;
    float lux;
    int brightness;

    while (!terminate) {
        // Read ALS data
        if (read_als_data(&als_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(als_data);

            // Apply gamma correction
            brightness = (int)gamma_correct(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data. Retrying...\n");
            for (int i = 0; i < 3; i++) {
                if (read_als_data(&als_data) == 0) {
                    break; // Success, exit retry loop
                } else {
                    usleep(100000); // 100ms delay
                }
            }
            if (als_data == 0) {
                fprintf(stderr, "VEML7700 sensor absent after multiple retries\n");
            }
        }

        usleep(200000); // 200ms delay
    }

    // Clean up
    set_led_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

