#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define error codes
#define ERROR_FLAME_SENSOR 1
#define ERROR_BUZZER 2
#define ERROR_LED 3
#define ERROR_LINE_REQUEST 4
#define ERROR_VALUE_READ 5
#define ERROR_LINE_RELEASE 6

// Define error messages
#define ERROR_MESSAGE "Error: "

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio(void);
int read_flame_sensor(void);
void activate_buzzer(void);
void deactivate_buzzer(void);
void activate_led(void);
void deactivate_led(void);
void log_event(const char *message);
void self_test(void);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config;

    // Request flame sensor line
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        log_event("Error: Failed to get flame sensor line.");
        return ERROR_LINE_REQUEST;
    }

    if (gpiod_line_request(flame_sensor_line, &config, 0) < 0) {
        log_event("Error: Failed to request flame sensor line.");
        return ERROR_LINE_REQUEST;
    }

    // Request buzzer line
    config.consumer = "buzzer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        log_event("Error: Failed to get buzzer line.");
        return ERROR_LINE_REQUEST;
    }

    if (gpiod_line_request(buzzer_line, &config, 0) < 0) {
        log_event("Error: Failed to request buzzer line.");
        return ERROR_LINE_REQUEST;
    }

    // Request LED line
    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_event("Error: Failed to get LED line.");
        return ERROR_LINE_REQUEST;
    }

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        log_event("Error: Failed to request LED line.");
        return ERROR_LINE_REQUEST;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_sensor_line);
    if (value < 0) {
        log_event("Error: Failed to read flame sensor value.");
        return ERROR_VALUE_READ;
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer(void) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        log_event("Error: Failed to activate buzzer.");
    }
}

