#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define CIRCULAR_BUFFER_SIZE 60
#define LUX_CONVERSION_FACTOR 1.2

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int gpio_fd = -1;
float lux_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;
float average_lux = 0.0;

// Function prototypes
int i2c_read(int fd, unsigned char command, unsigned char *data, int count);
float read_lux(int fd);
float calculate_average_lux(float lux_values[], int size);
void set_gpio_duty_cycle(int gpio_fd, float duty_cycle);
void signal_handler(int signal);

// I2C read function
int i2c_read(int fd, unsigned char command, unsigned char *data, int count) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    unsigned char buf[1];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Error: Could not write to I2C device");
        return -1;
    }

    if (read(fd, data, count) != count) {
        perror("Error: Could not read from I2C device");
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux(int fd) {
    unsigned char data[2];
    unsigned int raw_value;

    if (i2c_read(fd, 0x10, data, 2) != 0) {
        fprintf(stderr, "Error reading lux value. Skipping sample.\n");
        return -1.0; // Indicate an error
    }

    raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / LUX_CONVERSION_FACTOR;
}

// Calculate average lux value from circular buffer
float calculate_average_lux(float lux_values[], int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += lux_values[i];
    }
    return sum / size;
}

// Set GPIO duty cycle using sysfs
void set_gpio_duty_cycle(int gpio_fd, float duty_cycle) {
    char path[64];
    char value_str[16];
    int on_time, off_time;

    // Calculate on and off times based on duty cycle (50% = 0.5)
    on_time = (int)(duty_cycle * 2); // On time is twice the duty cycle
    off_time = 1000000 - on_time;    // Off time is the remaining time

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
    snprintf(value_str, sizeof(value_str), "%d", on_time);

    // Turn on the LED
    if (write(gpio_fd, value_str, strlen(value_str)) != strlen(value_str)) {
        perror("Error: Could not write to GPIO value file (on)");
    }

    // Wait for the on time
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = on_time * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);

    // Turn off the LED
    if (write(gpio_fd, value_str, strlen(value_str)) != strlen(value_str)) {
        perror("Error: Could not write to GPIO value file (off)");
    }

    // Wait for the off time
    ts.tv_sec = 0;
    ts.tv_nsec = off_time * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Export GPIO pin
    char export_path[64];
    snprintf(export_path, sizeof(export_path), "/sys/class/gpio/export");
    FILE *export_file = fopen(export_path, "w");
    if (export_file == NULL) {
        perror("Error: Could not open GPIO export file");
        close(i2c_fd);
        return 1;
    }
    fprintf(export_file, "%d", GPIO_PIN);
    fclose(export_file);

    // Set GPIO direction to output
    char direction_path[64];
    snprintf(direction_path, sizeof(direction_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    FILE *direction_file = fopen(direction_path, "w");
    if (direction_file == NULL) {
        perror("Error: Could not open GPIO direction file");
        close(i2c_fd);
        return 1;
    }
    fprintf(direction_file, "out");
    fclose(direction_file);

    // Open GPIO value file for writing
    gpio_fd = open(direction_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error: Could not open GPIO value file");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer with zeros
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0;
    }

    // Main loop
    while (program_running) {
        float lux = read_lux(i2c_fd);
        if (lux >= 0.0) {
            lux_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
            average_lux = calculate_average_lux(lux_buffer, CIRCULAR_BUFFER_SIZE);
            float duty_cycle = 0.5 + (average_lux / 1000.0) * 4.5; // Map average lux to duty cycle
            if (duty_cycle < 0.5) duty_cycle = 0.5;
            if (duty_cycle > 5.0) duty_cycle = 5.0;
            set_gpio_duty_cycle(gpio_fd, duty_cycle);
        } else {
            // Handle error, but continue the loop
            fprintf(stderr, "Error reading lux value, skipping.\n");
        }

        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    close(gpio_fd);

    // Unexport GPIO pin
    char unexport_path[64];
    snprintf(unexport_path, sizeof(unexport_path), "/sys/class/gpio/unexport");
    FILE *unexport_file = fopen(unexport_path, "w");
    if (unexport_file != NULL) {
        fprintf(unexport_file, "%d", GPIO_PIN);
        fclose(unexport_file);
    }

    return 0;
}

