#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define LED_PIN 17
#define BUTTON_PIN 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    printf("Caught signal, cleaning up...\n");
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(button_line, "blink_button", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_edge(led_line, GPIOD_LINE_EDGE_RISING) < 0) {
        perror("Error setting LED line edge");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_edge(button_line, GPIOD_LINE_EDGE_FALLING) < 0) {
        perror("Error setting button line edge");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led(int duration_ms)
{
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Error setting LED value high");
        return;
    }
    usleep(duration_ms * 1000); // Convert ms to microseconds
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error setting LED value low");
    }
}

// Function to handle button press
void handle_button_press()
{
    printf("Button pressed! Stopping blinking.\n");
    gpiod_line_set_value(led_line, 0); // Turn off LED
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Blinking LED... Press the button to stop.\n");

    while (1) {
        blink_led(1000); // Blink for 1 second
        if (gpiod_line_event_wait(button_line, 1000) < 0) {
            perror("Error waiting for button event");
            break;
        }
        if (gpiod_line_event_get(button_line, NULL) < 0) {
            perror("Error getting button event");
            break;
        }
        if (gpiod_line_event_get(button_line, NULL) == 1) {
            handle_button_press();
            break;
        }
    }

    // Cleanup (should not reach here if signal handler works)
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

