#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO5 as an output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    printf("LED control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Turn the LED on
        gpioWrite(LED_PIN, 1);
        printf("LED ON\n");
        fflush(stdout);

        // Wait 750 ms
        gpioDelay(750);

        // Turn the LED off
        gpioWrite(LED_PIN, 0);
        printf("LED OFF\n");
        fflush(stdout);

        // Wait 750 ms
        gpioDelay(750);
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

