#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define LED_GPIO 24
#define BUTTON_GPIO 22

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;

// Function to handle errors
void error_exit(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d, %s)\n", message, errno, strerror(errno));
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    exit(EXIT_FAILURE);
}

// Function to open the GPIO chip
int open_gpio_chip(const char *chip_name) {
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        error_exit("Failed to open GPIO chip");
    }
    return 0;
}

// Function to get a GPIO line
struct gpiod_line *get_gpio_line(int gpio) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        error_exit("Failed to get GPIO line");
    }
    return line;
}

// Function to set the direction of a GPIO line
int set_gpio_direction(int gpio, const char *direction) {
    struct gpiod_line *line = get_gpio_line(gpio);
    int ret = gpiod_line_set_direction(line, direction);
    gpiod_line_release(line);
    if (ret < 0) {
        error_exit("Failed to set GPIO direction");
    }
    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(int gpio, int value) {
    struct gpiod_line *line = get_gpio_line(gpio);
    int ret = gpiod_line_set_value(line, value);
    gpiod_line_release(line);
    if (ret < 0) {
        error_exit("Failed to set GPIO value");
    }
    return 0;
}

// Function to release GPIO resources
void release_gpio_resources() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    release_gpio_resources();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    if (open_gpio_chip(GPIO_CHIP) != 0) {
        return EXIT_FAILURE;
    }

    // Set the LED GPIO as output
    if (set_gpio_direction(LED_GPIO, "out") != 0) {
        release_gpio_resources();
        return EXIT_FAILURE;
    }

    // Set the button GPIO as input with pull-down
    if (set_gpio_direction(BUTTON_GPIO, "in") != 0) {
        release_gpio_resources();
        return EXIT_FAILURE;
    }

    // Main loop
    int led_state = 0; // 0 = off, 1 = on
    while (1) {
        int button_value = gpiod_line_get_value(button_line);
        if (!button_line) {
            error_exit("Failed to get button line value");
        }

        if (button_value < 0) {
            error_exit("Failed to get button value");
        }

        if (button_value == 0) { // Button is pressed
            if (led_state == 0) {
                set_gpio_value(LED_GPIO, 1);
                led_state = 1;
            }
        } else { // Button is released
            set_gpio_value(LED_GPIO, 0);
            led_state = 0;
        }

        usleep(50000); // 50ms delay
    }

    return 0;
}

