            gpiod_line_release(blue_line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **red_line, struct gpiod_line **green_line, struct gpiod_line **blue_line) {
    *chip = gpiod_chip_open_by_number(0);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *red_line = gpiod_chip_get_line(*chip, RED_PIN);
    if (!*red_line) {
        perror("Error getting RED GPIO line");
        gpiod_chip_close(*chip);
        return -1;
