    int green_duty_cycle = (int)((green / 100.0) * 100.0);
    int blue_duty_cycle = (int)((blue / 100.0) * 100.0);

    // Calculate total duty cycle
    int total_duty_cycle = red_duty_cycle + green_duty_cycle + blue_duty_cycle;

    // Calculate PWM period
    struct timespec period = {0, PWM_PERIOD_MS * 1000000L};

    // Calculate delay for each color channel
    struct timespec red_delay = {0, (red_duty_cycle * 1000000L) / total_duty_cycle};
    struct timespec green_delay = {0, (green_duty_cycle * 1000000L) / total_duty_cycle};
    struct timespec blue_delay = {0, (blue_duty_cycle * 1000000L) / total_duty_cycle};

    // Set PWM signal
    if (set_gpio_value(red_line, 1) < 0) return -1;
    nanosleep(&red_delay, NULL);
    if (set_gpio_value(red_line, 0) < 0) return -1;
