#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact indication
#define IMPACT_PIN 17

// Global variables
int i2c_handle;
double g_threshold = 2.0; // Default G-force threshold
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_lsm303();
accelerometer_data_t read_accelerometer_data();
double calculate_g_force(accelerometer_data_t data);
void impact_detected();
void log_data(accelerometer_data_t data, double g_force);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the LSM303DLHC accelerometer
int init_lsm303() {
    // Set CTRL_REG1_A to enable all axes and 100 Hz data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }

    // Set CTRL_REG4_A to 2G full-scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read accelerometer data from the LSM303DLHC
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    // Read all six bytes at once with auto-increment
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        data.x = data.y = data.z = 0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate G-force magnitude from accelerometer data
double calculate_g_force(accelerometer_data_t data) {
    // Convert raw data to G-force (assuming 2G full-scale)
    double x_g = (double)data.x / 16384.0;
    double y_g = (double)data.y / 16384.0;
    double z_g = (double)data.z / 16384.0;

    // Calculate the magnitude of the G-force vector
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Impact detection function
void impact_detected() {
    gpioWrite(IMPACT_PIN, 1); // Set GPIO HIGH
    gpioDelay(50);             // Wait for 50 ms
    gpioWrite(IMPACT_PIN, 0); // Set GPIO LOW
}

// Log data to file
void log_data(accelerometer_data_t data, double g_force) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, G: %.2f\n", timestamp, data.x, data.y, data.z, g_force);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        g_threshold = atof(argv[1]);
        printf("G-force threshold set to %.2f G\n", g_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303DLHC initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin for impact indication
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);
    gpioWrite(IMPACT_PIN, 0); // Ensure it starts LOW

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        double g_force = calculate_g_force(data);

        if (g_force > g_threshold) {
            impact_detected();
            log_data(data, g_force);
        }

        gpioDelay(100); // Delay for 100 ms (10 Hz sampling rate)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

