    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read accelerometer data from the LSM303DLHC
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    // Read all six bytes at once with auto-increment
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        data.x = data.y = data.z = 0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate G-force magnitude from accelerometer data
double calculate_g_force(accelerometer_data_t data) {
    // Convert raw data to G-force (assuming 2G full-scale)
    double x_g = (double)data.x / 16384.0;
    double y_g = (double)data.y / 16384.0;
    double z_g = (double)data.z / 16384.0;

    // Calculate the magnitude of the G-force vector
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

