#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define CSV_FILE "color_log.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void set_led_brightness(uint16_t als_value);
void signal_handler(int signal);
int i2c_write_byte(int handle, uint8_t reg, uint8_t value);
int i2c_read_byte(int handle, uint8_t reg);
int i2c_read_word(int handle, uint8_t reg);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// I2C write byte function with retry
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Failure
}

// I2C read byte function with retry
int i2c_read_byte(int handle, uint8_t reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Failure
}

// I2C read word function with retry
int i2c_read_word(int handle, uint8_t reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "I2C read word failed (reg 0x%02X): %s\n", reg, strerror(errno));
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "I2C read word failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Failure
}

// Initialize the ADPD188BI sensor
int initialize_sensor() {
    int result = i2c_write_byte(i2c_handle, MODE_REG, 0x01);
    if (result != 0) {
        fprintf(stderr, "Failed to initialize sensor.\n");
        return -1;
    }
    return 0;
}

// Read ALS, Red, Green, and Blue data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int als_lsb, als_msb, red, green, blue;

    als_lsb = i2c_read_word(i2c_handle, ALS_LSB_REG);
    als_msb = i2c_read_word(i2c_handle, ALS_MSB_REG);
    red = i2c_read_word(i2c_handle, RED_REG);
    green = i2c_read_word(i2c_handle, GREEN_REG);
    blue = i2c_read_word(i2c_handle, BLUE_REG);

    if (als_lsb < 0 || als_msb < 0 || red < 0 || green < 0 || blue < 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        data.als = 0; // Set default values in case of failure
        data.red = 0;
        data.green = 0;
        data.blue = 0;
        return data;
    }

    data.als = (als_msb << 8) | als_lsb;
    data.red = red;
    data.green = green;
    data.blue = blue;

    return data;
}

// Log the sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, data.als, data.red, data.green, data.blue);
    fflush(csv_file); // Ensure data is written to file immediately
}

// Set the LED brightness based on the ALS value
void set_led_brightness(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als_value / 65535.0) * 255.0);

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    gpioPWM(PWM_GPIO, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 255); // Set PWM range to 0-255

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        set_led_brightness(data.als);
        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(PWM_GPIO, 0); // Turn off LED
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

