#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define CTRL_REG3 0x2C
#define DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06

// Impact threshold (2g)
#define IMPACT_THRESHOLD 19.62

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_sensor();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
void log_impact(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the FXOS8700CQ sensor
int initialize_sensor() {
    // Set CTRL_REG1 to standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set DATA_CFG for ±2g range
    if (i2cWriteByteData(i2c_handle, DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to DATA_CFG\n");
        return -1;
    }

    // Set CTRL_REG1 to active mode (200 Hz ODR)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data from the FXOS8700CQ
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];
    int16_t x, y, z;

    // Read 6 bytes of accelerometer data (X, Y, Z)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0; // Set to 0.0 in case of error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine MSB and LSB, and shift right by 2 bits
    x = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 2;
    y = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 2;
    z = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 2;

    // Convert to m/s^2 (sensitivity = 4096 counts/g)
    data.x = (float)x * 9.81 / 4096.0;
    data.y = (float)y * 9.81 / 4096.0;
    data.z = (float)z * 9.81 / 4096.0;

    return data;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log an impact event to a file
void log_impact(accelerometer_data_t data, float magnitude) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

