#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Sensitivity (degrees per second per LSB)
#define SENSITIVITY 0.00875

// Sampling rate (Hz)
#define SAMPLING_RATE 20

// Data logging interval (ms)
#define LOG_INTERVAL_MS 50

// Maximum allowed rate (dps)
#define MAX_RATE 50

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int init_gyro(int fd);
gyro_data_t read_gyro_data(int fd);
void calibrate_gyro(int fd, gyro_data_t *data, int num_samples);
void log_data(FILE *fp, gyro_data_t data);
void signal_handler(int sig);
int detect_sensor(int fd);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write reg failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write reg address failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write reg address failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read block failed");
        return -1;
    }
    return 0;
}

// Gyroscope initialization function
int init_gyro(int fd) {
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) != 0) return -1; // Normal mode, all axes enabled, 100 Hz ODR
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) != 0) return -1; // 250 dps full-scale, continuous update
    return 0;
}

// Gyroscope data reading function
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t raw_data[6];
    if (i2c_read_block(fd, OUT_X_L, raw_data, 6) != 0) {
        data.x = data.y = data.z = 0.0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to degrees per second
    data.x = (float)x_raw * SENSITIVITY;
    data.y = (float)y_raw * SENSITIVITY;
    data.z = (float)z_raw * SENSITIVITY;

    return data;
}

// Gyroscope calibration function
void calibrate_gyro(int fd, gyro_data_t *data, int num_samples) {
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;
    gyro_data_t sample;

    printf("Calibrating gyroscope... Please keep the sensor stationary.\n");
    for (int i = 0; i < num_samples; i++) {
        sample = read_gyro_data(fd);
        x_sum += sample.x;
        y_sum += sample.y;
        z_sum += sample.z;
        usleep(10000); // 10 ms delay
    }

    data->x = x_sum / num_samples;
    data->y = y_sum / num_samples;
    data->z = z_sum / num_samples;

    printf("Calibration complete. Zero-rate offsets: X=%.2f, Y=%.2f, Z=%.2f\n", data->x, data->y, data->z);
}

// Data logging function
void log_data(FILE *fp, gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Function to detect the sensor
int detect_sensor(int fd) {
    uint8_t who_am_i;
    if (i2c_read_reg(fd, 0x0F, &who_am_i) != 0) {
        perror("Failed to read WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0xD3) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0xD3\n", who_am_i);
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Detect sensor
    if (detect_sensor(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    gyro_data_t zero_rates;
    calibrate_gyro(i2c_fd, &zero_rates, 100);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    gyro_data_t data;
    while (!terminate) {
        data = read_gyro_data(i2c_fd);

        // Apply zero-rate offsets
        data.x -= zero_rates.x;
        data.y -= zero_rates.y;
        data.z -= zero_rates.z;

        // Data validation
        if (fabs(data.x) > MAX_RATE || fabs(data.y) > MAX_RATE || fabs(data.z) > MAX_RATE) {
            fprintf(stderr, "Warning: Gyroscope data exceeds maximum rate!\n");
        }

        log_data(log_file, data);

        usleep(LOG_INTERVAL_MS * 1000); // Delay for sampling rate
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

