    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 accelerometer
int adxl345_init() {
    // Set range to full resolution, ±2g
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, ADXL345_RANGE) < 0) {
        fprintf(stderr, "Error setting ADXL345 range\n");
        return -1;
    }

    // Verify DEVID register
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID value: 0x%X\n", devid);
