#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Global variables
int i2c_handle_accel;
int i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} AccelData;

// Structure to hold magnetometer data
typedef struct {
    int16_t x, y, z;
} MagData;

// Function prototypes
int init_accelerometer();
int init_magnetometer();
AccelData read_accelerometer_data();
MagData read_magnetometer_data();
float calculate_heading(AccelData accel_data, MagData mag_data);
void log_data(float heading, AccelData accel_data, MagData mag_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize accelerometer
int init_accelerometer() {
    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C device for accelerometer: %d\n", i2c_handle_accel);
        return -1;
    }

    // Set accelerometer to 50 Hz, all axes enabled
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        i2cClose(i2c_handle_accel);
        return -1;
    }

    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C device for magnetometer: %d\n", i2c_handle_mag);
        return -1;
    }

    // Set magnetometer to continuous-conversion mode
    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        i2cClose(i2c_handle_mag);
        return -1;
    }

    return 0;
}

// Read accelerometer data
AccelData read_accelerometer_data() {
    AccelData data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = data.y = data.z = 0; // Return 0s on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

