float calculate_heading(AccelData accel_data, MagData mag_data) {
    float heading = atan2(mag_data.y, mag_data.x) * 180 / M_PI;

    // Adjust heading to be between 0 and 360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

