#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Register addresses
#define DATA_REG 0x01
#define CONTROL_REG 0x00

// Sampling interval (10 ms)
#define SAMPLING_INTERVAL_US 10000

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int init_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int16_t *data);
int calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
void log_data(FILE *fp, int16_t sensor1_data, int16_t sensor2_data, int16_t tdoa);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    int16_t tdoa;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the sensor
int init_sensor(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, CONTROL_REG, 0x80) != 0) {
        fprintf(stderr, "Error: Failed to write to control register (address 0x%02X): %s\n", CONTROL_REG, strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_sensor_data(int i2c_handle, int16_t *data) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, 2) != 2) {
        fprintf(stderr, "Error: Failed to read data from sensor (address 0x%02X): %s\n", DATA_REG, strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buffer[0] << 8) | buffer[1]);

    return 0;
}

// Calculate TDOA
int calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return sensor1_data - sensor2_data;
}

// Log data to file
void log_data(FILE *fp, int16_t sensor1_data, int16_t sensor2_data, int16_t tdoa) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus 1
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 1 at address 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 2 at address 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Error: Failed to initialize sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }
    if (init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error: Failed to initialize sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t sensor1_data, sensor2_data, tdoa;
    struct timespec ts;
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &sensor1_data) != 0) {
            fprintf(stderr, "Error: Failed to read sensor 1 data, retrying...\n");
            nanosleep(&(struct timespec){0, SAMPLING_INTERVAL_US * 1000000}, NULL); // Wait before retrying
            continue;
        }
        if (read_sensor_data(i2c_handle2, &sensor2_data) != 0) {
            fprintf(stderr, "Error: Failed to read sensor 2 data, retrying...\n");
            nanosleep(&(struct timespec){0, SAMPLING_INTERVAL_US * 1000000}, NULL); // Wait before retrying
            continue;
        }

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log data
        log_data(log_file, sensor1_data, sensor2_data, tdoa);

        // Wait for the next sample
        nanosleep(&(struct timespec){0, SAMPLING_INTERVAL_US * 1000000}, NULL);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

