#define SPI_FLAGS 0x80 // CPOL=1, CPHA=1, no auxiliary SPI

// Sensitivity Values
#define GYRO_SENSITIVITY 0.005 // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// Global Variables
static int spi_handle;
static FILE *fp;
static volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function Prototypes
int spi_transfer(int handle, uint8_t msb, uint8_t lsb, uint8_t data);
int read_register(int handle, uint8_t address, uint16_t *data);
imu_data_t process_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z);
int log_data(FILE *fp, imu_data_t data);
void cleanup(int signum);
void signal_handler(int signum);

// Function to transfer data over SPI
int spi_transfer(int handle, uint8_t msb, uint8_t lsb, uint8_t data) {
    char tx[4];
    char rx[4];

    tx[0] = msb;
    tx[1] = lsb;
    tx[2] = data;
    tx[3] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 4) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    return 0;
}

// Function to read a register from the ADIS16488A
int read_register(int handle, uint8_t address, uint16_t *data) {
    uint8_t msb, lsb;

    // Send MSB and LSB of the register address
    msb = address & 0xFF;
    lsb = (address >> 8) & 0xFF;

    if (spi_transfer(handle, msb, lsb, 0x00) != 0) {
        fprintf(stderr, "Failed to send register address\n");
        return -1;
    }

    // Read the 16-bit data
    if (spi_transfer(handle, msb, lsb, 0x00) != 0) {
        fprintf(stderr, "Failed to read register data\n");
        return -1;
    }

    *data = (uint16_t)spi_transfer(handle, msb, lsb, 0x00);
    return 0;
}

// Function to process raw data and convert to physical units
imu_data_t process_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z) {
    imu_data_t data;

    data.gyro_x = (float)gyro_x * GYRO_SENSITIVITY;
    data.gyro_y = (float)gyro_y * GYRO_SENSITIVITY;
    data.gyro_z = (float)gyro_z * GYRO_SENSITIVITY;
    data.accel_x = (float)accel_x * ACCEL_SENSITIVITY;
    data.accel_y = (float)accel_y * ACCEL_SENSITIVITY;
    data.accel_z = (float)accel_z * ACCEL_SENSITIVITY;

    return data;
}

// Function to log data to a CSV file
int log_data(FILE *fp, imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }

    return 0;
}

// Cleanup function to close SPI and file, terminate pigpio
void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        imu_data_t data;

        // Read gyroscope data
        if (read_register(spi_handle, X_GYRO, &gyro_x) != 0) {
            fprintf(stderr, "Failed to read gyro X\n");
            continue; // Skip to the next iteration
        }
        if (read_register(spi_handle, Y_GYRO, &gyro_y) != 0) {
            fprintf(stderr, "Failed to read gyro Y\n");
            continue; // Skip to the next iteration
        }
        if (read_register(spi_handle, Z_GYRO, &gyro_z) != 0) {
            fprintf(stderr, "Failed to read gyro Z\n");
            continue; // Skip to the next iteration
        }

        // Read accelerometer data
        if (read_register(spi_handle, X_ACCEL, &accel_x) != 0) {
            fprintf(stderr, "Failed to read accel X\n");
            continue; // Skip to the next iteration
        }
        if (read_register(spi_handle, Y_ACCEL, &accel_y) != 0) {
            fprintf(stderr, "Failed to read accel Y\n");
            continue; // Skip to the next iteration
        }
        if (read_register(spi_handle, Z_ACCEL, &accel_z) != 0) {
            fprintf(stderr, "Failed to read accel Z\n");
            continue; // Skip to the next iteration
        }

        // Process data
        data = process_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Log data
        if (log_data(fp, data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    cleanup(0);

    return 0;
}

