#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to read data from ADIS16448
int read_adis16448(int spi_handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the read command (register address with bit 15 set)
    tx_buf[0] = (reg_addr << 1) | 0x80; // MSB = 1 for read
    tx_buf[1] = 0x0000; // Dummy data for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(int16_t raw_data) {
    sensor_data_t data;
    data.gyro_x = (float)raw_data * GYRO_SCALE;
    data.gyro_y = (float)raw_data * GYRO_SCALE;
    data.gyro_z = (float)raw_data * GYRO_SCALE;
    data.accel_x = (float)raw_data * ACCL_SCALE;
    data.accel_y = (float)raw_data * ACCL_SCALE;
    data.accel_z = (float)raw_data * ACCL_SCALE;
    return data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
        int16_t accel_x_raw, accel_y_raw, accel_z_raw;

        // Read gyroscope data
        if (read_adis16448(spi_handle, X_GYRO_OUT, &gyro_x_raw) != 0) {
            fprintf(stderr, "Failed to read gyro X\n");
            continue; // Skip to the next iteration
        }
        if (read_adis16448(spi_handle, Y_GYRO_OUT, &gyro_y_raw) != 0) {
            fprintf(stderr, "Failed to read gyro Y\n");
            continue; // Skip to the next iteration
        }
        if (read_adis16448(spi_handle, Z_GYRO_OUT, &gyro_z_raw) != 0) {
            fprintf(stderr, "Failed to read gyro Z\n");
            continue; // Skip to the next iteration
        }

