#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6886 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B

// I2C Bus
#define I2C_BUS 1

// Global variables for I2C file descriptor and program termination
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    int retries = 3;
    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    int retries = 3;
    while (retries > 0) {
        if (write(fd, buf, 1) == 1) {
            if (read(fd, value, 1) == 1) {
                return 0; // Success
            } else {
                perror("I2C read failed");
                retries--;
                usleep(10000); // Wait 10ms before retrying
            }
        } else {
            perror("I2C write (for register selection) failed");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to verify the WHO_AM_I register
int verify_who_am_i(int fd) {
    uint8_t who_am_i;
    if (i2c_read_reg(fd, 0x75, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != 0x86) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x86.\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I register verified.\n");
    return 0;
}

// Function to initialize the MPU-6886
int init_mpu6886(int fd) {
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) { // Wake up the sensor
        fprintf(stderr, "Failed to wake up MPU-6886.\n");
        return -1;
    }
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) != 0) { // Set accelerometer range to +-2g
        fprintf(stderr, "Failed to set accelerometer range.\n");
        return -1;
    }
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) != 0) { // Set gyroscope range to +-250 dps
        fprintf(stderr, "Failed to set gyroscope range.\n");
        return -1;
    }
    printf("MPU-6886 initialized successfully.\n");
    return 0;
}

// Function to read accelerometer data
int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    int retries = 3;
    while (retries > 0) {
        if (write(fd, 0x3B, 1) != 1) {
            perror("Failed to write to accelerometer data register");
            retries--;
            usleep(10000);
            continue;
        }
        if (read(fd, data, 6) == 6) {
            *x = (int16_t)((data[0] << 8) | data[1]);
            *y = (int16_t)((data[2] << 8) | data[3]);
            *z = (int16_t)((data[4] << 8) | data[5]);
            return 0;
        } else {
            perror("Failed to read accelerometer data");
            retries--;
            usleep(10000);
        }
    }
    fprintf(stderr, "Failed to read accelerometer data after multiple retries.\n");
    return -1;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    int retries = 3;
    while (retries > 0) {
        if (write(fd, 0x43, 1) != 1) {
            perror("Failed to write to gyroscope data register");
            retries--;
            usleep(10000);
            continue;
        }
        if (read(fd, data, 6) == 6) {
            *x = (int16_t)((data[0] << 8) | data[1]);
            *y = (int16_t)((data[2] << 8) | data[3]);
            *z = (int16_t)((data[4] << 8) | data[5]);
            return 0;
        } else {
            perror("Failed to read gyroscope data");
            retries--;
            usleep(10000);
        }
    }
    fprintf(stderr, "Failed to read gyroscope data after multiple retries.\n");
    return -1;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x68) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 not found. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;

    while (!terminate) {
        // Read accelerometer data
        if (read_accel_data(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            // Read gyroscope data
            if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
                // Print the raw data
                printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                       accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
            } else {
                fprintf(stderr, "Failed to read gyroscope data in main loop.\n");
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data in main loop.\n");
        }

        usleep(50000); // 50ms delay
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

