#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_STATUS 0x0B
#define ADXL345_BW_RATE 0x2C
#define ADXL345_RANGE 0x31

// GPIO pin for LED
#define LED_PIN 17

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.5

// Full resolution mode
#define FULL_RESOLUTION 0x08

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
void control_led(int state);
void log_impact(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the ADXL345 accelerometer
int initialize_adxl345() {
    // Set data rate to 100 Hz and full resolution mode
    if (i2cWriteByteData(i2c_handle, ADXL345_BW_RATE, 0x0A) < 0) { // 100 Hz
        fprintf(stderr, "Error writing to BW_RATE register\n");
        return -1;
    }

    // Set range to +-2g
    if (i2cWriteByteData(i2c_handle, ADXL345_RANGE, FULL_RESOLUTION) < 0) {
        fprintf(stderr, "Error writing to RANGE register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, FULL_RESOLUTION) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Reads accelerometer data from the ADXL345
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    // Read all six bytes at once
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

