#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define ACCEL_RANGE 2.0f // +-2g range
#define ACCEL_SCALE 1024.0f // Counts per g
#define ACCEL_THRESHOLD 2.0f
#define LED_GPIO 17 // BCM numbering
#define LED_ON_TIME 500 // milliseconds
#define LOG_FILE "impact_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mma8451q(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int log_impact(float x, float y, float z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Initialize MMA8451Q sensor
int init_mma8451q(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x1A) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x1A\n", who_am_i);
        return -1;
    }

    // Set CTRL_REG1 to active mode and +-2g range
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) { // Active mode, 100 Hz ODR, +-2g range
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from MMA8451Q
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
    int16_t x_raw, y_raw, z_raw;

    x_msb = i2c_read_reg(fd, OUT_X_MSB);
    x_lsb = i2c_read_reg(fd, OUT_X_LSB);
    y_msb = i2c_read_reg(fd, OUT_Y_MSB);
    y_lsb = i2c_read_reg(fd, OUT_Y_LSB);
    z_msb = i2c_read_reg(fd, OUT_Z_MSB);
    z_lsb = i2c_read_reg(fd, OUT_Z_LSB);

    if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
        fprintf(stderr, "Error reading acceleration registers\n");
        return -1;
    }

    x_raw = (int16_t)((x_msb << 8) | x_lsb);
    y_raw = (int16_t)((y_msb << 8) | y_lsb);
    z_raw = (int16_t)((z_msb << 8) | z_lsb);

    // Convert to g-force units
    *x = (float)x_raw / ACCEL_SCALE;
    *y = (float)y_raw / ACCEL_SCALE;
    *z = (float)z_raw / ACCEL_SCALE;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact event to file
int log_impact(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8451Q sensor
    if (init_mma8451q(i2c_fd) < 0) {
        fprintf(stderr, "MMA8451Q initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    float x, y, z, magnitude;
    int led_state = 0;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue; // Continue to the next iteration
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(x, y, z);

        // Check for impact
        if (magnitude > ACCEL_THRESHOLD) {
            if (!led_state) {
                // Turn on LED
                if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
                    perror("Failed to set LED GPIO mode");
                    continue;
                }
                gpioWrite(LED_GPIO, 1);
                led_state = 1;

                // Log impact
                if (log_impact(x, y, z) < 0) {
                    fprintf(stderr, "Failed to log impact\n");
                }

                // Wait for LED ON time
                usleep(LED_ON_TIME * 1000); // Convert milliseconds to microseconds

                // Turn off LED
                gpioWrite(LED_GPIO, 0);
                led_state = 0;
            }
        }

        // Delay
        usleep(100000); // 100 ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

