#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// TMAG5273 I2C address
#define TMAG5273_ADDR 0x35

// Register addresses
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);
int setup_i2c(int address);
int setup_log_file(const char *filename);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading register: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    int x, y, z;

    x = i2c_read_reg(fd, X_REG);
    if (x == -1) return -1;
    y = i2c_read_reg(fd, Y_REG);
    if (y == -1) return -1;
    z = i2c_read_reg(fd, Z_REG);
    if (z == -1) return -1;

    data->x = (int16_t)((x << 8) | (x >> 8)); // Little-endian
    data->y = (int16_t)((y << 8) | (y >> 8));
    data->z = (int16_t)((z << 8) | (z >> 8));

    return 0;
}

// Log data function
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C setup function
int setup_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// Log file setup function
int setup_log_file(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }
    fseek(fp, 0, SEEK_END); // Reset file pointer to the end for appending

    return fp;
}

int main() {
    sensor_data_t sensor_data;
    const char *log_filename = "magnetic_field_log.csv";

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    i2c_fd = setup_i2c(TMAG5273_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Setup log file
    log_file = setup_log_file(log_filename);
    if (log_file == NULL) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            if (log_data(log_file, sensor_data) != 0) {
                fprintf(stderr, "Error logging data, continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, continuing...\n");
        }
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

