        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// Log file setup function
int setup_log_file(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }
    fseek(fp, 0, SEEK_END); // Reset file pointer to the end for appending

    return fp;
}

int main() {
    sensor_data_t sensor_data;
    const char *log_filename = "magnetic_field_log.csv";

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    i2c_fd = setup_i2c(TMAG5273_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Setup log file
    log_file = setup_log_file(log_filename);
    if (log_file == NULL) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
