int adxl345_read_register(int i2c_fd, uint8_t reg) {
    int value = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error: I2C read error (reg 0x%X): %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
