// Read acceleration data
int adxl345_read_acceleration(int i2c_fd, float *x, float *y, float *z) {
    int16_t x_raw = (int16_t)((adxl345_read_register(i2c_fd, ADXL345_DATAX1) << 8) | adxl345_read_register(i2c_fd, ADXL345_DATAX0));
    int16_t y_raw = (int16_t)((adxl345_read_register(i2c_fd, ADXL345_DATAY1) << 8) | adxl345_read_register(i2c_fd, ADXL345_DATAY0));
    int16_t z_raw = (int16_t)((adxl345_read_register(i2c_fd, ADXL345_DATAZ1) << 8) | adxl345_read_register(i2c_fd, ADXL345_DATAZ0));

