        gpiod_chip_close(gpio_chip);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "freefall_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return 1;
    }

    // I2C Initialization
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed\n");
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Create Event File Descriptor
    char event_path[64];
    snprintf(event_path, sizeof(event_path), "/sys/class/gpio/gpio%d/event", GPIO_PIN);
    int event_fd = open(event_path, O_RDONLY);
    if (event_fd < 0) {
        fprintf(stderr, "Error: Could not open event file: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set up interrupt callback
    struct gpiod_line_event event;
    event.user_data = 0; // Flag to indicate first interrupt

    // Polling Loop
    while (program_running) {
        ssize_t bytes_read = read(event_fd, &event, sizeof(event));
        if (bytes_read > 0) {
            if (event.events & GPIOD_LINE_EVENT_EDGE_FALLING) {
                if (event.user_data == 0) {
                    event.user_data = 1; // Set the flag to indicate the first interrupt
                } else {
                    freefall_callback(&event);
                    event.user_data = 0; // Reset the flag
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error: I/O error reading event file: %s\n", strerror(errno));
            break;
        }
    }

    // Cleanup
    close(event_fd);
    close(i2c_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

