                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error: I/O error reading event file: %s\n", strerror(errno));
            break;
        }
    }

    // Cleanup
    close(event_fd);
    close(i2c_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

