#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Function prototypes
int init_imu();
imu_data_t read_imu_data();
float calculate_acceleration_magnitude(imu_data_t data);
void log_data(imu_data_t data);
void fall_detection(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the IMU
int init_imu() {
    // Configure accelerometer: +-2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 12) < 0) {
        fprintf(stderr, "Error reading IMU data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0;
        return data;
    }

    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps (assuming +/- 2g and +/- 250 dps)
    data.accel_x = (float)raw_accel_x / 16384.0f; // 2^15 = 32768, but we are using 2g range
    data.accel_y = (float)raw_accel_y / 16384.0f;
    data.accel_z = (float)raw_accel_z / 16384.0f;
    data.gyro_x = (float)raw_gyro_x / 131.0f;   // 250 dps / 131 LSB/dps
    data.gyro_y = (float)raw_gyro_y / 131.0f;
    data.gyro_z = (float)raw_gyro_z / 131.0f;

    return data;
}

// Calculate acceleration magnitude
float calculate_acceleration_magnitude(imu_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log data to file
void log_data(imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Fall detection state machine
void fall_detection(imu_data_t data) {
    static time_t freefall_start_time = 0;
    static time_t impact_start_time = 0;
    static int in_freefall = 0;
    static int in_impact = 0;
    time_t current_time;
    float acceleration_magnitude;

    acceleration_magnitude = calculate_acceleration_magnitude(data);

    if (in_freefall) {
        if (acceleration_magnitude < 0.2f) {
            freefall_start_time = 0; // Reset freefall timer
            in_freefall = 0;         // Exit freefall state
            in_impact = 0;          // Reset impact state
        }
    } else if (in_impact) {
        if (acceleration_magnitude > 2.5f) {
            impact_start_time = 0; // Reset impact timer
            in_impact = 0;         // Exit impact state
            in_freefall = 0;         // Reset freefall state
        }
    } else {
        if (acceleration_magnitude < 0.2f) {
            freefall_start_time = time(NULL);
            in_freefall = 1;
        } else if (acceleration_magnitude > 2.5f) {
            impact_start_time = time(NULL);
            in_impact = 1;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (init_imu() < 0) {
        fprintf(stderr, "IMU initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

