#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADIS16266 Register Addresses
#define WHO_AM_I   0x0000
#define X_GYRO_OUT  0x0014
#define GLOB_CMD   0x0000

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    3

// Scaling Factor
#define GYRO_SCALE 0.0305 // deg/sec/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint16_t address);
int spi_write_register(int handle, uint16_t address, uint16_t value);
int verify_who_am_i(int handle);
int read_gyro_data(int handle, float *gyro_rate);
void log_data(float gyro_rate);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint16_t address) {
    char tx[3], rx[3];
    tx[0] = (address & 0x7F) | 0x80; // Set MSB for read
    tx[1] = 0x00; // Dummy byte
    tx[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    return (rx[1] << 8) | rx[2]; // Combine the two bytes
}

// SPI Write Register Function
int spi_write_register(int handle, uint16_t address, uint16_t value) {
    char tx[3], rx[3];
    tx[0] = (address & 0x7F); // Clear MSB for write
    tx[1] = (value >> 8) & 0xFF; // MSB of value
    tx[2] = value & 0xFF; // LSB of value

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Verify WHO_AM_I Register
int verify_who_am_i(int handle) {
    int who_am_i = spi_read_register(handle, WHO_AM_I);
    if (who_am_i == 0x3F5A) {
        printf("WHO_AM_I register verified: 0x%X\n", who_am_i);
        return 0;
    } else {
        fprintf(stderr, "WHO_AM_I register verification failed: 0x%X\n", who_am_i);
        return -1;
    }
}

// Read Gyro Data
int read_gyro_data(int handle, float *gyro_rate) {
    int16_t raw_gyro = spi_read_register(handle, X_GYRO_OUT);
    if (raw_gyro == -1) {
        return -1;
    }
    *gyro_rate = (float)raw_gyro * GYRO_SCALE;
    return 0;
}

// Log Data to File
void log_data(float gyro_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.6f\n", timestamp, gyro_rate);
    fflush(log_file); // Ensure data is written immediately
}

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I
    if (verify_who_am_i(spi_handle) != 0) {
        fprintf(stderr, "ADIS16266 verification failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Gyro Rate (deg/s)\n");
    fflush(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float gyro_rate;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_handle, &gyro_rate) == 0) {
            log_data(gyro_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

