#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Gyroscope I2C address
#define GYRO_ADDRESS 0x69

// Gyroscope registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Sensitivity scale factor
#define SENSITIVITY 8.75

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    while (retries > 0) {
        // Check WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, CTRL_REG1);
        if (who_am_i == 0xD3) {
            printf("WHO_AM_I register read successfully.\n");
            break;
        } else {
            fprintf(stderr, "Error: WHO_AM_I register read failed. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 for normal mode and all axes enabled
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
    if (status != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1. Retrying...\n");
        retries = 3; // Reset retries in case of failure
        while (retries > 0) {
            status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
            if (status == 0) break;
            gpioDelay(100);
            retries--;
        }
        if (retries == 0) {
            fprintf(stderr, "Error: Failed to write CTRL_REG1 after multiple retries.\n");
            return -1;
        }
    }

    // Configure CTRL_REG4 for +-250 dps full-scale range
    status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4. Retrying...\n");
        retries = 3; // Reset retries in case of failure
        while (retries > 0) {
            status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
            if (status == 0) break;
            gpioDelay(100);
            retries--;
        }
        if (retries == 0) {
            fprintf(stderr, "Error: Failed to write CTRL_REG4 after multiple retries.\n");
            return -1;
        }
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int status;

    // Read 6 bytes of data starting from OUT_X_L
    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data. Status: %d\n", status);
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to degrees per second
    data.x = (float)raw_x * SENSITIVITY / 114.285;
    data.y = (float)raw_y * SENSITIVITY / 114.285;
    data.z = (float)raw_z * SENSITIVITY / 114.285;

    return data;
}

// Log gyroscope data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%ld,%f,%f,%f\n", timestamp_ns, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

