#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

static volatile int terminate = 0;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

int main() {
    int flame_detected;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor value
        flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        if (flame_detected == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            fprintf(log_file, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            fflush(log_file);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log event to file
            if (flame_detected == 0) {
                fprintf(log_file, "%s - Flame detected: YES\n", timestamp);
                fflush(log_file);
                printf("FLAME DETECTED!\n");
            } else {
                fprintf(log_file, "%s - Flame detected: NO\n", timestamp);
                fflush(log_file);
            }
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

