#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D

#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read a register from the I2C device
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;

    if (read_register(fd, REG_X_LSB, &x_lsb) < 0) return -1;
    if (read_register(fd, REG_X_MSB, &x_msb) < 0) return -1;
    if (read_register(fd, REG_Y_LSB, &y_lsb) < 0) return -1;
    if (read_register(fd, REG_Y_MSB, &y_msb) < 0) return -1;
    if (read_register(fd, REG_Z_LSB, &z_lsb) < 0) return -1;
    if (read_register(fd, REG_Z_MSB, &z_msb) < 0) return -1;

    data->x = (int16_t)((x_msb << 8) | x_lsb);
    data->y = (int16_t)((y_msb << 8) | y_lsb);
    data->z = (int16_t)((z_msb << 8) | z_lsb);

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

