#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(int pin);
int log_data(int sensor1_state, int sensor2_state);
void handle_signal(int sig);
void cleanup(void);

// Signal handler
void handle_signal(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Error getting sensor 1 line");
        gpiod_chip_close(chip);
        return -1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Error getting sensor 2 line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        perror("Error requesting sensor 1 line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        perror("Error requesting sensor 2 line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    int value = gpiod_line_get_value(sensor1_line ? sensor1_line : sensor2_line);
    if (!value) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Log data to file
int log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Conveyor belt safety system monitoring started.\n");

    // Main loop
    while (!terminate) {
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        log_data(sensor1_state, sensor2_state);

        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Conveyor belt halted!\n");
        }

        usleep(50000); // 50ms
    }

    // Cleanup and exit
    cleanup();
    printf("Conveyor belt safety system monitoring stopped.\n");
    return 0;
}

