#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define DATA_REG 0x01
#define GRAVITY 9.81 // m/s^2
#define PI 3.14159265

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, char *buf, int len);
int mma8452q_init(int fd);
int mma8452q_read_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_fall_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int signum);

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for block read");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Error reading block data");
        return -1;
    }
    return 0;
}

// MMA8452Q initialization function
int mma8452q_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x2A) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x2A\n", who_am_i);
        return -1;
    }

    // Initialize CTRL_REG1
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) { // Standby mode
        fprintf(stderr, "Error setting CTRL_REG1 to standby mode\n");
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x0A) < 0) { // 100 Hz data rate
        fprintf(stderr, "Error setting CTRL_REG1 data rate\n");
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) { // Active mode
        fprintf(stderr, "Error setting CTRL_REG1 to active mode\n");
        return -1;
    }

    return 0;
}

// MMA8452Q read data function
int mma8452q_read_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2c_read_block(fd, DATA_REG, data, 6) < 0) {
        fprintf(stderr, "Error reading data registers\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 4) | (data[0] >> 4));
    *y = (int16_t)((data[3] << 4) | (data[2] >> 4));
    *z = (int16_t)((data[5] << 4) | (data[4] >> 4));

    return 0;
}

// Calculate tilt angle function
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 2048.0f * GRAVITY; // Assuming +/- 2g range
    float y_g = (float)y / 2048.0f * GRAVITY;
    float z_g = (float)z / 2048.0f * GRAVITY;

    float x_angle = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / PI;
    float y_angle = atan2(-y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / PI;
    float z_angle = atan2(-z_g, sqrt(x_g * x_g + y_g * y_g)) * 180.0 / PI;

    return x_angle;
}

// Log fall event function
void log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Raw data: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signum);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, MMA8452Q_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8452Q
    if (mma8452q_init(i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float tilt_angle_x, tilt_angle_y, tilt_angle_z;

    // Main loop
    while (program_running) {
        if (mma8452q_read_data(i2c_fd, &x, &y, &z) == 0) {
            tilt_angle_x = calculate_tilt_angle(x, y, z);
            tilt_angle_y = calculate_tilt_angle(y, x, z);
            tilt_angle_z = calculate_tilt_angle(z, y, x);

            if (fabs(tilt_angle_x) > 45.0 || fabs(tilt_angle_y) > 45.0 || fabs(tilt_angle_z) > 45.0) {
                log_fall_event(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        usleep(10000); // 10 ms loop interval
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

