#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
