// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retrying...\n", reg, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1;
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0;
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s. Retrying...\n", reg, value, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X).\n", reg, value);
    return -1;
}

// Initialize LIS3MDL sensor
int init_lis3mdl(int fd) {
    int retries = 3;
    while (retries > 0) {
        if (i2c_write_reg(fd, CTRL_REG1, 0x70) == 0) { // Continuous-conversion mode, 80 Hz ODR
            if (i2c_write_reg(fd, CTRL_REG4, 0x0C) == 0) { // +-4 gauss sensitivity
                if (i2c_write_reg(fd, CTRL_REG3, 0x00) == 0) { // High-performance mode
                    return 0; // Success
                }
            }
        }
        retries--;
        usleep(100000); // 100ms delay
    }
    fprintf(stderr, "LIS3MDL initialization failed.\n");
    return -1;
}

// Verify WHO_AM_I register
int verify_who_am_i(int fd) {
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != 0x3D) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X (expected 0x3D).\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I value: 0x%02X (OK).\n", who_am_i);
    return 0;
}

// Configure LIS3MDL for continuous-conversion mode and high-performance mode
int configure_lis3mdl(int fd) {
    int retries = 3;
    while (retries > 0) {
        if (i2c_write_reg(fd, CTRL_REG1, 0x70) == 0) { // Continuous-conversion mode, 80 Hz ODR
            if (i2c_write_reg(fd, CTRL_REG4, 0x0C) == 0) { // +-4 gauss sensitivity
                if (i2c_write_reg(fd, CTRL_REG3, 0x00) == 0) { // High-performance mode
                    return 0; // Success
                }
            }
        }
        retries--;
        usleep(100000); // 100ms delay
    }
    fprintf(stderr, "LIS3MDL configuration failed.\n");
    return -1;
}

// Read magnetometer data
int read_magnetometer_data(int fd, magnetometer_data_t *data) {
    int x_l = i2c_read_reg(fd, OUT_X_L);
    int x_h = i2c_read_reg(fd, OUT_X_L + 1);
    int y_l = i2c_read_reg(fd, OUT_X_L + 2);
    int y_h = i2c_read_reg(fd, OUT_X_L + 3);
    int z_l = i2c_read_reg(fd, OUT_X_L + 4);
    int z_h = i2c_read_reg(fd, OUT_X_L + 5);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        fprintf(stderr, "Failed to read magnetometer data.\n");
        return -1;
    }

    data->x = (int16_t)((x_h << 8) | x_l);
    data->y = (int16_t)((y_h << 8) | y_l);
    data->z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Calibrate magnetometer data
void calibrate_data(magnetometer_data_t raw_data, calibration_data_t *calibration_data, magnetometer_data_t *calibrated_data) {
    calibrated_data->x = (int16_t)((raw_data.x - calibration_data->x_offset) * calibration_data->x_scale);
    calibrated_data->y = (int16_t)((raw_data.y - calibration_data->y_offset) * calibration_data->y_scale);
    calibrated_data->z = (int16_t)((raw_data.z - calibration_data->z_offset) * calibration_data->z_scale);
}

// Convert raw data to milliGauss
float convert_to_mG(int16_t raw_value, float x_scale, float y_scale, float z_scale) {
    return (float)raw_value * x_scale * y_scale * z_scale * 0.146; // 0.146 mG/LSB
