// Calculate the magnitude of the magnetic field
float calculate_magnitude(float x_mG, float y_mG, float z_mG) {
    return sqrt(x_mG * x_mG + y_mG * y_mG + z_mG * z_mG);
}

// Log data to file
void log_data(float x_mG, float y_mG, float z_mG) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

