    char rx_buf[2];

    tx_buf[0] = RESET_REG | 0x80; // Write command
    tx_buf[1] = 0x52; // Reset value

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI reset failed\n");
        return -1;
    }

