int adxl354b_set_measurement_mode() {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = POWER_CTL | 0x80; // Write command
    tx_buf[1] = 0x00; // Clear RUN bit

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI mode setting failed (clear RUN bit)\n");
        return -1;
    }

    gpioDelay(1000); // Wait 1 ms

    tx_buf[0] = POWER_CTL | 0x80; // Write command
    tx_buf[1] = 0x01; // Set RUN bit

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
