        return -1;
    }

    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Function to read acceleration data from the ADXL354B
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char tx_buf[7];
    char rx_buf[7];
    int retries = 3;

    // Read XDATA (3 bytes)
    while (retries > 0) {
        tx_buf[0] = 0x08 | 0x80; // Read command for XDATA (MSB first)
        tx_buf[1] = 0x00; // Dummy byte for reading
        tx_buf[2] = 0x00; // Dummy byte for reading
        tx_buf[3] = 0x00; // Dummy byte for reading

        if (spiXfer(spi_handle, tx_buf, rx_buf, 4) == 0) {
            *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Error: SPI read failed (XDATA), retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }
    if (retries == 0) return -1;

    // Read YDATA (3 bytes)
    retries = 3;
    while (retries > 0) {
        tx_buf[0] = 0x0B | 0x80; // Read command for YDATA (MSB first)
        tx_buf[1] = 0x00; // Dummy byte for reading
        tx_buf[2] = 0x00; // Dummy byte for reading
        tx_buf[3] = 0x00; // Dummy byte for reading

