#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.0025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function Prototypes
int spi_read_register(uint8_t address, uint8_t *data);
int spi_write_register(uint8_t address, uint8_t data);
imu_data_t read_imu_data();
void log_imu_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to read a register from the ADIS16362
int spi_read_register(uint8_t address, uint8_t *data) {
    char tx[3];
    char rx[3];

    // Construct the SPI message
    tx[0] = address | 0x80; // Set MSB for read operation
    tx[1] = 0x00; // Dummy byte
    tx[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the data from the response
    *data = rx[1];

    return 0; // Indicate success
}

// Function to write a register in the ADIS16362
int spi_write_register(uint8_t address, uint8_t data) {
    char tx[3];
    char rx[3];

    // Construct the SPI message
    tx[0] = address & 0x7F; // Clear MSB for write operation
    tx[1] = data;
    tx[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    uint8_t x_gyro_data, y_gyro_data, z_gyro_data, x_accel_data, y_accel_data, z_accel_data;

    // Read gyroscope data
    if (spi_read_register(X_GYRO, &x_gyro_data) != 0) {
        data.x_gyro = 0.0; // Set to 0.0 on error
    } else {
        data.x_gyro = (double)((int16_t)x_gyro_data) * GYRO_SCALE;
    }

    if (spi_read_register(Y_GYRO, &y_gyro_data) != 0) {
        data.y_gyro = 0.0; // Set to 0.0 on error
    } else {
        data.y_gyro = (double)((int16_t)y_gyro_data) * GYRO_SCALE;
    }

    if (spi_read_register(Z_GYRO, &z_gyro_data) != 0) {
        data.z_gyro = 0.0; // Set to 0.0 on error
    } else {
        data.z_gyro = (double)((int16_t)z_gyro_data) * GYRO_SCALE;
    }

    // Read accelerometer data
    if (spi_read_register(X_ACCL, &x_accel_data) != 0) {
        data.x_accel = 0.0; // Set to 0.0 on error
    } else {
        data.x_accel = (double)((int16_t)x_accel_data) * ACCL_SCALE;
    }

    if (spi_read_register(Y_ACCL, &y_accel_data) != 0) {
        data.y_accel = 0.0; // Set to 0.0 on error
    } else {
        data.y_accel = (double)((int16_t)y_accel_data) * ACCL_SCALE;
    }

    if (spi_read_register(Z_ACCL, &z_accel_data) != 0) {
        data.z_accel = 0.0; // Set to 0.0 on error
    } else {
        data.z_accel = (double)((int16_t)z_accel_data) * ACCL_SCALE;
    }

    return data;
}

// Function to log IMU data to a file
void log_imu_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%ld,%lf,%lf,%lf,%lf,%lf,%lf\n",
            timestamp_ns, data.x_gyro, data.y_gyro, data.z_gyro,
            data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close SPI and log file
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
