#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 1000

static volatile int keep_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to log a message with a timestamp
void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to simulate self-parking
void self_parking()
{
    log_message("Self-parking sequence started");
    sleep(5);
    log_message("Self-parking sequence completed");
}

int main()
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request the GPIO line for input
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(line, "ir_sensor");
    if (ret < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_message("IR sensor monitoring started");

    // Main loop
    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO line value");
            break; // Exit loop on error
        }

        if (value == 0) { // Obstacle detected (LOW)
            log_message("Obstacle detected!");
            self_parking();
        }

        usleep(POLL_INTERVAL_MS * 1000); // Sleep for 1 second
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    log_message("IR sensor monitoring stopped");

    return 0;
}

