#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

static volatile int keep_running = 1;

// Structure to hold GPIO line information
typedef struct {
    int chip;
    struct gpiod_chip *chip_data;
    struct gpiod_line *sensor1_line;
    struct gpiod_line *sensor2_line;
} gpio_context_t;

// Function to handle Ctrl+C signal
void int_handler(int dummy)
{
    keep_running = 0;
}

// Function to get current timestamp as a string
char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read sensor value
int read_sensor(int gpio_line)
{
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log sensor data
void log_data(int sensor1_value, int sensor2_value)
{
    char* timestamp = get_timestamp();
    printf("%s - Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
}

// Function to request GPIO lines
int request_gpio_lines(gpio_context_t *ctx)
{
    struct gpiod_line_request_config config;

    // Request sensor 1 line
    if (gpiod_line_request_get_values(ctx->chip_data, ctx->sensor1_line, &config) < 0) {
        fprintf(stderr, "Error requesting sensor 1 line: %s\n", strerror(errno));
        return -1;
    }

    // Request sensor 2 line
    if (gpiod_line_request_get_values(ctx->chip_data, ctx->sensor2_line, &config) < 0) {
        fprintf(stderr, "Error requesting sensor 2 line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to release GPIO lines
void release_gpio_lines(gpio_context_t *ctx)
{
    if (ctx->sensor1_line) {
        gpiod_line_release(ctx->sensor1_line);
    }
    if (ctx->sensor2_line) {
        gpiod_line_release(ctx->sensor2_line);
    }
    if (ctx->chip_data) {
        gpiod_chip_close(ctx->chip_data);
    }
}

int main()
{
    gpio_context_t ctx;
    int ret;

    // Initialize GPIO context
    ctx.chip = 0; // GPIO chip number
    ctx.chip_data = NULL;
    ctx.sensor1_line = NULL;
    ctx.sensor2_line = NULL;

    // Register signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Open GPIO chip
    ctx.chip_data = gpiod_chip_open_by_name(GPIOCHIP);
    if (!ctx.chip_data) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines
    ret = request_gpio_lines(&ctx);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        release_gpio_lines(&ctx);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read sensor values
        int sensor1_value = read_sensor(ctx.sensor1_line);
        int sensor2_value = read_sensor(ctx.sensor2_line);

        // Log data
        log_data(sensor1_value, sensor2_value);

        // Wait 100 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&ts, NULL);
    }

    // Release GPIO lines
    release_gpio_lines(&ctx);

    printf("Exiting cleanly.\n");
    return 0;
}

