#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8

// ADIS16266 Register Addresses
#define MSC_CTRL 0x24
#define X_RATE_L 0x04
#define X_RATE_H 0x06
#define Y_RATE_L 0x08
#define Y_RATE_H 0x0A
#define Z_RATE_L 0x0C
#define Z_RATE_H 0x0E

// Global variables
int spi_handle;
int cs_line;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int channel, int speed);
int adis16266_init(int spi_handle);
int adis16266_read_register(int spi_handle, uint8_t address, uint16_t *data);
int adis16266_write_register(int spi_handle, uint8_t address, uint16_t data);
int adis16266_read_gyro_data(int spi_handle, float *x, float *y, float *z);
void signal_handler(int signal);

// SPI Initialization function
int spi_init(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// ADIS16266 Initialization function
int adis16266_init(int spi_handle) {
    // Enable data ready mode
    if (adis16266_write_register(spi_handle, MSC_CTRL, 0x0004) != 0) {
        fprintf(stderr, "Error writing to MSC_CTRL register\n");
        return -1;
    }
    return 0;
}

// ADIS16266 Read Register function
int adis16266_read_register(int spi_handle, uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading
    tx_buf[2] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI read: %d\n", spi_handle);
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// ADIS16266 Write Register function
int adis16266_write_register(int spi_handle, uint8_t address, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI write: %d\n", spi_handle);
        return -1;
    }

    return 0;
}

// ADIS16266 Read Gyro Data function
int adis16266_read_gyro_data(int spi_handle, float *x, float *y, float *z) {
    uint16_t x_raw, y_raw, z_raw;

    if (adis16266_read_register(spi_handle, X_RATE_L, &x_raw) != 0) {
        fprintf(stderr, "Error reading X_RATE_L\n");
        return -1;
    }
    if (adis16266_read_register(spi_handle, X_RATE_H, &x_raw) != 0) {
        fprintf(stderr, "Error reading X_RATE_H\n");
        return -1;
    }
    if (adis16266_read_register(spi_handle, Y_RATE_L, &y_raw) != 0) {
        fprintf(stderr, "Error reading Y_RATE_L\n");
