volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int channel, int speed);
int adis16266_init(int spi_handle);
int adis16266_read_register(int spi_handle, uint8_t address, uint16_t *data);
int adis16266_write_register(int spi_handle, uint8_t address, uint16_t data);
int adis16266_read_gyro_data(int spi_handle, float *x, float *y, float *z);
void signal_handler(int signal);

// SPI Initialization function
int spi_init(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// ADIS16266 Initialization function
int adis16266_init(int spi_handle) {
    // Enable data ready mode
    if (adis16266_write_register(spi_handle, MSC_CTRL, 0x0004) != 0) {
        fprintf(stderr, "Error writing to MSC_CTRL register\n");
        return -1;
    }
    return 0;
}

// ADIS16266 Read Register function
int adis16266_read_register(int spi_handle, uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading
    tx_buf[2] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI read: %d\n", spi_handle);
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
