// LSM6DSR I2C address (7-bit)
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G  0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCtrl+C pressed, exiting gracefully...\n");
}

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x6B)\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

