    *accel_y_g = (float)accel_y_raw * 0.000061;
    *accel_z_g = (float)accel_z_raw * 0.000061;
    *gyro_x_dps = (float)gyro_x_raw * 0.00875;   // Convert to dps
    *gyro_y_dps = (float)gyro_y_raw * 0.00875;
    *gyro_z_dps = (float)gyro_z_raw * 0.00875;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    int16_t accel_x_raw, accel_y_raw, accel_z_raw;
    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
    float accel_x_g, accel_y_g, accel_z_g;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    // Main loop
    while (!terminate) {
