        if (read_accel_gyro_data(&accel_x_raw, &accel_y_raw, &accel_z_raw, &gyro_x_raw, &gyro_y_raw, &gyro_z_raw) == 0) {
            // Convert raw data to physical units
            convert_data(accel_x_raw, accel_y_raw, accel_z_raw, gyro_x_raw, gyro_y_raw, gyro_z_raw, &accel_x_g, &accel_y_g, &accel_z_g, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Print the data
            printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g  |  Gyro: X=%.4f dps, Y=%.4f dps, Z=%.4f dps\n",
                   accel_x_g, accel_y_g, accel_z_g, gyro_x_dps, gyro_y_dps, gyro_z_dps);
