#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 register addresses
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0D);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer and magnetometer
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) { // Active mode, 100 Hz ODR
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) { // +/- 2g range
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, M_CTRL_REG1, 0x1F) < 0) { // Hybrid mode, 100 Hz ODR
        fprintf(stderr, "Error writing to M_CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, M_CTRL_REG2, 0x20) < 0) { // Hybrid mode
        fprintf(stderr, "Error writing to M_CTRL_REG2\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and magnetometer data
int read_fxos8700_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB for accelerometer data
    *accel_x = (int16_t)((buffer[0] << 6) | (buffer[1] >> 2));
    *accel_y = (int16_t)((buffer[2] << 6) | (buffer[3] >> 2));
    *accel_z = (int16_t)((buffer[4] << 6) | (buffer[5] >> 2));

    // Combine MSB and LSB for magnetometer data
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

