#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define POWER_CTL   0x2D
#define DATA_FORMAT 0x31
#define DATAX0      0x32
#define DATAX1      0x33
#define DATAY0      0x34
#define DATAY1      0x35
#define DATAZ0      0x36
#define DATAZ1      0x37

// I2C Device File
#define I2C_DEVICE "/dev/i2c-1"

// Log File
#define LOG_FILE "/var/log/tilt_events.log"

// Tilt Threshold (degrees)
#define TILT_THRESHOLD 30.0

// Global Variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int adxl345_init(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_x(int16_t x, int16_t y, int16_t z);
double calculate_tilt_y(int16_t x, int16_t y, int16_t z);
double calculate_tilt_z(int16_t x, int16_t y, int16_t z);
int log_tilt_event(double angle);
void signal_handler(int sig);

// I2C Read Function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C Write Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// ADXL345 Initialization Function
int adxl345_init(int fd) {
    // Set DATA_FORMAT register to enable measurement mode and set full resolution
    if (i2c_write_reg(fd, DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Failed to set DATA_FORMAT register.\n");
        return -1;
    }

    // Set POWER_CTL register to enable measurement
    if (i2c_write_reg(fd, POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to set POWER_CTL register.\n");
        return -1;
    }

    return 0;
}

// Read Accelerometer Data Function
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (write(fd, (char[]){DATAX0, DATAX1, DATAY0, DATAY1, DATAZ0, DATAZ1}, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    buf[0] = DATAX0;
    buf[1] = DATAX1;
    buf[2] = DATAY0;
    buf[3] = DATAY1;
    buf[4] = DATAZ0;
    buf[5] = DATAZ1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate Tilt Angle X Function
double calculate_tilt_x(int16_t x, int16_t y, int16_t z) {
    return atan2(x, sqrt(y * y + z * z)) * 180.0 / M_PI;
}

// Calculate Tilt Angle Y Function
double calculate_tilt_y(int16_t x, int16_t y, int16_t z) {
    return atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
}

// Calculate Tilt Angle Z Function
double calculate_tilt_z(int16_t x, int16_t y, int16_t z) {
    return atan2(z, sqrt(x * x + y * y)) * 180.0 / M_PI;
}

// Log Tilt Event Function
int log_tilt_event(double angle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int16_t x, y, z;
    double tilt_x, tilt_y, tilt_z;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(stdout, "ADXL345 tilt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        ret = read_accelerometer_data(i2c_fd, &x, &y, &z);
        if (ret != 0) {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate tilt angles
        tilt_x = calculate_tilt_x(x, y, z);
        tilt_y = calculate_tilt_y(x, y, z);
        tilt_z = calculate_tilt_z(x, y, z);

        // Log tilt events
        if (fabs(tilt_x) > TILT_THRESHOLD || fabs(tilt_y) > TILT_THRESHOLD || fabs(tilt_z) > TILT_THRESHOLD) {
            log_tilt_event(tilt_x);
        }

        // Print tilt angles to console
        printf("Tilt X: %.2f, Tilt Y: %.2f, Tilt Z: %.2f\n", tilt_x, tilt_y, tilt_z);

        // Wait 100ms
        usleep(100000);
    }

    // Cleanup
    fprintf(stdout, "Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    fprintf(stdout, "Exiting.\n");
    return 0;
}

