#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define THRESHOLD 5
#define SAMPLE_WINDOW_MS 5000
#define ALERT_DURATION_MS 1000

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold = 0;
    int high_count = 0;
    time_t start_time, current_time;
    double elapsed_time;
    int i;

    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    // Validate the threshold
    char *endptr;
    long val = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || val <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
        return 1;
    }

    threshold = (int)val;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin mode
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        time(&start_time);
        high_count = 0;
        elapsed_time = 0.0;

        // Sample GPIO pin for 5 seconds
        for (i = 0; i < SAMPLE_WINDOW_MS / 1000; i++) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(100); // 100 ms delay
            elapsed_time += 0.1;
        }

        // Check if threshold is exceeded
        if (high_count >= threshold) {
            time(&current_time);
            double time_elapsed = difftime(current_time, start_time);
            printf("%s ALERT: Threshold exceeded (%d high readings in %f seconds)\n", ctime(&current_time), high_count, time_elapsed);
        } else {
            time(&current_time);
            double time_elapsed = difftime(current_time, start_time);
            printf("%s Status: %d high readings in %f seconds\n", ctime(&current_time), high_count, time_elapsed);
        }

        // Pause for 1 second
        gpioDelay(SAMPLE_WINDOW_MS);
    }

    // Terminate pigpio
    gpioTerminate();
    return 0;
}

