#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE_2 0x21
#define MAX_RETRIES 3

int i2c_fd = -1; // Global file descriptor for I2C
FILE *log_file = NULL; // Global file pointer for log file

// Function to handle Ctrl+C signal
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Function to write a command to the BH1750 sensor
int bh1750_write_command(int fd, uint8_t command) {
    uint8_t buf[1];
    buf[0] = command;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(fd, buf, 1) == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing command 0x%02X: %s. Retrying...\n", command, strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to write command 0x%02X after %d retries.\n", command, MAX_RETRIES);
    return -1; // Failure
}

// Function to read data from the BH1750 sensor
int bh1750_read_data(int fd, uint8_t *data) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(fd, data, 2) == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading data: %s. Retrying...\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to read data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to calculate illuminance in lux
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value * 5.0 / 6.0;
}

// Function to log data to a file
int log_data(FILE *fp, float lux_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t data[2];
        uint16_t raw_value;
        float lux_value;

        // Write command to start high-resolution mode 2
        if (bh1750_write_command(i2c_fd, ONE_TIME_HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Error writing command to BH1750.\n");
            break; // Exit loop on error
        }

        // Wait for the maximum conversion time (180ms)
        usleep(180000); // 180ms = 180000 microseconds

        // Read data from the sensor
        if (bh1750_read_data(i2c_fd, data) < 0) {
            fprintf(stderr, "Error reading data from BH1750.\n");
            break; // Exit loop on error
        }

        // Combine the two bytes into a 16-bit value
        raw_value = (data[0] << 8) | data[1];

        // Calculate illuminance in lux
        lux_value = calculate_lux(raw_value);

        // Log the data
        if (log_data(log_file, lux_value) < 0) {
            fprintf(stderr, "Error logging data.\n");
            break; // Exit loop on error
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus and log file before exiting
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

