    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t data[2];
        uint16_t raw_value;
        float lux_value;

        // Write command to start high-resolution mode 2
        if (bh1750_write_command(i2c_fd, ONE_TIME_HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Error writing command to BH1750.\n");
            break; // Exit loop on error
        }

        // Wait for the maximum conversion time (180ms)
        usleep(180000); // 180ms = 180000 microseconds

        // Read data from the sensor
        if (bh1750_read_data(i2c_fd, data) < 0) {
            fprintf(stderr, "Error reading data from BH1750.\n");
            break; // Exit loop on error
        }

        // Combine the two bytes into a 16-bit value
        raw_value = (data[0] << 8) | data[1];

        // Calculate illuminance in lux
        lux_value = calculate_lux(raw_value);

        // Log the data
        if (log_data(log_file, lux_value) < 0) {
            fprintf(stderr, "Error logging data.\n");
            break; // Exit loop on error
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus and log file before exiting
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

