#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SERVER_PORT 12345
#define SECRET_KEY "MySecretKey"
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_data();
void play_tone(int frequency);
void log_frequency(int frequency);
void handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: MPR121 electrode config failed\n");
        return -1;
    }

    // Set touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: MPR121 touch threshold setting failed\n");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: MPR121 release threshold setting failed\n");
            return -1;
        }
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data() {
    char touch_status[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, touch_status, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    return (touch_status[1] << 8) | touch_status[0];
}

// Function to play a tone using hardware PWM
void play_tone(int frequency) {
    if (frequency <= 0) return; // Avoid division by zero

    // Calculate PWM duty cycle (adjust as needed for your speaker)
    int duty_cycle = (int)((float)frequency / PWM_FREQUENCY * PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to log the frequency to a file
void log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Frequency: %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    // Receive message from client
    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread > 0) {
        buffer[valread] = '\0'; // Null-terminate the received string

        // Check if the message starts with 'MOTION_DETECTED:'
        if (strncmp(buffer, "MOTION_DETECTED:", 17) == 0) {
            // Extract the shared secret key
            char *key = strstr(buffer, SECRET_KEY);
            if (key != NULL) {
                // Verify the shared secret key
                if (strcmp(key, SECRET_KEY) == 0) {
                    printf("Shared secret key verified!\n");

                    // Generate a random frequency based on touch data
                    int touch_data = read_touch_data();
                    if (touch_data >= 0) {
                        int frequency = (int)(220 * (1 + (float)touch_data / 4095) * (880 / 220)); // Logarithmic scale
                        if (frequency >= 220 && frequency <= 880) {
                            play_tone(frequency);
                            log_frequency(frequency);
                        } else {
                            fprintf(stderr, "Error: Frequency out of range\n");
                        }
                    } else {
                        fprintf(stderr, "Error: Failed to read touch data for frequency generation\n");
                    }
                } else {
                    fprintf(stderr, "Error: Invalid shared secret key\n");
                }
            } else {
                fprintf(stderr, "Error: Secret key not found in message\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid message format\n");
        }
    } else if (valread == 0) {
        printf("Client disconnected\n");
    } else {
        perror("recv failed");
    }

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to stop PWM and close resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop PWM
    gpioPWM(PWM_GPIO, 0);

    // Close I2C
    i2cClose(i2c_handle);

    // Close socket
    if (new_socket > 0) close(new_socket);
    if (server_fd > 0) close(server_fd);

    // Close log file
    if (log_file != NULL) fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM GPIO as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    // Accept connections in a loop
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len);
        if (new_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        handle_client(new_socket);
    }

    cleanup();
    return 0;
}

