#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x09
#define OUT_Y_L_M 0x0A
#define OUT_Y_H_M 0x0B
#define OUT_Z_L_M 0x0C
#define OUT_Z_H_M 0x0D

// GPIO pin for LED control
#define LED_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t z);
int set_led_brightness(int brightness);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize the LSM303DLHC magnetometer
int init_magnetometer(int fd) {
    int result = i2c_smbus_write_byte_data(fd, CTRL_REG1_M, 0x18); // Continuous conversion mode, 10 Hz
    if (result < 0) {
        syslog(LOG_ERR, "Failed to write to CTRL_REG1_M: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int result = i2c_smbus_read_i2c_block_data(fd, OUT_X_L_M, (char *)buffer, 6);
    if (result < 0) {
        syslog(LOG_ERR, "Failed to read magnetometer data: %s", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate the magnitude of the Z-axis magnetic field
float calculate_magnitude(int16_t z) {
    return (float)z * 0.1; // Convert to Gauss (adjust scaling as needed)
}

// Set LED brightness using hardware PWM
int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;

    int on_time = (int)(((float)brightness / 100.0) * 1000000.0); // Convert percentage to microseconds
    int off_time = 1000000 - on_time;

    if (gpiod_line_set_value(led_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set LED line high: %s", strerror(errno));
        return -1;
    }
    usleep(on_time);

    if (gpiod_line_set_value(led_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set LED line low: %s", strerror(errno));
        return -1;
    }
    usleep(off_time);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    closelog();
}

