    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LSM303_ADDR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize I2C, exiting");
        cleanup();
        return 1;
    }

