        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(z);

            // Map magnitude to brightness (0-100)
            brightness = (int)(magnitude / 10.0); // Adjust scaling as needed

