#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    int16_t x_offset;
    int16_t y_offset;
    int16_t z_offset;
} hard_iron_offsets_t;

// Function prototypes
int initialize_hmc5883l();
magnetometer_data_t read_magnetometer_data();
void apply_hard_iron_offsets(magnetometer_data_t data, hard_iron_offsets_t offsets);
void print_magnetometer_data(magnetometer_data_t data, hard_iron_offsets_t offsets);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configure register A: Gain = 1.3 Gauss, 8 samples averaging
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", HMC5883L_CONFIG_A);
        return -1;
    }

    // Configure register B: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", HMC5883L_CONFIG_B);
        return -1;
    }

    // Configure register C: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", HMC5883L_MODE);
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to apply hard-iron offsets
void apply_hard_iron_offsets(magnetometer_data_t data, hard_iron_offsets_t offsets) {
    data.x -= offsets.x_offset;
    data.y -= offsets.y_offset;
    data.z -= offsets.z_offset;
}

// Function to print magnetometer data
void print_magnetometer_data(magnetometer_data_t data, hard_iron_offsets_t offsets) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Hard-iron offsets (initial values)
    hard_iron_offsets_t offsets = {0, 0, 0};

    // Running average window size
    int window_size = 100;

    // Running average buffers
    int16_t x_buffer[window_size] = {0};
    int16_t y_buffer[window_size] = {0};
    int16_t z_buffer[window_size] = {0};
    int buffer_index = 0;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Apply hard-iron offsets
        apply_hard_iron_offsets(data, offsets);

        // Update running average buffers
        x_buffer[buffer_index] = data.x;
        y_buffer[buffer_index] = data.y;
        z_buffer[buffer_index] = data.z;
        buffer_index = (buffer_index + 1) % window_size;

        // Calculate running average offsets
        int16_t x_sum = 0;
        int16_t y_sum = 0;
        int16_t z_sum = 0;
        for (int i = 0; i < window_size; i++) {
            x_sum += x_buffer[i];
            y_sum += y_buffer[i];
            z_sum += z_buffer[i];
        }
        offsets.x_offset = x_sum / window_size;
        offsets.y_offset = y_sum / window_size;
        offsets.z_offset = z_sum / window_size;

        // Print magnetometer data
        print_magnetometer_data(data, offsets);

        // Delay for 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

