#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// LSM303D Registers
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG4    0x23
#define OUT_X_L_A    0x28
#define INT1_CFG     0x30

// Configuration
#define I2C_BUS       "/dev/i2c-1"
#define LSM303D_ADDR  0x1D
#define GPIO_PIN      23
#define SAMPLE_RATE   50 // Hz
#define BUFFER_SIZE   64
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

// Global Variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile bool running = true;
static float x_buffer[BUFFER_SIZE];
static float y_buffer[BUFFER_SIZE];
static float z_buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_lsm303d(int fd);
void configure_accelerometer(int fd);
void configure_interrupt(int fd);
void interrupt_handler(int line, struct gpiod_line_event *event);
void signal_handler(int sig);
void dump_buffer();

// I2C Read Function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C Write Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// LSM303D Initialization Function
int init_lsm303d(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (configure_accelerometer(fd) != 0) {
        fprintf(stderr, "Accelerometer configuration failed\n");
        return -1;
    }

    // Configure interrupt
    if (configure_interrupt(fd) != 0) {
        fprintf(stderr, "Interrupt configuration failed\n");
        return -1;
    }

    return 0;
}

// Accelerometer Configuration Function
int configure_accelerometer(int fd) {
    // CTRL_REG1: 0x57 for 50 Hz ODR, all axes enabled
    if (i2c_write_reg(fd, CTRL_REG1, 0x57) != 0) {
        return -1;
    }

    // CTRL_REG4: +-2g full-scale
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) != 0) {
        return -1;
    }

    return 0;
}

// Interrupt Configuration Function
void configure_interrupt(int fd) {
    // Set interrupt threshold (2000 mg = 125)
    if (i2c_write_reg(fd, INT1_CFG, 0x7D) != 0) {
        fprintf(stderr, "Failed to set interrupt threshold\n");
    }
}

// Interrupt Handler Function
void interrupt_handler(int line, struct gpiod_line_event *event) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s - Interrupt triggered! Dumping buffer...\n", buf);

    // Dump the last 10 samples from the circular buffer
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
