void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning

    // De-energize both solenoids
    if (solenoid1_line) {
        if (gpiod_line_set_value(solenoid1_line, 0) < 0) {
            fprintf(stderr, "Error: Failed to de-energize solenoid 1: %s\n", strerror(errno));
        }
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        if (gpiod_line_set_value(solenoid2_line, 0) < 0) {
            fprintf(stderr, "Error: Failed to de-energize solenoid 2: %s\n", strerror(errno));
        }
        gpiod_line_release(solenoid2_line);
    }

    // Release GPIO lines
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit the program
    exit(0);
}

