    if (gpiod_line_request_output(solenoid1_line, "solenoid1", 0) < 0) {
        fprintf(stderr, "Error: Failed to request solenoid 1 line for output: %s\n", strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(solenoid2_line, "solenoid2", 0) < 0) {
        fprintf(stderr, "Error: Failed to request solenoid 2 line for output: %s\n", strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // De-energize both solenoids initially
    if (gpiod_line_set_value(solenoid1_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to de-energize solenoid 1 initially: %s\n", strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(solenoid2_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to de-energize solenoid 2 initially: %s\n", strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Energize solenoid 1
        if (gpiod_line_set_value(solenoid1_line, 1) < 0) {
            fprintf(stderr, "Error: Failed to energize solenoid 1: %s\n", strerror(errno));
            break; // Exit loop on error
        }
        nanosleep(&(struct timespec){0, 500000000}, NULL); // 500 ms

        // De-energize solenoid 1
        if (gpiod_line_set_value(solenoid1_line, 0) < 0) {
            fprintf(stderr, "Error: Failed to de-energize solenoid 1: %s\n", strerror(errno));
            break; // Exit loop on error
        }
        nanosleep(&(struct timespec){0, 500000000}, NULL); // 500 ms

        // Energize solenoid 2
        if (gpiod_line_set_value(solenoid2_line, 1) < 0) {
            fprintf(stderr, "Error: Failed to energize solenoid 2: %s\n", strerror(errno));
            break; // Exit loop on error
        }
        nanosleep(&(struct timespec){0, 500000000}, NULL); // 500 ms

        // De-energize solenoid 2
        if (gpiod_line_set_value(solenoid2_line, 0) < 0) {
            fprintf(stderr, "Error: Failed to de-energize solenoid 2: %s\n", strerror(errno));
            break; // Exit loop on error
        }
        nanosleep(&(struct timespec){0, 500000000}, NULL); // 500 ms
    }

    // Release GPIO lines (should not reach here under normal operation due to signal handler)
    if (solenoid1_line) {
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        gpiod_line_release(solenoid2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

