#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for the door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define the expected 6-digit code
#define EXPECTED_CODE "123456"

// Define the timeout for each serial port (in seconds)
#define TIMEOUT_SEC 5

// Global variables for serial file descriptors
int serial_fd1 = -1;
int serial_fd2 = -1;

// Function prototypes
int init_gpio();
int init_serial(int port);
int read_code(int fd, char *code, int code_len);
int validate_code(const char *code, const char *expected_code);
int unlock_doors();
int lock_doors();
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int lock1_gpio;
    int lock2_gpio;
    const char *expected_code;
    int timeout_sec;
} config_t;

// Global configuration
config_t config = {LOCK1_GPIO, LOCK2_GPIO, EXPECTED_CODE, TIMEOUT_SEC};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio. Exiting.\n");
        return 1;
    }

    // Initialize the serial ports
    if (init_serial("/dev/serial0") != 0) {
        fprintf(stderr, "Error initializing serial port /dev/serial0. Exiting.\n");
        gpioTerminate();
        return 1;
    }
    if (init_serial("/dev/serial1") != 0) {
        fprintf(stderr, "Error initializing serial port /dev/serial1. Exiting.\n");
        close(serial_fd1);
        gpioTerminate();
        return 1;
    }

    // Main loop
    char code1[7] = {0}; // Buffer to store the code from serial port 1
    char code2[7] = {0}; // Buffer to store the code from serial port 2
    int code1_index = 0;
    int code2_index = 0;
    int lock1_state = 0; // 0 = locked, 1 = unlocked
    int lock2_state = 0;

    while (1) {
        // Read code from serial port 1
        if (read_code(serial_fd1, code1, sizeof(code1)) == 0) {
            code1_index = 0; // Reset index after reading
        } else {
            // Handle timeout or error
            fprintf(stderr, "Timeout or error reading from serial port 1.\n");
            code1_index = 0; // Reset index
        }

        // Read code from serial port 2
        if (read_code(serial_fd2, code2, sizeof(code2)) == 0) {
            code2_index = 0; // Reset index after reading
        } else {
            // Handle timeout or error
            fprintf(stderr, "Timeout or error reading from serial port 2.\n");
            code2_index = 0; // Reset index
        }

        // Check if both codes are complete and match the expected code
        if (code1_index == 6 && code2_index == 6 && validate_code(code1, config.expected_code) && validate_code(code2, config.expected_code)) {
            // Unlock the doors
            if (unlock_doors() == 0) {
                // Check if the doors were unlocked successfully
                if (lock1_state == 1 && lock2_state == 1) {
                    printf("Authentication successful. Doors unlocked.\n");
                } else {
                    fprintf(stderr, "Error unlocking doors. Lock states: Lock1=%d, Lock2=%d\n", lock1_state, lock2_state);
                }
            } else {
                fprintf(stderr, "Error unlocking doors.\n");
            }
        }

        // Small delay to avoid busy-waiting
        usleep(100000); // 100ms
    }

    return 0;
}

// Initialize pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.lock1_gpio, PI_OUTPUT);
    gpioSetMode(config.lock2_gpio, PI_OUTPUT);

    // Set initial state to locked (LOW)
    gpioWrite(config.lock1_gpio, 0);
    gpioWrite(config.lock2_gpio, 0);

    return 0;
}

// Initialize the serial port
int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return 1;
    }

    struct termios options;
    tcgetattr(fd, &options);
    options.c_cflag = B9600 | CS8 | CLOCAL | CREAD; // 9600 baud, 8 data bits, no parity, 1 stop bit
    options.c_iflag = IGNPAR; // Ignore parity errors
    options.c_oflag = 0;
    options.c_lflag = 0; // Non-canonical mode
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &options);

    return fd;
}

// Read a 6-digit code from the serial port
int read_code(int fd, char *code, int code_len) {
    int i;
    char c;

    // Read the code
    for (i = 0; i < code_len; i++) {
        c = fgetc(fd);
        if (c == EOF) {
            fprintf(stderr, "Error reading from serial port: EOF\n");
            return 1;
        } else if (c == '\n' || c == '\r') {
            // Ignore newline or carriage return characters
            continue;
        } else if (!isdigit(c)) {
            // Reset the index if a non-digit character is encountered
            i = 0;
            code[i++] = c;
        } else {
            code[i++] = c;
        }
    }

    code[i] = '\0'; // Null-terminate the string

    return 0;
}

// Validate the received code against the expected code
int validate_code(const char *code, const char *expected_code) {
    return strcmp(code, expected_code) == 0;
}

// Unlock the doors
int unlock_doors() {
    gpioWrite(config.lock1_gpio, 1);
    gpioWrite(config.lock2_gpio, 1);
    gpioDelay(2000); // 2 seconds
    gpioWrite(config.lock1_gpio, 0);
    gpioWrite(config.lock2_gpio, 0);
    return 0;
}

// Lock the doors
int lock_doors() {
    gpioWrite(config.lock1_gpio, 0);
    gpioWrite(config.lock2_gpio, 0);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down gracefully...\n", signal);

    // Unlock the doors
    lock_doors();

    // Close the serial ports
    if (serial_fd1 != -1) {
        close(serial_fd1);
    }
    if (serial_fd2 != -1) {
        close(serial_fd2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

