    // Request PIR sensor line as input
    pir_line = gpiod_chip_get_line(chip, PIR_SENSOR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR sensor line %d", PIR_SENSOR_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&pir_config, 0, sizeof(pir_config));
    pir_config.consumer = "pir_sensor";
    pir_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &pir_config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request PIR sensor line %d", PIR_SENSOR_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request relay line as output
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d", RELAY_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&relay_config, 0, sizeof(relay_config));
    relay_config.consumer = "relay";
    relay_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(relay_line, &relay_config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line %d", RELAY_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to release GPIO lines
int release_gpio_line(struct gpiod_line *line) {
    if (line) {
        if (gpiod_line_release(line) < 0) {
            syslog(LOG_ERR, "Failed to release PIR sensor line %d", PIR_SENSOR_PIN);
            return -1;
        }
        if (line->consumer) {
            if (gpiod_line_release(line) < 0) {
                syslog(LOG_ERR, "Failed to release relay line %d", RELAY_PIN);
                return -1;
            }
        }
    }
    return 0;
}

// Function to read PIR sensor value
int read_pir_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Function to activate the relay
int activate_relay(struct gpiod_line *line, int duration) {
    if (gpiod_line_set_value(line, 1) < 0) {
        syslog(LOG_ERR, "Failed to activate relay");
        return -1;
    }
    syslog(LOG_INFO, "Relay activated for %d seconds", duration);
    sleep(duration);
    return 0;
}

// Function to deactivate the relay
int deactivate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        syslog(LOG_ERR, "Failed to deactivate relay");
        return -1;
    }
    syslog(LOG_INFO, "Relay deactivated");
    return 0;
}

// Function to check for failsafe condition
int check_failsafe(struct gpiod_line *line, int duration) {
    int pir_value;
    time_t start_time = time(NULL);

    while (time(NULL) - start_time < duration) {
        pir_value = read_pir_sensor(line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor during failsafe check");
            return -1;
        }
        if (pir_value == 1) {
            syslog(LOG_WARNING, "Failsafe triggered! PIR sensor remains HIGH for %d seconds", duration);
            deactivate_relay(line);
            return 0; // Failsafe triggered, deactivate relay
        }
        usleep(50000); // Poll every 50ms
    }

    syslog(LOG_WARNING, "Failsafe timeout! PIR sensor remained HIGH for %d seconds", duration);
    deactivate_relay(line);
    return 0; // Failsafe timeout, deactivate relay
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");
    if (relay_line) {
        deactivate_relay(relay_line);
    }
    if (pir_line) {
        release_gpio_line(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    exit(0);
}

int main(void) {
    // Initialize syslog
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Door strike system started");

    // Main loop
    while (!terminate) {
        int pir_value = read_pir_sensor(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor, exiting");
            cleanup();
            return 1;
        }

        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected!");
            if (activate_relay(relay_line, RELAY_DURATION) < 0) {
                syslog(LOG_ERR, "Failed to activate relay, exiting");
                cleanup();
                return 1;
            }
            // Check for failsafe
            if (check_failsafe(pir_line, FAILSAFE_TIMEOUT) < 0) {
                syslog(LOG_ERR, "Failed to check failsafe, exiting");
                cleanup();
                return 1;
            }
        }
        usleep(50000); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

