#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the number of relays
#define NUM_RELAYS 4

// Define the activation time (in seconds)
#define ACTIVATION_TIME 300

// Define the pause time (in seconds)
#define PAUSE_TIME 60

// Global variables
volatile sig_atomic_t program_running = 1;
int current_relay = 0; // Keeps track of the current relay to activate

// Function prototypes
void log_message(int priority, const char *message);
void deactivate_all_relays();
void activate_relay(int gpio);
void deactivate_relay(int gpio);
void pause();
void signal_handler(int signal);
void timer_callback(int timer_id, void *userdata);

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to deactivate all relays
void deactivate_all_relays() {
    log_message(LOG_INFO, "Deactivating all relays");
    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);
}

// Function to activate a relay
void activate_relay(int gpio) {
    log_message(LOG_INFO, "Activating relay on GPIO %d", gpio);
    gpioWrite(gpio, 0); // Set GPIO to LOW to activate the relay
}

// Function to deactivate a relay
void deactivate_relay(int gpio) {
    log_message(LOG_INFO, "Deactivating relay on GPIO %d", gpio);
    gpioWrite(gpio, 1); // Set GPIO to HIGH to deactivate the relay
}

// Function to pause the system
void pause() {
    log_message(LOG_INFO, "Pausing system for 60 seconds");
    gpioDelay(PAUSE_TIME * 1000000); // Delay for 60 seconds (in microseconds)
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    log_message(LOG_WARNING, "Received signal %d, shutting down...", signal);
    program_running = 0;
    deactivate_all_relays();
    gpioTerminate();
    closelog();
    exit(0);
}

// Timer callback function
void timer_callback(int timer_id, void *userdata) {
    // This function is called every 60 seconds
    // It checks the current state and updates the relay accordingly
    int current_relay_to_activate = (current_relay + 1) % NUM_RELAYS; // Calculate the next relay to activate

    if (current_relay_to_activate != current_relay) {
        activate_relay(RELAY1_GPIO);
        current_relay = current_relay_to_activate;
    } else {
        pause();
    }
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    deactivate_all_relays();

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer callback function
    if (gpioSetTimerFuncEx(0, 60, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set up timer callback");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Sleep to allow the timer to run
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_all_relays();
    gpioTerminate();
    closelog();

    return 0;
}

