#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <sys/time.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C

// Circular Buffer Size
#define BUFFER_SIZE 100

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Circular buffer structure
typedef struct {
    AccelData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

// Global variables
int i2c_fd;
CircularBuffer buffer;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z);
AccelData get_latest_data(CircularBuffer *buffer);
void signal_handler(int signum);

// Initialize I2C
int init_i2c(int address) {
    int fd;
    char filename[20];

    snprintf(filename, 19, "/dev/i2c-%d", 1); // I2C bus 1 on Raspberry Pi
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize MPU6050
int init_mpu6050(int fd) {
    int status;

    // Wake up the MPU6050
    status = i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0x00);
    if (status < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Set accelerometer range to +-2g
    status = i2c_smbus_write_byte_data(fd, ACCEL_CONFIG, 0x00);
    if (status < 0) {
        perror("Error writing to ACCEL_CONFIG");
        return -1;
    }

    return 0;
}

// Read acceleration data from MPU6050
int read_acceleration(int fd, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    status = i2c_smbus_read_i2c_block_data(fd, 0x3B, 6, buf);
    if (status < 0) {
        perror("Error reading acceleration data");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Scale raw values to g units
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z) {
    buffer->data[buffer->head].x = x;
    buffer->data[buffer->head].y = y;
    buffer->data[buffer->head].z = z;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Get latest data from circular buffer
AccelData get_latest_data(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        AccelData empty = {0.0f, 0.0f, 0.0f};
        return empty;
    }

    int index = (buffer->tail + BUFFER_SIZE - 1) % BUFFER_SIZE;
    return buffer->data[index];
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int main() {
    float x, y, z;
    struct itimerspec its;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting signal handler");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    // Configure timer for 100 Hz sampling rate
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10 ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10 ms

    // Create timer event
    if (timer_create(CLOCK_REALTIME, NULL, &timer_id) == -1) {
        perror("Error creating timer");
        close(i2c_fd);
        return 1;
    }

    // Set timer event
    if (timer_settime(timer_id, 0, &its, NULL) == -1) {
        perror("Error setting timer");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(&buffer, x, y, z);

            // Get latest data
            AccelData latest_data = get_latest_data(&buffer);

            // Print latest data
            printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", latest_data.x, latest_data.y, latest_data.z);
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Sleep for 10 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10 ms
        nanosleep(&ts, NULL);
    }

    // Clean up
    close(i2c_fd);
    timer_delete(timer_id);

    printf("Exiting.\n");
    return 0;
}

