    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    // Configure timer for 100 Hz sampling rate
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10 ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10 ms

    // Create timer event
    if (timer_create(CLOCK_REALTIME, NULL, &timer_id) == -1) {
        perror("Error creating timer");
        close(i2c_fd);
        return 1;
    }

    // Set timer event
    if (timer_settime(timer_id, 0, &its, NULL) == -1) {
        perror("Error setting timer");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(&buffer, x, y, z);

            // Get latest data
            AccelData latest_data = get_latest_data(&buffer);

            // Print latest data
            printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", latest_data.x, latest_data.y, latest_data.z);
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Sleep for 10 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10 ms
        nanosleep(&ts, NULL);
    }

    // Clean up
    close(i2c_fd);
    timer_delete(timer_id);

    printf("Exiting.\n");
    return 0;
}

