#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 500

// Global variables
static volatile int running = 1;
static volatile int relay_active = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void deactivate_relay();
void log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        deactivate_relay();
        gpioTerminate();
        running = 0;
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    deactivate_relay();

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
void activate_relay() {
    if (!relay_active) {
        gpioWrite(RELAY_PIN, 1); // Activate relay (HIGH)
        relay_active = 1;
        printf("Relay activated\n");
    }
}

// Deactivate the relay
void deactivate_relay() {
    gpioWrite(RELAY_PIN, 0); // Deactivate relay (LOW)
    relay_active = 0;
    printf("Relay deactivated\n");
}

// Log alarm event to file
void log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Alarm triggered\n", timestamp);
    fclose(fp);
    printf("Alarm logged: %s: Alarm triggered\n", timestamp);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            activate_relay();
            log_alarm();
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce: Wait for debounce time
            deactivate_relay();
            gpioDelay(100 * 1000); // Wait before next check
        } else {
            gpioDelay(100 * 1000); // Check every 100ms
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_relay();
    gpioTerminate();

    return 0;
}

