int init_i2c(int bus, int addr);
int init_mpu6050(int fd);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_gyro_data(int fd, gyro_data_t *data);
float calculate_magnitude(gyro_data_t data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
void check_threshold(circular_buffer_t *buffer, float threshold);
void signal_handler(int sig);

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Initialize MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    if (write_register(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read a single byte from a register
int read_register(int fd, uint8_t reg) {
    uint8_t value = 0;
    if (ioctl(fd, I2C_SLAVE, 0x68) < 0) { // Assuming 0x68 is the address
        perror("Error: Could not set I2C slave address");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }
    if (read(fd, &value, 1) != 1) {
        perror("Error: Could not read register value");
        return -1;
    }
    return value;
}

// Write a single byte to a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (ioctl(fd, I2C_SLAVE, 0x68) < 0) { // Assuming 0x68 is the address
        perror("Error: Could not set I2C slave address");
        return -1;
    }
    if (write(fd, buf, 2) != 2) {
        perror("Error: Could not write register value");
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];
    if (ioctl(fd, I2C_SLAVE, 0x68) < 0) { // Assuming 0x68 is the address
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, &GYRO_XOUT_H, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error: Could not read gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

