float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if the magnitude exceeds the threshold
void check_threshold(circular_buffer_t *buffer, float threshold) {
    if (buffer->count > 0) {
        float max_magnitude = 0.0;
        for (int i = 0; i < buffer->count; i++) {
            int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE; // Corrected index calculation
            float magnitude = calculate_magnitude(buffer->data[index]);
            if (magnitude > max_magnitude) {
                max_magnitude = magnitude;
            }
        }
        if (max_magnitude > threshold) {
            printf("Threshold exceeded! Maximum magnitude: %.2f deg/s\n", max_magnitude);
        }
    }
}

