    int who_am_i = read_register(i2c_fd, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x68\n", who_am_i);
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized successfully. WHO_AM_I: 0x%02X\n", who_am_i);

    // Main loop
    gyro_data_t gyro_data;
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
