            add_to_buffer(&gyro_buffer, gyro_data);

            // Check threshold
            check_threshold(&gyro_buffer, 50.0);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Delay
        usleep(10000); // 10ms
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

