    if (monitor.error_log_file == NULL) {
        log_error(monitor.error_log_file, "Failed to open error log file.");
        fclose(monitor.log_file);
        serClose(monitor.uart_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (monitor.running) {
        // Send read command
        if (send_command(monitor.uart_fd, command, sizeof(command)) != 0) {
            log_error(monitor.error_log_file, "Failed to send read command.");
            error_flag = 1;
            continue;
        }

        // Wait for data
        int bytes_available = serDataAvailable(monitor.uart_fd);
        if (bytes_available < 9) {
            log_error(monitor.error_log_file, "Not enough data received from sensor.");
            error_flag = 1;
            gpioDelay(100000); // 100ms
            continue;
        }

        // Read sensor data
        if (read_sensor_data(monitor.uart_fd, sensor_data, 9) != 0) {
            log_error(monitor.error_log_file, "Failed to read sensor data.");
            error_flag = 1;
            gpioDelay(100000); // 100ms
            continue;
        }

        // Validate checksum
        int checksum = 0;
        for (int i = 0; i < 7; i++) {
            checksum += sensor_data[i];
        }
        checksum = (checksum + 1) ^ 0xFF;

        if (checksum != sensor_data[8]) {
            log_error(monitor.error_log_file, "Checksum validation failed.");
            error_flag = 1;
            gpioDelay(100000); // 100ms
            continue;
        }

        // Extract CO2 concentration
        if (extract_co2(sensor_data, 9, &co2_ppm) != 0) {
            log_error(monitor.error_log_file, "Failed to extract CO2 concentration.");
            error_flag = 1;
            gpioDelay(100000); // 100ms
            continue;
        }

        // Log data
        if (log_data(monitor.log_file, co2_ppm, error_flag) != 0) {
            log_error(monitor.error_log_file, "Failed to log data.");
        }

        // Send JSON to stdout
        if (send_json_to_stdout(monitor.log_file) != 0) {
            log_error(monitor.error_log_file, "Failed to send JSON to stdout.");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    serClose(monitor.uart_fd);
    fclose(monitor.log_file);
    fclose(monitor.error_log_file);
    gpioTerminate();

    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open UART
int open_uart(const char *device, int baud_rate) {
    int fd = serOpen(device, baud_rate, 0); // 0 for default flags
    if (fd < 0) {
        fprintf(stderr, "Failed to open serial device %s\n", device);
        return -1;
    }
    return fd;
}

// Send command to sensor
int send_command(int uart_fd, const unsigned char *command, int command_len) {
    int bytes_written = serWrite(uart_fd, (char *)command, command_len);
    if (bytes_written != command_len) {
        fprintf(stderr, "Failed to send command: %d bytes written, expected %d\n", bytes_written, command_len);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int uart_fd, unsigned char *data, int data_len) {
    int bytes_read = 0;
    int start_time = time(NULL);

    while (bytes_read < data_len && (time(NULL) - start_time) < TIMEOUT_SECONDS) {
        int available = serDataAvailable(uart_fd);
        if (available > 0) {
            for (int i = 0; i < available; i++) {
                data[bytes_read++] = serRead(uart_fd);
            }
        } else {
            gpioDelay(10000); // 10ms delay
        }
    }

    if (bytes_read != data_len) {
        fprintf(stderr, "Timeout reading sensor data\n");
        return 1;
    }
    return 0;
}

// Validate checksum
int validate_checksum(const unsigned char *data, int data_len, int *checksum) {
    int sum = 0;
    for (int i = 0; i < data_len - 1; i++) {
        sum += data[i];
    }
    *checksum = (sum + 1) ^ 0xFF;
    return 0;
}

// Extract CO2 concentration
int extract_co2(const unsigned char *data, int data_len, int *co2_ppm) {
    *co2_ppm = (data[2] << 8) | data[3];
    return 0;
}

// Log data to file
int log_data(FILE *log_file, int co2_ppm, int error_flag) {
    time_t current_time;
    struct tm *time_info;
    char timestamp[30];

    time(&current_time);
    time_info = localtime(&current_time);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    if (error_flag) {
        fprintf(log_file, "{\"timestamp\": \"%s\", \"co2_ppm\": null, \"error\": true}\n");
    } else {
        fprintf(log_file, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error\": false}\n", timestamp, co2_ppm);
    }
    fflush(log_file);
    return 0;
}

// Log error to file
int log_error(FILE *error_log_file, const char *message) {
    time_t current_time;
    struct tm *time_info;
    char timestamp[30];

    time(&current_time);
    time_info = localtime(&current_time);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Send JSON to stdout
int send_json_to_stdout(FILE *log_file) {
    char json_string[256];
    int bytes_available = serDataAvailable(monitor.uart_fd);
    if (bytes_available > 0) {
        for (int i = 0; i < bytes_available; i++) {
            json_string[i] = serRead(monitor.uart_fd);
        }
        json_string[bytes_available] = '\0';
        printf("%s", json_string);
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    monitor.running = 0;
}

