#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>
#include <time.h>

// Configuration
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x70
#define CONFIG_B 0x20
#define MODE 0x00
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_BUFFER_SIZE 100
#define SAMPLE_RATE_MS 100

// HMC5883L Registers
#define HMC5883L_X_MSB 0x03
#define HMC5883L_X_LSB 0x04
#define HMC5883L_Z_MSB 0x05
#define HMC5883L_Z_LSB 0x06
#define HMC5883L_Y_MSB 0x07
#define HMC5883L_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer for heading data
float heading_buffer[HEADING_BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z);
float compensate_heading(int16_t x, int16_t y, int16_t z, float x_offset, float y_offset);
float calculate_heading(int16_t x, int16_t y, int16_t z);
void control_gpio(float heading);
void add_to_buffer(float heading);
float get_average_heading();
void signal_handler(int signal);

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function to initialize the HMC5883L
int init_hmc5883l() {
    char buf[2];

    // Set CONFIG_A register
    buf[0] = CONFIG_A;
    buf[1] = 0x70; // 8-average, 15 Hz output rate, normal measurement
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Set CONFIG_B register
    buf[0] = CONFIG_B;
    buf[1] = 0x20; // 1.3 Gauss gain
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Set MODE register
    buf[0] = MODE;
    buf[1] = 0x00; // Continuous measurement mode
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Function to read data from the HMC5883L
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[1];
    char data[6];

    // Read X, Y, and Z data in a single burst
    buf[0] = HMC5883L_X_MSB | 0x80; // Enable auto-increment
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to auto-increment register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to compensate for hard-iron distortion
float compensate_heading(int16_t x, int16_t y, int16_t z, float x_offset, float y_offset) {
    float x_comp = (float)x - x_offset;
    float y_comp = (float)y - y_offset;
    float heading = atan2(y_comp, x_comp) * 180 / M_PI;
    return heading;
}

// Function to calculate heading in degrees
float calculate_heading(int16_t x, int16_t y, int16_t z) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to control the GPIO pin based on heading deviation
void control_gpio(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 10.0) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Function to add data to the circular buffer
void add_to_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % HEADING_BUFFER_SIZE;
}

// Function to calculate the average heading from the buffer
float get_average_heading() {
    float sum = 0.0;
    for (int i = 0; i < HEADING_BUFFER_SIZE; i++) {
        sum += heading_buffer[i];
    }
    return sum / HEADING_BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() != 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    float heading;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_RATE_MS * 1000000; // 100ms

    while (!terminate) {
        // Read magnetometer data
        if (read_hmc5883l_data(&x, &y, &z) == 0) {
            // Compensate for hard-iron distortion
            heading = compensate_heading(x, y, z, 100.0, -50.0);

            // Calculate heading in degrees
            heading = calculate_heading(x, y, z);

            // Control GPIO pin
            control_gpio(heading);

            // Add to circular buffer
            add_to_buffer(heading);

            // Calculate average heading
            float avg_heading = get_average_heading();

            // Print data (for debugging)
            printf("X: %d, Y: %d, Z: %d, Heading: %.2f, Avg Heading: %.2f\n", x, y, z, heading, avg_heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Sleep for 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low before exiting
    gpioTerminate();

    return 0;
}

