#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and sensor addresses
#define I2C_BUS 1
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x24
#define BH1750_ADDR_3 0x25

// Define lux thresholds
#define RED_THRESHOLD 50.0
#define GREEN_THRESHOLD 150.0
#define BLUE_THRESHOLD 300.0

// Define log file name
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio();
int init_i2c();
int init_bh1750(int i2c_bus, int i2c_address);
float read_lux(int i2c_fd);
void set_relay_state(int red_pin, int green_pin, int blue_pin, float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize I2C bus
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR_1) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize BH1750 sensor
int init_bh1750(int i2c_bus, int i2c_address) {
    int fd;
    if (ioctl(i2c_bus, I2C_SLAVE, i2c_address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_data[1] = {0x10}; // Continuous high-resolution mode
    if (write(i2c_bus, config_data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read lux value from BH1750 sensor
float read_lux(int i2c_fd) {
    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1.0;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / 1.2;
}

// Function to set relay states based on lux value
void set_relay_state(int red_pin, int green_pin, int blue_pin, float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < RED_THRESHOLD) {
        red_state = 1;
    } else if (lux >= RED_THRESHOLD && lux < GREEN_THRESHOLD) {
        green_state = 1;
    } else if (lux >= GREEN_THRESHOLD && lux < BLUE_THRESHOLD) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpioWrite(red_pin, red_state);
    gpioWrite(green_pin, green_state);
    gpioWrite(blue_pin, blue_state);
}

// Function to log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
