#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range
#define PWM_RANGE 255

// Distance range (cm)
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to set motor direction and speed
void set_motor_speed(int motor_a_distance, int motor_b_distance) {
    int motor_a_forward = (motor_a_distance < 50) ? 1 : 0;
    int motor_a_pwm = (motor_a_forward) ? 255 : 0;

    int motor_b_forward = (motor_b_distance < 50) ? 1 : 0;
    int motor_b_pwm = (motor_b_forward) ? 255 : 0;

    // Motor A
    gpioWrite(MOTOR_A_IN1, motor_a_forward);
    gpioWrite(MOTOR_A_IN2, !motor_a_forward); // Invert for backward
    gpioPWM(MOTOR_A_IN2, motor_a_pwm);

    // Motor B
    gpioWrite(MOTOR_B_IN3, motor_b_forward);
    gpioWrite(MOTOR_B_IN4, !motor_b_forward); // Invert for backward
    gpioPWM(MOTOR_B_IN4, motor_b_pwm);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <distance1_cm> <distance2_cm>\n", argv[0]);
        return 1;
    }

    int distance1_cm = atoi(argv[1]);
    int distance2_cm = atoi(argv[2]);

    if (distance1_cm < MIN_DISTANCE || distance1_cm > MAX_DISTANCE ||
        distance2_cm < MIN_DISTANCE || distance2_cm > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance values must be between %d and %d cm\n", MIN_DISTANCE, MAX_DISTANCE);
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control started. Press Ctrl+C to stop.\n");

    // Main loop
    while (program_running) {
        set_motor_speed(distance1_cm, distance2_cm);
        gpioDelay(100); // 100 ms delay
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    // Clean up
    gpioTerminate();

    printf("Motor control stopped.\n");

    return 0;
}

