        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read MPU-6050 data
        if (retry_i2c_read(read_mpu6050_data, (int16_t *)accel_x, (int16_t *)accel_y, (int16_t *)accel_z, (int16_t *)gyro_x, (int16_t *)gyro_y, (int16_t *)gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch(accel_x, accel_y, accel_z);
            roll = calculate_roll(accel_x, accel_y, accel_z);

