            fprintf(stderr, "Failed to read MPU-6050 data.\n");
        }

        delay(100); // Delay for 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        return -1;
    }

    // Set sample rate divider
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        return -1;
    }
    if (write(i2c_fd, &MPU6050_SMPLRT_DIV, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        return -1;
    }

    // Configure DLPF (Digital Low Pass Filter)
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        return -1;
    }
    if (write(i2c_fd, &MPU6050_CONFIG, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        return -1;
    }

    // Configure gyroscope
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        return -1;
    }
    if (write(i2c_fd, &MPU6050_GYRO_CONFIG, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read MPU-6050 data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 14) == 14) {
            *accel_x = (buffer[0] << 8) | buffer[1];
            *accel_y = (buffer[2] << 8) | buffer[3];
            *accel_z = (buffer[4] << 8) | buffer[5];
            *gyro_x = (buffer[8] << 8) | buffer[9];
            *gyro_y = (buffer[10] << 8) | buffer[11];
            *gyro_z = (buffer[12] << 8) | buffer[13];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s. Retrying...\n", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// Calculate pitch
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float x = (float)accel_x;
    float y = (float)accel_y;
    float z = (float)accel_z;
    return atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
}

// Calculate roll
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float x = (float)accel_x;
    float y = (float)accel_y;
    float z = (float)accel_z;
    return atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
}

// Set servo angle using PWM
int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_PULSE_WIDTH || angle > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid servo angle: %d. Must be between %d and %d.\n", angle, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }

    // Calculate pulse width
    int pulse_width = (int)(((float)(angle - SERVO_MIN_PULSE_WIDTH) / (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)) * PWM_PERIOD);

    // Set PWM period
    char pwm_period_path[50];
    snprintf(pwm_period_path, sizeof(pwm_period_path), "/sys/class/pwm/pwmchip2/pwm%d/period", PWM_CHANNEL);
    int fd = open(pwm_period_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period file: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, &pulse_width, 4) != 4) {
        fprintf(stderr, "Failed to write to PWM period file: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Exponential backoff retry function
int retry_i2c_read(int (*func)(int16_t *), int16_t *data, int retries) {
    int result = -1;
    for (int i = 0; i < retries; i++) {
        result = func(data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", i + 1, retries);
            usleep(10000 * (1 << i)); // Exponential backoff
        }
    }
    return -1; // Failure after retries
}

