#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define log file name
#define LOG_FILE "lighting.log"

// Structure to hold relay state and GPIO pin
typedef struct {
    int gpio_pin;
    int relay_number;
    int on;
    int brightness;
} RelayState;

// Global variables
RelayState relays[4];
int num_relays = 4;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Function prototypes
int read_schedule(const char *filename, int *relays, int *num);
void set_relay_state(int relay_number, int on, int brightness);
void fade_brightness(int relay_number, int target_brightness);
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read the lighting schedule from a file
int read_schedule(const char *filename, int *relays, int *num) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        log_message("Error: Could not open schedule file.");
        return -1;
    }

    char line[256];
