// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MIN_DISTANCE 2       // cm
#define MAX_DISTANCE 30      // cm
#define MIN_FREQUENCY 200    // Hz
#define MAX_FREQUENCY 2000   // Hz
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile int echo_start = 0;
volatile int echo_end = 0;
volatile int echo_valid = 0;
volatile int running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, long timeout);
float calculateDistance(long pulse_width);
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, shutting down...\n");
        gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
        gpioTerminate();        // Terminate pigpio
        running = 0;            // Set the running flag to 0
        exit(0);                 // Exit the program
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulseIn(int pin, int level, long timeout) {
    long start = gpioTick();
    while (gpioRead(pin) != level) {
        if (gpioTick() - start > timeout) {
            return 0; // Timeout
        }
    }
    long pulse_start = gpioTick();
    while (gpioRead(pin) == level) {
        if (gpioTick() - pulse_start > timeout) {
            return 0; // Timeout
        }
    }
    return gpioTick() - pulse_start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the PWM frequency of the buzzer
void setBuzzerFrequency(float frequency) {
    int range = 1000; // PWM range
    int dutycycle = range / 2; // 50% duty cycle

    // Calculate the PWM frequency based on the range
    int period = range / frequency;
    int half_period = period / 2;

    gpioSetPWMfrequency(BUZZER_PIN, frequency);
    gpioPWM(BUZZER_PIN, dutycycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range for the buzzer
    gpioSetPWMrange(BUZZER_PIN, 1000);
    gpioSetPWMrange(BUZZER_PIN, 1000); // Set range to 1000 for accurate frequency control

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        triggerSensor();
        long pulse_width = pulseIn(ECHO_PIN, 1, TIMEOUT_US);
        float distance = calculateDistance(pulse_width);

        if (distance > 0) {
            float frequency = mapDistanceToFrequency(distance);
            setBuzzerFrequency(frequency);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(60); // Delay for 60 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
    gpioTerminate();        // Terminate pigpio

    return 0;
}

