void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a sine wave for proximity simulation
float generate_proximity() {
    static float time = 0.0;
    time += 0.01; // Increment time by 0.01 seconds
    return 0.5 * (1 + sin(2 * M_PI * time)); // Sine wave with amplitude 0.5
}

