#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
void convert_gyro_data(gyro_data_t raw_data, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C interface
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0); // I2C bus 1, address 0x68, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw gyroscope data from MPU-6050
gyro_data_t read_gyro_data() {
    gyro_data_t raw_data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        raw_data.x = 0; raw_data.y = 0; raw_data.z = 0; // Return zeroed data on error
        return raw_data;
    }

    raw_data.x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_data.y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_data.z = (int16_t)((buf[4] << 8) | buf[5]);

    return raw_data;
}

// Convert raw gyroscope data to degrees/second
void convert_gyro_data(gyro_data_t raw_data, float *x, float *y, float *z) {
    *x = (float)raw_data.x / 131.0;
    *y = (float)raw_data.y / 131.0;
    *z = (float)raw_data.z / 131.0;
}

// Log gyroscope data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float x, y, z;
    gyro_data_t raw_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        raw_data = read_gyro_data();

        // Convert raw data to degrees/second
        convert_gyro_data(raw_data, &x, &y, &z);

        // Log data
        log_data(x, y, z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

