#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody lookup table (frequency, duration in ms)
const unsigned short melody[] = {
    440, 200,  // A4, 200ms
    494, 200,  // B4, 200ms
    523, 200,  // C5, 200ms
    0, 500      // Rest, 500ms
};

// Define constants
#define NUM_NOTES 6
#define DEBOUNCE_DELAY 50 // milliseconds
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // 50% duty cycle

// Global variables
volatile int playing = 0; // Flag to control playback
int button_pressed = 0;  // Flag to track button press state

// Function prototypes
void play_melody();
void button_callback(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping playback and cleaning up...\n", signal);
    gpioHardwarePWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();              // Terminate pigpio
    exit(0);
}

// Function to play the melody
void play_melody() {
    playing = 1; // Set the flag to start playback
    for (int i = 0; i < NUM_NOTES; i++) {
        if (melody[i] != 0) {
            gpioHardwarePWM(BUZZER_PIN, 500); // 50% duty cycle
            gpioPWM(BUZZER_PIN, 500); // Set PWM duty cycle
            gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQUENCY);
            gpioDelay(melody[i] * 1000); // Convert ms to us
        } else {
            gpioDelay(500 * 1000); // Rest
        }
    }
    playing = 0; // Reset the flag after playback
}

// Interrupt handler for the button
void button_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick < DEBOUNCE_DELAY * 1000) {
        return; // Ignore the press
    }
    last_tick = current_tick;

    if (level == 0) { // Button pressed (active-low)
        button_pressed = 1;
        play_melody();
    } else {
        button_pressed = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", BUZZER_PIN);
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler for the button
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO %d\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            gpioDelay(1000); // Wait for button release
        }
        gpioDelay(100); // Small delay to reduce CPU usage
    }

    // The program should never reach here due to the infinite loop
    gpioTerminate();
    return 0;
}

