#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_TIMEOUT_MS 1000
#define WINDOW_SIZE 5

// Global variables
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int window[WINDOW_SIZE] = {0}; // Initialize window to 0
static int window_index = 0;

// Function prototypes
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int request_gpio_input(struct gpiod_line *line);
int read_gpio_value(struct gpiod_line *line);
int log_event(const char *timestamp, int value);
int check_earthquake_alert(int *window, int new_value);
void signal_handler(int sig);
void cleanup();

// Function to get current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to initialize GPIO
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line)
{
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Function to request GPIO input
int request_gpio_input(struct gpiod_line *line)
{
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read GPIO value
int read_gpio_value(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

