#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define MR_REG_M 0x02
#define CRA_REG_M 0x00

// Calibration offsets
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

// Heading range
#define HEADING_MIN 0.0f
#define HEADING_MAX 360.0f

// Number of compass directions
#define NUM_DIRECTIONS 8

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Structure to hold compass direction
typedef struct {
    char direction[4];
    float heading;
} compass_direction_t;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int configure_magnetometer(int fd);
int read_magnetometer_data(int fd, magnetometer_data_t *data);
float calibrate_magnetometer_data(magnetometer_data_t data);
float calculate_heading(float x, float y);
void determine_compass_direction(float heading, compass_direction_t *direction);
void log_data(FILE *fp, magnetometer_data_t data, compass_direction_t direction);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Error: Could not acquire bus access and/or talk to slave.");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write to I2C device.");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error: Could not read from I2C device.");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;

    if (ioctl(fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Error: Could not acquire bus access and/or talk to slave.");
        return -1;
    }

    if (write(fd, buf, 2) != 2) {
        perror("Error: Could not write to I2C device.");
        return -1;
    }

    return 0;
}

// Configure magnetometer function
int configure_magnetometer(int fd) {
    if (i2c_write_reg(fd, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Error configuring magnetometer.\n");
        return -1;
    }

    // Optionally set output data rate to 15 Hz
    if (i2c_write_reg(fd, CRA_REG_M, 0x14) != 0) {
        fprintf(stderr, "Error setting output data rate.\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data function
int read_magnetometer_data(int fd, magnetometer_data_t *data) {
    uint8_t buffer[6];
    if (i2c_read_reg(fd, 0x03, buffer, 6) != 0) {
        fprintf(stderr, "Error reading magnetometer data.\n");
        return -1;
    }

    // Combine MSB and LSB for each axis
    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Apply calibration offsets
    data->x = (float)x * 0.001f - X_OFFSET;
    data->y = (float)y * 0.001f - Y_OFFSET;
    data->z = (float)z * 0.001f - Z_OFFSET;

    return 0;
}

// Calibrate magnetometer data function
float calibrate_magnetometer_data(magnetometer_data_t data) {
    return data.x;
}

// Calculate heading function
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x);
    if (heading < 0) {
        heading += 2 * M_PI;
    }
    return heading;
}

// Determine compass direction function
void determine_compass_direction(float heading, compass_direction_t *direction) {
    if (heading >= 0 && heading < HEADING_MIN) {
        strcpy(direction->direction, "N");
        direction->heading = heading;
    } else if (heading >= HEADING_MIN && heading < HEADING_MIN + 45.0f) {
        strcpy(direction->direction, "NE");
        direction->heading = heading;
    } else if (heading >= HEADING_MIN + 45.0f && heading < HEADING_MIN + 90.0f) {
        strcpy(direction->direction, "E");
        direction->heading = heading;
    } else if (heading >= HEADING_MIN + 90.0f && heading < HEADING_MIN + 135.0f) {
        strcpy(direction->direction, "SE");
        direction->heading = heading;
    } else if (heading >= HEADING_MIN + 135.0f && heading < HEADING_MIN + 180.0f) {
        strcpy(direction->direction, "S");
        direction->heading = heading;
    } else if (heading >= HEADING_MIN + 180.0f && heading < HEADING_MIN + 225.0f) {
        strcpy(direction->direction, "SW");
        direction->heading = heading;
    } else if (heading >= HEADING_MIN + 225.0f && heading < HEADING_MIN + 270.0f) {
        strcpy(direction->direction, "W");
        direction->heading = heading;
    } else if (heading >= HEADING_MIN + 270.0f && heading < HEADING_MIN + 315.0f) {
        strcpy(direction->direction, "NW");
        direction->heading = heading;
    } else {
        strcpy(direction->direction, "N");
        direction->heading = heading;
    }
}

// Log data function
void log_data(FILE *fp, magnetometer_data_t data, compass_direction_t direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f,%.2f,%s\n", timestamp, data.x, data.y, data.z, direction.heading, direction.direction);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device.");
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer(i2c_fd) != 0) {
        fprintf(stderr, "Error configuring magnetometer. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file.");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    fflush(log_file);

    magnetometer_data_t magnetometer_data;
    compass_direction_t compass_direction;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &magnetometer_data) == 0) {
            // Calibrate magnetometer data
            magnetometer_data.x = calibrate_magnetometer_data(magnetometer_data);

            // Calculate heading
            float heading = calculate_heading(magnetometer_data.x, magnetometer_data.y);

            // Determine compass direction
            determine_compass_direction(heading, &compass_direction);

            // Log data
            log_data(log_file, magnetometer_data, compass_direction);

            // Print compass direction and heading to console
            printf("Heading: %.2f, Direction: %s\n", compass_direction.heading, compass_direction.direction);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Skipping.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

