#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define relay state
#define RELAY_OFF 0
#define RELAY_ON 1

// Global variables
static volatile int relay_state = RELAY_OFF;
static volatile unsigned long last_touch_time = 0;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signal);
void log_relay_state(const char *state);
void toggle_relay();
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, shutting down gracefully...\n");
        relay_state = RELAY_OFF; // Ensure relay is off on exit
        log_relay_state("OFF");
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to log relay state to JSON file
void log_relay_state(const char *state) {
    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        perror("Error opening relay_log.json");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"\n}", timestamp, state);
    fclose(fp);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = (relay_state == RELAY_OFF) ? RELAY_ON : RELAY_OFF;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state(relay_state == RELAY_ON ? "ON" : "OFF");
}

// Callback function for touch sensor
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Debounce the touch
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        toggle_relay();
        last_touch_time = current_time;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set pull-down resistor on touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set initial relay state
    gpioWrite(RELAY_PIN, relay_state);

    // Set up interrupt on touch sensor pin
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    return 0;
}

