#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO lines for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the chip name for the GPIO chip
#define CHIP_NAME "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_moisture();
int control_relay(int relay_number, int state);
int log_event(int moisture_level);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Received signal %d, cleaning up...\n", sig);
        terminate = 1;
    }
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    struct gpiod_line_request_config config;

    // Request relay 1 as output
    if (gpiod_line_request_output(relay1_line, "irrigation", 0) < 0) {
        fprintf(stderr, "Error requesting relay 1 as output: %s\n", strerror(errno));
        return -1;
    }

    // Request relay 2 as output
    if (gpiod_line_request_output(relay2_line, "irrigation", 0) < 0) {
        fprintf(stderr, "Error requesting relay 2 as output: %s\n", strerror(errno));
        return -1;
    }

    // Request relay 3 as output
    if (gpiod_line_request_output(relay3_line, "irrigation", 0) < 0) {
        fprintf(stderr, "Error requesting relay 3 as output: %s\n", strerror(errno));
        return -1;
    }

    // Request relay 4 as output
    if (gpiod_line_request_output(relay4_line, "irrigation", 0) < 0) {
        fprintf(stderr, "Error requesting relay 4 as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the simulated soil moisture value
int read_moisture() {
    static int moisture_level = 0;
    static int seed = 0;
    if (seed == 0) {
        srand(time(NULL));
        seed = rand();
    }
    moisture_level = (seed % 101); // Generates a value between 0 and 100
    if (moisture_level < 0) moisture_level = 0;
    return moisture_level;
}

// Function to control a relay (activate or deactivate)
int control_relay(int relay_number, int state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    if (gpiod_line_set_value(relay_number_line, state) < 0) {
        fprintf(stderr, "Error setting value for relay %d: %s\n", relay_number, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to log an event to the log file
int log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Relay 1, Moisture: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Deactivate all relays
    control_relay(1, 1);
    control_relay(2, 1);
    control_relay(3, 1);
    control_relay(4, 1);

    // Release the GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the line handles for the relays
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error getting line handle for one of the relays: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Main loop
    while (!terminate) {
        // Read the moisture level
        int moisture_level = read_moisture();

        // Log the event
        if (log_event(moisture_level) < 0) {
            fprintf(stderr, "Error logging event.\n");
        }

