#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins for servos
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 100

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo sweep parameters
#define NOZZLE_STEPS 5
#define NOZZLE_DELAY 2 // seconds

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        if (gpioServo(gpio, pulse_width) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Servo write failed, retrying in %d ms...\n", delay_ms);
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Servo write failed after multiple retries\n");
    return -1; // Failure
}

// Function to open the valve
int open_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_MAX_PULSE_WIDTH);
}

// Function to close the valve
int close_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_MIN_PULSE_WIDTH);
}

// Function to sweep the nozzle
int sweep_nozzle() {
    int pulse_widths[NOZZLE_STEPS];
    for (int i = 0; i < NOZZLE_STEPS; i++) {
        pulse_widths[i] = SERVO_MIN_PULSE_WIDTH + (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) * i / (NOZZLE_STEPS - 1);
    }

    for (int i = 0; i < NOZZLE_STEPS; i++) {
        if (set_servo_pulse_width(NOZZLE_SERVO_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting nozzle pulse width at step %d\n", i);
            return -1;
        }
        gpioDelay(NOZZLE_DELAY * 1000); // Delay in microseconds
    }
    return 0;
}

// Function to simulate soil moisture reading
int simulate_moisture_reading() {
    return rand() % 101; // Generates a number between 0 and 100
}

// Function to check moisture level and control watering
int check_moisture_level() {
    int moisture_level = simulate_moisture_reading();
    printf("Moisture level: %d\n", moisture_level);

    if (moisture_level < MOISTURE_THRESHOLD_LOW) {
        printf("Moisture level below threshold, opening valve and sweeping nozzle.\n");
        if (open_valve() != 0) {
            fprintf(stderr, "Failed to open valve\n");
            return -1;
        }
        if (sweep_nozzle() != 0) {
            fprintf(stderr, "Failed to sweep nozzle\n");
            close_valve();
            return -1;
        }
        if (close_valve() != 0) {
            fprintf(stderr, "Failed to close valve\n");
            return -1;
        }
        printf("Watering complete.\n");
    } else if (moisture_level >= MOISTURE_THRESHOLD_HIGH) {
        printf("Moisture level above threshold, skipping watering.\n");
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Main loop
    while (!terminate) {
        if (check_moisture_level() != 0) {
            fprintf(stderr, "Error in moisture level check, continuing...\n");
        }
        gpioDelay(5000000); // Wait 5 seconds
    }

    // Stop servos and terminate GPIO
    close_valve();
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

