#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity factor for gyroscope
#define GYRO_SENSITIVITY 131.0f

// Sampling rate (Hz)
#define SAMPLING_RATE 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c(const char *device);
int read_gyro_data(int fd, gyro_data_t *data);
void log_data(FILE *fp, struct timespec ts, gyro_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C communication
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    char buf[6];
    int16_t gyro_x, gyro_y, gyro_z;

    // Read 6 bytes of gyroscope data
    if (read(fd, buf, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert raw values to degrees/second
    data->x = (float)gyro_x / GYRO_SENSITIVITY;
    data->y = (float)gyro_y / GYRO_SENSITIVITY;
    data->z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Log data to file
void log_data(FILE *fp, struct timespec ts, gyro_data_t data) {
    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f\n", ts.tv_sec, ts.tv_nsec, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    struct timespec ts;
    gyro_data_t gyro_data;
    int retries = 3; // Number of retries for I2C operations

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c("/dev/i2c-1");
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Wake up the MPU-6050
    char wake_up_data[2] = {PWR_MGMT_1, 0x00};
    if (write(i2c_fd, wake_up_data, 2) != 2) {
        perror("Error waking up MPU-6050");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }

        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Log data
            log_data(log_file, ts, gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
            // Attempt to re-initialize I2C
            close(i2c_fd);
            i2c_fd = init_i2c("/dev/i2c-1");
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            // Wake up the MPU-6050 again
            char wake_up_data[2] = {PWR_MGMT_1, 0x00};
            if (write(i2c_fd, wake_up_data, 2) != 2) {
                perror("Error waking up MPU-6050");
                break;
            }
        }

        // Delay for sampling rate
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 1000000000 / SAMPLING_RATE; // 10ms delay
        nanosleep(&delay, NULL);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

