#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms timeout
#define MIN_GUARD_US 60000 // 60ms guard time

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "Signal received, exiting gracefully...\n");
}

// Function to initialize GPIO lines
int init_gpio()
{
    struct gpiod_line_request_config config;

    // Request trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error: Could not get trigger line %d\n", TRIGGER_PIN);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "ultrasonic_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request trigger line %d\n", TRIGGER_PIN);
        return -1;
    }

    // Request echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error: Could not get echo line %d\n", ECHO_PIN);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "ultrasonic_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(echo_line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request echo line %d\n", ECHO_PIN);
        return -1;
    }

    return 0;
}

// Function to trigger the ultrasonic sensor
int trigger_sensor()
{
    struct gpiod_line *line = trigger_line;
    if (!line) return -1;

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: Could not set trigger line %d high\n", TRIGGER_PIN);
        return -1;
    }

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000; // 10 microseconds
    nanosleep(&ts, NULL);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: Could not set trigger line %d low\n", TRIGGER_PIN);
        return -1;
    }
    return 0;
}

// Function to measure the echo pulse width
long measure_pulse_width()
{
    struct timespec start, end;
    long duration_us = 0;

    // Wait for the echo line to go high
    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("clock_gettime");
            return -1;
        }
        if (errno == EINTR) {
            // Interrupted by signal, return -1
            return -1;
        }
    }

    // Wait for the echo line to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("clock_gettime");
            return -1;
        }
        if (errno == EINTR) {
            // Interrupted by signal, return -1
            return -1;
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        perror("clock_gettime");
        return -1;
    }

    duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    if (duration_us < 0 || duration_us > TIMEOUT_US) {
        fprintf(stderr, "Error: Pulse width out of range (%ld us)\n", duration_us);
        return -1;
    }

    return duration_us;
}

// Function to calculate distance in centimeters
float calculate_distance(long duration_us)
{
    return (float)duration_us * 0.01715;
}

// Function to log the distance to a file
int log_distance(float distance_cm)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, distance_cm) < 0) {
        perror("fprintf");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main()
{
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "GPIO initialized successfully\n");

    // Main loop
    while (!terminate) {
        if (trigger_sensor() < 0) {
            fprintf(stderr, "Sensor trigger failed\n");
            continue; // Retry
        }

        long duration_us = measure_pulse_width();
        if (duration_us < 0) {
            fprintf(stderr, "Sensor measurement failed\n");
            continue; // Retry
        }

        float distance_cm = calculate_distance(duration_us);

        if (log_distance(distance_cm) < 0) {
            fprintf(stderr, "Failed to log distance\n");
        }

        // Guard time
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = MIN_GUARD_US;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Exiting\n");
    return EXIT_SUCCESS;
}

