#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLL_INTERVAL_MS 100

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP 0x0086
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP 0x0090
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_SPAD_NB 0x0050
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms for reset

    // Initialize ranging mode (short distance)
    if (i2cWriteByteData(i2c_handle, 0x0080, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, 0x0081, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    int distance = -1; // Default to error value
    int status;

    // Read distance data
    status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read distance data\n");
        return -1;
    }

    distance = status;

    // Read range status
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }

    // Check for valid range status
    if (status != 0) {
        fprintf(stderr, "Error: Invalid range status: %d\n", status);
        return -1;
    }

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
            gpioWrite(GPIO_RELAY, (distance <= DISTANCE_THRESHOLD) ? 1 : 0); // Open door if close
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Close door
    gpioTerminate();

    return 0;
}

