// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error: Could not acquire bus access and/or talk to slave.");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_smbus_write_byte_data(fd, GYRO_CONFIG, 0x00) < 0) {
        perror("Error: Could not write to GYRO_CONFIG register.");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    // Read high and low bytes for each axis
    int16_t high, low;

    high = i2c_smbus_read_byte_data(fd, GYRO_XOUT_H);
    if (high < 0) {
        perror("Error: Could not read high byte for GYRO_XOUT_H.");
        return -1;
    }
    low = i2c_smbus_read_byte_data(fd, GYRO_XOUT_L);
    if (low < 0) {
        perror("Error: Could not read low byte for GYRO_XOUT_L.");
        return -1;
    }

    *gyro_x = (high << 8) | low;

    high = i2c_smbus_read_byte_data(fd, GYRO_YOUT_H);
    if (high < 0) {
        perror("Error: Could not read high byte for GYRO_YOUT_H.");
        return -1;
    }
    low = i2c_smbus_read_byte_data(fd, GYRO_YOUT_L);
    if (low < 0) {
        perror("Error: Could not read low byte for GYRO_YOUT_L.");
        return -1;
    }

    *gyro_y = (high << 8) | low;

    high = i2c_smbus_read_byte_data(fd, GYRO_ZOUT_H);
    if (high < 0) {
        perror("Error: Could not read high byte for GYRO_ZOUT_H.");
        return -1;
    }
    low = i2c_smbus_read_byte_data(fd, GYRO_ZOUT_L);
    if (low < 0) {
        perror("Error: Could not read low byte for GYRO_ZOUT_L.");
        return -1;
    }

    *gyro_z = (high << 8) | low;

    return 0;
}

// Function to convert raw data to degrees/second
void convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *degrees_x, float *degrees_y, float *degrees_z) {
    *degrees_x = (float)gyro_x / 131.0;
    *degrees_y = (float)gyro_y / 131.0;
    *degrees_z = (float)gyro_z / 131.0;
}

// Function to log data to the console
void log_data(float degrees_x, float degrees_y, float degrees_z) {
    printf("Gyro X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", degrees_x, degrees_y, degrees_z);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device.");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    int16_t gyro_x, gyro_y, gyro_z;
    float degrees_x, degrees_y, degrees_z;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert data to degrees/second
            convert_data(gyro_x, gyro_y, gyro_z, &degrees_x, &degrees_y, &degrees_z);

            // Log data to the console
            log_data(degrees_x, degrees_y, degrees_z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        }

        // Delay for 100 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource cleanup.
    close(i2c_fd);
    return 0;
}

