#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define watering interval (seconds)
#define WATERING_INTERVAL 86400

// Define watering duration (seconds)
#define WATERING_DURATION 5

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay17 = NULL;
static struct gpiod_line *relay18 = NULL;
static struct gpiod_line *relay27 = NULL;
static struct gpiod_line *relay22 = NULL;
static FILE *log_file = NULL;

// Function prototypes
int gpio_init(struct gpiod_chip *chip, int pin, struct gpiod_line **line);
int gpio_set_direction(struct gpiod_line *line, const char *direction);
int gpio_write(struct gpiod_line *line, int value);
int gpio_read(struct gpiod_line *line, int *value);
int water_relay(struct gpiod_line *relay);
int log_watering_event(FILE *log_file);
void signal_handler(int sig);

// GPIO initialization function
int gpio_init(struct gpiod_chip *chip, int pin, struct gpiod_line **line) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));

    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d from chip %s\n", pin, GPIOCHIP);
        return -1;
    }

    if (gpiod_line_request(*line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error: Could not request line %d as output\n", pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// GPIO direction setting function
int gpio_set_direction(struct gpiod_line *line, const char *direction) {
    int ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set direction of line %d to %s\n", line->line, direction);
        return -1;
    }
    return 0;
}

// GPIO write function
int gpio_write(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value of line %d to %d\n", line->line, value);
        return -1;
    }
    return 0;
}

// GPIO read function
int gpio_read(struct gpiod_line *line, int *value) {
    int ret = gpiod_line_get_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get value of line %d\n", line->line);
        return -1;
    }
    return 0;
}

// Relay control function
int water_relay(struct gpiod_line *relay) {
    if (gpio_write(relay, 0) != 0) { // Activate relay (LOW)
        fprintf(stderr, "Error: Failed to activate relay on line %d\n", relay->line);
        return -1;
    }
    return 0;
}

// Logging function
int log_watering_event(FILE *log_file) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - Relay activated\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (relay17) {
        gpiod_line_release(relay17);
    }
    if (relay18) {
        gpiod_line_release(relay18);
    }
    if (relay27) {
        gpiod_line_release(relay27);
    }
    if (relay22) {
        gpiod_line_release(relay22);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s\n", GPIOCHIP);
        return 1;
    }

    // Initialize GPIO lines
    struct gpiod_line *lines[] = {relay17, relay18, relay27, relay22};
    for (int i = 0; i < 4; i++) {
        if (gpio_init(chip, lines[i]->line, &lines[i]) != 0) {
            fprintf(stderr, "Error: Failed to initialize GPIO line %d\n", lines[i]->line);
            // Release already initialized lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Set GPIO direction to output
    for (int i = 0; i < 4; i++) {
        if (gpio_set_direction(lines[i], "out") != 0) {
            fprintf(stderr, "Error: Failed to set direction for GPIO %d\n", lines[i]->line);
            // Release already initialized lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Open log file
    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file\n");
        // Release GPIO lines
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate relays sequentially
        for (int i = 0; i < 4; i++) {
            if (water_relay(lines[i]) != 0) {
                fprintf(stderr, "Error: Failed to water relay on GPIO %d\n", lines[i]->line);
                break; // Exit the loop if there's an error
            }
            if (log_watering_event(log_file) != 0) {
                fprintf(stderr, "Error: Failed to log watering event\n");
            }
            sleep(WATERING_DURATION);
        }

        // Wait for the specified interval
        sleep(WATERING_INTERVAL);
    }

    return 0;
}

