    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s\n", GPIOCHIP);
        return 1;
    }

    // Initialize GPIO lines
    struct gpiod_line *lines[] = {relay17, relay18, relay27, relay22};
    for (int i = 0; i < 4; i++) {
        if (gpio_init(chip, lines[i]->line, &lines[i]) != 0) {
