            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Set GPIO direction to output
    for (int i = 0; i < 4; i++) {
        if (gpio_set_direction(lines[i], "out") != 0) {
            fprintf(stderr, "Error: Failed to set direction for GPIO %d\n", lines[i]->line);
            // Release already initialized lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Open log file
    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file\n");
        // Release GPIO lines
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate relays sequentially
        for (int i = 0; i < 4; i++) {
            if (water_relay(lines[i]) != 0) {
                fprintf(stderr, "Error: Failed to water relay on GPIO %d\n", lines[i]->line);
                break; // Exit the loop if there's an error
            }
            if (log_watering_event(log_file) != 0) {
                fprintf(stderr, "Error: Failed to log watering event\n");
            }
            sleep(WATERING_DURATION);
        }

        // Wait for the specified interval
        sleep(WATERING_INTERVAL);
    }

    return 0;
}

