// Define the number of steps in the sunrise simulation
#define NUM_STEPS 31

// Define the PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int pin, int mode);
int set_pwm_frequency(int pin, int frequency);
int set_pwm_duty_cycle(int pin, int duty_cycle);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes for the relay pins
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1; // Indicate failure
    }

    // Set PWM frequency for all relays
    if (set_pwm_frequency(RELAY1_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY2_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to set the mode of a GPIO pin
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d mode to %d", pin, mode);
        log_event(message);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to set the PWM frequency for a GPIO pin
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != 0) {
