    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Smart lighting sunrise simulation started. Press Ctrl+C to exit.\n");

    // Main loop to simulate sunrise
    for (int i = 0; i < NUM_STEPS && program_running; i++) {
        // Calculate the duty cycle for each relay
        int duty_cycle1 = (int)(((float)i / NUM_STEPS) * 255.0);
        int duty_cycle2 = (int)(((float)i / NUM_STEPS) * 255.0);
        int duty_cycle3 = (int)(((float)i / NUM_STEPS) * 255.0);
        int duty_cycle4 = (int)(((float)i / NUM_STEPS) * 255.0);

        // Set the duty cycles for all relays
        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle1) != 0 ||
            set_pwm_duty_cycle(RELAY2_PIN, duty_cycle2) != 0 ||
            set_pwm_duty_cycle(RELAY3_PIN, duty_cycle3) != 0 ||
            set_pwm_duty_cycle(RELAY4_PIN, duty_cycle4) != 0) {
            fprintf(stderr, "Failed to set duty cycle for one or more relays\n");
            log_event("Failed to set duty cycle for one or more relays");
            program_running = 0; // Stop the simulation
            break;
        }

        // Log the event
        char message[200];
        sprintf(message, "Step %d: Relays set to duty cycles %d, %d, %d, %d", i + 1, duty_cycle1, duty_cycle2, duty_cycle3, duty_cycle4);
        log_event(message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Turn off all relays before exiting
    set_pwm_duty_cycle(RELAY1_PIN, 0);
    set_pwm_duty_cycle(RELAY2_PIN, 0);
    set_pwm_duty_cycle(RELAY3_PIN, 0);
    set_pwm_duty_cycle(RELAY4_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Smart lighting sunrise simulation finished.\n");

    return 0;
}

