#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_thresholds(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set gyroscope full-scale range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second (±250 deg/s range)
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check thresholds and control LED
void check_thresholds(float x, float y, float z) {
    if (fabs(x) > 250.0f || fabs(y) > 250.0f || fabs(z) > 250.0f) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(x, y, z);

            // Check thresholds and control LED
            check_thresholds(x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data, attempting re-initialisation...\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100ms delay
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not open I2C bus after re-initialisation\n");
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: MPU-6050 initialisation failed after re-initialisation\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        // Delay for 50ms (20Hz sampling rate)
        gpioDelay(50000);
    }

    // This point should not be reached due to the signal handler
    return 0;
}

