#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO_PIN 8
#define GYRO_SCALE_FACTOR 131.0
#define GYRO_SENSITIVITY 131.0 // For +/- 250 dps range
#define GYRO_REGISTER_START 0x43
#define GYRO_REGISTER_END 0x48
#define NUM_GYRO_READS 3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "gyro_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int fd, int16_t *x_rate, int16_t *y_rate, int16_t *z_rate);
void convert_gyro_data(int16_t x_raw, int16_t y_raw, int16_t z_raw, float *x_dps, float *y_dps, float *z_dps);
void log_data(FILE *fp, float timestamp, float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode_val = (mode & 0x03) << 4;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits_val = (bits & 0x03) << 2;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    uint8_t tx_buf[6] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00}; // Dummy data for reading
    uint8_t rx_buf[6];

    if (spi_transfer(fd, tx_buf, rx_buf, 6) != 0) {
        return -1;
    }

    *x_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y_rate = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    *z_rate = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_gyro_data(int16_t x_raw, int16_t y_raw, int16_t z_raw, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x_raw / GYRO_SENSITIVITY;
    *y_dps = (float)y_raw / GYRO_SENSITIVITY;
    *z_dps = (float)z_raw / GYRO_SENSITIVITY;
}

// Function to log data to file
void log_data(FILE *fp, float timestamp, float x_rate, float y_rate, float z_rate) {
    fprintf(fp, "%.9f,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (chip != NULL) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for chip select
    cs_line = gpiod_chip_get_line(chip, CS_GPIO_PIN);
    if (cs_line == NULL) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "mpu9250_cs";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,x_rate,y_rate,z_rate\n");
    }
    rewind(log_file);

    int16_t x_raw, y_raw, z_raw;
    float x_dps, y_dps, z_dps;
    float timestamp;
    int retry;

    // Main loop
    while (!terminate) {
        timestamp = time(NULL);
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_gyro_data(spi_fd, &x_raw, &y_raw, &z_raw) == 0) {
                convert_gyro_data(x_raw, y_raw, z_raw, &x_dps, &y_dps, &z_dps);
                log_data(log_file, timestamp, x_dps, y_dps, z_dps);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Gyro read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read gyro data after %d retries. Skipping.\n", RETRY_COUNT);
        }

        usleep(10000); // 10ms delay
    }

    cleanup();
    return 0;
}

