#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 10000000 // 3.9 MHz
#define CS_GPIO_PIN 8
#define LED_GPIO_PIN 17
#define BUFFER_SIZE 64
#define DEG_PER_LSB 131.0
#define MAX_DEG_PER_S 200.0
#define BLINK_INTERVAL_MS 500

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint32_t speed);
int spi_transfer(int fd, uint8_t reg, uint8_t *data, int len);
int mpu6050_init(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double convert_to_deg_per_s(int16_t raw_data);
bool check_stability(double x, double y, double z);
void blink_led(int pin, int interval_ms);
void print_buffer();
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = (mode & 0x00) | (mode & 0x01) | (mode & 0x02) | (mode & 0x04) | (mode & 0x08) | (mode & 0x10) | (mode & 0x20) | (mode & 0x40);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t reg, uint8_t *data, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)reg,
        .rx_buf = (unsigned long)data,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t data[2] = {0x00, 0x00};
    if (spi_transfer(fd, PWR_MGMT_1, data, 2) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250°/s
    data[0] = 0x00; // No change
    if (spi_transfer(fd, GYRO_CONFIG, data, 1) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (spi_transfer(fd, GYRO_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Convert raw data to degrees per second
double convert_to_deg_per_s(int16_t raw_data) {
    return (double)raw_data * DEG_PER_LSB;
}

// Check for stability
bool check_stability(double x, double y, double z) {
    if (fabs(x) > MAX_DEG_PER_S || fabs(y) > MAX_DEG_PER_S || fabs(z) > MAX_DEG_PER_S) {
        return true;
    }
    return false;
}

// Blink LED function
void blink_led(int pin, int interval_ms) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gyro_stability_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Error requesting LED line for output");
        return;
    }

    struct gpiod_line_set_value_config led_config;
    memset(&led_config, 0, sizeof(led_config));
    led_config.value = 1; // Turn on LED
    led_config.flags = 0;

    if (gpiod_line_set_value(led_line, &led_config) < 0) {
        perror("Error setting LED value");
        gpiod_line_release(led_line);
        return;
    }

    struct gpiod_line_set_value_config off_config;
    memset(&off_config, 0, sizeof(off_config));
    off_config.value = 0; // Turn off LED
    off_config.flags = 0;

    if (gpiod_line_set_value(led_line, &off_config) < 0) {
        perror("Error setting LED value (off)");
        gpiod_line_release(led_line);
        return;
    }

    usleep(interval_ms * 1000); // Convert ms to microseconds

    struct gpiod_line_set_value_config on_config;
    memset(&on_config, 0, sizeof(on_config));
    on_config.value = 1; // Turn on LED
    on_config.flags = 0;

    if (gpiod_line_set_value(led_line, &on_config) < 0) {
        perror("Error setting LED value (on)");
        gpiod_line_release(led_line);
