// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = (mode & 0x00) | (mode & 0x01) | (mode & 0x02) | (mode & 0x04) | (mode & 0x08) | (mode & 0x10) | (mode & 0x20) | (mode & 0x40);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t reg, uint8_t *data, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)reg,
        .rx_buf = (unsigned long)data,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t data[2] = {0x00, 0x00};
    if (spi_transfer(fd, PWR_MGMT_1, data, 2) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250°/s
    data[0] = 0x00; // No change
    if (spi_transfer(fd, GYRO_CONFIG, data, 1) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (spi_transfer(fd, GYRO_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Convert raw data to degrees per second
double convert_to_deg_per_s(int16_t raw_data) {
    return (double)raw_data * DEG_PER_LSB;
}

// Check for stability
bool check_stability(double x, double y, double z) {
    if (fabs(x) > MAX_DEG_PER_S || fabs(y) > MAX_DEG_PER_S || fabs(z) > MAX_DEG_PER_S) {
