#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C

// LED GPIO pin
#define LED_PIN 21

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_mpu6050();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_roll(int16_t x, int16_t y, int16_t z);
float calculate_pitch(int16_t x, int16_t y, int16_t z);
void control_led(float roll, float pitch);
void log_data(int16_t x, int16_t y, int16_t z, float roll, float pitch);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle); // Close I2C handle
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set accelerometer full-scale range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer full-scale range\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x3B, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data (read %d bytes)\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate roll angle
float calculate_roll(int16_t x, int16_t y, int16_t z) {
    float roll = atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
    return roll;
}

// Calculate pitch angle
float calculate_pitch(int16_t x, int16_t y, int16_t z) {
    float pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;
    return pitch;
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float roll, float pitch) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%d,%d,%.2f,%.2f\n", timestamp, x, y, z, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float roll, pitch;

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            // Calculate roll and pitch
            roll = calculate_roll(x, y, z);
            pitch = calculate_pitch(x, y, z);

            // Control LED
            control_led(roll, pitch);

            // Log data
            log_data(x, y, z, roll, pitch);

            // Print data to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data. Continuing...\n");
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    return 0;
}

