#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define GPIO_PIN 17
#define LED_ON 1
#define LED_OFF 0
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_write_register(int fd, unsigned char reg, unsigned char data);
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity);
int log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity);
int set_gpio_output(struct gpiod_chip *chip, struct gpiod_line *line, int value);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_register(int fd, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = ioctl(fd, I2C_SLAVE, SI1145_ADDR);
        if (result == -1) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        result = ioctl(fd, I2C_SLAVE, reg);
        if (result == -1) {
            perror("Error setting I2C register address");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("Error reading from I2C");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_register(int fd, unsigned char reg, unsigned char data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = ioctl(fd, I2C_SLAVE, SI1145_ADDR);
        if (result == -1) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        result = ioctl(fd, I2C_SLAVE, reg);
        if (result == -1) {
            perror("Error setting I2C register address");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        result = write(fd, &data, 1);
        if (result == 1) {
            return 0; // Success
        } else {
            perror("Error writing to I2C");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to write register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity) {
    unsigned char data[4];
    int result;

    // Read ambient light (2 bytes)
    result = i2c_read_register(fd, 0x20, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading ambient light data\n");
        return -1;
    }
    *ambient_light = (data[1] << 8) | data[0];

    // Read proximity (2 bytes)
    result = i2c_read_register(fd, 0x22, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    *proximity = (data[1] << 8) | data[0];

    return 0;
}

