int log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_chip *chip, struct gpiod_line *line, int value) {
    int result = gpiod_line_set_value(line, value);
    if (result < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    unsigned short ambient_light, proximity;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip == NULL) {
        perror("Error opening GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (gpio_line == NULL) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "biometric_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    result = gpiod_line_request(gpio_line, &config, 0);
    if (result < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            // Log data
            log_data(log_file, ambient_light, proximity);

            // Control LED based on proximity
            if (proximity > 100) {
                set_gpio_output(gpio_chip, gpio_line, LED_ON);
            } else {
                set_gpio_output(gpio_chip, gpio_line, LED_OFF);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    set_gpio_output(gpio_chip, gpio_line, LED_OFF); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

