#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXRS290 Register Addresses
#define X_RATE_REG 0x02
#define Y_RATE_REG 0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // No special flags needed

// Global Variables
int spi_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t address, uint8_t *data);
int spi_write_register(uint8_t address, uint8_t data);
int16_t read_gyro_data(uint8_t address);
void log_data(int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// SPI Read Register Function
int spi_read_register(uint8_t address, uint8_t *data) {
    char tx[3];
    char rx[2];

    tx[0] = address | 0x80; // Read bit set
    tx[1] = 0x00;           // Dummy byte
    tx[2] = 0x00;           // Dummy byte

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI read failed for address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }

    *data = rx[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t address, uint8_t data) {
    char tx[3];
    char rx[3];

    tx[0] = address & 0x7F; // Read bit cleared
    tx[1] = data;
    tx[2] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI write failed for address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }

    return 0;
}

// Read Gyro Data Function
int16_t read_gyro_data(uint8_t address) {
    uint8_t data[2];
    int16_t raw_rate;

    if (spi_read_register(address, &data[0]) != 0) {
        fprintf(stderr, "Failed to read X/Y rate register 0x%02X\n", address);
        return 0; // Return 0 on error
    }

    if (spi_read_register(address + 1, &data[1]) != 0) {
        fprintf(stderr, "Failed to read X/Y rate register 0x%02X\n", address + 1);
        return 0; // Return 0 on error
    }

    raw_rate = (int16_t)((data[0] << 8) | data[1]);
    return raw_rate;
}

// Log Data Function
void log_data(int16_t x_rate, int16_t y_rate) {
    time_t now = time(NULL);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp = now * 1000000 + ts.tv_nsec / 1000;

    fprintf(data_file, "%ld,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(data_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen("gyro_data.csv", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,X_rate,Y_rate\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t x_rate = read_gyro_data(X_RATE_REG);
        int16_t y_rate = read_gyro_data(Y_RATE_REG);

        log_data(x_rate, y_rate);

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(data_file);
    gpioTerminate();

    return 0;
}

