#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define ANGULAR_VELOCITY_THRESHOLD 20.0
#define CIRCULAR_BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10

// ADXRS290 Registers
#define RATE_XL_REG 0x02
#define RATE_XH_REG 0x03

// Structure for circular buffer entry
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} BufferEntry;

// Circular buffer
BufferEntry circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_spi();
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
float convert_to_degs_per_sec(int16_t raw_data);
void add_to_circular_buffer(float angular_velocity);
float get_angular_velocity();
void control_led(float angular_velocity);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    char tx_buffer[4];
    char rx_buffer[4];

    // Construct the SPI message to read the X-axis angular rate
    tx_buffer[0] = 0x80 | (RATE_XL_REG & 0x07); // Read bit set to 1
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte
    tx_buffer[3] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 4) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit angular rate
    *x_rate = (rx_buffer[1] << 8) | rx_buffer[2];
    *y_rate = (rx_buffer[3] << 8) | rx_buffer[0];

    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_degs_per_sec(int16_t raw_data) {
    return (float)raw_data / 200.0; // Sensitivity is 200 LSB/deg/s
}

// Function to add data to the circular buffer
void add_to_circular_buffer(float angular_velocity) {
    pthread_mutex_lock(&buffer_mutex);
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    circular_buffer[buffer_index].timestamp = ts;
    circular_buffer[buffer_index].angular_velocity = angular_velocity;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to get the angular velocity from the circular buffer
float get_angular_velocity() {
    pthread_mutex_lock(&buffer_mutex);
    int index = (buffer_index - 1 + CIRCULAR_BUFFER_SIZE) % CIRCULAR_BUFFER_SIZE; // Get the oldest entry
    float angular_velocity = circular_buffer[index].angular_velocity;
    pthread_mutex_unlock(&buffer_mutex);
    return angular_velocity;
}

// Function to control the LED
void control_led(float angular_velocity) {
    if (fabs(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_rate_raw, y_rate_raw;
    float angular_velocity;

    printf("Gyroscope data acquisition started...\n");

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x_rate_raw, &y_rate_raw) == 0) {
            // Convert to degrees per second
            angular_velocity = convert_to_degs_per_sec(x_rate_raw);

            // Add to circular buffer
            add_to_circular_buffer(angular_velocity);

            // Control LED
            control_led(angular_velocity);

            // Print angular velocity (optional)
            printf("Angular Velocity: %.2f deg/s\n", angular_velocity);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Delay to achieve desired sample rate
        gpioDelay(1000000 / SAMPLE_RATE_HZ); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

