#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 255

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_lamp_brightness(int gpio_pin, int brightness) {
    if (gpioPWM(gpio_pin, brightness) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio_pin);
    }
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio_pin) {
    int brightness;
    int duration = 60; // Fade duration in seconds (60 seconds)

    for (int i = 0; i <= duration; i++) {
        brightness = (int)(((float)i / duration) * PWM_RANGE);
        set_lamp_brightness(gpio_pin, brightness);
        gpioDelay(1000); // Delay for 1ms (1000 microseconds)
    }
    set_lamp_brightness(gpio_pin, 0); // Turn off the lamp
}

// Function to fade all lamps sequentially
void fade_all_lamps(int duration) {
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid fade duration. Must be between 1 and 3600 seconds.\n");
        return;
    }

    // Fade lamp 1
    printf("Fading lamp 1 (GPIO %d) for %d seconds...\n", LAMP1_GPIO, duration);
    fade_lamp(LAMP1_GPIO);
    printf("Lamp 1 faded.\n");

    // Fade lamp 2
    printf("Fading lamp 2 (GPIO %d) for %d seconds...\n", LAMP2_GPIO, duration);
    fade_lamp(LAMP2_GPIO);
    printf("Lamp 2 faded.\n");

    // Fade lamp 3
    printf("Fading lamp 3 (GPIO %d) for %d seconds...\n", LAMP3_GPIO, duration);
    fade_lamp(LAMP3_GPIO);
    printf("Lamp 3 faded.\n");
}

int main(int argc, char *argv[]) {
    int duration;

    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the argument to an integer
