        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio_pin);
    }
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio_pin) {
    int brightness;
    int duration = 60; // Fade duration in seconds (60 seconds)

    for (int i = 0; i <= duration; i++) {
        brightness = (int)(((float)i / duration) * PWM_RANGE);
        set_lamp_brightness(gpio_pin, brightness);
        gpioDelay(1000); // Delay for 1ms (1000 microseconds)
    }
    set_lamp_brightness(gpio_pin, 0); // Turn off the lamp
