#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RED_RELAY_PIN 17
#define YELLOW_RELAY_PIN 22
#define GREEN_RELAY_PIN 23
#define YELLOW_RELAY_PIN_2 24

// Define the duration of each state in seconds
#define RED_DURATION 10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *red_line, *yellow_line, *green_line, *yellow_line_2;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
void set_relay_state(int relay_pin, int state);
void red_state(void);
void red_yellow_state(void);
void green_state(void);
void yellow_state(void);
void traffic_light_cycle(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    yellow_line_2 = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN_2);

    if (!red_line || !yellow_line || !green_line || !yellow_line_2) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request lines for output
    if (gpiod_line_request_output(red_line, "traffic_light", 0) < 0) {
        perror("Error requesting red line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(yellow_line, "traffic_light", 0) < 0) {
        perror("Error requesting yellow line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(green_line, "traffic_light", 0) < 0) {
        perror("Error requesting green line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(yellow_line_2, "traffic_light", 0) < 0) {
        perror("Error requesting yellow line 2 for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    printf("Releasing GPIO lines...\n");
    gpiod_line_release(red_line);
    gpiod_line_release(yellow_line);
    gpiod_line_release(green_line);
    gpiod_line_release(yellow_line_2);
    gpiod_chip_close(chip);
    printf("GPIO cleanup complete.\n");
}

// Set relay state
void set_relay_state(int relay_pin, int state) {
    int ret;
    if (state == 0) { // Active-low
        ret = gpiod_line_set_value(red_line, 1); // Assuming red_line controls all relays
        if (ret < 0) {
            perror("Error setting red relay state");
        }
        ret = gpiod_line_set_value(yellow_line, 1);
        if (ret < 0) {
            perror("Error setting yellow relay state");
        }
        ret = gpiod_line_set_value(green_line, 1);
        if (ret < 0) {
            perror("Error setting green relay state");
        }
        ret = gpiod_line_set_value(yellow_line_2, 1);
        if (ret < 0) {
            perror("Error setting yellow relay state 2");
        }
    } else {
        ret = gpiod_line_set_value(red_line, 0);
        if (ret < 0) {
            perror("Error setting red relay state");
        }
        ret = gpiod_line_set_value(yellow_line, 0);
        if (ret < 0) {
            perror("Error setting yellow relay state");
        }
        ret = gpiod_line_set_value(green_line, 0);
        if (ret < 0) {
            perror("Error setting green relay state");
        }
        ret = gpiod_line_set_value(yellow_line_2, 0);
        if (ret < 0) {
            perror("Error setting yellow relay state 2");
        }
    }
}

// Red state
void red_state(void) {
    printf("Red state (10 seconds)\n");
    set_relay_state(RED_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN, 0);
    set_relay_state(GREEN_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN_2, 0);
    sleep(RED_DURATION);
    set_relay_state(RED_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN, 1);
    set_relay_state(GREEN_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN_2, 1);
    printf("Red state transition complete.\n");
}

// Red + Yellow state
void red_yellow_state(void) {
    printf("Red + Yellow state (2 seconds)\n");
    set_relay_state(RED_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN, 1);
    set_relay_state(GREEN_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN_2, 0);
    sleep(RED_YELLOW_DURATION);
    set_relay_state(RED_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN, 0);
    set_relay_state(GREEN_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN_2, 1);
    printf("Red + Yellow state transition complete.\n");
}

// Green state
void green_state(void) {
    printf("Green state (10 seconds)\n");
    set_relay_state(RED_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN, 0);
    set_relay_state(GREEN_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN_2, 1);
    sleep(GREEN_DURATION);
    set_relay_state(RED_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN, 1);
    set_relay_state(GREEN_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN_2, 0);
    printf("Green state transition complete.\n");
}

// Yellow state
void yellow_state(void) {
    printf("Yellow state (3 seconds)\n");
    set_relay_state(RED_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN, 1);
    set_relay_state(GREEN_RELAY_PIN, 0);
    set_relay_state(YELLOW_RELAY_PIN_2, 1);
    sleep(YELLOW_DURATION);
    set_relay_state(RED_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN, 0);
    set_relay_state(GREEN_RELAY_PIN, 1);
    set_relay_state(YELLOW_RELAY_PIN_2, 0);
    printf("Yellow state transition complete.\n");
}

// Traffic light cycle
void traffic_light_cycle(void) {
    red_state();
    red_yellow_state();
    green_state();
    yellow_state();
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Traffic light simulator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        traffic_light_cycle();
    }

    return 0;
}

