#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY_MS 100
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_reset();
int mpr121_stop_mode();
int mpr121_enable_electrode_0();
int mpr121_configure_touch_threshold();
int mpr121_configure_release_threshold();
int mpr121_configure_debounce();
int mpr121_configure_charge_time();
int mpr121_run_mode();
int read_touch_status();
void relay_on();
void relay_off();
void log_error(const char *message);
void signal_handler(int signal);

// Function to reset the MPR121
int mpr121_reset() {
    char buf[2];
    buf[0] = 0x80; // Reset command
    buf[1] = 0x63; // Reset value

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("MPR121 reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete
    return 0;
}

// Function to stop the MPR121
int mpr121_stop_mode() {
    char buf[2];
    buf[0] = 0x5E; // Stop mode command
    buf[1] = 0x00; // Stop mode value

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("MPR121 stop mode failed");
        return -1;
    }
    return 0;
}

// Function to enable electrode 0
int mpr121_enable_electrode_0() {
    char buf[2];
    buf[0] = 0x5D; // Enable electrode command
    buf[1] = 0x01; // Enable electrode 0

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("MPR121 enable electrode 0 failed");
        return -1;
    }
    return 0;
}

// Function to configure touch threshold
int mpr121_configure_touch_threshold() {
    char buf[2];
    buf[0] = 0x41; // Touch threshold command
    buf[1] = TOUCH_THRESHOLD; // Touch threshold value

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("MPR121 touch threshold configuration failed");
        return -1;
    }
    return 0;
}

// Function to configure release threshold
int mpr121_configure_release_threshold() {
    char buf[2];
    buf[0] = 0x42; // Release threshold command
    buf[1] = RELEASE_THRESHOLD; // Release threshold value

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
