#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Motor A GPIOs
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIOs
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable pins
#define ENA 24
#define ENB 25

// PWM frequency
#define PWM_FREQUENCY 1000

// PID parameters
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20.0

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();
float simulate_tilt_error();
float simulate_distance();
int calculate_motor_speed(float tilt_error, float distance);
void set_motor_speed(int motor, int speed);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins as outputs and set HIGH
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    // Set PWM frequency
    gpioSetPWMfrequency(ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(ENB, PWM_FREQUENCY);

    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    // Stop motors
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);

    // Disable enable pins
    gpioWrite(ENA, 0);
    gpioWrite(ENB, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Simulate tilt error
float simulate_tilt_error() {
    static float last_error = 0.0;
    static float integral = 0.0;
    static float dt = 0.05; // 50ms delay

    float error = (float)(rand() % 200 - 10) / 10.0; // Simulate tilt error between -1.0 and 1.0
    integral += error * dt;
    float derivative = (error - last_error) / dt;

    float output = KP * error + KI * integral + KD * derivative;

    last_error = error;

    // Clamp the output to the range [-255, 255]
    if (output < -255.0) output = -255.0;
    if (output > 255.0) output = 255.0;

    return output;
}

// Simulate distance sensor
float simulate_distance() {
    return (float)(rand() % 400 + 2) / 10.0; // Simulate distance between 2.0 and 40.0 cm
}

// Calculate motor speed based on PID output
int calculate_motor_speed(float tilt_error, float distance) {
    float pid_output = simulate_tilt_error();
    int motor_a_speed = (int)pid_output;
    int motor_b_speed = (int)pid_output;

    // Clamp the output to the range [-255, 255]
    if (motor_a_speed < -255.0) motor_a_speed = -255.0;
    if (motor_a_speed > 255.0) motor_a_speed = 255.0;
    if (motor_b_speed < -255.0) motor_b_speed = -255.0;
    if (motor_b_speed > 255.0) motor_b_speed = 255.0;

    return motor_a_speed;
}

// Set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 0) {
        gpioPWM(MOTOR_A_FORWARD, speed);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else if (motor == 1) {
        gpioPWM(MOTOR_B_FORWARD, speed);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Self-balancing robot started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        // Simulate tilt error and distance
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        // Calculate motor speeds
        int motor_a_speed = calculate_motor_speed(tilt_error, distance);
        int motor_b_speed = calculate_motor_speed(tilt_error, distance);

        // Set motor speeds
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            printf("Obstacle detected! Reversing motors.\n");
            set_motor_speed(0, 50); // Reverse Motor A
            set_motor_speed(1, 50); // Reverse Motor B
        } else {
            set_motor_speed(0, motor_a_speed);
            set_motor_speed(1, motor_b_speed);
        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50); // 50ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

