#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static int relay_state = 0; // 0 = OFF, 1 = ON

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        // Debounce the touch sensor
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds

        // Check if the touch sensor is still HIGH after the debounce delay
        if (touch_detected == 1) {
            // Toggle the relay state
            relay_state = !relay_state;

            // Set the relay pin to the new state
            gpioWrite(RELAY_PIN, relay_state);

            // Print the new relay state
            printf("Relay is now %s\n", relay_state ? "ON" : "OFF");
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    return 0;
}

