        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds

        // Check if the touch sensor is still HIGH after the debounce delay
        if (touch_detected == 1) {
            // Toggle the relay state
            relay_state = !relay_state;

            // Set the relay pin to the new state
            gpioWrite(RELAY_PIN, relay_state);

            // Print the new relay state
            printf("Relay is now %s\n", relay_state ? "ON" : "OFF");
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    return 0;
}

