#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Default ALSA parameters
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_CHANNELS   1
#define DEFAULT_FORMAT      16 // ALSA format for 16-bit signed little-endian
#define DEFAULT_PERIOD_SIZE 1024

// Global variables
snd_pcm_t *pcm_handle;
int running = 1;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle, int sample_rate, int channels, int format, int period_size);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size);
double calculate_rms(const short *buffer, int buffer_size);
void map_amplitude_to_rgb(double rms, int sensitivity, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
        running = 0;
    }
}

// Initialize ALSA audio capture
int init_alsa(snd_pcm_t **pcm_handle, int sample_rate, int channels, int format, int period_size) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    // Open PCM device for capture
    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set format
    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, format)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, channels)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int rate = sample_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set period size
    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, period_size, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Capture audio data from ALSA
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size) {
    int err;
    int frames_to_read = buffer_size / 2; // Each short is 2 bytes

    while (running && frames_to_read > 0) {
        err = snd_pcm_readi(pcm_handle, buffer, frames_to_read);
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            return -1;
        } else if (err != frames_to_read) {
            fprintf(stderr, "Short read, expected %d, got %d\n", frames_to_read, err);
            return -1;
        }
        frames_to_read -= err;
    }
    return 0;
}

// Calculate RMS amplitude of audio data
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

// Map RMS amplitude to RGB color values
void map_amplitude_to_rgb(double rms, int sensitivity, int *red, int *green, int *blue) {
    // Non-linear transition from cool to warm colors
    double normalized_rms = rms / 32768.0; // Normalize to 16-bit range
    double normalized_rms_linear = normalized_rms * 2.0; // Scale to 0-2 range

    // Cool colors (blue, green)
    if (normalized_rms_linear < 1.0) {
        *red = 0;
        *green = (int)(normalized_rms_linear * 255.0);
        *blue = (int)(255.0 - normalized_rms_linear * 255.0);
    } else {
        // Warm colors (red, yellow)
        *red = (int)(normalized_rms_linear * 255.0);
        *green = 255;
        *blue = 0;
    }

    // Scale to 0-255 range
    *red = (int)((double)*red / sensitivity);
    *green = (int)((double)*green / sensitivity);
    *blue = (int)((double)*blue / sensitivity);
}

// Set RGB LED color using pigpio PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main(int argc, char *argv[]) {
    int sensitivity = 1.0; // Default sensitivity
    int red, green, blue;
    short *buffer;
    int buffer_size;
    double rms;
    int err;

    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Error: Sensitivity must be a positive value\n");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA
    if (alsa_available()) {
        snd_pcm_t *pcm_handle;
        if (init_alsa(&pcm_handle, DEFAULT_SAMPLE_RATE, DEFAULT_CHANNELS, DEFAULT_FORMAT, DEFAULT_PERIOD_SIZE) != 0) {
            fprintf(stderr, "ALSA initialization failed\n");
            gpioTerminate();
            return 1;
        }

        buffer_size = DEFAULT_PERIOD_SIZE * DEFAULT_CHANNELS;
        buffer = (short *)malloc(buffer_size * sizeof(short));
        if (buffer == NULL) {
            fprintf(stderr, "Failed to allocate memory for audio buffer\n");
            snd_pcm_close(pcm_handle);
            gpioTerminate();
            return 1;
        }

        while (running) {
            if (capture_audio(pcm_handle, buffer, buffer_size) == 0) {
                rms = calculate_rms(buffer, buffer_size);
                map_amplitude_to_rgb(rms, sensitivity, &red, &green, &blue);
                set_led_color(red, green, blue);
            } else {
                fprintf(stderr, "Error capturing audio, exiting\n");
                break;
            }
            gpioDelay(10000); // 10 ms delay
        }
        free(buffer);
        snd_pcm_close(pcm_handle);
    } else {
        fprintf(stderr, "ALSA not available, simulating audio input\n");
        // Simulate audio input with a sine wave
        double angle = 0.0;
        double frequency = 440.0; // A4
        double amplitude = 0.0;
        buffer_size = DEFAULT_PERIOD_SIZE * DEFAULT_CHANNELS;
        buffer = (short *)malloc(buffer_size * sizeof(short));
        if (buffer == NULL) {
            fprintf(stderr, "Failed to allocate memory for audio buffer\n");
            gpioTerminate();
            return 1;
        }

        while (running) {
            for (int i = 0; i < buffer_size; i++) {
                buffer[i] = (short)(amplitude * 32767); // Scale to 16-bit range
                amplitude += 0.01 * sin(angle); // Sine wave
                angle += 2 * M_PI * frequency / DEFAULT_SAMPLE_RATE;
            }
            rms = calculate_rms(buffer, buffer_size);
            map_amplitude_to_rgb(rms, sensitivity, &red, &green, &blue);
            set_led_color(red, green, blue);
            gpioDelay(10000); // 10 ms delay
        }
        free(buffer);
    }

    // Clean up
    gpioTerminate();
    if (alsa_available()) {
        snd_pcm_close(pcm_handle);
    }

    return 0;
}

