#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ID              (0x12)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)
#define TCS34725_ATIME           (0x81)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_CONTROL_AEN     (0x10)

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int initialize_sensor();
color_data_t read_color_data();
void log_data(color_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Check if the sensor is present
    int id = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and RGBC
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }
    gpioDelay(3); // Wait for power-on (at least 3ms)

    // Set integration time (154ms)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Enable RGBC (again after power-on)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
color_data_t read_color_data() {
    color_data_t data;
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data\n");
        data.clear = 0; data.red = 0; data.green = 0; data.blue = 0;
        return data;
    }

    data.clear = (buffer[1] << 8) | buffer[0];
    data.red   = (buffer[3] << 8) | buffer[2];
    data.green = (buffer[5] << 8) | buffer[4];
    data.blue  = (buffer[7] << 8) | buffer[6];

    return data;
}

// Function to log data to a CSV file
void log_data(color_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);
    fflush(fp); // Ensure data is written to file immediately
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv\n");
        cleanup();
        return 1;
    }

    // Write the header row
    fprintf(fp, "timestamp,clear,red,green,blue\n");

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        color_data_t data = read_color_data();
        log_data(data);
        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

