#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 11
#define RELAY2_PIN 13
#define RELAY3_PIN 15
#define RELAY4_PIN 17

// Define chip name for the GPIO chip
#define GPIO_CHIP "gpiochip0"

// Define the number of relays
#define NUM_RELAYS 4

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 518400

// Define the number of steps for the brightness simulation
#define BRIGHTNESS_STEPS 100

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL, NULL, NULL, NULL};

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_relay_state(int pin, int state);
void simulate_brightness(int pin, int step);
void sunrise();
void daytime();
void sunset();
void nighttime();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the GPIO chip and lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Open the relay lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, "/gpio17/pin%d", i + 1);
        if (!line) {
            fprintf(stderr, "Error opening line %d: %s\n", i + 1, strerror(errno));
            cleanup_gpio();
            return -1;
        }
        relay_lines[i] = line;
        if (gpiod_line_request_output(line, "sunlight_simulator", 0) < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", i + 1, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to cleanup the GPIO chip and lines
void cleanup_gpio() {
    // Turn off all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(relay_lines[i]->number, 0);
    }

    // Release the GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(relay_lines[i]);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to set the state of a relay (active-low)
void set_relay_state(int pin, int state) {
    if (pin != RELAY1_PIN && pin != RELAY2_PIN && pin != RELAY3_PIN && pin != RELAY4_PIN) {
        fprintf(stderr, "Invalid relay pin: %d\n", pin);
        return;
    }

    if (state != 0 && state != 1) {
        fprintf(stderr, "Invalid relay state: %d\n", state);
        return;
    }

    if (relay_lines[pin - 11] == NULL) {
        fprintf(stderr, "Relay line for pin %d is NULL\n", pin);
        return;
    }

    if (gpiod_line_set_value(relay_lines[pin - 11], state) < 0) {
        fprintf(stderr, "Error setting value for line %d: %s\n", pin, strerror(errno));
    }
}

// Function to simulate brightness by toggling the relay state
void simulate_brightness(int pin, int step) {
    if (pin != RELAY1_PIN && pin != RELAY2_PIN && pin != RELAY3_PIN && pin != RELAY4_PIN) {
        fprintf(stderr, "Invalid relay pin: %d\n", pin);
        return;
    }

    if (step < 0 || step > BRIGHTNESS_STEPS) {
        fprintf(stderr, "Invalid brightness step: %d\n", step);
        return;
    }

    int duty_cycle = (int)(((float)step / BRIGHTNESS_STEPS) * 100.0);
    if (gpiod_line_set_value(relay_lines[pin - 11], (duty_cycle > 50) ? 0 : 1) < 0) {
        fprintf(stderr, "Error setting value for line %d: %s\n", pin, strerror(errno));
    }
}

// Function to simulate sunrise
void sunrise() {
    printf("Simulating sunrise...\n");
    for (int i = 0; i <= BRIGHTNESS_STEPS; i++) {
        simulate_brightness(RELAY1_PIN, i);
        simulate_brightness(RELAY2_PIN, i);
        simulate_brightness(RELAY3_PIN, i);
        simulate_brightness(RELAY4_PIN, i);
        sleep(1);
    }
    printf("Sunrise complete.\n");
}

// Function to simulate daytime
void daytime() {
    printf("Simulating daytime...\n");
    for (int i = 0; i < BRIGHTNESS_STEPS; i++) {
        simulate_brightness(RELAY1_PIN, i);
        simulate_brightness(RELAY2_PIN, i);
        simulate_brightness(RELAY3_PIN, i);
        simulate_brightness(RELAY4_PIN, i);
        sleep(1);
    }
    printf("Daytime complete.\n");
}

// Function to simulate sunset
void sunset() {
    printf("Simulating sunset...\n");
    for (int i = BRIGHTNESS_STEPS - 1; i >= 0; i--) {
        simulate_brightness(RELAY1_PIN, i);
        simulate_brightness(RELAY2_PIN, i);
        simulate_brightness(RELAY3_PIN, i);
        simulate_brightness(RELAY4_PIN, i);
        sleep(1);
    }
    printf("Sunset complete.\n");
}

// Function to simulate nighttime
void nighttime() {
    printf("Simulating nighttime...\n");
    for (int i = 0; i <= BRIGHTNESS_STEPS; i++) {
        simulate_brightness(RELAY1_PIN, i);
        simulate_brightness(RELAY2_PIN, i);
        simulate_brightness(RELAY3_PIN, i);
        simulate_brightness(RELAY4_PIN, i);
        sleep(1);
    }
    printf("Nighttime complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    return 0;
}

