#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log motion detection events to a file
void log_motion_event(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s Motion detected\n", timestamp);
    fclose(fp);
}

// Function to generate a timestamped filename for the video
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(50 * sizeof(char)); // Allocate memory for the filename

    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(filename, 50, "%Y%m%dT%H%M%S.h264", timeinfo);
    return filename;
}

// Function to execute the raspivid command
int execute_raspivid(const char* filename) {
    char command[100];
    snprintf(command, sizeof(command), "raspivid -o %s -t 5000", filename);
    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid command");
        return -1;
    }
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Debouncing logic
        unsigned long current_time = gpioTick();
        if (sensor_value == 0) { // Obstacle detected (active-low signal)
            if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS * 1000) {
                // Get timestamp
                char* timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    // Log motion event
                    log_motion_event(timestamp);

                    // Generate filename
                    char* filename = generate_filename();
                    if (filename != NULL) {
                        // Execute raspivid
                        if (execute_raspivid(filename) == 0) {
                            printf("Motion detected and video recorded: %s\n", filename);
                        } else {
                            fprintf(stderr, "Failed to execute raspivid\n");
                        }
                        free(filename);
                    } else {
                        fprintf(stderr, "Failed to generate filename\n");
                    }
                    free(timestamp);
                } else {
                    fprintf(stderr, "Failed to get timestamp\n");
                }

                // Update last trigger time
                last_trigger_time = current_time;
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(50); // 50ms delay
    }

    // Clean up
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

