#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
gyro_data_t convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050: %s\n", strerror(errno));
        return -1;
    }

    // Set sample rate divider to 125 Hz
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider: %s\n", strerror(errno));
        return -1;
    }

    // Set gyroscope full-scale range to ±250°/s
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read raw gyroscope data from MPU-6050
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, 0x43, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw gyroscope data to degrees per second
gyro_data_t convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    gyro_data_t data;
    data.x = (float)raw_x / 131.0;
    data.y = (float)raw_y / 131.0;
    data.z = (float)raw_z / 131.0;
    return data;
}

// Log gyroscope data to CSV file
void log_data(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed. Attempting re-initialization...\n");
        int retries = 3;
        while (retries > 0) {
            fprintf(stderr, "Attempting re-initialization (attempt %d)...\n", 4 - retries);
            if (init_mpu6050() == 0) {
                fprintf(stderr, "MPU-6050 re-initialisation successful.\n");
                break; // Exit retry loop if successful
            } else {
                fprintf(stderr, "MPU-6050 re-initialisation failed. Retrying in 1 second...\n");
                gpioDelay(1000); // Wait 1 second before retrying
                retries--;
            }
        }
        if (retries == 0) {
            fprintf(stderr, "Error: MPU-6050 re-initialisation failed after multiple attempts. Exiting.\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    gyro_data_t dps;
    struct timespec sleep_time = {0, 10000}; // 10 ms = 100 Hz

    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            dps = convert_to_dps(raw_x, raw_y, raw_z);
            log_data(dps);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Attempting re-initialization...\n");
            // Attempt re-initialization
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: MPU-6050 re-initialisation failed. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

