#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int zone, int state);
void log_data(int moisture, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down gracefully...\n");
        program_running = 0; // Set the flag to exit the main loop

        // Deactivate all relays
        control_relay(1, 1); // Zone 1
        control_relay(2, 1); // Zone 2
        control_relay(3, 1); // Zone 3
        control_relay(4, 1); // Zone 4

        // Close the log file
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp != NULL) {
            fprintf(fp, "Program terminated.\n");
            fclose(fp);
        } else {
            perror("Error closing log file");
        }

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to HIGH (deactivated)
    control_relay(1, 1); // Zone 1
    control_relay(2, 1); // Zone 2
    control_relay(3, 1); // Zone 3
    control_relay(4, 1); // Zone 4

    return 0; // Indicate success
}

// Function to read the moisture sensor value
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random number between 0 and 100
    return rand() % 101;
}

// Function to control the relay (active-low)
void control_relay(int zone, int state) {
    int pin;

    switch (zone) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid zone number: %d\n", zone);
            return;
    }

    // Set the relay state (active-low)
    gpioWrite(pin, state);
}

// Function to log data to a file
void log_data(int moisture, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    // Get the current time
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    // Write the data to the log file
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Moisture: %d, Relay: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            moisture, relay_state);

    fclose(fp);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the moisture sensor
        int moisture = read_moisture_sensor();

        // Control the relays based on the moisture level
        if (moisture < 30) {
            control_relay(1, 0); // Zone 1
            control_relay(2, 0); // Zone 2
            control_relay(3, 0); // Zone 3
            control_relay(4, 0); // Zone 4
        } else {
            control_relay(1, 1); // Zone 1
            control_relay(2, 1); // Zone 2
            control_relay(3, 1); // Zone 3
            control_relay(4, 1); // Zone 4
        }

        // Log the data
        log_data(moisture, gpioRead(RELAY1_PIN)); // Read the current state of the first relay
        log_data(moisture, gpioRead(RELAY2_PIN)); // Read the current state of the second relay
        log_data(moisture, gpioRead(RELAY3_PIN)); // Read the current state of the third relay
        log_data(moisture, gpioRead(RELAY4_PIN)); // Read the current state of the fourth relay

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

