#define DATA_FORMAT 0x31
#define POWER_CTL 0x2D
#define DATAX0 0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Scaling factor (LSB/g)
#define SCALE_FACTOR 256.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_adxl345();
int read_accelerometer_data(accelerometer_data_t *data);
int detect_freefall(accelerometer_data_t data);
void log_freefall_event(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure ADXL345
int configure_adxl345() {
    // Set DATA_FORMAT register to enable full resolution and ±2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register: %s\n", strerror(errno));
        return -1;
    }

    // Set POWER_CTL register to enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(accelerometer_data_t *data) {
    char raw_data[6];
    int16_t x, y, z;

    // Read 6 bytes starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force
    data->x = (float)x / SCALE_FACTOR;
    data->y = (float)y / SCALE_FACTOR;
    data->z = (float)z / SCALE_FACTOR;

    return 0;
}

// Detect freefall
int detect_freefall(accelerometer_data_t data) {
    static int freefall_start = 0;
    static int freefall_confirmed = 0;
    static time_t freefall_start_time = 0;
    static int freefall_confirmed_time = 0;
    static int freefall_confirmed_count = 0;

    // Check if all axes are below the threshold
    if (fabs(data.x) < FREEFALL_THRESHOLD && fabs(data.y) < FREEFALL_THRESHOLD && fabs(data.z) < FREEFALL_THRESHOLD) {
        if (freefall_start == 0) {
            freefall_start = 1;
            freefall_start_time = time(NULL);
            freefall_confirmed_count = 0;
        } else {
            time_t current_time = time(NULL);
            if (difftime(current_time, freefall_start_time) >= FREEFALL_DURATION) {
                freefall_confirmed = 1;
                freefall_confirmed_time = current_time;
                freefall_confirmed_count = 1;
                freefall_start = 0; // Reset start time
            } else {
                freefall_confirmed_count++;
            }
        }
    } else {
        freefall_start = 0;
        freefall_confirmed = 0;
        freefall_confirmed_count = 0;
    }

    return (freefall_confirmed == 1 && freefall_confirmed_count == 2);
}

// Log freefall event
void log_freefall_event(accelerometer_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADXL345
    if (configure_adxl345() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    accelerometer_data_t data;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer_data(&data) == 0) {
            // Detect freefall
            if (detect_freefall(data)) {
                printf("Freefall detected!\n");
                // Log freefall event
                log_freefall_event(data);

                // Activate alarm
                gpioWrite(ALARM_PIN, 1);
                gpioDelay(5000); // 5 seconds
                gpioWrite(ALARM_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Continuing...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

