#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_US 100000 // 100 ms
#define MAX_DISTANCE_CM 400 // Maximum measurable distance in cm (4 meters)
#define MAX_PULSE_WIDTH_US 23200 // Maximum pulse width in microseconds
#define MAX_PULSE_WIDTH_CM (MAX_PULSE_WIDTH_US / 10000.0) // Convert to cm
#define MAX_RETRIES 3

// Define mutex
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global variables
volatile unsigned int pulse_start_tick = 0;
volatile unsigned int pulse_end_tick = 0;
volatile int echo_received = 0;
volatile int echo_valid = 0;
volatile int echo_distance_cm = 0;
volatile int echo_timeout = 0;
volatile int echo_retries = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_distance_cm(unsigned int pulse_start, unsigned int pulse_end);
void log_distance(double distance_cm);
void signal_handler(int signal);
void *sensor_thread(void *arg);

// Function to trigger a 10 µs pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 µs
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) {
        // Rising edge
        pulse_start_tick = tick;
        echo_received = 1;
        echo_timeout = 0;
        echo_retries = 0;
    } else if (level == 0) {
        // Falling edge
        pulse_end_tick = tick;
        echo_received = 2;
    }
}

// Function to calculate distance in centimeters
double calculate_distance_cm(unsigned int pulse_start, unsigned int pulse_end) {
    if (pulse_start == 0 || pulse_end == 0) {
        return -1.0; // Indicate error
    }

    unsigned int pulse_width = pulse_end - pulse_start;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    if (pulse_width > MAX_PULSE_WIDTH_US) {
        return -1.0; // Indicate error
    }

    return (double)pulse_width / 10000.0; // Convert to cm
}

// Function to log distance to file
void log_distance(double distance_cm) {
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening distance_log.txt");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f\n", timestamp, distance_cm);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioSetISRFuncEx(TRIG_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable interrupt
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

// Thread function for sensor monitoring
void *sensor_thread(void *arg) {
    while (1) {
        trigger_pulse();
        gpioDelay(200); // Wait 200 ms

        if (echo_received == 0) {
            // Timeout occurred
            echo_distance_cm = -1.0;
        } else if (echo_received == 1) {
            // Wait for falling edge
            int retries = 0;
            while (echo_retries < MAX_RETRIES) {
                if (echo_timeout > 0) {
                    echo_distance_cm = -1.0;
                    break;
                }
                gpioDelay(10); // Small delay to avoid busy-waiting
                if (gpioRead(ECHO_PIN) == 0) {
                    echo_timeout = 0;
                    break;
                } else {
                    echo_timeout = 0;
                    echo_retries++;
                    if (echo_retries >= MAX_RETRIES) {
                        echo_distance_cm = -1.0;
                        break;
                    }
                }
            }
        } else if (echo_received == 2) {
            // Calculate distance
            double distance_cm = calculate_distance_cm(pulse_start_tick, pulse_end_tick);

            if (distance_cm >= 0.0 && distance_cm <= MAX_DISTANCE_CM) {
                // Validate distance
                if (distance_cm > 0.0 && distance_cm < MAX_PULSE_WIDTH_CM) {
                    echo_valid = 1;
                    echo_distance_cm = (double)pulse_end_tick - pulse_start_tick;
                } else {
                    echo_valid = 0;
                    echo_distance_cm = -1.0;
                }
            } else {
                echo_valid = 0;
                echo_distance_cm = -1.0;
            }
        }

        if (echo_valid) {
            log_distance((double)pulse_end_tick - pulse_start_tick);
        }

        gpioDelay(50); // Delay between measurements
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set interrupt callback
    gpioSetISRFuncEx(TRIG_PIN, EITHER_EDGE, 0, echo_callback, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        perror("Failed to create sensor thread");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIG_PIN, 0);
        gpioDelay(200);
    }

    // Cleanup (should not reach here due to signal handler)
    pthread_join(sensor_thread_id, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    return 0;
}

