        gpioDelay(10);
        gpioWrite(TRIG_PIN, 0);
        gpioDelay(200);
    }

    // Cleanup (should not reach here due to signal handler)
    pthread_join(sensor_thread_id, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
