#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <string.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
float calculate_magnitude(float x, float y, float z);
void freefall_detected();
void impact_detected();
void activate_buzzer();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // I2C bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize LIS3DH
int init_lis3dh() {
    // Set data rate to 100 Hz and full scale to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full scale to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw acceleration value to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 16384.0f;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to detect freefall
void freefall_detected() {
    float magnitude = calculate_magnitude(0.0f, 0.0f, 0.0f); // Read from zeroed values
    if (magnitude < 0.2f) {
        printf("Freefall detected!\n");
    }
}

// Function to detect impact
void impact_detected() {
    float magnitude = calculate_magnitude(0.0f, 0.0f, 0.0f); // Read from zeroed values
    if (magnitude > 1.5f) {
        printf("Impact detected!\n");
        activate_buzzer();
    }
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main(int argc, char *argv[]) {
    int freefall_threshold = 0.2f;
    int impact_threshold = 1.5f;

    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    printf("Freefall threshold: %.2f g\n", freefall_threshold);
    printf("Impact threshold: %.2f g\n", impact_threshold);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float x_g, y_g, z_g;
    float magnitude;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Convert to g
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x_g, y_g, z_g);

            // Detect fall and impact
            freefall_detected();
            impact_detected();

            // Print acceleration values (optional)
            printf("X: %.2f g, Y: %.2f g, Z: %.2f g, Magnitude: %.2f g\n", x_g, y_g, z_g, magnitude);
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

