#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration structure
typedef struct {
    int i2c_address;
    float threshold;
    int i2c_handle;
} Config;

// Global variables
static volatile int running = 1;
static Config config;

// Function prototypes
int parse_arguments(int argc, char *argv[], Config *config);
int initialize_pigpio(Config *config);
int initialize_i2c(Config *config);
int configure_sensor(Config *config);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
float convert_to_g(int16_t raw_value);
void log_event(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[], Config *config) {
    config->i2c_address = 0x18; // Default I2C address
    config->threshold = 2.0;    // Default threshold
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                config->i2c_address = strtol(optarg, NULL, 0);
                if (config->i2c_address < 0x08 || config->i2c_address > 0x77) {
                    fprintf(stderr, "Error: I2C address must be between 0x08 and 0x77\n");
                    return 1;
                }
                break;
            case 't':
                config->threshold = strtof(optarg, NULL);
                if (config->threshold <= 0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    return 0;
}

// Initialize pigpio
int initialize_pigpio(Config *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c(Config *config) {
    config->i2c_handle = i2cOpen(1, config->i2c_address, 0); // Bus 1, address, flags
    if (config->i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (error code %d)\n", config->i2c_handle);
        return 1;
    }
    return 0;
}

// Configure the LIS3DH sensor
int configure_sensor(Config *config) {
    char buf[2];
    buf[0] = CTRL_REG1;
    buf[1] = 0x57; // 100Hz, high resolution, enable all axes
    if (i2cWriteByteData(config->i2c_handle, buf[0], buf[1]) != 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG1\n");
        return 1;
    }

    buf[0] = CTRL_REG4;
    buf[1] = 0x88; // +/-2g, high resolution
    if (i2cWriteByteData(config->i2c_handle, buf[0], buf[1]) != 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_REG4\n");
        return 1;
    }

    return 0;
}

// Read acceleration data from the sensor
