        // Add sensor values to circular buffer
        add_to_buffer(left_value);
        add_to_buffer(center_value);
        add_to_buffer(right_value);

        // Check center sensor and trigger actions
        if (center_value == 0) {
            move_forward();
        } else if (center_value == 1) {
            if (left_value == 0) {
                turn_left();
            } else if (right_value == 0) {
                turn_right();
            } else {
                stop();
            }
        } else {
            stop();
        }

        // Check for consecutive no-line readings and trigger alert
        if (center_value == 1) {
            int no_line_count = 0;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                if (circular_buffer[i] == 1) {
                    no_line_count++;
                }
            }
            if (no_line_count >= 5) {
                alert_gpio(ALERT_PIN, 2000); // Alert for 2 seconds
            }
        }

        gpioDelay(10000); // Delay for 10 ms (10000 microseconds)
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated\n");

    return 0;
}

