            log_event("I2C Write Error", "Failed to start conversion");
            return -1;
        }
        gpioDelay(1); // Small delay after write

        // Wait for conversion to complete (register 0xC1 should be 0x00)
        int timeout = 50; // Number of polls to wait
        while (i2cReadByteData(i2c_handle, 0xC1) != 0x00 && timeout > 0) {
            gpioDelay(1); // Small delay between polls
            timeout--;
        }

        if (timeout == 0) {
            log_event("I2C Read Error", "Conversion timeout");
            return -1;
        }

        // Read two bytes from register 0xC0
        char buffer[2];
        result = i2cReadByteData(i2c_handle, 0xC0);
        if (result < 0) {
            log_event("I2C Read Error", "Failed to read data");
            return -1;
        }
        buffer[0] = (char)result;

        result = i2cReadByteData(i2c_handle, 0xC0 + 1);
        if (result < 0) {
            log_event("I2C Read Error", "Failed to read data");
            return -1;
        }
        buffer[1] = (char)result;

        *field_raw = (buffer[1] << 8) | buffer[0];
        return 0; // Success
    }

    log_event("I2C Read Error", "Max retries reached");
    return -1; // Failure after max retries
}

// Convert raw data to milliTesla
float convert_to_mT(int field_raw) {
    return (float)field_raw * 25 / 1000.0;
}

// Check if the field strength exceeds the threshold
int check_threshold(float mT_value) {
    return (mT_value > THRESHOLD_MT);
}

// Control the relay (active high)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log events to file
void log_event(const char *event_type, const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - %s: %s\n", timestamp, event_type, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    log_event("System Shutdown", "Program terminated gracefully.");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is initially off

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int field_raw;
    float mT_value;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Starting magnetic field monitoring...\n");

    while (!terminate) {
        // Read sensor data
        if (read_si7210_data(&field_raw) == 0) {
            // Convert to milliTesla
            mT_value = convert_to_mT(field_raw);

            // Check threshold
            if (check_threshold(mT_value)) {
                if (relay_state == 0) {
                    control_relay(1); // Activate relay
                    relay_state = 1;
                    log_event("Relay Activation", "Threshold exceeded");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0); // Deactivate relay
                    relay_state = 0;
                    log_event("Relay Deactivation", "Threshold not exceeded");
                }
            }

            // Log event
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Field: %.2f mT", mT_value);
            log_event("Sensor Data", log_message);
        } else {
            log_event("Sensor Read Error", "Failed to read sensor data");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    cleanup();
    return 0;
}

