#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

int server_fd, new_socket;
FILE *log_file;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (new_socket > 0) {
        close(new_socket);
    }
    if (server_fd > 0) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off the relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    // Receive data from the client
    valread = read(client_socket, buffer, 1024);
    if (valread < 0) {
        perror("Error reading from socket");
        close(client_socket);
        return;
    }

    buffer[valread] = '\0'; // Null-terminate the buffer

    // Check for the "ON" command
    if (strstr(buffer, "ON") != NULL) {
        gpioWrite(GPIO_PIN, 1); // Turn on the relay
        log_event("Relay turned ON");
        send(client_socket, "Relay ON\n", strlen("Relay ON\n"), 0);
    }
    // Check for the "OFF" command
    else if (strstr(buffer, "OFF") != NULL) {
        gpioWrite(GPIO_PIN, 0); // Turn off the relay
        log_event("Relay turned OFF");
        send(client_socket, "Relay OFF\n", strlen("Relay OFF\n"), 0);
    }
    // If the command is neither "ON" nor "OFF", log an error
    else {
        log_event("Invalid command received");
        send(client_socket, "Invalid command\n", strlen("Invalid command\n"), 0);
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    int opt = 1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initially turn off the relay

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set socket options to reuse address
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_event("Setsockopt failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Socket bind failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_event("Socket listen failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections in a loop
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            log_event("Socket accept failed");
            continue; // Continue listening for new connections
        }

        handle_client(new_socket);
    }

    return 0;
}

