#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define GPIO_RELAY 18
#define FLOW_THRESHOLD 5.0
#define POLLING_INTERVAL_MS 100
#define SLF3S_START_MEASUREMENT 0x36
#define SLF3S_READ_COMMAND 0x00

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
int send_command(int handle, uint8_t command);
int read_data(int handle, uint8_t *data, int count);
float convert_to_ml_min(int16_t raw_value);
void control_relay(int state);
void log_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to send a command to the sensor
int send_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Failed to send command 0x%02X: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to convert raw value to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value / 1500.0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Function to log data to file
void log_data(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // De-energize relay
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Initialize relay GPIO
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initially de-energized

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t sensor1_data[3];
    uint8_t sensor2_data[3];
    int16_t raw_flow1, raw_flow2;
    float flow1, flow2;
    int relay_state = 0; // 0 = de-energized, 1 = energized

    while (program_running) {
        // Start measurement on both sensors
        if (send_command(i2c_handle1, SLF3S_START_MEASUREMENT) != 0) {
            fprintf(stderr, "Error starting measurement on sensor 1\n");
        }
        if (send_command(i2c_handle2, SLF3S_START_MEASUREMENT) != 0) {
            fprintf(stderr, "Error starting measurement on sensor 2\n");
        }

        // Wait for 100ms
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds

        // Read data from sensors
        if (read_data(i2c_handle1, sensor1_data, 3) != 0) {
            fprintf(stderr, "Error reading data from sensor 1\n");
        }
        if (read_data(i2c_handle2, sensor2_data, 3) != 0) {
            fprintf(stderr, "Error reading data from sensor 2\n");
        }

        // Validate CRC-8 for sensor 1
        uint8_t crc1 = sensor1_data[2];
        uint8_t data1[2] = {sensor1_data[0], sensor1_data[1]};
        crc1 = crc8(data1, 2, 0x31); // CRC-8 polynomial 0x31, initial value 0xFF

        // Validate CRC-8 for sensor 2
        uint8_t crc2 = sensor2_data[2];
        uint8_t data2[2] = {sensor2_data[0], sensor2_data[1]};
        crc2 = crc8(data2, 2, 0x31); // CRC-8 polynomial 0x31, initial value 0xFF

        // Convert raw data to ml/min
        raw_flow1 = (int16_t)((sensor1_data[0] << 8) | sensor1_data[1]);
        raw_flow2 = (int16_t)((sensor2_data[0] << 8) | sensor2_data[1]);

        flow1 = convert_to_ml_min(raw_flow1);
        flow2 = convert_to_ml_min(raw_flow2);

        // Control relay based on flow rates
        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            if (relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            }
        } else {
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }
        }

        // Log data
        log_data(flow1, flow2);

        // Print flow rates to console
        printf("Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n", flow1, flow2);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

