    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // De-energize relay
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Initialize relay GPIO
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initially de-energized

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t sensor1_data[3];
    uint8_t sensor2_data[3];
    int16_t raw_flow1, raw_flow2;
    float flow1, flow2;
    int relay_state = 0; // 0 = de-energized, 1 = energized

    while (program_running) {
        // Start measurement on both sensors
        if (send_command(i2c_handle1, SLF3S_START_MEASUREMENT) != 0) {
            fprintf(stderr, "Error starting measurement on sensor 1\n");
        }
        if (send_command(i2c_handle2, SLF3S_START_MEASUREMENT) != 0) {
            fprintf(stderr, "Error starting measurement on sensor 2\n");
        }

        // Wait for 100ms
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds

        // Read data from sensors
        if (read_data(i2c_handle1, sensor1_data, 3) != 0) {
            fprintf(stderr, "Error reading data from sensor 1\n");
        }
        if (read_data(i2c_handle2, sensor2_data, 3) != 0) {
            fprintf(stderr, "Error reading data from sensor 2\n");
        }

        // Validate CRC-8 for sensor 1
        uint8_t crc1 = sensor1_data[2];
        uint8_t data1[2] = {sensor1_data[0], sensor1_data[1]};
        crc1 = crc8(data1, 2, 0x31); // CRC-8 polynomial 0x31, initial value 0xFF

        // Validate CRC-8 for sensor 2
        uint8_t crc2 = sensor2_data[2];
        uint8_t data2[2] = {sensor2_data[0], sensor2_data[1]};
        crc2 = crc8(data2, 2, 0x31); // CRC-8 polynomial 0x31, initial value 0xFF

        // Convert raw data to ml/min
        raw_flow1 = (int16_t)((sensor1_data[0] << 8) | sensor1_data[1]);
        raw_flow2 = (int16_t)((sensor2_data[0] << 8) | sensor2_data[1]);

        flow1 = convert_to_ml_min(raw_flow1);
        flow2 = convert_to_ml_min(raw_flow2);

        // Control relay based on flow rates
        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            if (relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            }
        } else {
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }
        }

        // Log data
        log_data(flow1, flow2);

        // Print flow rates to console
        printf("Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n", flow1, flow2);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

