#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24

// Define constants
#define RAIN_THRESHOLD 0 // Sensor outputs LOW when rain is detected
#define DRY_THRESHOLD 1  // Sensor outputs HIGH when dry
#define RAIN_DETECTED 1
#define RAIN_DRY 0
#define DRY_DETECTED 1
#define DRY_DRY 0
#define RAIN_DEBOUNCE_TIME 5 // seconds
#define DRY_DEBOUNCE_TIME 3 // seconds
#define MOTOR_DELAY 5 // seconds

// Global variables
static volatile int running = 1;
static int rain_detected = 0;
static int dry_detected = 0;
static int rain_debounce_count = 0;
static int dry_debounce_count = 0;
static int rain_debounce_time = 0;
static int dry_debounce_time = 0;
static int motor_running = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    gpioSetMode(ENA_PIN, PI_OUTPUT);
    gpioSetMode(IN1_PIN, PI_OUTPUT);
    gpioSetMode(IN2_PIN, PI_OUTPUT);

    gpioWrite(ENA_PIN, 0); // Ensure motor is initially stopped
    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);

    log_message(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to close the window
void close_window() {
    log_message(LOG_INFO, "Closing window...");
    gpioWrite(ENA_PIN, 1);
    gpioWrite(IN1_PIN, 1);
    gpioWrite(IN2_PIN, 0);
    gpioDelay(MOTOR_DELAY * 1000000); // Delay for 5 seconds
    gpioWrite(ENA_PIN, 0);
    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);
    log_message(LOG_INFO, "Window closed");
}

// Function to stop the motor
void stop_motor() {
    log_message(LOG_INFO, "Stopping motor...");
    gpioWrite(ENA_PIN, 0);
    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);
    log_message(LOG_INFO, "Motor stopped");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain window controller started");

    while (running) {
        int sensor_value = read_rain_sensor();

        if (sensor_value == RAIN_DETECTED) {
            if (!rain_detected) {
                rain_detected = 1;
                rain_debounce_count = 0;
                rain_debounce_time = time(NULL);
                log_message(LOG_INFO, "Rain detected");
            } else {
                // Rain detected, but already in debounce mode
                // Do nothing, just wait for the debounce time to expire
                gpioDelay(1000000); // Wait 1 second
            }
        } else if (sensor_value == DRY_DETECTED) {
            if (!dry_detected) {
                dry_detected = 1;
                dry_debounce_count = 0;
                dry_debounce_time = time(NULL);
                log_message(LOG_INFO, "Dry detected");
            } else {
                // Dry detected, but already in debounce mode
                // Do nothing, just wait for the debounce time to expire
                gpioDelay(1000000); // Wait 1 second
            }
        } else {
            // Sensor value is neither RAIN_DETECTED nor DRY_DETECTED
            // Do nothing, just wait for the next poll
            gpioDelay(200000); // Wait 200ms
        }

        if (rain_detected && dry_detected) {
            close_window();
            motor_running = 1;
        } else if (dry_detected && !motor_running) {
            dry_detected = 0;
        } else if (rain_detected && !motor_running) {
            rain_detected = 0;
        }

        gpioDelay(200000); // Poll every 200ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

