// Define GPIO pins
#define SERVO_PIN 18
#define BUTTON_PIN_1 21
#define BUTTON_PIN_2 22

// Define servo pulse widths (microseconds)
#define LOCKED_PULSE 2000
#define UNLOCKED_PULSE 1000

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to track servo state
int servo_state = 0; // 0 = locked, 1 = unlocked

// Function prototypes
void lock_door();
void unlock_door();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to lock the door
void lock_door() {
    if (servo_state == 0) {
        gpioServo(SERVO_PIN, LOCKED_PULSE);
        printf("Door locked.\n");
        servo_state = 1;
    }
}

// Function to unlock the door
void unlock_door() {
    if (servo_state == 1) {
        gpioServo(SERVO_PIN, UNLOCKED_PULSE);
        printf("Door unlocked.\n");
        servo_state = 0;
    }
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick_1 = 0;
    static uint32_t last_tick_2 = 0;
    uint32_t current_tick = gpioTick();

    if (gpio == BUTTON_PIN_1) {
        if (level == 0) { // Button pressed (low signal)
            if (current_tick - last_tick_1 > DEBOUNCE_DELAY * 1000) { // Debounce
                lock_door();
                last_tick_1 = current_tick;
            }
        } else { // Button released (high signal)
            last_tick_1 = 0; // Reset last tick
        }
    } else if (gpio == BUTTON_PIN_2) {
        if (level == 0) { // Button pressed (low signal)
            if (current_tick - last_tick_2 > DEBOUNCE_DELAY * 1000) { // Debounce
                unlock_door();
                last_tick_2 = current_tick;
            }
        } else { // Button released (high signal)
            last_tick_2 = 0; // Reset last tick
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN_1, PI_INPUT);
    gpioSetMode(BUTTON_PIN_2, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN_1, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_PIN_2, PI_PUD_UP);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback functions for button presses
    gpioSetAlertFunc(BUTTON_PIN_1, button_callback);
    gpioSetAlertFunc(BUTTON_PIN_2, button_callback);

    printf("Door control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100); // Sleep for 100ms to avoid busy-waiting
    }

    return 0;
}

