#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17

// Define floodlight activation time
#define FLOODLIGHT_DURATION 60 // seconds

// Global variable to track floodlight state
static volatile int floodlight_state = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_floodlight();
int deactivate_floodlight();
int log_event(const char *event_type, const char *timestamp, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        deactivate_floodlight();
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR sensor pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin as output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to activate the floodlight
int activate_floodlight() {
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate floodlight\n");
        return 1;
    }
    floodlight_state = 1;
    return 0;
}

// Function to deactivate the floodlight
int deactivate_floodlight() {
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate floodlight\n");
        return 1;
    }
    floodlight_state = 0;
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, const char *timestamp, int duration) {
    FILE *fp = fopen("security_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(fp, "%s - %s - Duration: %d seconds\n", timestamp, event_type, duration);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        // Check for motion
        if (motion_detected == 1) {
            // Get current timestamp
