// Define constants
#define MPR121_I2C_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_STATUS_REG 0x00
#define ELE0_TOUCH_THRESHOLD 0x0C
#define ELE0_RELEASE_THRESHOLD 0x0D
#define DEBOUNCE_TIME_MS 200
#define RELAY_OFF 0
#define RELAY_ON 1

// Global variables
int i2c_handle;
volatile int relay_state = RELAY_OFF;
volatile unsigned long last_touch_time = 0;

// Function prototypes
int mpr121_init();
int read_touch_status();
void toggle_relay();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_GPIO, RELAY_OFF);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) return -1; // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) return -1; // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) return -1; // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) return -1; // Debounce

    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) return -1; // FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) return -1; // FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x01) < 0) return -1; // FFI/SFI/CDT

    if (i2cWriteByteData(i2c_handle, 0x7B, 0x01) < 0) return -1; // Auto config
    if (i2cWriteByteData(i2c_handle, 0x7C, 0x01) < 0) return -1; // Auto config
    if (i2cWriteByteData(i2c_handle, 0x7D, 0x01) < 0) return -1; // Auto config

    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) return -1; // Enable electrode 0

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status() {
    int status = i2cReadWordData(i2c_handle, TOUCH_STATUS_REG);
    if (status < 0) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }
    return status;
}

// Function to toggle the relay
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    printf("Relay toggled to %d\n", relay_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, RELAY_OFF);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Check if electrode 0 is touched
        if (touch_status & 0x01) {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_TIME_MS * 1000) {
                toggle_relay();
                last_touch_time = current_time;
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

