#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pthread.h>
#include <stdarg.h>

// Configuration
#define PORT 5000
#define GPIO_CHIP "gpiochip0"
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define LOG_FILE "security.log"

// Global variables
static int server_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t pwm_thread;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
void cleanup_gpio(void);
void *pwm_thread_func(void *arg);
int parse_command(char *command, int *angle, char *pir_status);
int set_servo_angle(int angle);
int read_pir_sensor(void);
void log_event(const char *message, ...);
void log_error(const char *message, ...);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        log_event("Received signal, shutting down...");
    }
}

// Initialize GPIO
int init_gpio(void) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        log_error("Failed to open GPIO chip: %s", GPIO_CHIP);
        return -1;
    }

    servo_line = gpiod_chip_get_line(gpio_chip, SERVO_GPIO);
    if (!servo_line) {
        log_error("Failed to get servo GPIO line: %d", SERVO_GPIO);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        log_error("Failed to get PIR GPIO line: %d", PIR_GPIO);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "servo_pwm";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(servo_line, &config, 0) < 0) {
        log_error("Failed to request servo GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    config.consumer = "pir_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &config, 0) < 0) {
        log_error("Failed to request PIR GPIO line for input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    log_event("GPIO initialized successfully.");
    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    log_event("GPIO resources released.");
}

// PWM thread function
void *pwm_thread_func(void *arg) {
    int angle = *(int *)arg;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 20; // 50 Hz

    while (!terminate) {
        if (set_servo_angle(angle) != 0) {
            log_error("Failed to set servo angle.");
            break;
        }
        nanosleep(&sleep_time, NULL);
    }

    pthread_exit(NULL);
    return NULL;
}

// Parse command
int parse_command(char *command, int *angle, char *pir_status) {
    char *token;
    char *rest = command;

    token = strtok_r(rest, " ", &rest);
    if (token == NULL) {
        log_error("Invalid command format.");
        return -1;
    }

    if (strcmp(token, "SERVO") == 0) {
        token = strtok_r(rest, " ", &rest);
        if (token == NULL) {
            log_error("Missing angle value for SERVO command.");
            return -1;
        }

        token = strtok_r(rest, " ", &rest);
        if (token == NULL) {
            log_error("Missing angle value for SERVO command.");
            return -1;
        }

        *angle = atoi(token);
        if (*angle < 0 || *angle > 180) {
            log_error("Invalid angle value for SERVO command.");
            return -1;
        }
    } else if (strcmp(token, "PIR") == 0) {
        *pir_status = "0";
    } else if (strcmp(token, "PIR:1") == 0) {
        *pir_status = "1";
    } else {
        log_error("Unknown command.");
        return -1;
    }

    return 0;
}

// Set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_error("Invalid angle for servo.");
        return -1;
    }

    // Map angle (0-180) to pulse width (1-2 ms)
    int pulse_width = (int)(1.5 * angle / 180.0);

    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_error("Failed to set servo line value to 1.");
        return -1;
    }
    usleep(pulse_width * 1000); // Convert ms to microseconds

    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_error("Failed to set servo line value to 0.");
        return -1;
    }

    return 0;
}

// Read PIR sensor
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_error("Failed to read PIR sensor value.");
        return -1;
    }
    return value;
}

// Log event
void log_event(const char *message, ...) {
    va_list args;
    va_start(args, message);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    syslog(LOG_USER, "%s: ", timestamp);
    vfprintf(log_file, message, args);
    fflush(log_file);
    va_end(args);
}

// Log error
void log_error(const char *message, ...) {
    va_list args;
    va_start(args, message);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    syslog(LOG_ERR, "%s: ", timestamp);
    vfprintf(log_file, message, args);
    fflush(log_file);
    va_end(args);
}

int main(int argc, char *argv[]) {
    int angle = 90; // Default servo angle
    char pir_status[10];
    int pir_value;
    int new_pir_value;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int opt = 1;

    // Open syslog
    openlog("security_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file.");
        syslog(LOG_ERR, "Failed to open log file.");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_error("GPIO initialization failed.");
        syslog(LOG_ERR, "GPIO initialization failed.");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Create PWM thread
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_DETACHED);
    if (pthread_create(&pwm_thread, &attr, pwm_thread_func, &angle) != 0) {
        log_error("Failed to create PWM thread.");
        syslog(LOG_ERR, "Failed to create PWM thread.");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_error("Socket creation failed.");
        syslog(LOG_ERR, "Socket creation failed.");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_error("Setsockopt failed.");
        syslog(LOG_ERR, "Setsockopt failed.");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Bind failed.");
        syslog(LOG_ERR, "Bind failed.");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_error("Listen failed.");
        syslog(LOG_ERR, "Listen failed.");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    log_event("Listening for connections...");

    // Accept connections
    while (!terminate) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            log_error("Accept failed.");
            syslog(LOG_ERR, "Accept failed.");
            break;
        }

        // Read command
        char buffer[1024] = {0};
        ssize_t bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            log_error("Receive failed.");
