#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_MS 2000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void control_relay(int state);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    // Send measurement command (0x20)
    result = i2cWriteByte(i2c_handle, 0x20);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 120ms)
    gpioDelay(120);

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert raw data to lux
    unsigned int raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2;

    return 0;
}

// Control the relay (activate or deactivate)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log data to file
void log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_relay(0); // Deactivate relay
    gpioTerminate();
}

int main() {
    float lux;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_bh1750(&lux) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/%d)\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS);
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read BH1750 after %d retries. Skipping this cycle.\n", RETRY_COUNT);
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue; // Skip to the next cycle
        }

        // Control relay based on lux value
        if (lux < LUX_THRESHOLD) {
            control_relay(1); // Activate relay
        } else {
            control_relay(0); // Deactivate relay
        }

        // Log data
        log_data(lux);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

