#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 128
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static int tare_offset = 0;
static int scale = 128;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int solenoid_state = 0; // 0 = LOW, 1 = HIGH

// Function prototypes
int hx711_read(int *data);
int hx711_tare(int *data, int num_readings);
int hx711_convert(int *data, int tare_offset, int scale);
float hx711_average_weight(int *raw_data, int num_readings);
void solenoid_control(int state);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// HX711 read function
int hx711_read(int *data) {
    int i;
    // Wait for DOUT to go LOW
    while (gpioRead(HX711_DOUT) == 1) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        if (gpioTime(0, 0, 0) > 1000000) { // Timeout after 1 second
            log_message(LOG_ERR, "HX711: DOUT not ready");
            return -1; // Indicate error
        }
    }

    // Clock out 24 bits
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
        if (gpioRead(HX711_DOUT) == 1) {
            data[i] = 1;
        } else {
            data[i] = 0;
        }
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    return 0; // Indicate success
}

// HX711 tare function
int hx711_tare(int *data, int num_readings) {
    int sum = 0;
    int i;
    int reading;

    log_message(LOG_INFO, "Starting tare sequence");

    for (i = 0; i < num_readings; i++) {
        if (hx711_read(data) != 0) {
            log_message(LOG_ERR, "HX711 tare: Read error");
            return -1; // Indicate error
        }
        sum += hx711_convert(data, 0, scale); // Use tare_offset = 0 for now
        gpioDelay(10); // Small delay between readings
    }

    tare_offset = sum / num_readings;
