#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT CleanSession "clean_session"
#define MQTT_Keepalive "keepalive"

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    char *payload = message->payload;
    int level = 0;

    if (payload[0] == 'O' || payload[0] == 'o') {
        level = 1; // Energize relay
    } else if (payload[0] == 'F' || payload[0] == 'f') {
        level = 0; // De-energize relay
    } else {
        syslog(LOG_ERR, "Invalid payload received: %s", payload);
        return;
    }

    gpioWrite(GPIO_PIN, level);
    syslog(LOG_INFO, "Received message: %s, setting GPIO %d to %d", payload, GPIO_PIN, level);
}

int connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "Connected to MQTT broker.");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        char *error_string = mosquitto_connack_string(result);
        syslog(LOG_ERR, "Connection failed: %s", error_string);
        free(error_string);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with code %d", rc);
}

int main() {
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_Keepalive);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        mosquitto_loop(mosq, -1, 1); // Non-blocking loop with a timeout
        if (!running) break;
    }

    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

