#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servos and exiting...\n", signal);
}

// Function to set the PWM frequency and range for a given GPIO pin
int set_servo_pin(int pin, int pulse_width) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }

    gpioSetPWMfrequency(pin, PWM_FREQUENCY);
    gpioSetPWMrange(pin, PWM_RANGE);

    // Convert pulse width to PWM value (0-2000)
    int pwm_value = (int)(((float)pulse_width / 2000.0) * PWM_RANGE);

    if (gpioPWM(pin, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", pin);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Define pulse widths for each servo
    int pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    int num_servos = sizeof(pulse_widths) / sizeof(pulse_widths[0]);

    // Set servo positions
    for (int i = 0; i < num_servos; i++) {
        if (set_servo_pin(SERVO1_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting servo 1 position\n");
            goto cleanup;
        }
        printf("Servo 1 set to %d us\n", pulse_widths[i]);
    }

    for (int i = 0; i < num_servos; i++) {
        if (set_servo_pin(SERVO2_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting servo 2 position\n");
            goto cleanup;
        }
        printf("Servo 2 set to %d us\n", pulse_widths[i]);
    }

    for (int i = 0; i < num_servos; i++) {
        if (set_servo_pin(SERVO3_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting servo 3 position\n");
            goto cleanup;
        }
        printf("Servo 3 set to %d us\n", pulse_widths[i]);
    }

    for (int i = 0; i < num_servos; i++) {
        if (set_servo_pin(SERVO4_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting servo 4 position\n");
            goto cleanup;
        }
        printf("Servo 4 set to %d us\n", pulse_widths[i]);
    }

    for (int i = 0; i < num_servos; i++) {
        if (set_servo_pin(SERVO5_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting servo 5 position\n");
            goto cleanup;
        }
        printf("Servo 5 set to %d us\n", pulse_widths[i]);
    }

    // Hold servo positions for 3 seconds
    gpioDelay(3000000); // 3 seconds = 3000000 microseconds

    // Stop PWM on all servos
    for (int i = 0; i < num_servos; i++) {
        gpioPWM(SERVO1_PIN, 0);
        gpioPWM(SERVO2_PIN, 0);
        gpioPWM(SERVO3_PIN, 0);
        gpioPWM(SERVO4_PIN, 0);
        gpioPWM(SERVO5_PIN, 0);
    }

cleanup:
    // Stop PWM on all servos
    for (int i = 0; i < num_servos; i++) {
        gpioPWM(SERVO1_PIN, 0);
        gpioPWM(SERVO2_PIN, 0);
        gpioPWM(SERVO3_PIN, 0);
        gpioPWM(SERVO4_PIN, 0);
        gpioPWM(SERVO5_PIN, 0);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

