    int pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    int num_servos = sizeof(pulse_widths) / sizeof(pulse_widths[0]);

    // Set servo positions
    for (int i = 0; i < num_servos; i++) {
        if (set_servo_pin(SERVO1_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting servo 1 position\n");
            goto cleanup;
