            fprintf(stderr, "Error setting servo 5 position\n");
            goto cleanup;
        }
        printf("Servo 5 set to %d us\n", pulse_widths[i]);
    }

    // Hold servo positions for 3 seconds
    gpioDelay(3000000); // 3 seconds = 3000000 microseconds

    // Stop PWM on all servos
    for (int i = 0; i < num_servos; i++) {
