#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_A_A 4
#define MOTOR_A_B 5

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define MOTOR_B_A 6
#define MOTOR_B_B 12

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
pthread_mutex_t encoder_mutex_a = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder_mutex_b = PTHREAD_MUTEX_INITIALIZER;

// Target speed (RPM)
#define TARGET_SPEED 50

// PI controller parameters
#define KP 0.5
#define KI 0.05
#define PWM_FREQUENCY 10000 // 10 kHz

// Stall detection parameters
#define STALL_TIMEOUT 2 // seconds

// Global flag for program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold motor data
typedef struct {
    int pwm_pin;
    int dir_pin;
    int a_pin;
    int b_pin;
    int a_phase;
    int b_phase;
    int count;
    pthread_mutex_t mutex;
} MotorData;

// Structure to hold encoder data
typedef struct {
    int a_pin;
    int b_pin;
    int count;
    pthread_mutex_t mutex;
} EncoderData;

// Function prototypes
void motor_a_forward(int duty_cycle);
void motor_b_forward(int duty_cycle);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
void *encoder_thread(void *arg);
void *motor_control_thread(void *arg);
void signal_handler(int signal);
void log_message(const char *message);

// Motor control thread function
void *motor_control_thread(void *arg) {
    MotorData *motor_data = (MotorData *)arg;
    int duty_cycle;
    double error, integral, output;
    double last_error = 0;
    double integral_limit = 100.0; // Adjust as needed
    double last_integral = 0;
    double last_output = 0;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000000; // 10 ms

    while (program_running) {
        // Read encoder counts
        pthread_mutex_lock(&motor_data->mutex);
        int current_a_count = encoder_a_count;
        int current_b_count = encoder_b_count;
        encoder_a_count = 0; // Reset encoder count
        encoder_b_count = 0; // Reset encoder count
        pthread_mutex_unlock(&motor_data->mutex);

        // Calculate error
        error = TARGET_SPEED - (current_a_count + current_b_count) / 64.0; // Average RPM

        // Calculate integral
        integral = error - last_error;
        if (integral > integral_limit) integral = integral_limit;
        if (integral < -integral_limit) integral = -integral_limit;

        // Calculate output
        output = KP * error + KI * integral;

        // Limit output to [0, 255]
        if (output < 0) output = 0;
        if (output > 255) output = 255;

        // Calculate duty cycle (PWM)
        duty_cycle = (int)output;

        // Set motor direction and PWM
        gpioWrite(motor_data->dir_pin, 1); // Forward
        gpioPWM(motor_data->pwm_pin, duty_cycle);

        // Update last output and error
        last_output = output;
        last_error = error;

        // Log data
        log_message("Motor A: RPM = (A+B)/64, PWM = Duty Cycle, Error = Target - (A+B)/64, Integral = Target - (A+B)/64 - Previous Error, Output = Kp*Error + Ki*Integral, Duty Cycle = Output");

        // Stall detection
        if (current_a_count == 0 && current_b_count == 0) {
            time_t start_time = time(NULL);
            while (current_a_count == 0 && current_b_count == 0 && program_running) {
                gpioDelay(1000); // Check every 1 ms
                if (time(NULL) - start_time > STALL_TIMEOUT) {
                    log_message("Motor A Stall Detected!");
                    program_running = 0; // Stop the program
                    break;
                }
            }
        }

        nanosleep(&ts, NULL);

    }

    // Stop the motor
    gpioWrite(motor_data->dir_pin, 0);
    gpioPWM(motor_data->pwm_pin, 0);

    pthread_exit(NULL);
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&encoder_mutex_a);
    if (level == 1) {
        encoder_a_count++;
    }
    pthread_mutex_unlock(&encoder_mutex_a);
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&encoder_mutex_b);
    if (level == 1) {
        encoder_b_count++;
    }
    pthread_mutex_unlock(&encoder_mutex_b);
}

// Motor A forward function
void motor_a_forward(int duty_cycle) {
    gpioWrite(MOTOR_A_DIR, 1); // Forward
    gpioPWM(MOTOR_A_PWM, duty_cycle);
}

// Motor B forward function
void motor_b_forward(int duty_cycle) {
    gpioWrite(MOTOR_B_DIR, 1); // Forward
    gpioPWM(MOTOR_B_PWM, duty_cycle);
}

// Signal handler function
void signal_handler(int signal) {
    log_message("Caught signal, stopping motors and exiting...");
    program_running = 0;
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_A_PWM, 0);
    gpioWrite(MOTOR_B_DIR, 0);
    gpioWrite(MOTOR_B_PWM, 0);
    gpioTerminate();
    exit(0);
}

// Logging function
void log_message(const char *message) {
    FILE *fp = fopen("motor_control.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_A_A, PI_INPUT);
    gpioSetMode(MOTOR_A_B, PI_INPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_A, PI_INPUT);
    gpioSetMode(MOTOR_B_B, PI_INPUT);

    // Set up interrupts for encoders
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        log_message("Failed to set ISR for Encoder A A");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        log_message("Failed to set ISR for Encoder A B");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        log_message("Failed to set ISR for Encoder B A");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        log_message("Failed to set ISR for Encoder B B");
        gpioTerminate();
        return 1;
    }

    // Set up threads
    pthread_t motor_thread, encoder_thread;
    MotorData motor_a_data = {MOTOR_A_PWM, MOTOR_A_DIR, MOTOR_A_A, MOTOR_A_B, ENCODER_A_A, ENCODER_A_B, 0, motor_a_data.mutex};
    EncoderData encoder_a_data = {ENCODER_A_A, ENCODER_A_B, 0, encoder_a_data.mutex};
    EncoderData encoder_b_data = {ENCODER_B_A, ENCODER_B_B, 0, encoder_b_data.mutex};

    if (pthread_create(&motor_thread, NULL, motor_control_thread, &motor_a_data) != 0) {
        log_message("Failed to create motor thread");
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder_thread, NULL, encoder_thread, &encoder_a_data) != 0) {
        log_message("Failed to create encoder thread");
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder_thread, NULL, encoder_thread, &encoder_b_data) != 0) {
        log_message("Failed to create encoder thread");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Motor control thread will handle motor control and RPM calculation
        // This loop is for other tasks or just to keep the program running
        gpioDelay(100000); // 100 ms
    }

    // Clean up
    pthread_join(motor_thread, NULL);
    pthread_join(encoder_thread, NULL);

    gpioTerminate();
    return 0;
}

