#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_CMD 0x21
#define BH1750_CONTINUOUS_HIGH_RES_MODE_2 0x10
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DAWN 200
#define LUX_THRESHOLD_DUSK 50
#define HYSTERESIS_THRESHOLD 10
#define POLL_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, BH1750_CMD, BH1750_CONTINUOUS_HIGH_RES_MODE_2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return 1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }

    // Convert raw data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to control the relay (ON/OFF)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
