        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, relay_state); // Write the new state to the relay pin
    return 0;
}

