        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read the sensor after the delay
            if (read_touch_sensor() == 1) {
                toggle_relay();
                log_relay_state(relay_state);
            }
        }

        gpioDelay(10 * 1000); // Sleep for 10 ms to reduce CPU usage
    }

    return 0; // This line will not be reached due to the infinite loop
}

