#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define LPM_HYSTERESIS 0.5
#define DEBOUNCE_TIMEOUT 1 // seconds

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int solenoid_state = 1; // 1 = open, 0 = closed
static volatile int running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulse_count);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);
void cleanup();

// ISR function for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate LPM
double calculate_lpm(int pulse_count) {
    return (pulse_count / PULSES_PER_LITER) * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close the valve
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open the valve
        solenoid_state = 1;
        log_data(lpm, solenoid_state);
    }
}

// Function to log data to file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_data(-1.0, -1); // Log shutdown event
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    running = 0; // Stop the ISR

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Set solenoid to safe state (open)
    gpioWrite(SOLENOID_GPIO, 1);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", SOLENOID_GPIO);
        cleanup();
        return 1;
    }

    // Set initial solenoid state
    gpioWrite(SOLENOID_GPIO, 1);

    // Open the log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR with debounce timeout
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Reset pulse count
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function

        // Calculate LPM
        double lpm = calculate_lpm(pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        log_data(lpm, solenoid_state);
    }

    return 0;
}

