#define TARGET_WEIGHT_THRESHOLD 0.1

// Global variables (minimize usage)
static volatile int running = 1;
static int socket_fd = -1;
static int calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int servo_pin = SERVO_PIN;
static int servo_range = SERVO_RANGE;
static int servo_delay = SERVO_DELAY;
static int log_file = -1;

// Function prototypes
int read_config();
int initialize_gpio();
int initialize_socket();
int initialize_servo();
int read_hx711();
double calibrate_weight(int raw_value);
double calculate_target_weight(double known_weight, double calibration_factor);
int dispense_ingredient(double target_weight);
int send_weight(double actual_weight);
int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int timeout_hx711();

// Function to read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s. Using default values.\n", CONFIG_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "servo_pin") == 0) {
                servo_pin = atoi(value);
            } else if (strcmp(key, "servo_range") == 0) {
                servo_range = atoi(value);
            } else if (strcmp(key, "servo_delay") == 0) {
                servo_delay = atoi(value);
            } else {
                fprintf(stderr, "Warning: Unknown config option %s\n", key);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize the socket
int initialize_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Socket creation failed");
        return -1;
    }

    // Set socket options
    if (setsockopt(socket_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("Setsockopt failed");
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    // Bind socket to address and port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(server_port);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        perror("Listen failed");
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    return 0;
}

