    gpioDelay(servo_delay * 1000); // Delay for servo to settle
    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT); // Ensure DATA pin is input
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT); // Ensure SCK pin is output

    // Wait for DATA pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
    }

    if (timeout_count >= 1000) {
        fprintf(stderr, "Error: HX711 DATA pin timeout\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Short delay
    }

    // Pulse the SCK pin 25th time to set the gain to 128
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the weight
double calibrate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
