// Function to calculate the target weight
double calculate_target_weight(double known_weight, double calibration_factor) {
    return known_weight * (SERVO_RANGE / 100.0);
}

// Function to dispense the ingredient
int dispense_ingredient(double target_weight) {
    int pulse_width = 0;
    int i;

    // Map target weight to servo pulse width
    for (i = 0; i < SERVO_RANGE; i++) {
        if (i * 100.0 >= target_weight) {
            pulse_width = i;
            break;
        }
    }

    // Set servo pulse width
    gpioServo(servo_pin, pulse_width);
    gpioDelay(servo_delay * 1000); // Delay for servo to move

    return 0;
}

// Function to send the actual weight back to the client
int send_weight(double actual_weight) {
    char response[256];
    snprintf(response, sizeof(response), "%.2f", actual_weight);

    if (send(socket_fd, response, strlen(response), 0) < 0) {
        perror("Send failed");
        return -1;
    }

    return 0;
}

// Function to log the dispensing event
int log_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root, *target_weight_json, *actual_weight_json, *error_json;
    json_t *log_entry;
    char timestamp[30];
    struct timeval tv;
    struct tm *tm_info;

    // Get current timestamp
    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    // Create JSON objects
    root = json_object();
    target_weight_json = json_real(target_weight);
    actual_weight_json = json_real(actual_weight);
    error_json = json_string(error_message);

    // Append to log file
    if (log_file != -1) {
        log_entry = json_object();
        json_object_set_new(log_entry, "timestamp", json_string(timestamp));
        json_object_set_new(log_entry, "target_weight", target_weight_json);
        json_object_set_new(log_entry, "actual_weight", actual_weight_json);
        json_object_set_new(log_entry, "error", error_json);

        if (json_dumpf(log_entry, log_file, JSON_INDENT(4)) != 0) {
            fprintf(stderr, "Error writing to log file\n");
            json_decref(root);
            json_decref(target_weight_json);
            json_decref(actual_weight_json);
            json_decref(error_json);
            return -1;
        }
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
        json_decref(root);
        json_decref(target_weight_json);
        json_decref(actual_weight_json);
        json_decref(error_json);
        return -1;
    }

    json_decref(root);
    json_decref(target_weight_json);
    json_decref(actual_weight_json);
    json_decref(error_json);

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);

    // Stop servo
    gpioServo(servo_pin, 0);

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close log file
    if (log_file != -1) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Timeout function for HX711
int timeout_hx711() {
    int data = 0;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT); // Ensure DATA pin is input
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT); // Ensure SCK pin is output

    // Wait for DATA pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < 1000) {
