    gpioDelay(1); // Short delay

    return data;
}

int main() {
    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize socket
    if (initialize_socket() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize servo
    if (initialize_servo() != 0) {
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Dispensing server started. Listening on %s:%d\n", server_ip, server_port);

    while (running) {
        // Accept connection
        struct sockaddr_in address;
        int addrlen = sizeof(address);
        int new_socket = accept(socket_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(address.sin_addr), ntohs(address.sin_port));

        // Receive target weight
        char buffer[1024] = {0};
        ssize_t bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Receive failed");
            close(new_socket);
            continue; // Continue listening for other connections
        }
        buffer[bytes_received] = '\0';

        double target_weight = atof(buffer);

        // Check for valid target weight
        if (target_weight < 0 || target_weight > 1000) {
            fprintf(stderr, "Error: Invalid target weight: %.2f\n", target_weight);
            const char *error_message = "Invalid target weight";
            send_weight(-1.0); // Send error weight
            log_event(target_weight, -1.0, error_message);
            close(new_socket);
            continue; // Continue listening for other connections
        }

        // Dispense ingredient
        printf("Dispensing %.2f grams\n", target_weight);
        dispense_ingredient(target_weight);

        // Read actual weight
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed\n");
            const char *error_message = "HX711 read failed";
            send_weight(-1.0); // Send error weight
            log_event(target_weight, -1.0, error_message);
            close(new_socket);
            continue; // Continue listening for other connections
        }

        double actual_weight = calibrate_weight(raw_value);

        // Send actual weight
        send_weight(actual_weight);

        // Log event
        const char *error_message = "None";
        log_event(target_weight, actual_weight, error_message);

        // Close connection
        close(new_socket);
    }

    // Cleanup (should not reach here if signal handler is working)
    close(socket_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

