    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
    return touch_detected;
}

// Function to toggle the relay
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state(relay_state);
}

