            debounce_time = atoi(argv[i + 1]);
            if (debounce_time <= 0) {
                fprintf(stderr, "Invalid debounce time. Using default value (%d ms).\n", DEBOUNCE_TIME);
                debounce_time = DEBOUNCE_TIME;
            }
            i++; // Skip the next argument
        }
    }
}

