    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-controlled desk lamp. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
        }
        gpioDelay(1000); // Check every 1 ms
    }

    return 0;
}

