#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEFAULT_ANGLE 90

static volatile int running = 1;
static volatile int angle = DEFAULT_ANGLE;
static struct termios old_termios, new_termios;

// Function to handle keyboard input
void handle_keyboard_input() {
    char input;
    while (running) {
        input = getchar();
        if (input == '+') {
            angle = (angle + 10) % 181; // Clamp to 0-180
            gpioServo(GPIO_PIN, angle * 1000 / 180 + MIN_PULSE_WIDTH); // Convert angle to pulse width
            printf("Angle: %d\n", angle);
        } else if (input == '-') {
            angle = (angle - 10 + 181) % 181; // Clamp to 0-180
            gpioServo(GPIO_PIN, angle * 1000 / 180 + MIN_PULSE_WIDTH); // Convert angle to pulse width
            printf("Angle: %d\n", angle);
        } else if (input == 'q') {
            running = 0;
            printf("Quitting...\n");
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

// Function to restore terminal settings
void restore_terminal_settings() {
    if (tcgetattr(STDIN_FILENO, &old_termios) != 0) {
        perror("tcgetattr");
        exit(EXIT_FAILURE);
    }
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        exit(EXIT_FAILURE);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(GPIO_PIN, 180); // Assuming 0-180 degrees

    // Set PWM duty cycle (optional, but recommended)
    gpioPWM(GPIO_PIN, 0); // Start with 0 duty cycle

    // Save the current terminal settings
    if (tcgetattr(STDIN_FILENO, &old_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }
    if (tcgetattr(STDIN_FILENO, &new_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_iflag &= ~(IXON | IXOFF | IXANY);
    new_termios.c_oflag &= ~OPOST;
    new_termios.c_cflag &= ~(PARENB | PARODD);
    new_termios.c_cflag &= ~(CSTOPB | CSIZE);
    new_termios.c_cflag &= ~CRTSCTS;
    new_termios.c_cflag |= CS8;
    new_termios.c_cflag &= ~IGNBRK;
    new_termios.c_cflag &= ~IXANY;
    new_termios.c_cflag &= ~ONLCR;
    new_termios.c_cflag &= ~ISTRIP;
    new_termios.c_cflag &= ~INLCR;
    new_termios.c_cflag &= ~IGNCR;
    new_termios.c_cflag &= ~ICRNL;
    new_termios.c_iflag &= ~(IXON | IXOFF | IXANY);
    new_termios.c_oflag &= OPOST;
    new_termios.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    new_termios.c_cc[VMIN] = 0;  // Non-canonical mode
    new_termios.c_cc[VTIME] = 5; // Read timeout of 0.5 seconds

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Start handling keyboard input
    handle_keyboard_input();

    // Restore terminal settings before exiting
    restore_terminal_settings();

    // Stop PWM pulses
    gpioServo(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

