#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

static volatile int pulse_count = 0;
static volatile int running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio_line()
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motor_rpm";
    config.request_type = GPIOD_LINE_REQUEST_FLAG_INPUT;
    config.flags = 0; // No special flags

    int ret = gpiod_line_request_input(line, "motor_rpm", &config);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to read the Hall-effect sensor
int read_sensor()
{
    struct gpiod_line_event event;
    memset(&event, 0, sizeof(event));
    event.consumer = "motor_rpm";
    event.line = line;
    event.event_type = GPIOD_LINE_EVENT_RISING_EDGE;

    int ret = gpiod_line_event_wait(line, &event, DEBOUNCE_MS * 1000); // Convert ms to microseconds
    if (ret < 0) {
        fprintf(stderr, "Error waiting for event: %s\n", strerror(-ret));
        return -1;
    }

    if (ret > 0) {
        pulse_count++;
        return 1; // Rising edge detected
    } else {
        return 0; // Timeout or error
    }
}

// Function to calculate RPM
double calculate_rpm()
{
    return (pulse_count / 5.0) * 60.0;
}

// Function to log RPM data to a file
int log_rpm(double rpm)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print RPM to stdout
void print_rpm(double rpm)
{
    printf("RPM: %.2f\n", rpm);
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line as input
    if (init_gpio_line() < 0) {
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (running) {
        if (read_sensor() == 1) {
            pulse_count++;
        }
        // Calculate RPM every 5 seconds
        if (time(NULL) % 5 == 0) {
            double rpm = calculate_rpm();
            log_rpm(rpm);
            print_rpm(rpm);
        }
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000; // 10ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

