{
    return (pulse_count / 5.0) * 60.0;
}

// Function to log RPM data to a file
int log_rpm(double rpm)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print RPM to stdout
void print_rpm(double rpm)
{
    printf("RPM: %.2f\n", rpm);
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line as input
    if (init_gpio_line() < 0) {
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (running) {
        if (read_sensor() == 1) {
            pulse_count++;
        }
        // Calculate RPM every 5 seconds
        if (time(NULL) % 5 == 0) {
            double rpm = calculate_rpm();
            log_rpm(rpm);
            print_rpm(rpm);
        }
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000; // 10ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

