#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME_MS 500
#define RELAY_OFF_TIME_MS 500
#define MAX_TOUCH_DURATION_MS 10000 // 10 seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_PIN);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    int touch_count = 0;
    int last_touch_state = 0; // Store the last touch state

    while (program_running) {
        int touch_state = read_touch_sensor();

        if (touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            touch_count++;
            if (touch_count >= MAX_TOUCH_DURATION_MS) {
                // Failsafe: Force relay OFF
                printf("Failsafe triggered: Touching for too long. Forcing relay OFF.\n");
                control_relay(0);
                touch_count = 0; // Reset the counter
            } else {
                // Toggle relay state
                relay_state = !relay_state;
                if (control_relay(relay_state) != 0) {
                    fprintf(stderr, "Failed to toggle relay state\n");
                }
                printf("Relay toggled to state: %d\n", relay_state);
            }
        }

        last_touch_state = touch_state;

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup before exiting
    printf("Cleaning up and exiting...\n");
    control_relay(0); // Ensure relay is OFF
    gpioTerminate();   // Terminate pigpio

    return 0;
}

