#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define flow sensor calibration
#define PULSES_PER_LITER 450

// Define target flow rate
#define TARGET_FLOW_RATE 5.0 // L/min

// Define flow rate range
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 20.0

// Define PWM range
#define PWM_RANGE 255

// Define PWM duty cycle range
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 255

// Define flow rate range for proportional control
#define MIN_FLOW_RATE_PROPORTIONAL 0.0
#define MAX_FLOW_RATE_PROPORTIONAL 20.0

// Define PWM period in microseconds
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
double current_flow_rate = 0.0;
double integral = 0.0;
double last_error = 0.0;
FILE *log_file = NULL;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count);
double calculate_flow_rate_lpm(int pulse_count);
double proportional_control(double current_flow_rate, double target_flow_rate);
void log_data(double timestamp_ms, double flow_rate, double valve_position);
void signal_handler(int signal);
int initialize_gpio();
int open_log_file();
int close_log_file();
int cleanup_gpio();

// Interrupt handler for pulse counter
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0; // pulses/second * 60 seconds/minute
}

// Function to calculate flow rate in L/min
double calculate_flow_rate_lpm(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0; // pulses/second * 60 seconds/minute
}

// Proportional control function
double proportional_control(double current_flow_rate, double target_flow_rate) {
    double error = target_flow_rate - current_flow_rate;
    integral += error;
    double output = Kp * error; // Proportional gain

    // Anti-windup
    if (output > PWM_DUTY_CYCLE_MAX) {
        output = PWM_DUTY_CYCLE_MAX;
    }
    if (output < PWM_DUTY_CYCLE_MIN) {
        output = PWM_DUTY_CYCLE_MIN;
    }

    return output;
}

// Function to log data to file
void log_data(double timestamp_ms, double flow_rate, double valve_position) {
    if (log_file != NULL) {
        fprintf(log_file, "%lf,%lf,%lf\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        close_log_file();
    }
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE);

    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE); // Set PWM range to 0-255

    gpioWrite(VALVE_ENABLE_PIN, 1); // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 0); // Disable the valve

    return 0;
}

// Function to open the log file
int open_log_file() {
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }
    return 0;
}

// Function to close the log file
int close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    return 0;
}

// Function to cleanup GPIO resources
int cleanup_gpio() {
    gpioWrite(VALVE_ENABLE_PIN, 0); // Disable the valve
    gpioPWM(VALVE_PWM_PIN, 0); // Stop PWM
    gpioTerminate();
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    // Validate target flow rate
    if (sscanf(argv[1], "%lf", &target_flow_rate) != 1) {
        fprintf(stderr, "Invalid target flow rate. Must be a number.\n");
        return 1;
    }

    if (target_flow_rate < MIN_FLOW_RATE || target_flow_rate > MAX_FLOW_RATE) {
        fprintf(stderr, "Target flow rate must be between %lf and %lf L/min.\n", MIN_FLOW_RATE, MAX_FLOW_RATE);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for flow sensor
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL);

    // Main control loop
    while (1) {
        // Calculate flow rate
        double current_flow_rate = calculate_flow_rate_lpm(pulse_count);

        // Proportional control
        double output = proportional_control(current_flow_rate, target_flow_rate);

        // Set valve position
        gpioPWM(VALVE_PWM_PIN, (int)output);

        // Log data
        double timestamp_ms = time_time();
        log_data(timestamp_ms, current_flow_rate, output);

        // Update pulse count
        pulse_count = 0; // Reset pulse count for the next interval

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

