#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define valid RFID tag
#define VALID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}

// Define debounce time (ms)
#define DEBOUNCE_TIME 50

// Define lock disengage time (seconds)
#define DISENGAGE_TIME 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_rfid_tag();
int check_tag_validity(unsigned char *tag_data);
int read_button();
int disengage_locks();
int engage_locks();
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to read RFID tag data via SPI
int read_rfid_tag() {
    unsigned char tag_data[10];
    int result = spiXfer(spi_handle, tag_data, tag_data, 10);

    if (result != 10) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return 1; // Indicate failure
    }

    // Check for no tag present (all zeros)
    if (memcmp(tag_data, VALID_TAG, 10) == 0) {
        return 0; // Tag present
    } else {
        return 1; // No tag present
    }
}

// Function to check the validity of the RFID tag data
int check_tag_validity(unsigned char *tag_data) {
    if (memcmp(tag_data, VALID_TAG, 10) == 0) {
        return 0; // Valid
    } else {
        return 1; // Invalid
    }
}

// Function to read the button press
int read_button() {
    int button_state = gpioRead(BUTTON_PIN);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce

    // Active-low button, so LOW means pressed
    if (button_state == 0) {
        return 0; // Button pressed
    } else {
        return 1; // Button not pressed
    }
}

// Function to disengage the locks
int disengage_locks() {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    log_event("Locks disengaged");
    return 0;
