void encoder_interrupt_handler(int line, struct gpiod_line_event *event, void *user_data) {
    int pin;
    struct gpiod_line *line_ptr;
    int direction_1 = 0, direction_2 = 0;

    if (line == line1) {
        pin = B_PIN_1;
        line_ptr = line1;
        direction_1 = (event->value == 1) ? 1 : -1;
    } else if (line == line2) {
        pin = B_PIN_2;
        line_ptr = line2;
        direction_2 = (event->value == 1) ? 1 : -1;
    } else {
        fprintf(stderr, "Invalid line: %d\n", line);
        return;
    }

    pthread_mutex_lock(&encoder_mutex_1);
    encoder_count_1 += direction_1;
    pthread_mutex_unlock(&encoder_mutex_1);

    pthread_mutex_lock(&encoder_mutex_2);
    encoder_count_2 += direction_2;
    pthread_mutex_unlock(&encoder_mutex_2);
}

// Encoder thread function
void *encoder_thread(void *arg) {
    struct gpiod_line_event *event;
    int line;

    while (!terminate) {
        // Read encoder counts
        pthread_mutex_lock(&encoder_mutex_1);
        int current_count_1 = encoder_count_1;
        encoder_count_1 = 0; // Reset count after reading
        pthread_mutex_unlock(&encoder_mutex_1);

        pthread_mutex_lock(&encoder_mutex_2);
        int current_count_2 = encoder_count_2;
        encoder_count_2 = 0; // Reset count after reading
        pthread_mutex_unlock(&encoder_mutex_2);

        // Calculate RPM
        double rpm_1 = (double)current_count_1 / 600.0 * 60.0; // 600 pulses/rev
        double rpm_2 = (double)current_count_2 / 600.0 * 60.0; // 600 pulses/rev

        // Motor control
        motor_control(1, TARGET_RPM);
        motor_control(2, TARGET_RPM);

        // Log data
        log_data(rpm_1, rpm_2, 0.0, 0.0); // Placeholder for PID output

        usleep(SAMPLE_TIME_US);
    }

    pthread_exit(NULL);
}

// Motor control thread function
void *motor_control_thread(void *arg) {
    while (!terminate) {
        // Calculate RPM (placeholder)
        double rpm_1 = 0.0;
        double rpm_2 = 0.0;

        // Motor control
        motor_control(1, TARGET_RPM);
        motor_control(2, TARGET_RPM);

        // Log data
        log_data(rpm_1, rpm_2, 0.0, 0.0); // Placeholder for PID output

        usleep(SAMPLE_TIME_US);
    }

    pthread_exit(NULL);
}

// Motor control mutex
pthread_mutex_t line_mutex_motor = PTHREAD_MUTEX_INITIALIZER;

int main() {
    pthread_t encoder_thread_id, motor_control_thread_id;
    struct sigaction sa;

    // Set up signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing libgpiod\n");
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(&chip1, &chip2, &line1, &line2, &line3, &line4, &line5, &line6, &line7, &line8, &line9, &line10, &line11, &line12) < 0) {
        gpiod_init();
        return 1;
    }

    // Create encoder thread
    if (pthread_create(&encoder_thread_id, NULL, encoder_thread, NULL) != 0) {
        perror("pthread_create (encoder)");
        cleanup_gpio(chip1, chip2, line1, line2, line3, line4, line5, line6, line7, line8, line9, line10, line11, line12);
        gpiod_init();
        return 1;
    }

    // Create motor control thread
    if (pthread_create(&motor_control_thread_id, NULL, motor_control_thread, NULL) != 0) {
        perror("pthread_create (motor control)");
        terminate = 1; // Signal encoder thread to stop
        pthread_join(encoder_thread_id, NULL);
        cleanup_gpio(chip1, chip2, line1, line2, line3, line4, line5, line6, line7, line8, line9, line10, line11, line12);
        gpiod_init();
        return 1;
    }

    // Wait for signal
    while (!terminate) {
        sleep(1);
    }

    // Join threads
    pthread_join(encoder_thread_id, NULL);
    pthread_join(motor_control_thread_id, NULL);

    // Cleanup
    cleanup_gpio(chip1, chip2, line1, line2, line3, line4, line5, line6, line7, line8, line9, line10, line11, line12);
    gpiod_init();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

