#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the solenoid valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO chip and lines
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *valve1_line = NULL;
struct gpiod_line *valve2_line = NULL;

// Function prototypes
int initialize_gpio();
int request_gpio_line(int gpio, const char *line_name);
int set_gpio_value(struct gpiod_line *line, int value);
int log_event(int valve_number, int duration_ms);
void cleanup_gpio();
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the GPIO chip
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_chip_flags flags = 0; // No special flags needed

    valve1_line = gpiod_chip_get_line(gpio_chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Error: Could not get GPIO %d line: %s\n", VALVE1_GPIO, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    valve2_line = gpiod_chip_get_line(gpio_chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Error: Could not get GPIO %d line: %s\n", VALVE2_GPIO, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", flags) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %s\n", VALVE1_GPIO, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", flags) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %s\n", VALVE2_GPIO, strerror(errno));
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to request a GPIO line
int request_gpio_line(int gpio, const char *line_name) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO %d line: %s\n", gpio, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, line_name, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %s\n", gpio, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
int log_event(int valve_number, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - Valve %d activated for %d ms\n", timestamp, valve_number, duration_ms);
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Greenhouse water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Activate Valve 1
        if (set_gpio_value(valve1_line, 1) == 0) {
            if (log_event(1, 500) != 0) {
                fprintf(stderr, "Error logging event for Valve 1.\n");
            }
            usleep(500000); // 500 ms
        } else {
            fprintf(stderr, "Error activating Valve 1.\n");
        }

        // Pause for 5 seconds
        usleep(5000000); // 5 seconds

        // Activate Valve 2
        if (set_gpio_value(valve2_line, 1) == 0) {
            if (log_event(2, 1000) != 0) {
                fprintf(stderr, "Error logging event for Valve 2.\n");
            }
            usleep(1000000); // 1000 ms
        } else {
            fprintf(stderr, "Error activating Valve 2.\n");
        }

        // Pause for 10 seconds
        usleep(10000000); // 10 seconds
    }

    return 0;
}

