    if (!fp) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - Valve %d activated for %d ms\n", timestamp, valve_number, duration_ms);
    fclose(fp);
    return 0;
}

