// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELE0_TH 0x41
#define MPR121_ELE0_RL 0x42
#define MPR121_ELE1_TH 0x43
#define MPR121_ELE1_RL 0x44
#define MPR121_ELE2_TH 0x45
#define MPR121_ELE2_RL 0x46
#define MPR121_ELE3_TH 0x47
#define MPR121_ELE3_RL 0x48
#define MPR121_ELE4_TH 0x49
#define MPR121_ELE4_RL 0x4A
#define MPR121_ELE5_TH 0x4B
#define MPR121_ELE5_RL 0x4C
#define MPR121_ELE6_TH 0x4D
#define MPR121_ELE6_RL 0x4E
#define MPR121_ELE7_TH 0x4F
#define MPR121_ELE7_RL 0x50
#define MPR121_ELE8_TH 0x51
#define MPR121_ELE8_RL 0x52
#define MPR121_ELE9_TH 0x53
#define MPR121_ELE9_RL 0x54
#define MPR121_ELE10_TH 0x55
#define MPR121_ELE10_RL 0x56
#define MPR121_ELE11_TH 0x57
#define MPR121_ELE11_RL 0x58
#define MPR121_ELE_EN 0x2A
#define MPR121_FILTER_CFG 0x2C
#define MPR121_ELE0_CFG 0x5E
#define MPR121_ELE1_CFG 0x5F
#define MPR121_ELE2_CFG 0x60
#define MPR121_ELE3_CFG 0x61
#define MPR121_ELE4_CFG 0x62
#define MPR121_ELE5_CFG 0x63
#define MPR121_ELE6_CFG 0x64
#define MPR121_ELE7_CFG 0x65
#define MPR121_ELE8_CFG 0x66
#define MPR121_ELE9_CFG 0x67
#define MPR121_ELE10_CFG 0x68
#define MPR121_ELE11_CFG 0x69

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status();
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELE_EN, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_ELE0_TH + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_ELE0_RL + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_FILTER_CFG, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to set filter/charge time\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_ELE0_CFG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELE_EN, 0x3F) < 0) {
        fprintf(stderr, "Error: Failed to enable all electrodes\n");
        return -1;
    }

    gpioDelay(1000); // 1 ms delay

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status() {
    int touch_status_low, touch_status_high;

    touch_status_low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_low < 0) {
        fprintf(stderr, "Error: Failed to read touch status low byte\n");
        return -1;
    }

    touch_status_high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status high byte\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Function to toggle the relay
void toggle_relay() {
    int current_relay_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_relay_state);
    printf("Relay toggled to state: %d\n", !current_relay_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    printf("MPR121 and Relay Control Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status >= 0) {
            if (touch_status > 0) {
                toggle_relay();
            }
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

