#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define POLLING_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_t event_thread;

// Function prototypes
void *event_detection(void *arg);
void log_event(const char *event_type, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Structure to pass arguments to the event detection thread
typedef struct {
    int pir_gpio;
    int relay_gpio;
    int unlock_duration_ms;
    int rate_limit_duration_s;
} event_config_t;

// Function to log events with millisecond precision
void log_event(const char *event_type, int gpio_pin) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - GPIO: %d\n", timestamp, event_type, gpio_pin);
        fflush(log_file); // Ensure immediate write to file
    }
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Event detection thread function
void *event_detection(void *arg) {
    event_config_t *config = (event_config_t *)arg;
    int pir_gpio = config->pir_gpio;
    int relay_gpio = config->relay_gpio;
    int unlock_duration_ms = config->unlock_duration_ms;
    int rate_limit_duration_s = config->rate_limit_duration_s;

    while (running) {
        int pir_value = gpioRead(pir_gpio);
        if (pir_value == 1) {
            log_event("Motion Detected", pir_gpio);

            // Activate relay
            gpioWrite(relay_gpio, 1);
            gpioDelay(unlock_duration_ms * 1000); // Convert ms to microseconds
            gpioWrite(relay_gpio, 0);

            // Rate limiting
            struct timespec rate_limit_ts = {0, rate_limit_duration_s * 1000000}; // 2 seconds
            nanosleep(&rate_limit_ts, NULL);

            log_event("Door Unlocked", relay_gpio);
        }
        gpioDelay(POLLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }
    pthread_exit(NULL);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        pthread_mutex_lock(&log_mutex);
        fclose(log_file);
        pthread_mutex_unlock(&log_mutex);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistors for PIR sensors
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);

    // Initialize log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create event detection thread
    event_config_t event_config_1 = {PIR_SENSOR_1, RELAY_PIN, UNLOCK_DURATION_MS, RATE_LIMIT_DURATION_S};
    event_config_t event_config_2 = {PIR_SENSOR_2, RELAY_PIN, UNLOCK_DURATION_MS, RATE_LIMIT_DURATION_S};

    if (pthread_create(&event_thread, NULL, event_detection, &event_config_1) != 0) {
        perror("Failed to create event detection thread");
        cleanup();
        return 1;
    }

    // Main loop (can be used for other tasks)
    printf("Door unlock system started. Press Ctrl+C to exit.\n");
    while (running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Wait for the event detection thread to finish
    pthread_join(event_thread, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

