// Define minimum and maximum duration for each step
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define minimum and maximum duty cycle
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global variable to signal program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    shutdown = 1;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to generate a random pattern
void generate_pattern(int *motor1_duty_cycle, int *motor2_duty_cycle, int *duration, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        // Seed the random number generator with time(NULL)
        srand(time(NULL));

        // Generate random duty cycles
        motor1_duty_cycle[i] = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
        motor2_duty_cycle[i] = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;

