    for (int i = 0; i < num_steps; i++) {
        // Set motor 1 duty cycle
        gpioPWM(MOTOR1_PIN, motor1_duty_cycle[i]);

        // Set motor 2 duty cycle
        gpioPWM(MOTOR2_PIN, motor2_duty_cycle[i]);

