#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0
#define DEFAULT_THRESHOLD 10.0
#define TIMEOUT_US 500000 // 0.5 seconds in microseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Function prototypes
int initialize_gpio();
int read_hx711();
double convert_to_weight(int raw_value, double scale_factor, double offset);
void control_solenoid(double weight, double threshold);
void log_data(double weight);
void load_calibration_data(double *scale_factor, double *offset);
void save_calibration_data(double scale_factor, double offset);
void signal_handler(int signal);
void timeout_handler();

// Structure to hold calibration data
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially unlocked

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    gpioWrite(HX711_CLOCK_PIN, 0);

    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay

    data = data ^ 0x800000; // Two's complement

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight, double threshold) {
    if (weight > threshold) {
        gpioWrite(SOLENOID_PIN, 1); // Engage lock (active high)
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Release lock
    }
}

// Function to log data to file
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Function to load calibration data from file
void load_calibration_data(double *scale_factor, double *offset) {
    char line[256];
    if (fgets(line, sizeof(line), calibration_file) != NULL) {
        char *token = strtok(line, ",");
        if (token != NULL) {
            *scale_factor = atof(token);
        }
        token = strtok(NULL, ",");
        if (token != NULL) {
            *offset = atof(token);
        }
    } else {
        fprintf(stderr, "Error: Calibration file is empty or malformed\n");
        *scale_factor = DEFAULT_SCALE_FACTOR;
        *offset = DEFAULT_OFFSET;
    }
}

// Function to save calibration data to file
void save_calibration_data(double scale_factor, double offset) {
    if (calibration_file != NULL) {
        fprintf(calibration_file, "%.6f,%.6f\n", scale_factor, offset);
        fflush(calibration_file);
    } else {
        fprintf(stderr, "Error: Calibration file is not open\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Timeout handler
void timeout_handler() {
    fprintf(stderr, "Timeout occurred, skipping this reading.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Open calibration file
    calibration_file = fopen("calibration.txt", "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Calibration file not found, using defaults\n");
        double scale_factor = DEFAULT_SCALE_FACTOR;
        double offset = DEFAULT_OFFSET;
    } else {
        double scale_factor, offset;
        load_calibration_data(&scale_factor, &offset);
    }

    // Save calibration data to file
    save_calibration_data(scale_factor, offset);

    // Perform one-time startup calibration
    int raw_values[100];
    for (int i = 0; i < 100; i++) {
        raw_values[i] = read_hx711();
        if (raw_values[i] == -1) {
            fprintf(stderr, "Error reading HX711 during startup calibration\n");
            running = 0; // Stop the calibration loop if there's an error
            break;
        }
        gpioDelay(10); // Small delay between readings
    }

    if (running) {
        double offset = 0.0;
        for (int i = 0; i < 100; i++) {
            offset += raw_values[i];
            gpioDelay(10);
        }
        offset /= 100.0;
        scale_factor = 1.0; // Use default scale factor for now

        // Save the final offset to the calibration file
        save_calibration_data(scale_factor, offset);

        printf("Startup calibration complete. Offset: %.6f\n", offset);
    }

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_weight(raw_value, scale_factor, offset);
            control_solenoid(weight, DEFAULT_THRESHOLD);
            log_data(weight);
        } else {
            fprintf(stderr, "Error reading HX711\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked on exit
    fclose(log_file);
    fclose(calibration_file);
    gpioTerminate();

    return 0;
}

