#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_MS 50
#define RAIN_DETECTED_THRESHOLD 3
#define MOTOR_DURATION_SECONDS 5
#define PWM_FREQUENCY 1000 // Hz
#define PWM_DUTY_CYCLE 150 // 150/255
#define PWM_RANGE 255

// Global variables
static volatile int running = 1;
static int rain_detected = 0;
static int window_closed = 0;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_window();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[DEBOUNCE_READINGS];
    int i;
    int rain_count = 0;

    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        gpioDelay(DEBOUNCE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        if (readings[i] == 0) { // LOW indicates rain
            rain_count++;
        }
    }

    return rain_count >= RAIN_DETECTED_THRESHOLD ? 1 : 0; // Return 1 if rain is detected, 0 otherwise
}

// Function to close the window
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
    gpioDelay(MOTOR_DURATION_SECONDS * 1000000); // Convert seconds to microseconds
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Window closed.");
}

// Function to stop the window
void stop_window() {
    log_event("Stopping window...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Window stopped.");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
