#define SCALE_FACTOR 100.0  // Adjust this based on your load cell calibration
#define OFFSET 0.0         // Adjust this based on your load cell calibration

// Stock level threshold (in grams)
#define STOCK_LEVEL_THRESHOLD 100.0

// Solenoid activation duration (in seconds)
#define SOLENOID_DURATION 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void activate_solenoid();
void log_event(const char *event);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low (data ready)
    int timeout = 1000; // Timeout after 1000 attempts
    while (gpioRead(HX711_DT) && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: HX711 data line stuck high (timeout)\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)raw_value / SCALE_FACTOR + OFFSET;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid\n");
        return;
    }
    log_event("Solenoid activated");
    gpioDelay(SOLENOID_DURATION * 1000); // Delay for 5 seconds
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid\n");
    }
    log_event("Solenoid deactivated");
}

