            log_event("Error: Failed to read HX711 data");
        } else {
            double weight = calculate_weight(raw_value);
            printf("Weight: %.2f g\n", weight);

            if (weight < STOCK_LEVEL_THRESHOLD) {
                activate_solenoid();
            }

            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight);
            log_event(log_message);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

