#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_DURATION 5 // seconds

// Global variables
FILE *log_file = NULL;
FILE *calibration_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_hx711();
double calibrate_load_cell();
double calculate_weight(double raw_value, double calibration_factor);
void control_solenoid(int state);
void log_event(double weight);
void handle_signal(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 100) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the load cell
double calibrate_load_cell() {
    double known_weight;
    double raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight\n");
        return 0.0; // Return a default calibration factor
    }

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error reading raw value during calibration\n");
        return 0.0; // Return a default calibration factor
    }

    double calibration_factor = (double)raw_value / known_weight;
    return calibration_factor;
}

// Function to calculate weight from raw value and calibration factor
double calculate_weight(double raw_value, double calibration_factor) {
    return raw_value / calibration_factor;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    printf("Solenoid set to %s\n", state ? "HIGH" : "LOW");
}

// Function to log events to a file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void handle_signal(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Open calibration file
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file\n");
        cleanup();
        return 1;
    }

    // Calibrate the load cell
    double calibration_factor = calibrate_load_cell();
    if (calibration_factor == 0.0) {
        fprintf(stderr, "Calibration failed, using default value\n");
    } else {
        printf("Calibration factor: %.6f\n", calibration_factor);
        fprintf(calibration_file, "calibration_factor: %.6f\n", calibration_factor);
        fclose(calibration_file);
    }

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight((double)raw_value, calibration_factor);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight exceeds threshold, unlocking solenoid...\n");
                control_solenoid(1); // Activate solenoid
                gpioDelay(SOLENOID_DURATION * 1000); // Wait for specified duration
                control_solenoid(0); // Deactivate solenoid
                log_event(weight);
            } else {
                log_event(weight);
            }
        } else {
            fprintf(stderr, "Error reading weight\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

