}

// Function to calculate weight from raw value and calibration factor
double calculate_weight(double raw_value, double calibration_factor) {
    return raw_value / calibration_factor;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    printf("Solenoid set to %s\n", state ? "HIGH" : "LOW");
}

// Function to log events to a file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void handle_signal(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Open calibration file
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file\n");
        cleanup();
        return 1;
    }

    // Calibrate the load cell
    double calibration_factor = calibrate_load_cell();
    if (calibration_factor == 0.0) {
        fprintf(stderr, "Calibration failed, using default value\n");
    } else {
        printf("Calibration factor: %.6f\n", calibration_factor);
        fprintf(calibration_file, "calibration_factor: %.6f\n", calibration_factor);
        fclose(calibration_file);
    }

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight((double)raw_value, calibration_factor);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight exceeds threshold, unlocking solenoid...\n");
                control_solenoid(1); // Activate solenoid
                gpioDelay(SOLENOID_DURATION * 1000); // Wait for specified duration
                control_solenoid(0); // Deactivate solenoid
                log_event(weight);
            } else {
                log_event(weight);
            }
        } else {
            fprintf(stderr, "Error reading weight\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

