#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
int control_relay(int state);
int log_event(int relay_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request sensor line as input
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Error getting sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "obstacle_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(sensor_line, &config, 0) < 0) {
        perror("Error requesting sensor line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request relay line as output
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Error getting relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "relay_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(relay_line, &config, 0) < 0) {
        perror("Error requesting relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        perror("Error setting relay value");
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Relay State: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            continue; // Retry reading the sensor
        }

        // Toggle relay state if obstacle detected (active-low sensor)
        int relay_state = !sensor_value;
        if (control_relay(relay_state) < 0) {
            fprintf(stderr, "Error controlling relay, retrying...\n");
            continue; // Retry controlling the relay
        }

        // Log the event
        if (log_event(relay_state) < 0) {
            fprintf(stderr, "Error logging event, retrying...\n");
        }

        // Delay to avoid excessive CPU usage
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Obstacle avoidance system stopped.\n");
    return 0;
}

