#include <time.h>

// Configuration file path
#define CONFIG_FILE "watering.conf"

// GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18

// Signal handlers
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio(const char *chip_name, int line_number, int direction);
int read_config_file(const char *filename, int *duration);
int set_valve_state(int chip, int line, int state);
int sleep_safe(int seconds);
void signal_handler(int sig);

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *line;

int main() {
    int duration;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (init_gpio(GPIO_CHIP, GPIO_LINE, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO line as output.\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Read configuration from file
    if (read_config_file(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Error reading configuration file.\n");
        set_valve_state(GPIO_CHIP, GPIO_LINE, 0); // Ensure valve is off
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Main loop
    while (program_running) {
        if (set_valve_state(GPIO_CHIP, GPIO_LINE, 1) != 0) {
            fprintf(stderr, "Error setting valve state to HIGH.\n");
            break;
        }
        printf("Valve ON\n");
        if (sleep_safe(duration) != 0) {
            fprintf(stderr, "Error sleeping for %d seconds.\n", duration);
            break;
        }
        if (set_valve_state(GPIO_CHIP, GPIO_LINE, 0) != 0) {
            fprintf(stderr, "Error setting valve state to LOW.\n");
            break;
        }
        printf("Valve OFF\n");
    }

    // Cleanup
    set_valve_state(GPIO_CHIP, GPIO_LINE, 0); // Ensure valve is off
    gpiod_chip_close(chip);
    gpiod_line_release(line);

    return 0;
}

// Initialize GPIO line as output
int init_gpio(const char *chip_name, int line_number, int direction) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip_name, line_number);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", line_number, strerror(errno));
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", line_number, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    if (direction != 0 && direction != 1) {
        fprintf(stderr, "Invalid direction: %d. Must be 0 (active-low) or 1 (active-high).\n", direction);
        gpiod_line_release(line);
        return -1;
    }

    if (direction == 0) {
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting initial value of GPIO line %d to 0: %s\n", line_number, strerror(errno));
            gpiod_line_release(line);
            return -1;
        }
    } else {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting initial value of GPIO line %d to 1: %s\n", line_number, strerror(errno));
            gpiod_line_release(line);
            return -1;
        }
    }

    return 0;
}

// Read configuration from file
int read_config_file(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from configuration file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "%d", duration) != 1) {
        fprintf(stderr, "Error parsing duration from configuration file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (*duration <= 0 || *duration > 3600) {
        fprintf(stderr, "Error: Invalid duration in configuration file. Must be between 1 and 3600.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Set valve state (HIGH or LOW)
int set_valve_state(int chip, int line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO line %d to %d: %s\n", line, state, strerror(errno));
        return -1;
    }
    return 0;
}

// Sleep for a specified number of seconds
int sleep_safe(int seconds) {
    struct timespec ts;
    ts.tv_sec = seconds;
    ts.tv_nsec = 0;
    if (nanosleep(&ts, NULL) != 0) {
        if (errno == EINTR) {
            return 0; // Interrupted by signal
        }
        fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    program_running = 0;
    printf("Signal received, shutting down...\n");
}

