#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for sensors and motors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_1 22
#define LEFT_MOTOR_2 23
#define RIGHT_MOTOR_1 24
#define RIGHT_MOTOR_2 25

// Define motor speeds
#define STRAIGHT_SPEED 150
#define LEFT_SPEED 75
#define RIGHT_SPEED 75

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void set_motor_speed(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void stop_motors();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    gpioSetMode(LEFT_MOTOR_1, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_2, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_1, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_2, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(LEFT_MOTOR_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_2, PWM_FREQUENCY);

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Set motor speeds
void set_motor_speed(int left_speed, int right_speed) {
    gpioPWM(LEFT_MOTOR_1, left_speed);
    gpioPWM(LEFT_MOTOR_2, 0);
    gpioPWM(RIGHT_MOTOR_1, right_speed);
    gpioPWM(RIGHT_MOTOR_2, 0);
}

// Log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fclose(fp);
}

// Stop motors
void stop_motors() {
    gpioPWM(LEFT_MOTOR_1, 0);
    gpioPWM(LEFT_MOTOR_2, 0);
    gpioPWM(RIGHT_MOTOR_1, 0);
    gpioPWM(RIGHT_MOTOR_2, 0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Line following robot started. Press Ctrl+C to stop.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR);
        int middle_sensor = read_sensor(MIDDLE_SENSOR);
        int right_sensor = read_sensor(RIGHT_SENSOR);

        // Determine motor speeds based on sensor readings
        int left_speed, right_speed;
        if (middle_sensor == 0) {
            left_speed = STRAIGHT_SPEED;
            right_speed = STRAIGHT_SPEED;
        } else if (left_sensor == 0) {
            left_speed = LEFT_SPEED;
            right_speed = STRAIGHT_SPEED;
        } else if (right_sensor == 0) {
            left_speed = STRAIGHT_SPEED;
            right_speed = RIGHT_SPEED;
        } else {
            stop_motors();
        }

        // Set motor speeds
        set_motor_speed(left_speed, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motors();
    gpioTerminate();
    return 0;
}

