#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Global variable to track servo position
int servo_position = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_servo_position(int position);
void lock_door();
void unlock_door();
void button_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set lock button pin as input with pull-up resistor
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    // Set unlock button pin as input with pull-up resistor
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handlers for button presses
    gpioSetAlertFunc(LOCK_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON_PIN, button_callback);

    return 0; // Indicate success
}

// Set servo position using pigpio
void set_servo_position(int position) {
    // Ensure position is within safe range
    if (position < SERVO_MIN_PULSE_WIDTH) {
        position = SERVO_MIN_PULSE_WIDTH;
    } else if (position > SERVO_MAX_PULSE_WIDTH) {
        position = SERVO_MAX_PULSE_WIDTH;
    }

    gpioServo(SERVO_PIN, position);
    servo_position = position; // Update global position
}

// Lock the door
void lock_door() {
    printf("Locking door...\n");
    set_servo_position(SERVO_MIN_PULSE_WIDTH);
    gpioDelay(1000); // Debounce delay
}

// Unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    set_servo_position(SERVO_MAX_PULSE_WIDTH);
    gpioDelay(1000); // Debounce delay
}

// Button press callback function
void button_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick[2] = {0, 0}; // Store last tick for each button
    uint32_t current_tick = gpioTick();

    // Debounce the lock button
    if (gpio == LOCK_BUTTON_PIN && (current_tick - last_tick[0] > 100000)) { // 100ms debounce
        lock_door();
        last_tick[0] = current_tick;
    }

    // Debounce the unlock button
    if (gpio == UNLOCK_BUTTON_PIN && (current_tick - last_tick[1] > 100000)) { // 100ms debounce
        unlock_door();
        last_tick[1] = current_tick;
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control system started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running)
    while (1) {
        gpioDelay(100); // Small delay to prevent CPU hogging
    }

    return 0;
}

