#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the duration of the motor pulses in milliseconds
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Define the delay between motor pulses in milliseconds
#define DELAY_DURATION 100

// Global variables for GPIO lines
struct gpiod_line *motor1_line = NULL;
struct gpiod_line *motor2_line = NULL;

// Function prototypes
int initialize_gpio(struct gpiod_chip *chip, int gpio_pin);
int set_gpio_value(struct gpiod_line *line, int value);
int pulse_motor(struct gpiod_line *line, int duration_ms);
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        cleanup_gpio(NULL, motor1_line);
        cleanup_gpio(NULL, motor2_line);
        exit(0);
    }
}

// Function to initialize a GPIO line
int initialize_gpio(struct gpiod_chip *chip, int gpio_pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_request_output(line, "haptic_feedback", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", gpio_pin);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO line value to %d\n", value);
        return -1;
    }
    return 0;
}

// Function to pulse a motor
int pulse_motor(struct gpiod_line *line, int duration_ms) {
    if (set_gpio_value(line, 1) < 0) {
        return -1;
    }
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
    if (set_gpio_value(line, 0) < 0) {
        return -1;
    }
    return 0;
}

// Function to cleanup a GPIO line
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        if (gpiod_line_release(line) < 0) {
            fprintf(stderr, "Error: Could not release GPIO line\n");
            return -1;
        }
    }
    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(chip, MOTOR1_GPIO) < 0) {
        cleanup_gpio(chip, NULL);
        return 1;
    }
    if (initialize_gpio(chip, MOTOR2_GPIO) < 0) {
        cleanup_gpio(chip, motor1_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Pulse motor 1
        if (pulse_motor(motor1_line, MOTOR1_DURATION) < 0) {
            break; // Exit loop on error
        }

        // Delay
        usleep(DELAY_DURATION * 1000);

        // Pulse motor 2
        if (pulse_motor(motor2_line, MOTOR2_DURATION) < 0) {
            break; // Exit loop on error
        }

        // Delay
        usleep(DELAY_DURATION * 1000);
    }

    // Cleanup GPIO lines before exiting
    cleanup_gpio(chip, motor1_line);
    cleanup_gpio(chip, motor2_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

