#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <zmq.h>

// Configuration
#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_SERVER_PORT 5555
#define ZMQ_CLIENT_PORT 5556
#define ZMQ_TOPIC "SOUND_ALERTS"
#define SOUND_THRESHOLD 0 // Active-low sensor, logic 0 means sound detected
#define ALARM_DURATION 1 // seconds
#define POLL_INTERVAL_MS 10

// Global variables (minimize usage)
static volatile int running = 1;
static void *context = NULL;
static void *server_socket = NULL;
static void *client_socket = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
void cleanup_gpio();
void cleanup_zmq();
void signal_handler(int signal);
void alarm_led_on();
void alarm_led_off();
void publish_alert(const char *message);
void subscribe_alerts();
void process_alerts();
void sound_sensor_callback(int gpio, int level, uint32_t tick);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(SOUND_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to initialize ZeroMQ
int initialize_zmq() {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return 1;
    }

    server_socket = zmq_socket(context, ZMQ_STREAM);
    if (!server_socket) {
        fprintf(stderr, "Failed to create ZeroMQ socket (server)\n");
        zmq_ctx_destroy(context);
        return 1;
    }

    int bind_result = zmq_bind(server_socket, "tcp://*:5555");
    if (bind_result != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket (server): %s\n", zmq_strerror(errno));
        zmq_close(server_socket);
        zmq_ctx_destroy(context);
        return 1;
    }

    client_socket = zmq_socket(context, ZMQ_STREAM);
