#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100
#define PULSE_TIMEOUT_US 10000 // 10ms timeout

// NEC Constants
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE_1 1690
#define NEC_BIT_SPACE_0 560

// Global Variables
static volatile int pulse_count = 0;
static volatile unsigned int last_tick = 0;
static volatile unsigned int pulse_data[PULSE_BUFFER_SIZE];
static volatile int pulse_index = 0;
static struct mosquitto *mqtt_client = NULL;
static struct mosquitto *mqtt_client_options = NULL;
static int running = 1;

// Function Prototypes
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(unsigned int *pulse_data, int pulse_count, unsigned int *address, unsigned int *command);
void publish_mqtt(unsigned int address, unsigned int command);
void signal_handler(int signal);
void cleanup();

// IR Callback Function
void ir_callback(int gpio, int level, uint32_t tick)
{
    unsigned int pulse_length = tick - last_tick;
    last_tick = tick;

    if (level == FALLING_EDGE)
    {
        if (pulse_count < PULSE_BUFFER_SIZE)
        {
            pulse_data[pulse_count++] = pulse_length;
        }
        else
        {
            // Buffer overflow, reset
            pulse_count = 0;
        }
    }
}

// NEC Decoding Function
int decode_nec(unsigned int *pulse_data, int pulse_count, unsigned int *address, unsigned int *command)
{
    if (pulse_count < 68) return -1; // Not enough pulses

    // Validate header
    if (pulse_data[0] < NEC_HEADER_MARK * 0.8 || pulse_data[0] > NEC_HEADER_MARK * 1.2 ||
        pulse_data[1] < NEC_HEADER_SPACE * 0.8 || pulse_data[1] > NEC_HEADER_SPACE * 1.2)
    {
        syslog(LOG_ERR, "NEC Header validation failed");
        return -1;
    }

    // Decode address and command
    *address = 0;
    *command = 0;

    for (int i = 0; i < 32; i++)
    {
        if (pulse_data[2 + (i * 2) + 1] > NEC_BIT_MARK * 0.8 && pulse_data[2 + (i * 2) + 1] < NEC_BIT_MARK * 1.2)
        {
            if (pulse_data[2 + (i * 2) + 3] > NEC_BIT_SPACE_1 * 0.8 && pulse_data[2 + (i * 2) + 3] < NEC_BIT_SPACE_1 * 1.2)
            {
                *address |= (1 << i);
            }
            else if (pulse_data[2 + (i * 2) + 3] > NEC_BIT_SPACE_0 * 0.8 && pulse_data[2 + (i * 2) + 3] < NEC_BIT_SPACE_0 * 1.2)
            {
                *address &= ~(1 << i);
            }
            else
            {
                syslog(LOG_ERR, "Invalid bit space length");
                return -1;
            }
        }
        else
        {
            syslog(LOG_ERR, "Invalid bit mark length");
            return -1;
        }
    }

    // Validate checksum
    unsigned int checksum = 0;
    for (int i = 0; i < 32; i++)
    {
        checksum += (address >> i) & 1;
    }
    checksum = ~checksum & 0xFFFF; // Invert and mask to 16 bits

    if (checksum != (pulse_data[34] > NEC_BIT_MARK * 0.8 && pulse_data[34] < NEC_BIT_MARK * 1.2 &&
                     pulse_data[35] > NEC_BIT_SPACE_1 * 0.8 && pulse_data[35] < NEC_BIT_SPACE_1 * 1.2))
    {
        syslog(LOG_ERR, "Checksum validation failed");
        return -1;
    }

    return 0;
}

// MQTT Publish Function
void publish_mqtt(unsigned int address, unsigned int command)
{
    json_t *root = json_object();
    json_object_set_new(root, "address", json_integer(address));
    json_object_set_new(root, "command", json_integer(command));

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(5));
    if (!json_str)
    {
        syslog(LOG_ERR, "Failed to serialize JSON");
        json_decref(root);
        return;
    }

    int ret = mosquitto_publish(mqtt_client, mqtt_client_options, MQTT_TOPIC, strlen(json_str), json_str, 0, false);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    }

    json_decref(root);
    free(json_str);
}

// Signal Handler Function
void signal_handler(int signal)
{
    syslog(LOG_INFO, "Signal received, cleaning up...");
    running = 0;
}

// Cleanup Function
void cleanup()
{
    syslog(LOG_INFO, "Cleaning up resources...");

    if (mqtt_client)
    {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
    }

    if (mqtt_client_options)
    {
        mosquitto_destroy(mqtt_client_options);
        mosquitto_lib_cleanup();
    }

    gpioTerminate();
    closelog();
}

int main()
{
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set alert function for falling edge
    gpioSetAlertFuncEx(GPIO_PIN, ir_callback, NULL);

    // Initialize MQTT
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client)
    {
        syslog(LOG_ERR, "Failed to create MQTT client");
        cleanup();
        return 1;
    }

    mqtt_client_options = mosquitto_client_options_new(mqtt_client);
    if (!mqtt_client_options)
    {
        syslog(LOG_ERR, "Failed to create MQTT client options");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, NULL);
    mosquitto_message_callback_set(mqtt_client, NULL);
    mosquitto_loop_callback_set(mqtt_client, NULL);

    int ret = mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR decoder started");

    while (running)
    {
        // Check for pulse data and decode
        if (pulse_count > 0)
        {
            unsigned int address, command;
            if (decode_nec(pulse_data, pulse_count, &address, &command) == 0)
            {
                syslog(LOG_INFO, "Decoded: Address = 0x%08X, Command = 0x%08X", address, command);
                publish_mqtt(address, command);
            }
            else
            {
                syslog(LOG_ERR, "NEC decoding failed");
            }
            pulse_count = 0; // Reset pulse count after processing
        }

        gpioDelay(1000); // Check every 1ms
    }

    cleanup();
    return 0;
}

