#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define SLEEP_SECONDS 1

// Structure to hold sensor data
typedef struct {
    int fd;
    int address;
    float lux;
    int valid;
} sensor_t;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize an I2C device
int i2c_init(int bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read lux value from a BH1750 sensor
float read_bh1750(int fd) {
    unsigned char data[2];
    int result;

    // Send measurement command (0x20)
    result = write(fd, "\x20", 1);
    if (result != 1) {
        perror("Error writing to I2C device");
        return NAN;
    }

    // Wait for measurement (at least 180ms)
    usleep(180000); // 180ms

    // Read 2 bytes of data
    result = read(fd, data, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return NAN;
    }

    // Convert big-endian data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to process sensor data
void process_sensor_data(sensor_t *sensors, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        sensors[i].lux = read_bh1750(sensors[i].fd);
        if (sensors[i].lux == NAN) {
            sensors[i].valid = 0;
            fprintf(stderr, "Error reading sensor %d\n", i + 1);
        } else {
            sensors[i].valid = 1;
        }
    }
}

// Function to format sensor data into a string
char* format_sensor_data(sensor_t *sensors, int num_sensors) {
    char *buffer = malloc(256); // Allocate memory for the string
    if (buffer == NULL) {
        perror("Failed to allocate memory for sensor data string");
        return NULL;
    }
    int offset = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].valid) {
            offset += snprintf(buffer + offset, 256 - offset, "%d,%.2f;", i + 1, sensors[i].lux);
        } else {
            offset += snprintf(buffer + offset, 256 - offset, "%d,NAN;", i + 1);
        }
    }

    return buffer;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data, const char *multicast_addr, int port) {
    int sockfd;
    struct sockaddr_in addr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket() failed");
        return -1;
    }

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL) failed");
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(multicast_addr);
    addr.sin_port = htons(port);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto() failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensors
    sensor_t sensors[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].address = 0x23 + i; // Start at 0x23, increment for others
        sensors[i].fd = i2c_init(I2C_BUS, sensors[i].address);
        if (sensors[i].fd < 0) {
            fprintf(stderr, "Failed to initialize sensor %d\n", i + 1);
            // Attempt to close any previously opened file descriptors
            for (int j = 0; j < i; j++) {
                close(sensors[j].fd);
            }
            return 1;
        }
        sensors[i].valid = 1; // Initialize validity to true
    }

    // Main loop
    while (!terminate) {
        // Process sensor data
        process_sensor_data(sensors, NUM_SENSORS);

        // Format sensor data into a string
        char *data = format_sensor_data(sensors, NUM_SENSORS);
        if (data == NULL) {
            fprintf(stderr, "Failed to format sensor data\n");
            continue; // Skip to the next iteration
        }

        // Send data via UDP multicast
        if (send_udp_multicast(data, MULTICAST_ADDR, MULTICAST_PORT) < 0) {
            fprintf(stderr, "Failed to send UDP multicast data\n");
        }

        free(data); // Free the allocated memory

        // Sleep for one second
        sleep(SLEEP_SECONDS);
    }

    // Close I2C file descriptors
    for (int i = 0; i < NUM_SENSORS; i++) {
        close(sensors[i].fd);
    }

    return 0;
}

