#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define RETRY_DELAY_MS 100
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_read(int fd, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

int i2c_write(int fd, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = write(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

float read_airflow(int fd) {
    unsigned char data[2];
    int raw_flow;
    float flow_slpm;

    if (i2c_write(fd, (unsigned char[]){0x00}, 1) != 0) {
        fprintf(stderr, "Failed to send start condition.\n");
        return -1.0;
    }

    if (i2c_read(fd, data, 2) != 0) {
        fprintf(stderr, "Failed to read flow data.\n");
        return -1.0;
    }

    raw_flow = (data[0] << 8) | data[1];
    raw_flow = raw_flow & 0x3FFF; // Mask to 14 bits

    flow_slpm = (float)(raw_flow - 3277) * 0.1;

    return flow_slpm;
}

int log_flow(float flow_rate) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fclose(fp);

    return 0;
}

int main() {
    int fd;
    float airflow;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    signal(SIGINT, signal_handler);

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        airflow = read_airflow(fd);
        if (airflow >= 0) {
            if (log_flow(airflow) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Error reading airflow.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    close(fd);
    printf("Airflow monitoring stopped.\n");

    return 0;
}

