#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Structure to hold configuration
typedef struct {
    int i2c_address;
    int interval;
    char *output_filename;
} config_t;

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static config_t config = {DEFAULT_I2C_ADDRESS, DEFAULT_INTERVAL, DEFAULT_OUTPUT_FILENAME};
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(int address);
int read_sensor_data(sensor_data_t *data);
float convert_to_g(int16_t raw);
int log_data(FILE *fp, float x_g, float y_g, float z_g);
int log_error(const char *message);
void signal_handler(int signum);
void cleanup();

// I2C setup function
int i2c_setup(int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-1");
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        log_error("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data function
int read_sensor_data(sensor_data_t *data) {
    unsigned char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, buffer, 6) == 6) {
            // Combine high and low bytes for each axis
            data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
            data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
            data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

            return 0; // Success
        } else {
            log_error("I2C read failed, retrying...");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
        }
    }

    log_error("I2C read failed after multiple retries");
    return -1; // Failure
}

// Convert raw data to g function
float convert_to_g(int16_t raw) {
    return (float)raw * 0.000244;
}

// Log data function
int log_data(FILE *fp, float x_g, float y_g, float z_g) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g) < 0) {
        log_error("Failed to write to CSV file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Log error function
int log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, terminating...\n", signum);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                config.i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                config.interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                config.output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f output_filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open log file
    log_file = fopen(config.output_filename, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_setup(config.i2c_address);
    if (i2c_fd == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    sensor_data_t sensor_data;
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            x_g = convert_to_g(sensor_data.x);
            y_g = convert_to_g(sensor_data.y);
            z_g = convert_to_g(sensor_data.z);

            if (log_data(log_file, x_g, y_g, z_g) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(config.interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

