        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, terminating...\n", signum);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                config.i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                config.interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                config.output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f output_filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open log file
    log_file = fopen(config.output_filename, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_setup(config.i2c_address);
    if (i2c_fd == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    sensor_data_t sensor_data;
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            x_g = convert_to_g(sensor_data.x);
            y_g = convert_to_g(sensor_data.y);
            z_g = convert_to_g(sensor_data.z);

            if (log_data(log_file, x_g, y_g, z_g) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(config.interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

