#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define POWER_ON_CMD 0x01
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, int addr, int data) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, int addr, unsigned char *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

float read_bh1750(int fd) {
    unsigned char buf[2];
    if (i2c_write(fd, BH1750_ADDR, POWER_ON_CMD) < 0) return -1.0;
    usleep(200000); // Wait for power-on
    if (i2c_write(fd, BH1750_ADDR, CONTINUOUS_HIGH_RES_MODE) < 0) return -1.0;
    usleep(200000); // Wait for mode setting

    if (i2c_read(fd, BH1750_ADDR, buf, 2) < 0) return -1.0;

    unsigned int raw = (buf[0] << 8) | buf[1];
    return (float)raw / 1.2;
}

int create_udp_socket() {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }
    return sockfd;
}

int set_multicast_ttl(int sockfd, int ttl) {
    struct ip_mreq mreq;
    mreq.imr_multiaddr.s_addr = inet_addr(MULTICAST_ADDR);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting multicast TTL");
        return -1;
    }
    return 0;
}

int send_udp_packet(int sockfd, const char *message, const char *addr, int port) {
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, addr, &dest_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    int sockfd = create_udp_socket();
    if (sockfd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (set_multicast_ttl(sockfd, TTL) < 0) {
        close(i2c_fd);
        close(sockfd);
        return EXIT_FAILURE;
    }

    while (program_running) {
        float lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading BH1750 sensor. Retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        char message[32];
        snprintf(message, sizeof(message), "lux: %.2f", lux);

        if (send_udp_packet(sockfd, message, MULTICAST_ADDR, MULTICAST_PORT) < 0) {
            fprintf(stderr, "Error sending UDP packet. Retrying in 1 second...\n");
        }

        sleep(1);
    }

    close(i2c_fd);
    close(sockfd);

    return EXIT_SUCCESS;
}

