            if (memcmp(magic_word_bytes, (unsigned char *)&MAGIC_WORD, 8) == 0) {
                // Magic word found, parse the TLV data
                if (parse_tlv_data(buffer, bytes_read) == 0) {
                    // Detect objects
                    if (detect_objects(buffer, bytes_read) == 0) {
                        // Get current timestamp
                        radar_data.timestamp = time(NULL);
                        radar_data.object_index = 0; // Assign a dummy index
                        radar_data.range_m = 0.0;      // Assign dummy values
                        radar_data.velocity_mps = 0.0;

                        // Write data to CSV
                        if (write_data_to_csv(radar_data) != 0) {
                            fprintf(stderr, "Error writing data to CSV\n");
                        }
                    } else {
                        fprintf(stderr, "Error detecting objects\n");
                    }
                } else {
                    fprintf(stderr, "Error parsing TLV data\n");
                }
            } else {
                fprintf(stderr, "Invalid magic word: ");
                for (int i = 0; i < 8; i++) {
                    fprintf(stderr, "%02X", magic_word_bytes[i]);
                }
                fprintf(stderr, "\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading UART data\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

