#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 500
#define MAX_LINE_LENGTH 256
#define MAX_RANGE 10.0
#define MAX_TIMESTAMP 1000000000 // Maximum timestamp for sanity checking

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, no stop bits
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT_MS / 100; // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 0;
    timeout.tv_usec = TIMEOUT_MS * 1000; // Convert milliseconds to microseconds

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

int parse_data(const char *data, struct tm *tm_info, float *range) {
    char *token;
    char *rest = strdup(data); // Duplicate the string for strtok_r
    if (rest == NULL) {
        perror("strdup() error");
        return -1;
    }

    token = strtok_r(rest, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid data format (missing timestamp)\n");
        free(rest);
        return -1;
    }

    tm_info->tm_year = atoi(token);
    token = strtok_r(NULL, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid data format (missing range)\n");
        free(rest);
        return -1;
    }

    *range = atof(token);

    if (*range < 0.0 || *range > MAX_RANGE) {
        fprintf(stderr, "Error: Range out of bounds: %.2f\n", *range);
        free(rest);
        return -1;
    }

    return 0;
}

int log_data(const char *timestamp, float range) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (timeinfo == NULL) {
        perror("Error getting local time");
        return -1;
    }

    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
    return 0;
}

int main() {
    int uart_fd;
    char uart_buffer[MAX_LINE_LENGTH];
    float range;
    struct tm tm_info;
    char *timestamp_str;
    int bytes_read;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, uart_buffer, sizeof(uart_buffer));
        if (bytes_read > 0) {
            if (parse_data(uart_buffer, &tm_info, &range) == 0) {
                timestamp_str = ctime(&tm_info.tm_jday * 86400 + tm_info.tm_hour * 3600 + tm_info.tm_min * 60 + tm_info.tm_sec);
                timestamp_str[strlen(timestamp_str) - 1] = '\0'; // Remove trailing newline
                if (log_data(timestamp_str, range) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error parsing data: %s\n", uart_buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        usleep(10000); // 10ms delay
    }

    close(uart_fd);
    printf("Radar data acquisition stopped.\n");

    return EXIT_SUCCESS;
}

