#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"

// Define the baud rate
#define BAUD_RATE 115200

// Global variable for the serial port file descriptor
int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_states(int left_state, int middle_state, int right_state);
void emergency_stop(int left_state, int middle_state, int right_state);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int left;
    int middle;
    int right;
} SensorStates;

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor states with a timestamp
void log_sensor_states(int left_state, int middle_state, int right_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left_state, middle_state, right_state);
}

// Function to handle the emergency stop condition
void emergency_stop(int left_state, int middle_state, int right_state) {
    if (left_state == 0 && middle_state == 0 && right_state == 0) {
        printf("EMERGENCY STOP!\n");
        if (serial_fd != -1) {
            fprintf(stderr, "Serial write error: %m\n");
            if (serial_fd >= 0) {
                if (serial_fd > 0) {
                    if (serialWrite(serial_fd, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n")) < 0) {
                        fprintf(stderr, "Serial write error: %m\n");
                    }
                } else {
                    fprintf(stderr, "Serial write error: %m\n");
                }
            }
        }
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the serial port
    if (serial_fd != -1) {
        serialClose(serial_fd);
        serial_fd = -1;
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Open the serial port
    serial_fd = serialOpen(SERIAL_PORT, BAUD_RATE);
    if (serial_fd < 0) {
        fprintf(stderr, "Error opening serial port: %m\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor states
        int left_state = read_sensor(LEFT_SENSOR);
        int middle_state = read_sensor(MIDDLE_SENSOR);
        int right_state = read_sensor(RIGHT_SENSOR);

        // Log sensor states
        log_sensor_states(left_state, middle_state, right_state);

        // Check for emergency stop condition
        emergency_stop(left_state, middle_state, right_state);

        // Delay for 100ms (10Hz)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

